/* venueAdmin help. Loaded the first time ? opens. Not a first-paint script. */
(function (global) {
  "use strict";
  const entries = [{"id":"botdee-ask-floqr","title":"Ask FloqR with BOT DEE","body":"Ask FloqR with BOT DEE — tap the animated mark or wait for the prompt, then type what you want in plain words. Products: Mingl, RydR, BartR, ShoutOut, FloqCAST (superstar), clubs. Goals: say “I want to be able to…” (e.g. become a Club Admin) or “make me a superstar” for steps and links.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"Open FloqCAST","href":"./floqcast-search.html?from=botdee"}],"searchPhrases":["ask floqr","bot dee","botdee","ask bot dee","plain words","i want to be able to","help","make me a superstar","floqai","Ask FloqR with BOT DEE","Open BOT DEE","Open FloqCAST"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"index.html#botDeeHelpPopout","kind":"help"},{"id":"help-search-settings-appearance","title":"Settings on Search","body":"On the Home Search screen, tap Settings to open Profile & Settings on the Appearance tab — Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green) lives there. The Settings tile uses the same chrome icon pack as the other Search marks.","steps":[],"links":[{"label":"Open Appearance","href":"./patron-portal.html?from=search&tab=appearance"}],"searchPhrases":["settings","appearance","site chrome","search settings","theme settings","change chrome","Settings on Search","Open Appearance"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"index.html#settingsBtnCard","kind":"help"},{"id":"help-botdee-memory","title":"BOT DEE saved chats","body":"Open Feature & Orders → My BOT DEE to save chats after the pause, export, or delete history. The five-minute pause ends the live BOT DEE session. If you opt in, BOT DEE keeps that chat so you can come back later. Guests are not saved. Mingl conversations stay in Mingl.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"},{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["saved chat","bot dee memory","opt in history","export bot dee","delete bot dee history","pause vs save","five minute pause","300 seconds","my bot dee","feature and orders","memory settings","BOT DEE saved chats","My BOT DEE","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-knows-of-me","title":"What BOT DEE knows of me","body":"Facts BOT DEE stored with your approval live in Feature & Orders → My BOT DEE. The list is empty if memory is off or nothing is stored. Export or delete facts here. BOT DEE never stores your IP address. Mingl chats are not copied.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["what bot dee knows","bot dee facts","approved facts","delete fact","personalize","dsar","my bot dee","What BOT DEE knows of me","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-version-smartview","title":"Version SMARTview","body":"Type Ver, Vers, or Version — capitals do not matter. BOT DEE shows the version card. A longer question like “what is your version?” still shows that card.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["version smartview","ver command","vers command","version command","bot dee version","floqr version","what version is bot dee","Version SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-version-smartview-status","title":"Version SMARTview status is a live probe","body":"Service status is probed on this Version request: Functions and package reachable with Gemini configured → Operational; Functions and package up but Gemini not configured → Degraded; Functions not in this request → Unavailable. It is never a static Not checked label. AI model shows the configured Gemini model id for this deployment even when this turn did not generate. Frontend and backend package stamps can differ; both are labeled. Master Admin may see extra diagnostics after Technical Details — patrons do not.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["version operational","not checked","bot dee health","service status smartview","gemini version card","Version SMARTview status is a live probe","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-version-smartview-tabs","title":"Version SMARTview tabs","body":"Overview describes BOT DEE and opens Technical Details without leaving chat. What's New lists verified BOT DEE and Gemini changes only — not Master Admin, beta tester tools, or other FLOQR product notes. Help repeats the Ver / Vers / Version command. Switching tabs or expanding details keeps your unsent draft and scroll. The card uses your Site Chrome — there is no second theme.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["version what's new","version overview","technical details bot dee","version smartview tabs","bot dee what's new","gemini what's new","Version SMARTview tabs","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview","title":"Room SMARTview","body":"In BOT DEE chat, say Open Room SMARTview, Start a group chat, or plan a Cancun trip in plain words. Confirm shows Join Now or Set a schedule. Join Now opens a Mingl-friends session now and does not paint Search. Set a schedule is when the BOT DEE room starts — not Shared Itinerary — and turns on Search SMARTnotification for you and invited Mingl friends. Invite Mingl friends only — host plus 7 guests. Guests can invite too. Joining is not a payment and does not open a shared tab. BOT DEE never takes card numbers. Private BOT DEE messages stay private. Site Chrome follows your Appearance theme. A live room stays open until the host taps End Room, about four hours after it opens, or everyone has been gone about 15 minutes. Pausing private BOT DEE chat is separate.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["room smartview","start a group chat","open room smartview","create a room","group chat bot dee","talk to bot dee together","invite mingl friends","let's plan our cancun trip","let's plan a trip to cancun","plan a cancun trip","cancun trip with friends","schedule a room","join now or set a schedule","when does the room expire","last person logs out","one-time live session","Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-smartvisuals-notification","title":"Mingl Room SMARTnotification","body":"A compact Mingl Room Invitation can appear on Search when you Set a schedule for a BOT DEE room, or when a Mingl friend invited you to one. The host sees their own scheduled room on Search without the Cancun demo query. View Invitation opens Room SMARTview. Join Now goes to BOT DEE, not Mingl chat. Not Now hides the card this tab; Inbox still has Review BOT DEE invite. The Cancun demo query is Studio-only. Art is illustration, not a photo. Join Now rooms without a schedule do not paint Search.","steps":[],"links":[{"label":"Open Search","href":"./?start=search"}],"searchPhrases":["smartnotification","smart notification","mingl room invitation","view invitation","join at scheduled time","scheduled room search","cancun trip","smartvisuals","smartstencils","smartbackgrounds","travel partner","fly to cancun","labeled ad","Mingl Room SMARTnotification","Open Search"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"index.html#categoryPage","kind":"help"},{"id":"help-smartvisuals-room","title":"Room SMARTview with SMARTvisuals","body":"Room SMARTview shows the Mingl invitation: schedule, RSVP or live status, and Join Now. Join Now on Search opens BOT DEE (not Mingl chat) with room= and t=. SMARTstencils and SMARTbackgrounds follow the authorized room title — Cancun Trip uses travel art, not a real Cancun photo. Private BOT DEE chat is never used to pick art. A labeled Ad below is a sample from those tags. It stays empty for private chat or injection and is not a live advertiser.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["room smartview invitation","join now mingl","join at scheduled time","smartstencils","smartbackgrounds","cancun trip room","bot-dee itinerary","travel partner","exclusive mingl room deals","Room SMARTview with SMARTvisuals","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"index.html#categoryPage","kind":"help"},{"id":"help-botdee-room-smartview-schedule","title":"Join Now or set a schedule","body":"After Room SMARTview setup, choose Join Now or Set a schedule. Join Now opens the BOT DEE session now and does not put a card on Search. Set a schedule is when the BOT DEE room starts — not Shared Itinerary. Saving a future time turns on Search SMARTnotification for you and invited Mingl friends only. Guests RSVP until the room is live, then Join Now opens BOT DEE (not Mingl chat).","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["join now or set a schedule","set a schedule","schedule a room","join at scheduled time","smartnotification search","when does the room start","Join Now or set a schedule","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-invite","title":"Invite Mingl friends","body":"After you confirm Room SMARTview (Join Now or Set a schedule), Invite shows your Mingl friends only. Tap a friend, or type Invite lorna, to send an Inbox invite (Review BOT DEE invite). The chip stays greyed with Invite sent so you know it went — tapping again does not send a second invite. That is a Room SMARTview command — it does not open VIP reserV or a People SMARTview Invite. If a chip is you or someone already in the session, it stays marked That's you or Already in this session and does not send another invite. Not a public join link. Cap is host plus 7. Guests can invite more Mingl friends unless the host turns that off. Joining is not a payment.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["invite others to this chat","invite friends bot dee","bring my friends into this conversation","invite mingl friends","invite lorna","review bot dee invite","that's you","already in this session","cannot invite myself","invite sent","greyed chip","mslorna","Invite Mingl friends","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-join","title":"Join a BOT DEE session","body":"Open the Inbox invite or Search Join Now while signed in as the Mingl friend it was sent to. Join Now opens BOT DEE (not Mingl chat). You and invited Mingl friends share the Room SMARTview group chat; names show for members. Wrong account, expired, or revoked invites refuse. Joining the room is not joining a shared tab and does not approve a payment. BOT DEE never takes card numbers.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["join room smartview","join this bot dee chat","can my friends join us","group chat with lorna","join now search","Join a BOT DEE session","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-end","title":"End Room SMARTview","body":"Only the host can end a room. Ending does not charge anyone or erase other people’s private chats. An unpaid shared tab must be paid or voided first. A live room stays open until End Room, about four hours after it opens, or everyone has been gone about 15 minutes. Pausing private BOT DEE chat is not room logout. A guest leaving does not end the room while the host is still present.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["end this room","close room smartview","end group chat bot dee","when does the room expire","last person logs out","End Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-tab","title":"Room SMARTview shared tab","body":"Opt in first. Then add a line. Close as one payer or split. Only confirming uids are charged, via FloqR Stripe. Joining the room does not join a tab. BOT DEE never takes card numbers. Club POS is later.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["shared tab","split the bill","who is paying room","pay together bot dee","Room SMARTview shared tab","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-who-pays","title":"Who is paying","body":"Ask Who’s paying in a Room SMARTview to see opt-in status. Nobody is charged because someone said buy. Card last four stay on the payer’s own receipt.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["who's paying","who is paying","who pays in the room","Who is paying","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-kick","title":"Remove someone from Room SMARTview","body":"Only the host can remove a guest. A kicked friend cannot read further room messages. A model reply cannot kick anyone.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["remove from room","kick from room smartview","remove jalen","Remove someone from Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-smartview-share","title":"Share into Room SMARTview","body":"Share this conversation never copies your private BOT DEE thread. BOT DEE shows a preview of selected shareable facts from this message, marked tentative. You can edit or drop facts. Private profiles and SMARTsummary stay out.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["share this conversation","share our plans","share with my friends bot dee","Share into Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-collab","title":"Share a headless booking in Room SMARTview","body":"When you are in a Room SMARTview, the host's VIP reserV or ShoutOut picks appear for everyone in the session. Members vote Yes or No. Hold it and pay stay with the host — joining and voting are not a payment. BOT DEE never takes card numbers. Stripe still opens in a pop-out.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["vote the table","share vip reserv","vote host pick","headless booking vote","shared picks room smartview","Share a headless booking in Room SMARTview","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-room-elect-host","title":"Elect a Room SMARTview host","body":"Anyone in the session can be host. Nominate yourself or another joined member. A candidate becomes host at 60 percent of currently joined members (rounded up). If the host leaves, remaining members elect a new host — the room stays open. Kick and End stay with the elected host.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["make me host","elect host","vote for host","60 percent host","change room host","Elect a Room SMARTview host","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview","title":"View my SMARTview","body":"View my SMARTview shows your People card from public-within-FLOQR fields, using the same Profile Media as your FLOQR public page — not venue or restaurant mocks. Edit my SMARTsummary changes the text in your default profile language. Save translates it to every other FLOQR language, including English. Master Admin → Features → BOT DEE → SMARTviews is where labeled mock venue and restaurant cards live. There is no live Places or Yelp.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"},{"label":"SMARTviews (Master Admin)","href":"./master-admin.html#featuresBotDee-smartviews"}],"searchPhrases":["smartview","smart view","view my smartview","venue card","restaurant card","public page","mock smartview","people smartview","person card","edit my smart summary","smartsummary","edit my smartsummary","View my SMARTview","Open BOT DEE","My BOT DEE","SMARTviews (Master Admin)"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-smartview-edit","title":"Edit your SMARTsummary","body":"Only you can edit your SMARTsummary, in your default profile language. That language is the source — English is the source only when your default is English. Save is immediate. FLOQR then translates SMARTsummary into every other supported language, including English. Gemini will not overwrite text you edited unless you ask it to regenerate. If your public profile changes, FLOQR asks you to review the summary instead of replacing it.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["edit smart summary","edit my smartview","owner authored summary","regenerate summary","smartsummary","edit smartsummary","Edit your SMARTsummary","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartview-translation","title":"How SMARTview translation works","body":"Your SMARTsummary is stored in your default profile language — that language is the source, even when it is not English. After you save, FLOQR queues a translation to every other supported language, including English. An English viewer sees the English SMARTsummary once that job finishes. While a translation is pending or failed, viewers see the source language with a clear label — never a stale translation presented as current.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["smartview translation","translation pending","source language summary","stale translation","english translation","smartsummary translation","How SMARTview translation works","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartview-privacy","title":"SMARTview privacy and visibility","body":"SMARTview shows only fields you already made public within FLOQR. It is not open-web search. Dating appears only with explicit opt-in. Hide a field in My Profile and it leaves SMARTview. Blocked people cannot see your card. Report an incorrect summary from the summary overlay.","steps":[],"links":[{"label":"Profile visibility","href":"./patron-portal.html?tab=profile"},{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["smartview privacy","who can see smartview","dating opt in","hide smartview field","SMARTview privacy and visibility","Profile visibility","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html","kind":"help"},{"id":"help-botdee-smartview-media","title":"SMARTview photos and videos","body":"The compact card uses the same hero as your FLOQR public profile — the first Profile Media item (8 photos + 2 videos). Tap it for Photos and Videos from those public slots. Swipe or use arrows, then X (or Escape) to return to the same chat scroll and unsent draft.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["smartview photos","smartview videos","close overlay","escape smartview","SMARTview photos and videos","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview-categories","title":"SMARTview categories","body":"Four tabs: Social, Dating, Dining, and Future Travels. Social opens on Music, then Nightlife, Sports, and Events. Tags are only what you shared — no duplicate headings and no invented trips, ratings, or relationships. Future travel shows only destinations you marked public.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["smartview categories","social music tab","dating dining travels","future travels smartview","SMARTview categories","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview-chrome","title":"SMARTview and Site Chrome","body":"People SMARTview uses the viewing patron’s existing FLOQR Site Chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). There is no second theme setting. Changing chrome updates the card in place without losing your chat draft.","steps":[],"links":[{"label":"Appearance","href":"./patron-portal.html?tab=profile"}],"searchPhrases":["smartview chrome","black tiffany smartview","site chrome smartview","theme smartview","SMARTview and Site Chrome","Appearance"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartview-review","title":"Review and correct a SMARTsummary","body":"Gemini drafts the SMARTsummary in your default profile language from public-within-FLOQR fields only — never on each view. If a fact is wrong, hide the source field in Profile visibility or edit the SMARTsummary yourself. Owner-authored text is not overwritten. Profile changes that conflict with your summary ask for a review. Report an incorrect card from the summary overlay.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["correct smart summary","wrong smartview","gemini overwrite","review smart summary","smartsummary","Review and correct a SMARTsummary","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartcard","title":"People SMARTcards","body":"When more than one public FLOQR profile matches, BOT DEE shows compact People SMARTcards in the chat: full-width photo first, then name and handle, then a compact SMARTsummary with no padded box. Tap a card to open that person’s full SMARTview — same stacked layout. Cards use the same public profile and SMARTsummary as SMARTview — not a second stored summary. Opening a card does not call Gemini.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["smartcard","smart card","people smartcard","who is","who am i","compact people card","select person smartview","People SMARTcards","Open BOT DEE","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartcard-search","title":"Ask BOT DEE who someone is","body":"Ask “Who am I?” to open your own SMARTview. Ask “Who is …”, “What do you know of …”, or “What about …” plus a first name, last name, display name, Mingl or FloqR handle, or a social handle (Instagram, TikTok, X). Matches use those identity fields only — not bios, likes, drinks, or genres. One match opens a People SMARTview card in the chat — not a markdown list or photo dump. Several matches show compact SMARTcards to pick from. Private, blocked, or unpublished profiles are not listed — BOT DEE will not confirm whether that account exists.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["who am i","who is","what do you know of","what about","tell me about","display name","find person on floqr","do you know this person","people search bot dee","lookup public profile","identity only","not bio","Ask BOT DEE who someone is","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-smartcard-sync","title":"SMARTsummary stays in sync","body":"Edit your SMARTsummary in your default profile language. Save is immediate. Cards and SMARTview already showing you update from the same record. Translations to other FLOQR languages run in the background and never overwrite a newer edit. If you hide your public profile, block someone, or delete the account, those cards disappear. Gemini does not overwrite text you wrote.","steps":[],"links":[{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["smartsummary sync","card update live","edit summary translations","hide profile smartcard","gemini overwrite summary","SMARTsummary stays in sync","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-botdee-smartview-troubleshoot","title":"SMARTview troubleshooting","body":"Empty card: the patron hid those fields or you are blocked. Save failed: sign in and retry — translations queue on the server, not this browser. Pending or failed translation shows the source language with a label. Edit is owner-only. Master Admin SMARTviews is still the mock catalog; live Places and Yelp stay off until counsel. Theme follows Site Chrome — there is no second SMARTview theme.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"SMARTviews (Master Admin)","href":"./master-admin.html#featuresBotDee-smartviews"}],"searchPhrases":["smartview not showing","smartview save failed","empty smartview","places yelp smartview","SMARTview troubleshooting","Open BOT DEE","SMARTviews (Master Admin)"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-research-library","title":"BOT DEE Research Library","body":"Save places and cards you asked BOT DEE about. A Google Place ID is not a copy of Google’s photos or reviews. You can refresh or delete a saved item. Licensed caches stay off until the provider is approved.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["research library","saved places","google place id","refresh research","BOT DEE Research Library","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-explain","title":"Explain My Recommendation","body":"Each recommendation can show evidence, the date it was checked, whether personalization was on, and if a placement is sponsored. You can ask BOT DEE not to personalize this search.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["explain my recommendation","why this result","sponsored","don't personalize","nonpersonalized","Explain My Recommendation","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"master-admin.html#featuresBotDee","kind":"help"},{"id":"help-botdee-privacy-assistant","title":"BOT DEE Privacy Assistant","body":"Change what other FLOQR users see in My Profile visibility — BOT DEE does not add a second public switch. If web research attached the wrong person, you can dispute it here without changing your profile. BOT DEE cannot promise that a third-party site will delete the original page.","steps":[],"links":[{"label":"Profile visibility","href":"./patron-portal.html?tab=profile"},{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["privacy assistant","profile visibility","wrong person","dispute match","not a second public toggle","BOT DEE Privacy Assistant","Profile visibility","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html","kind":"help"},{"id":"help-botdee-place-search","title":"Ask BOT DEE for FLOQR venues","body":"Ask in plain words — sushi restaurants in Washington DC, clubs in DC, or a named club. BOT DEE searches onboarded FLOQR venues only, not Google or Yelp. Matching clubs open a compact Place SMARTview (name, short blurb, ratings, public-page link) with a SMARTbackground — not a photo well. Naming a city with VIP reserV (reservations in Miami) still attaches Place SMARTview next to the VIP card. Patron photos and ShoutOut pitches stay off unless you asked for those. If nothing is onboarded yet, BOT DEE says so.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"}],"searchPhrases":["sushi restaurants","sushi in washington dc","restaurants in dc","clubs in washington dc","dining search","find a club","japanese restaurant","bot dee venues","bot dee restaurants","reservations in miami","place smartview miami","vip reserv miami","Ask BOT DEE for FLOQR venues","Open BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-page","title":"BOT DEE","body":"Chat with BOT DEE on the BOT DEE page in plain words: events and clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, your profile, staff schedules, or Club Admin tools. Press Enter to send a message; Shift+Enter starts a new line. Type help (like version) and BOT DEE explains itself and asks what you want help with. BOT DEE chats like a person (try How are you?) and only looks things up when you ask how to do something in FLOQR. If you are signed in, BOT DEE keeps this chat when you refresh or open another phone. After the pause timer, BOT DEE can recap where you left off — pause does not delete the chat, memories, or workflows. BOT DEE asks how it can help at the start of a conversation (and again if you come back after a pause). Mid-chat replies stay short. Answers use classification for your account. Signed-in BOT DEE uses the same public volunteered profile datapoints you can see (music, food, travel, hobbies, and the rest of Privacy datapoint sharing) — never email, phone, card numbers, or GPS. The + at the top right opens saved chats. Collapse and New chat only hide the canvas — BOT DEE still keeps that history and uses it on Send. Export or delete stays in My BOT DEE. Saved chats, memories, and approved facts live in My Profile → Feature & Orders → My BOT DEE. Tap a photo in the chat to pop it out into a separate window. Close with X or Close to see the chat again.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["bot dee","botdee","ask bot dee","bot dee page","chat with bot dee","help","bot dee help","what can you do","resume chat","refresh bot dee","other phone","general search","search everything","what can i search","enter to send","shift enter","how are you bot dee","floqai","floqai page","ask floqai","public profile","enlarge photo","tap photo","pop out photo","photo window","my bot dee","saved chats","plus button","new chat","collapse chats","rename chat","rename chats","privacy","session pause","keyboard","BOT DEE","Open BOT DEE","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"botdee.html#botDeeChatPage","kind":"help"},{"id":"help-botdee-privacy-session","title":"BOT DEE privacy and session","body":"The five-minute pause ends this live BOT DEE session. It does not delete this signed-in chat, memories, or workflows. Opt-in copies in My Profile → Feature & Orders → My BOT DEE stay too. Guests stay ephemeral. Mingl chats are never copied here. Press Enter to send a message; Shift+Enter starts a new line. Type help or privacy on the BOT DEE page. The + control lists saved chats without deleting them. Collapse is visual only — Send still uses stored history. Name, tone, and recap live in My Profile → Feature & Orders → My BOT DEE — not as a button on the chat.","steps":[],"links":[{"label":"Open BOT DEE","href":"./botdee.html"},{"label":"My BOT DEE","href":"./patron-portal.html?tab=feature-orders&sub=botdee"}],"searchPhrases":["privacy","session","pause","five minute pause","5 minute pause","keyboard","enter sends","shift enter","bot dee settings","call me","demeanor","socially cool","remind me where we left off","BOT DEE privacy and session","Open BOT DEE","My BOT DEE"],"audiences":["patron","serviceMember","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#foBotDeePane","kind":"help"},{"id":"help-vip-book-table","title":"Book a VIP table (VIP reserV)","body":"Search a VIP reserV club, pick a night on the floor map, hold a table, accept Terms, and pay the deposit when the club requires one. Open VIP reserV from Search (when granted) or the profile menu. Choose a venue first, then the floor map and night, tap a green table (details open in a pop-out), hold it for 30 minutes, continue to the Terms page, and pay the deposit with FloqR Stripe (or confirm without checkout if the venue does not require a deposit). A table only shows booked/unavailable (isReserved=1) after that payment or no-deposit confirm — a hold alone stays amber. Bars and the DJ booth are never bookable. At Aurelia, use Explore 3D walk-through for the interactive room (2D map stays the booking UI). Brand name VIP reserV is never translated.","steps":[],"links":[{"label":"Open VIP reserV","href":"./vip.html?from=botdee"},{"label":"Aurelia 3D walk-through","href":"./reports/vip-aurelia-demo/?from=botdee"}],"searchPhrases":["vip reserv","vipreserv","vip table","book a table","book vip","reserve a table","table reservation","vip booth","floor map","decades table","lima twist table","table deposit","hold a table","aurelia vip","aurelia 3d","explore 3d","3d walk-through","search a vip reserv club","isReserved","headless vip","vip from chat","mezzanine","hold a vip table at aurelia","Book a VIP table (VIP reserV)","Open VIP reserV","Aurelia 3D walk-through"],"audiences":["patron","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-choose-venue","title":"Choose a VIP reserV venue","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker.","steps":[],"links":[{"label":"Open VIP reserV","href":"./vip.html?from=botdee"}],"searchPhrases":["choose a venue","vip venue","subscribed clubs","vip reserv clubs","only clubs subscribed","select venue vip","vip deposit","vip dress code","nearest vip","Choose a VIP reserV venue","Open VIP reserV"],"audiences":["patron","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-floor-map","title":"VIP reserV floor map","body":"Green = available, amber = held (30 min), red = booked (only after deposit paid when required — or after confirm when the club does not require a deposit), grey = not bookable / blocked, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club, and Aurelia each have a published 2D plan; Aurelia also offers Explore 3D walk-through.","steps":[],"links":[{"label":"Open VIP reserV","href":"./vip.html?from=botdee"},{"label":"Aurelia 3D walk-through","href":"./reports/vip-aurelia-demo/?from=botdee"}],"searchPhrases":["vip floor map","floor plan","table map","dj booth blue","available green","aurelia floor map","VIP reserV floor map","Open VIP reserV","Aurelia 3D walk-through"],"audiences":["patron","venueAdmin","masterAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-terms-consent","title":"VIP reserV Terms & consent","body":"After you hold a table, VIP reserV opens a separate Terms page with the full venue Terms text. Accept once (covers refund, no-show, age 21+, and minimum spend). Optional marketing is separate. Consent is stored with the Terms version hash before FloqR Stripe Checkout — then receipt and door pass, like a paid ShoutOut.","steps":[],"links":[{"label":"Open VIP reserV","href":"./vip.html?from=botdee"},{"label":"VIP Terms page","href":"./vip-terms.html?from=botdee"}],"searchPhrases":["vip terms","table terms","vip consent","accept terms vip","minimum spend disclosure","vip terms of use","VIP reserV Terms & consent","Open VIP reserV","VIP Terms page"],"audiences":["patron","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-door-pass","title":"VIP reserV door pass","body":"After your deposit confirms, open My Profile → Guest List & reserV (or ?tab=passes) and tap Show pass for a one-time QR. Open full pass opens pass.html. Bring ID 21+. Door staff use VIP reserV Door to check you in.","steps":[],"links":[{"label":"My door passes","href":"./patron-portal.html?from=botdee&tab=passes"},{"label":"Open VIP reserV","href":"./vip.html?from=botdee"}],"searchPhrases":["vip pass","door pass","qr table","vip qr","show pass","table check in","passes","VIP reserV door pass","My door passes","Open VIP reserV"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-door-ops","title":"VIP reserV door check-in","body":"VIP Managers open VIP reserV Door for tonight’s list. Scan or paste a pass token, confirm ID 21+, then check in. Mark no-show only after grace. Opening a notify link never changes reservation status. Club Admin → Feature Mgmt → Passes issues guest/promoter QR passes, lists tonight’s passes, reveals QR, and check-in (ID 21+). VIP table Show pass on My Profile still uses the same pass.html viewer.","steps":[],"links":[{"label":"VIP reserV Door","href":"./vip-door.html?from=botdee"}],"searchPhrases":["vip door","door check in","vip manager","mark no show","table door","club admin passes","issue pass","qr door pass","passes tab","VIP reserV door check-in","VIP reserV Door"],"audiences":["serviceMember","venueAdmin","masterAdmin"],"helpPartition":"serviceMemberHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-club-admin","title":"Club Admin VIP reserV management","body":"Club Admin → Feature Mgmt → VIP reserV manages tonight’s reservations: check in, no-show, cancel, block/unblock sections, and walk-in book. Feature Mgmt also holds ShoutOut (Queue / Display / Template Mgmt) and FloqCAST. Firestore isBooked controls map booked status — set to 1 only after deposit pay (FloqMedia/Club Stripe), Club POS confirm, or admin-recorded payment. Cancel always clears isBooked to 0. For FloqMedia / Club Stripe, Cancel can also refund the deposit per the club’s refund policy (full by default, or hours-based partial/none). Club POS voids stay on Toast/SpotOn. Holds never set isBooked. Door staff can also use VIP reserV Door.","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee&tab=panelVipReserv"},{"label":"VIP reserV Door","href":"./vip-door.html?from=botdee"}],"searchPhrases":["vip club admin","manage vip reservations","vip deposit required","paid before booked","block vip table","walk-in vip","vip admin book","require deposit before booked","cancel vip refund","vip refund policy","clear isBooked","negate vip payment","Club Admin VIP reserV management","Club Admin","VIP reserV Door"],"audiences":["venueAdmin","masterAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-deposit-settings","title":"VIP reserV deposit before booked","body":"Clubs set Require deposit before table is marked booked in Club Admin → VIP reserV. When required, holding a table only shows amber; the floor map turns red (booked/unavailable) after FloqR Stripe deposit payment — or after Club Admin records payment on a walk-in. If deposit is not required, confirming Terms marks the table booked without checkout.","steps":[],"links":[{"label":"Club Admin VIP reserV","href":"./admin.html?from=botdee&tab=panelVipReserv"},{"label":"Book VIP reserV","href":"./vip.html?from=botdee"}],"searchPhrases":["vip deposit settings","deposit before booked","table booked after pay","require deposit vip","isReserved after payment","VIP reserV deposit before booked","Club Admin VIP reserV","Book VIP reserV"],"audiences":["venueAdmin","patron","masterAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-payment-collector","title":"VIP reserV payment collector & Club POS","body":"Preferred for live clubs with Toast/SpotOn: Club POS — FLOQR books, holds, and maps the table; the POS owns deposit, open tab, and spend. Alternatives: Club Stripe (venue Connect from Club Admin → Stripe onboarding — FLOQR stores the account in stripeConnectAccounts, not a typed acct id), FloqMedia Stripe (FloqR platform), or VIP reserV engine + CSV. Aurelia (Demo Club) defaults to FloqMedia Stripe — ask BOT DEE how to set FloqMedia Stripe for Aurelia for the Master Admin and Club Admin steps.","steps":[],"links":[{"label":"Club Admin VIP reserV","href":"./admin.html?from=botdee&location=temp-democlub-1&tab=panelVipReserv"},{"label":"Master Admin VIP Payments","href":"./master-admin.html?from=botdee&tab=featuresVipPayments"},{"label":"Set FloqMedia Stripe for Aurelia","href":"./admin.html?from=botdee&location=temp-democlub-1&tab=panelVipReserv"}],"searchPhrases":["club pos vip","toast vip","spoton vip","vip payment collector","floqr stripe vip","club stripe vip","vip csv export","vip sandbox","pos owns payment","VIP reserV payment collector & Club POS","Club Admin VIP reserV","Master Admin VIP Payments","Set FloqMedia Stripe for Aurelia"],"audiences":["venueAdmin","masterAdmin","patron"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-table-isbooked","title":"VIP table isBooked status in Firestore","body":"Every VIP-onboarded club keeps one Firestore doc per table number for each night: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Doc id is the printed table number (e.g. T1, B3). getVipAvailability treats isBooked as the booking-status control for the floor map (booked only when isBooked is \"1\"). After payment completes (FloqMedia Stripe / Club Stripe deposit, Club POS confirm, or admin-recorded payment), isBooked is set to \"1\" and isBookedYes to \"yes\". Free tables stay \"0\" / \"no\". Holds do not set isBooked. Cancel always clears isBooked to \"0\" and, for FloqMedia/Club Stripe, can refund the deposit per Club Admin refund policy. Club Admin can call ensureVipTables to seed upcoming nights; getVipAvailability also ensures docs.","steps":[],"links":[{"label":"Aurelia Club Admin VIP reserV","href":"./admin.html?from=botdee&location=temp-democlub-1&tab=panelVipReserv"},{"label":"Book Aurelia VIP","href":"./vip.html?from=botdee&location=temp-democlub-1"}],"searchPhrases":["isBooked","table is booked firestore","vip table status","table number key","vipNights tables","isBooked yes","firestore vip tables","cancel clears isBooked","vip stripe refund","refund policy vip","VIP table isBooked status in Firestore","Aurelia Club Admin VIP reserV","Book Aurelia VIP"],"audiences":["venueAdmin","masterAdmin","patron"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-vip-floqr-stripe-aurelia","title":"Set FloqMedia Stripe for Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) uses FloqMedia Stripe (FloqR Checkout) as the default VIP deposit collector — patrons pay on FloqR’s platform Stripe, then the table marks booked. Master Admin steps: 1) Open Master Admin → Features Mgmt → VIP reserV Payments. 2) Confirm VIP Reservations is enabled for the network (Features & Services / Release Control if needed). 3) Seed / refresh POS providers only if you also enable Club POS later — not required for FloqMedia Stripe. 4) Leave Aurelia on FloqMedia Stripe unless a live club needs Club POS or Club Stripe. 5) After deposits, open VIP reserV Payments → Network VIP billing to review FloqR settlements / invoices. Club Admin steps (Aurelia): 1) Sign in as temp_clubadmin_1@floqr-demo.com (Email OTP on home) or your Club Admin account assigned to Aurelia. 2) Open Club Admin → VIP reserV (location=temp-democlub-1). 3) Under Payment collector, choose FloqMedia Stripe (FloqR). 4) Keep Require deposit before table is marked booked checked for demos. 5) Tap Save payment collector — status should confirm FloqMedia Stripe. 6) Smoke test: vip.html?location=temp-democlub-1 → hold a table → Terms → Pay deposit (Stripe test card 4242…). 7) Door / billing: Open Door for check-in; Refresh billing for statements. Do not choose Club POS for Aurelia demos unless you intentionally connect Toast/SpotOn sandbox. FloqMedia, Stripe, ShoutOut, and VIP reserV stay untranslated brand names.","steps":[],"links":[{"label":"Aurelia Club Admin VIP reserV","href":"./admin.html?from=botdee&location=temp-democlub-1&tab=panelVipReserv"},{"label":"Master Admin VIP Payments","href":"./master-admin.html?from=botdee&tab=featuresVipPayments"},{"label":"Book Aurelia VIP","href":"./vip.html?from=botdee&location=temp-democlub-1"}],"searchPhrases":["aurelia stripe","floqmedia stripe","floqr stripe aurelia","set stripe for aurelia","demo club vip payment","temp-democlub-1 stripe","how to configure vip stripe","master admin vip stripe","club admin vip stripe","default vip payment aurelia","Set FloqMedia Stripe for Aurelia (Demo Club)","Aurelia Club Admin VIP reserV","Master Admin VIP Payments","Book Aurelia VIP"],"audiences":["venueAdmin","masterAdmin","patron"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-become-club-admin","title":"Become a Club Admin","body":"Request Club Admin access, then get venue approval.","steps":[],"links":[{"label":"Request Club Admin access","href":"./role-request.html?from=botdee&type=clubAdmin"}],"searchPhrases":["become a club admin","club admin","be an admin","I want to be a club admin","Become a Club Admin","Request Club Admin access"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-role-profiles","title":"Role profiles overview","body":"See how Club Admin, DJ, Promoter, and hospitality roles work.","steps":[],"links":[{"label":"Role profiles overview","href":"./role-profiles.html?from=botdee"}],"searchPhrases":["role profiles","role profiles overview","how roles work","service roles","Role profiles overview"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"","kind":"help"},{"id":"help-staff-scheduling","title":"Calendar & Scheduler","body":"Club Admin Calendar shows Draft (purple), Pending (amber), Confirmed (green), and Open/unfilled cards — each with a written status, not color alone. Scheduler is the people × days draft/publish grid. Website ingest / publicVenueCalendar returns Confirmed assignments only. A green Paid this month pill is shown to Club Admins when staffSchedulingPaid=1.","steps":[],"links":[{"label":"Scheduling portal","href":"./scheduling.html?from=botdee","search":"scheduling portal","blurb":"DJ / promoter / club shift calendar"},{"label":"Club Admin Calendar & Scheduler","href":"./admin.html?from=botdee&tab=scheduling","search":"calendar scheduler","blurb":"Draft / Pending / Confirmed / Open cards plus Scheduler drafts"}],"searchPhrases":["staff scheduling","scheduling subscription","subscribe $20","resubscribe","staffSchedulingPaid","paid this month","not paid this month","staff calendar","schedule shifts","scheduling portal","work schedule","draft shift","purple card","pending shift","confirmed shift","open shift","unfilled","assignment card","website ingest","confirmed only","public calendar","Calendar & Scheduler","Scheduling portal","Club Admin Calendar & Scheduler"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelScheduling","kind":"help"},{"id":"help-club-notification-subscriptions","title":"Club SMS and WhatsApp notification subscriptions","body":"Club Admin → Notifications: Send test alert uses the boxes currently checked. In-app (and Push) writes a System Message in FloqR Inbox. Email uses club admin addresses. SMS and WhatsApp still need a paid subscription plus an E.164 alert phone. Green pill = Firebase subscription 1 (prepaid $10 pack); red = 0. If Send test alert returns Authentication Error - invalid username, Firebase secret TWILIO_ACCOUNT_SID must be the Account SID starting with AC (34 characters) from console.twilio.com — not the Auth Token and not an API Key (SK).","steps":[],"links":[{"label":"Club Admin Notifications","href":"./admin.html?from=botdee&tab=notifications"}],"searchPhrases":["sms notification subscription","whatsapp notification subscription","save notification choices","sms already paid","notification stripe again","sms credits","whatsapp credits","club notifications","alert phone","sms subscribed","green sms","red whatsapp","invalid username","twilio account sid","send test alert","authentication error","in-app notification","system message","floqr inbox test","Club SMS and WhatsApp notification subscriptions","Club Admin Notifications"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelNotifications","kind":"help"},{"id":"help-club-sms-notification","title":"SMS notification subscription","body":"The SMS pill is green when Firebase smsSubscribed is 1 (prepaid $10 pack, 466 credits, not monthly or yearly). Red/flashing means 0 — open ? and tap Subscribe $10. Credits remaining and last paid date are in this help. Uncheck SMS and Save to pause alerts without losing the paid pack.","steps":[],"links":[{"label":"Club Admin Notifications","href":"./admin.html?from=botdee&tab=notifications"}],"searchPhrases":["sms","sms credits","sms subscribe","green sms","466 credits","SMS notification subscription","Club Admin Notifications"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelNotifications","kind":"help"},{"id":"help-club-whatsapp-notification","title":"WhatsApp notification subscription","body":"The WhatsApp pill is green when Firebase whatsappSubscribed is 1 (prepaid $10 pack, 233 credits, not monthly or yearly). Red/flashing means 0 — open ? and tap Subscribe $10. Credits remaining and last paid date are in this help. Uncheck WhatsApp and Save to pause alerts without losing the paid pack.","steps":[],"links":[{"label":"Club Admin Notifications","href":"./admin.html?from=botdee&tab=notifications"}],"searchPhrases":["whatsapp","whatsapp credits","whatsapp subscribe","red whatsapp","233 credits","WhatsApp notification subscription","Club Admin Notifications"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelNotifications","kind":"help"},{"id":"help-schedule-message-templates","title":"Schedule message templates","body":"Club Admin → Notifications → Message templates. These are System Messages (Inbox / Email / SMS / WhatsApp), not ShoutOuts. Edit title and body for New shift needs confirmation, Schedule update, Shift confirmed, and Shift declined. Placeholders: {club} {role} {when} {link} {worker}. Worker inbox uses Review & confirm shift — never Open Related ShoutOut.","steps":[],"links":[{"label":"Message templates","href":"./admin.html?from=botdee&tab=notifications&notify=templates"},{"label":"Club Admin Notifications","href":"./admin.html?from=botdee&tab=notifications"}],"searchPhrases":["message template","system message","schedule invite","shift confirmation message","open related shoutout","new shift needs your confirmation","edit system message","notification templates","confirm or decline this shift","Schedule message templates","Message templates","Club Admin Notifications"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#notifyTemplatesPane","kind":"help"},{"id":"help-schedule-confirm","title":"Confirm assigned shifts","body":"Inbox / Email / SMS links open Work Calendar. Look at each pending assignment, tick it (or Select all), then Approve selected. Opening the link does not confirm. Only the assigned service member can approve — Club Admin cannot confirm on their behalf.","steps":[],"links":[{"label":"Work Calendar","href":"./patron-portal.html?from=botdee&tab=work-calendar"},{"label":"Message templates","href":"./admin.html?from=botdee&tab=notifications&notify=templates"}],"searchPhrases":["confirm shift","approve shift","select all shifts","pending assignment","schedule notify","review and confirm shift","my assigned shifts","decline shift","Confirm assigned shifts","Work Calendar","Message templates"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#portalWorkCalendar","kind":"help"},{"id":"help-template-catalog-report","title":"Template catalog report","body":"Lists every ShoutOut template type and which LED sizes it supports (Is96x48, Is64x48, Is64x32). A venue only offers a template when at least one of those flags is 1 and the matching VenueSupports* flag is 1. Birthday / split-media templates are 1 on 96×48, 64×48, and 64×32. 96×48 is 3-line side-by-side; 64×48 and 64×32 loop the photo then the 3-line shoutout with a FLOQR + handle card.","steps":[],"links":[{"label":"Club Admin Reports","href":"./admin.html?from=botdee&tab=reports"},{"label":"Master Admin Template Catalog","href":"./master-admin.html?from=botdee&tab=templateCatalogReport"}],"searchPhrases":["template catalog","template types","Is96x48","display sizes","which templates","split media","birthday 64x32","template report","Template catalog report","Club Admin Reports","Master Admin Template Catalog"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelReports","kind":"help"},{"id":"help-club-display-screens","title":"FLOQR display screens","body":"Firebase clubLocations stores VenueSupports96x48, VenueSupports64x48, and VenueSupports64x32 as 0 or 1. templates stores Is96x48, Is64x48, and Is64x32 the same way. A venue only lists a template when at least one pair is 1. Xibo URLs stay display.html?location=id and display2.html?location=id — screen size is not in the URL. Birthday is offered on all three sizes (3-line side-by-side on 96×48; photo/shoutout loop on 64×48 and 64×32). Primary is display.html. Secondary is display2.html.","steps":[],"links":[{"label":"Club Public Profile display screens","href":"./admin.html?from=botdee&tab=public-profile"},{"label":"Display 1 (Xibo)","href":"./display.html"}],"searchPhrases":["display screens","64x48","96x48","64x32","primary shoutout led","birthday template screen","VenueSupports96x48","Is96x48","xibo display url","screen datapoint","led size","FLOQR display screens","Club Public Profile display screens","Display 1 (Xibo)"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelPublicProfile","kind":"help"},{"id":"help-staff-week-calendar","title":"Scheduler","body":"Club Admin Scheduler is a people × days week grid. Save shift closes the editor with Schedule card successfully saved. Create drafts, Publish schedule so workers confirm pending until confirmed, Select shifts to multi-delete, and Website ingest to put published shifts on the club site. Default shift window = club open − 2 hours through close + 1 hour.","steps":[],"links":[{"label":"Club Admin Scheduler","href":"./admin.html?from=botdee&tab=scheduling"}],"searchPhrases":["scheduler","schedule grid","week calendar","round robin","publish schedule","people days","shift chips","worker photo","staff schedule","7shifts","assign shift","open minus two hours","copy previous week","public holiday","pending shift","confirmed shift","delete shift","select shifts","multi delete","user guide","create a schedule","schedule card successfully saved","save shift","Scheduler","Club Admin Scheduler"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#schedGridHeading","kind":"help"},{"id":"help-staff-schedule-user-guide","title":"Staff Scheduling User Guide","body":"Open the ? beside Scheduler on Club Admin Scheduling. Create draft shifts, Publish schedule so workers confirm pending→confirmed, then Select shifts to delete several at once. Example: all Wednesday drafts plus a Thursday confirmed chip.","steps":["Open Club Admin → Scheduling (unlocked when staffSchedulingPaid=1 / paid this month).","Tap + on a person/day cell, set role and times, leave Save as draft checked, then Save shift. Save closes the editor and shows Schedule card successfully saved. Optional: Round Robin fill or Copy previous week into drafts.","Review dashed draft chips, then tap Publish schedule. Workers get Inbox / Email / SMS / WhatsApp with a confirm link.","Published chips stay pending until the worker confirms. Confirmed has a green outline.","To delete several: tap Select shifts. Filter Drafts, tap Wednesday’s column header, switch to All or Confirmed, tap a Thursday confirmed chip, then Delete selected."],"links":[{"label":"Scheduler help","href":"./admin.html?from=botdee&tab=scheduling"},{"label":"Club Admin Scheduling","href":"./admin.html?from=botdee&tab=scheduling"}],"searchPhrases":["user guide","staff scheduling user guide","create a schedule","create schedule","publish schedule","how to schedule staff","how to publish a schedule","make a schedule","staff schedule steps","scheduling help","scheduler","Staff Scheduling User Guide","Scheduler help","Club Admin Scheduling"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#schedGridHeading","kind":"help"},{"id":"help-create-publish-schedule","title":"Create and publish a staff schedule","body":"Add draft shifts on the people × days grid, review chips, then Publish schedule. Workers must confirm before a shift becomes confirmed. BOT DEE: create a schedule, publish schedule, how to schedule staff.","steps":["Open Club Admin → Scheduling after the venue is paid this month.","Manual: tap + on a cell, set worker/role/times, Save as draft. Repeat, or use Round Robin / Copy previous week.","Tap Publish schedule. Shifts become pending and workers are notified to confirm.","The worker uses the Inbox / Email / SMS / WhatsApp confirm link. The chip then shows confirmed."],"links":[{"label":"Create and publish (Scheduler)","href":"./admin.html?from=botdee&tab=scheduling"}],"searchPhrases":["create a schedule","create schedule","publish schedule","how to publish a schedule","how to schedule staff","make a work schedule","assign shifts","save as draft","pending until confirmed","worker confirm shift","Create and publish a staff schedule","Create and publish (Scheduler)"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#schedGridHeading","kind":"help"},{"id":"help-multi-delete-shifts","title":"Delete multiple scheduled or draft shifts","body":"Select shifts, mix day headers and chips, then Delete selected. Example: all Wednesday drafts plus one Thursday confirmed shift.","steps":["On the week grid, tap Select shifts.","Choose Drafts, then tap the Wednesday column header to select every Wednesday draft.","Switch the filter to All or Confirmed and tap the Thursday confirmed chip (or any other chips you want gone).","Tap Delete selected and confirm. Drafts vanish quietly; pending and confirmed workers get a cancelled notice if they were already notified."],"links":[{"label":"Multi-delete (Scheduler)","href":"./admin.html?from=botdee&tab=scheduling"}],"searchPhrases":["multi delete","delete multiple shifts","delete wednesday drafts","delete confirmed shift","select shifts","bulk delete shifts","delete drafts","delete thursday shift","remove several shifts","multi-delete schedule","Delete multiple scheduled or draft shifts","Multi-delete (Scheduler)"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#schedGridHeading","kind":"help"},{"id":"help-staff-worksheet","title":"Work Sheet - Weekly Staff Calendar","body":"Elected service members open Work Calendar in Settings. Inbox / Email / SMS confirmation links land here. Review pending assignments, tick each shift (or Select all), then Approve selected — opening the message does not confirm. The week grid shows published colleague shifts. Drafts stay in Club Admin.","steps":[],"links":[{"label":"Work Calendar tab","href":"./patron-portal.html?from=botdee&tab=work-calendar"},{"label":"Work Sheet","href":"./staff-worksheet.html?from=botdee"}],"searchPhrases":["staff calendar","work sheet","worksheet","weekly staff calendar","colleague schedule","who is working","my shifts this week","elected staff schedule","confirm shift","approve selected","my assigned shifts","Work Sheet - Weekly Staff Calendar","Work Calendar tab","Work Sheet"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"staff-worksheet.html","kind":"help"},{"id":"help-service-members","title":"Services & Service Members","body":"Everyone starts as a FLOQR patron. On My Profile & Settings, tap Elect to become a service member to unlock this tab. Choose your service role (Waitress, DJ, Promoter, and more), search and select one or more clubs, then submit at the bottom of this page. Profile template guide — patron social profiles stay on Public Media. Service roles use dedicated profile templates on My Profile: • Patron — music, travel, hobbies, nightlife style, looking to meet; 8 photos and 2 short videos. • Promoter — active cities, events, guest lists, VIP tables, venue relationships, promo media. • DJ — genres, residencies, booking availability, mix links, crowd style, performance media. • Waitress / Waitress / Bottle Girl — venue experience, service style, languages, nights, bottle service, professional media. • Bus Boys or Security — floor support, door, security stations, venue experience, professional media. • Venue Manager — venues managed, ops specialties, staff coordination, professional media. Club Admin approval — each club's Club Admin approves your association after you submit. Club Admins: open Club Admin → Employee/Workers → Pending Worker Requests (Approve or Reject), or on this tab open Review & elect.","steps":[],"links":[{"label":"Services & Service Members","href":"./patron-portal.html?from=botdee&tab=service-members"},{"label":"My Profile & Settings","href":"./patron-portal.html?from=botdee&tab=profile"},{"label":"Club Admin Employee/Workers","href":"./admin.html?from=botdee&tab=employees"}],"searchPhrases":["service members","services and service members","request club admin","request access","elect service member","worker association","request dj access","request promoter","bus boys or security","venue manager","approve worker request","become a waitress","bottle girl","affiliate club","profile template guide","approve waitress","pending worker requests","Services & Service Members","My Profile & Settings","Club Admin Employee/Workers"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#portalServiceMembers","kind":"help"},{"id":"help-venue-website-ingest","title":"Club website ingest (API, RSS, iframe)","body":"Club Admin → Scheduling → Website ingest. Generate a secret (shown once; only a hash is stored). Pull published staff shifts onto the official club website with JSON (?format=json&dataset=schedule|hours|profile|all), RSS, or an iframe snippet. Drafts, worker email, and phone are never included. Rotate the secret if it leaks.","steps":[],"links":[{"label":"Website ingest","href":"./admin.html?from=botdee&tab=scheduling#schedWebsiteIngest"}],"searchPhrases":["website ingest","club website schedule","rss feed","iframe schedule","schedule api","ingest secret","embed staff schedule","official website","json schedule feed","pull schedule onto website","Club website ingest (API, RSS, iframe)","Website ingest"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#schedWebsiteIngest","kind":"help"},{"id":"help-venue-hours-calendar","title":"Venue opening hours","body":"On Club Public Profile, set the default weekly open/closed hours, then add period overrides for special weeks without losing the default. The public club page shows a Sun–Sat week grid with the date range (e.g. Sun 9 – Sat 15, Aug 2026) and calendar coloring. Upcoming public holidays list open/close hours and call out when they differ from the usual weekday. Staff Scheduling uses open − 2h through close + 1h. Guest List can suggest open nights.","steps":[],"links":[{"label":"Club Public Profile","href":"./admin.html?from=botdee&tab=publicProfile"}],"searchPhrases":["club hours","opening times","venue schedule","hours exception","period override","public holiday","open closed days","venue calendar","Venue opening hours","Club Public Profile"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#clubVenueHoursCard","kind":"help"},{"id":"help-club-admin-affiliation","title":"Club Admin venue assignment","body":"Club Admins only open the Venue Command Center for a club they are assigned to. Opening admin.html without a venue no longer defaults to Zebbies. Demo accounts temp_clubadmin_N@floqr-demo.com map to temp-democlub-N. Unassigned admins request assignment from Master Admin.","steps":[],"links":[{"label":"Request Club Admin access","href":"./role-request.html?from=botdee&type=clubAdmin"},{"label":"Club Admin portal","href":"./admin.html?from=botdee"}],"searchPhrases":["club admin assignment","affiliated club","request venue assignment","temp_clubadmin","temp-democlub","not an elected club admin","zebbies default","Club Admin venue assignment","Request Club Admin access","Club Admin portal"],"audiences":["venueAdmin","masterAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#adminVenueGate","kind":"help"},{"id":"help-venue-command-center","title":"Venue Command Center","body":"Approve ShoutOuts, review venue performance, and reconcile account activity for this location.","steps":[],"links":[{"label":"Venue Command Center","href":"./admin.html?from=botdee"}],"searchPhrases":["venue command center","club admin","approve shoutouts","venue performance","account activity","reconcile account","floqr club admin","Venue Command Center"],"audiences":["venueAdmin","masterAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html","kind":"help"},{"id":"help-floqr-inbox-rules","title":"FloqR Inbox","body":"FloqR Inbox holds System Messages and internal support messages. The list loads first so your messages appear quickly. Tap the floating New Message button to compose — type a name or @username to find an allowed recipient (Club Admin, CSR, or approved staff). Patron-to-patron chat stays in Mingl after both patrons Mingl back. Opening a schedule invite does not confirm a shift — review and Approve selected on Work Calendar.","steps":[],"links":[{"label":"FloqR Inbox","href":"./patron-portal.html?tab=inbox&from=botdee"}],"searchPhrases":["floqr inbox","inbox","new message","send message","recipient","@username","compose message","inbox empty","floating new message","system message","club admin message","FloqR Inbox"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html#portalMessages","kind":"help"},{"id":"help-club-messaging-credit","title":"SMS & WhatsApp Credit","body":"Each $10 pack funds $7.00 of Twilio delivery capacity; FloqR keeps $3.00 as platform profit on the pack. SMS pack → 466 messages (≈ $0.015 all-in US SMS). WhatsApp pack → 233 messages (≈ $0.030 Twilio + Meta marketing). When balance reaches 0, buy another $10 messaging bundle before sending more campaign messages. Ops SMS unlock ($10) also grants one SMS pack. WhatsApp service ($10) grants one WhatsApp pack. Pack math: $10 → 466 SMS or 233 WhatsApp ($7.00 Twilio / $3.00 FloqR).","steps":[],"links":[{"label":"Messaging Credit","href":"./admin.html?from=botdee#panelMessagingCredit"}],"searchPhrases":["messaging credit","sms pack","whatsapp pack","buy sms bundle","twilio credits","466 sms","SMS & WhatsApp Credit","Messaging Credit"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelMessagingCredit","kind":"help"},{"id":"help-club-marketing-campaigns","title":"Marketing campaigns","body":"Pick an industry template, load background and extra images, edit copy, then save or send. Sending debits SMS or WhatsApp credits from Messaging Credit.","steps":[],"links":[{"label":"Marketing Campaigns","href":"./admin.html?from=botdee#panelMarketingCampaigns"}],"searchPhrases":["marketing campaign","sms blast","whatsapp campaign","industry template","send test marketing","Marketing campaigns","Marketing Campaigns"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelMarketingCampaigns","kind":"help"},{"id":"help-club-in-app-marketing","title":"In-app marketing","body":"Post a flyer or a video of 30 seconds or less as your club. Once it is paid and approved by FLOQR it shows on the Search loading splash, Mingl, RydR and other FLOQR screens. Club ad posters lets a team member post ads for the club (Club Ad Poster role). No SMS credits required.","steps":[],"links":[{"label":"In-App Marketing","href":"./admin.html?from=botdee#panelInAppMarketing"}],"searchPhrases":["spot ad","in-app marketing","advertisement pool","mingl ad","rydr ad","interstitial","In-app marketing","In-App Marketing"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html#panelInAppMarketing","kind":"help"},{"id":"help-club-template-repository","title":"Your club's templates","body":"Templates made only for your club are listed first and marked Exclusive. Each card shows Description, How it works (for your primary LED), and Tag chips — Description and How it works are Master Admin–owned (read-only). You edit Tag chips only on club-owned templates via Manage template tags; shared FloqR Tag chips stay read-only. Assigned templates are what patrons can pick; use Assign or Remove to change that. Search finds a template even with a missing accent or a small typo.","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee"}],"searchPhrases":["club templates","exclusive templates","assign template","remove template","tengo muchos dolares","heist templates","template description","template tags club admin","Your club's templates","Club Admin"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html","kind":"help"},{"id":"help-employee-network","title":"Employee / Worker Network","body":"Only people linked to this club are listed: staff elected or approved here, club admins, and staff affiliated with this club. To give someone a role, type their name, username, or email under Elect Patron for Role, tap Select next to the right person, choose the role, then tap Elect Selected Patron Role and confirm. The person needs a FLOQR patron account first. Waiters, waitresses, and bottle girls on the list can be made customer service representatives (CSR).","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee"}],"searchPhrases":["employee network","worker network","elect patron","elect role","give staff a role","add a waitress","add staff","club staff list","designate csr","customer service representative","Employee / Worker Network","Club Admin"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html","kind":"help"},{"id":"help-staff-marketing-consent","title":"Staff marketing consent","body":"When you join a venue or event team, you must tick the marketing consent box. It lets that venue or event organizer, and its admins and managers, use your FLOQR name, role, and published photos and videos on their websites, flyers, and social media (Instagram, Facebook, TikTok, YouTube and similar) without asking you again for each use. They may not publish your phone number or email. You can withdraw at any time in My Profile on the Services & Service Members tab. This stops new marketing; materials already printed or posted do not have to be recalled. Club Admins see each staff member's consent status in Employee / Worker Network and Featured service staff.","steps":[],"links":[{"label":"Services & Service Members","href":"./patron-portal.html?from=botdee&tab=service-members"},{"label":"Club Admin Employee/Workers","href":"./admin.html?from=botdee&tab=employees"}],"searchPhrases":["marketing consent","staff marketing consent","use my photos","club can use my photos","withdraw marketing consent","photo consent staff","instagram consent","flyer photo consent","Staff marketing consent","Services & Service Members","Club Admin Employee/Workers"],"audiences":["patron","serviceMember","venueAdmin"],"helpPartition":"patronHelpverbiage","source":"help-repository-seed","page":"patron-portal.html","kind":"help"},{"id":"help-featured-staff","title":"Featured service staff","body":"Tick the staff you want on your public club page. For each person, tap one of their FLOQR photos or choose Upload from computer. You can change the role shown under their name. Press Save Public Profile to publish your changes. Before publishing photos, get each person's agreement and tick the photo consent box.","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee"}],"searchPhrases":["featured staff","featured service staff","staff on club page","show staff on club page","staff photo","waiters on club page","bottle service on club page","Featured service staff","Club Admin"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html","kind":"help"},{"id":"help-club-website-feed","title":"Club website feed","body":"Show your published FLOQR club page on your own website. Press Generate feed key and links, then paste the iframe code into your website, or give your web admin the JSON or RSS link. The feed shows upcoming events, featured DJs, featured staff, gallery, and contact details, following your Public page controls. Staff photos appear only when photo consent is confirmed. Generating a new key turns off the old links, including the staff schedule links.","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee"}],"searchPhrases":["club website feed","website feed","embed on my website","put events on my website","iframe","rss feed","club api","website widget","staff list on website","Club website feed","Club Admin"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html","kind":"help"},{"id":"help-template-tags","title":"Template tags","body":"Under each template patrons see Description, How it works (for the venue LED size), and Tag chips. Club Admin and Template Administrators/Managers edit Tag chips only on club-owned templates (your tags replace catalog tags). Shared FloqR templates stay read-only — FLOQR / Master Admin owns those tags. Description and How it works are always Master Admin–owned. Add words patrons might type, such as game night or birthday. Template Managers can add tags; Administrators and Club Admins can also remove them. Assign roles under Role Activity & Permission.","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee"}],"searchPhrases":["template tags","add tags","tag templates","administer templates","manage templates","template administrator","template manager","club owned template tags","shared floqr tags","Template tags","Club Admin"],"audiences":["venueAdmin","serviceMember"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"template-tags.html","kind":"help"},{"id":"help-scheduling-schedule-for","title":"Staff Scheduling","body":"Plan shifts and bookings, then notify each person by Inbox, Email, SMS or WhatsApp. Under Schedule for, choose whose calendar you are working on: My DJ schedule is your own calendar, Club lists the clubs you manage, and Promoting company lists the companies you promote for. Each calendar has its own $20/month subscription. Shifts sent to you appear under My assignments, where you confirm or decline them.","steps":[],"links":[{"label":"Open Staff Scheduling","href":"./scheduling.html?from=botdee"}],"searchPhrases":["staff scheduling","schedule for","owner id","whose schedule","scheduling page","create shift","dj schedule","club schedule","promoting company schedule","plan shifts","Staff Scheduling","Open Staff Scheduling"],"audiences":["venueAdmin","serviceMember"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"scheduling.html","kind":"help"},{"id":"help-display-idle-default","title":"Idle board: Use ShoutOut @ venue","body":"When no ShoutOut is playing, Display 1 shows “Use ShoutOut @” followed by your venue name. Each approved ShoutOut plays for 10 minutes, then the board returns to that message on its own. Reset display to default in Club Admin does the same right away.","steps":[],"links":[{"label":"Club Admin","href":"./admin.html?from=botdee"}],"searchPhrases":["use shoutout @","idle board","default display message","board stuck on shoutout","reset display","Idle board: Use ShoutOut @ venue","Club Admin"],"audiences":["venueAdmin"],"helpPartition":"venueAdminHelpverbiage","source":"help-repository-seed","page":"admin.html","kind":"help"}];
  const packs = {"ru":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Компактное приглашение Mingl Room может появиться в Search, когда вы задали расписание room BOT DEE или друг Mingl пригласил вас. Хост видит свою запланированную room на Search без демо-запроса Cancun. Смотреть приглашение открывает Room SMARTview. Join Now ведёт в BOT DEE, не в Mingl chat. Не сейчас скрывает карточку в этой вкладке; Inbox сохраняет Review BOT DEE invite. Демо-запрос Cancun — только Studio. Картинка — иллюстрация, не фото. Rooms Join Now без расписания не появляются в Search."},"help-smartvisuals-room":{"title":"Room SMARTview и SMARTvisuals","body":"Room SMARTview показывает приглашение Mingl: расписание, RSVP или эфир и Join Now. Join Now в Search открывает BOT DEE (не Mingl chat) с room= и t=. SMARTstencils и SMARTbackgrounds следуют разрешённому названию — Cancun Trip даёт travel-иллюстрацию, не настоящее фото Cancun. Личный чат BOT DEE не выбирает картинку. Подписанный Ad снизу — образец из этих тегов. Пусто для личного чата или инъекции; это не живой рекламодатель."},"help-scheduling-schedule-for":{"title":"Расписание персонала","body":"Планируйте смены и букинги и уведомляйте каждого через Inbox, Email, SMS или WhatsApp. В разделе «Расписание для» выберите, с чьим календарём вы работаете: «Моё расписание DJ» — ваш собственный календарь, «Клуб» — клубы, которыми вы управляете, «Промо-компания» — компании, для которых вы промоутер. У каждого календаря своя подписка за 20 $ в месяц. Смены, назначенные вам, появляются в разделе «Мои назначения», где их можно подтвердить или отклонить."},"help-staff-marketing-consent":{"title":"Согласие персонала на маркетинг","body":"Присоединяясь к команде заведения или мероприятия, вы должны отметить согласие на маркетинг. Оно позволяет этому заведению или организатору, а также его администраторам и менеджерам, использовать ваше имя в FLOQR, роль и опубликованные фото и видео на своих сайтах, флаерах и в соцсетях (Instagram, Facebook, TikTok, YouTube и похожих) без повторного запроса для каждого использования. Публиковать ваш телефон или email они не могут. Отозвать согласие можно в любой момент в разделе «Мой профиль», вкладка «Сервисы и участники сервиса». Это прекращает новый маркетинг; уже напечатанные или опубликованные материалы изымать не обязательно. Club Admins видят статус согласия каждого сотрудника в «Сети сотрудников и персонала» и в «Избранном персонале»."},"help-botdee-privacy-session":{"title":"Конфиденциальность и сессия BOT DEE","body":"Пауза в пять минут завершает живую сессию BOT DEE. Она не удаляет этот чат для вошедшего пользователя, воспоминания или рабочие процессы. Копии в «Мой профиль» → «Функции и заказы» → My BOT DEE тоже остаются. Гости остаются эфемерными. Чаты Mingl сюда не копируются. Enter отправляет сообщение; Shift+Enter начинает новую строку. Имя и тон задаются в «Мой профиль» → My BOT DEE, не кнопкой в чате."},"help-botdee-place-search":{"title":"Спросить BOT DEE про площадки FLOQR","body":"Спросите простыми словами — суши-рестораны в Washington DC, клубы в DC или конкретный клуб. BOT DEE ищет только onboarded площадки FLOQR, не Google и не Yelp. Совпадения открывают компактный Place SMARTview (название, краткий текст, рейтинги, ссылка на публичную страницу) с SMARTbackground — не фото-лунку. Название города вместе с VIP reserV (reservations in Miami) всё равно прикрепляет Place SMARTview рядом с картой VIP. Фото посетителей и питчи ShoutOut не показываются, если вы об этом не просили. Если площадки ещё нет — BOT DEE так и скажет."},"help-botdee-page":{"title":"BOT DEE","body":"Общайтесь с BOT DEE на странице BOT DEE простыми словами: события и клубы, ShoutOut, Mingl, RydR, BartR, FloqCAST, ваш профиль, расписания персонала или инструменты Club Admin. Нажмите Enter, чтобы отправить сообщение; Shift+Enter начинает новую строку. BOT DEE общается как человек (попробуйте How are you?) и ищет только когда вы спрашиваете, как сделать что-то в FLOQR. Если вы вошли в аккаунт, BOT DEE сохраняет этот чат при обновлении страницы или на другом телефоне, а после паузы может продолжить сохранённую историю. Пауза не удаляет чат. Ответы учитывают классификацию вашего аккаунта. После входа BOT DEE видит те же публичные добровольные данные профиля, что и вы (музыка, еда, путешествия, хобби и остальные пункты Privacy datapoint sharing) — никогда email, телефон, данные карты или GPS. Нажмите «Настройки» под полем чата для сохранённых чатов и воспоминаний. Нажмите фото в чате, чтобы открыть его в отдельном окне. Закройте крестиком или «Закрыть», чтобы снова увидеть чат. Знак + справа вверху открывает сохранённые чаты и не удаляет их."},"help-botdee-smartview-troubleshoot":{"title":"Устранение неполадок SMARTview","body":"Пустая карточка: поля скрыты или вы в блоке. Ошибка сохранения: войдите — переводы на сервере. Ожидание или сбой: исходный язык с меткой. Правит только владелец. SMARTviews Master Admin — mock; Places и Yelp выключены. Тема следует Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary остаётся синхронным","body":"Правите SMARTsummary на языке профиля. Сохранение сразу. Открытые карточки и SMARTview обновляются из той же записи. Переводы идут в фоне и не затирают более новую правку. Если скрыть профиль, заблокировать человека или удалить аккаунт, карточки исчезают. Gemini не перезаписывает ваш текст."},"help-botdee-smartcard-search":{"title":"Спросить BOT DEE, кто это","body":"«Who am I?» открывает ваш SMARTview. «Who is …», «What do you know of …» или «What about …» плюс имя, фамилия, display name, хендл Mingl или FloqR либо соцсеть (Instagram, TikTok, X). Совпадение только по этим полям личности — не по био, лайкам, напиткам или жанрам. Один результат — карточка People SMARTview в чате, не markdown и не сетка фото. Несколько — компактные SMARTcard. Приватные, заблокированные и неопубликованные не показываются — BOT DEE не подтверждает, что аккаунт существует."},"help-botdee-smartcard":{"title":"SMARTcard людей","body":"Если подходит несколько публичных профилей FLOQR, BOT DEE показывает компактные карточки в чате: сначала фото на всю ширину, затем имя и хендл, затем сжатый SMARTsummary без пустой рамки. Нажмите карточку, чтобы открыть полный SMARTview — та же укладка. Это тот же публичный профиль и SMARTsummary. Открытие не вызывает Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Введите Ver, Vers или Version — регистр не важен. BOT DEE показывает карточку версии. Более длинный вопрос вроде «какая у тебя версия?» тоже показывает эту карточку."},"help-botdee-version-smartview-status":{"title":"Статус Version SMARTview — живая проверка","body":"Состояние службы проверяется на этом запросе Version: Functions и пакет доступны и Gemini настроен → Работает; Functions и пакет есть, Gemini не настроен → Ограничено; Functions нет в этом запросе → Недоступно. Никогда не статическая метка Не проверено. Модель ИИ показывает настроенный id Gemini этого развёртывания, даже если этот ход не генерировал. Штампы фронтенда и бэкенда могут различаться; оба подписаны. Master Admin видит доп. диагностику в технических сведениях — гости нет."},"help-botdee-version-smartview-tabs":{"title":"Вкладки Version SMARTview","body":"Обзор описывает BOT DEE и открывает технические сведения, не покидая чат. Что нового показывает только проверенные изменения BOT DEE и Gemini — не Master Admin, не инструменты бета-тестеров и не другие заметки продуктов FLOQR. Справка повторяет команду Ver / Vers / Version. Смена вкладки или раскрытие сохраняет неотправленный черновик и прокрутку. Карточка берёт ваш Site Chrome — второй темы нет."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"В чате BOT DEE скажите Open Room SMARTview, Start a group chat или простыми словами запланируйте поездку в Cancun. Дальше: Войти сейчас или Задать расписание. Войти сейчас открывает сессию друзей Mingl сразу и не ставит карточку на Search. Задать расписание — старт room BOT DEE, не Shared Itinerary, и включает Search SMARTnotification для вас и приглашённых друзей Mingl. Приглашайте только друзей Mingl — хост плюс 7 гостей. Гости тоже могут приглашать. Вход — не платёж и не общий счёт. BOT DEE никогда не берёт номера карт. Личные сообщения остаются личными. Site Chrome следует Appearance. Живая room открыта, пока хост не нажмёт End Room, около четырёх часов после открытия, или если все отсутствуют около 15 минут. Пауза личного чата BOT DEE отдельно."},"help-botdee-room-smartview-invite":{"title":"Пригласить друзей Mingl","body":"После Confirm (Join Now или Set a schedule) кнопка Invite показывает только друзей Mingl. Нажмите друга или напишите Invite lorna — Inbox получит Review BOT DEE invite. Фишка остаётся серой с Invite sent — повторное нажатие не шлёт второе приглашение. Это команда Room SMARTview, не VIP reserV и не People SMARTview Invite. Это не публичная ссылка. Лимит: хост плюс 7. Гости могут приглашать, пока хост не отключит это. Вход не списывает деньги. Если фишка — это вы или человек уже в сессии, она помечена «Это вы» или «Уже в этой сессии» и не шлёт второе приглашение."},"help-botdee-room-smartview-join":{"title":"Войти в сессию BOT DEE","body":"Откройте приглашение Inbox или Search Join Now, войдя как друг Mingl, которому оно отправлено. Join Now открывает BOT DEE, не Mingl chat. Вы и приглашённые друзья Mingl делите групповой чат Room SMARTview; имена видят участники. Чужой аккаунт, срок и отзыв отказывают. Вход в room — не вход в общий счёт и не согласие на оплату. BOT DEE никогда не берёт номера карт."},"help-botdee-room-smartview-end":{"title":"Завершить Room SMARTview","body":"Только хост может завершить room. Завершение никого не списывает и не стирает чужие личные чаты. Неоплаченный общий счёт нужно оплатить или аннулировать сначала. Живая room открыта до End Room, около четырёх часов после открытия, или если все отсутствуют около 15 минут. Пауза личного чата BOT DEE — не выход из room. Гость, который уходит, не завершает room, пока хост на месте."},"help-botdee-room-smartview-tab":{"title":"Общий счёт Room SMARTview","body":"Сначала opt-in. Затем добавьте строку. Закройте одним плательщиком или раздельно. Списывают только подтвердившие uid через FloqR Stripe. Вход в room — не вход в счёт. BOT DEE никогда не берёт номера карт. Club POS позже."},"help-botdee-room-smartview-who-pays":{"title":"Кто платит","body":"Спросите Who’s paying в Room SMARTview, чтобы увидеть opt-in. Никого не списывают потому, что кто-то сказал купить. Последние четыре карты остаются на квитанции плательщика."},"help-botdee-room-smartview-kick":{"title":"Удалить из Room SMARTview","body":"Только хост может удалить гостя. Удалённый друг не читает дальнейшие сообщения room. Ответ модели никого не исключает."},"help-botdee-room-smartview-share":{"title":"Поделиться в Room SMARTview","body":"Share this conversation никогда не копирует ваш личный тред BOT DEE. BOT DEE показывает предпросмотр выбранных фактов из этого сообщения, помеченных как предварительные. Можно править или убрать факты. Профили и SMARTsummary остаются вне room."},"help-botdee-room-smartview-schedule":{"title":"Войти сейчас или задать расписание","body":"После настройки Room SMARTview выберите Войти сейчас или Задать расписание. Войти сейчас открывает сессию BOT DEE сразу и не ставит карточку на Search. Задать расписание — старт room BOT DEE, не Shared Itinerary. Будущее время включает Search SMARTnotification только для вас и приглашённых друзей Mingl. Гости RSVP, пока room не в эфире; затем Join Now открывает BOT DEE (не Mingl chat)."},"help-botdee-room-collab":{"title":"Общий headless-заказ в Room SMARTview","body":"В Room SMARTview выбор хоста по VIP reserV или ShoutOut виден всем в сессии. Участники голосуют Да или Нет. Hold it и оплата остаются у хоста — вход и голос не платёж. BOT DEE никогда не берёт номера карт. Stripe открывается во всплывающем окне."},"help-botdee-room-elect-host":{"title":"Выбор хоста Room SMARTview","body":"Любой в сессии может быть хостом. Номинируйте себя или другого участника. Кандидат становится хостом при 60% текущих участников (округление вверх). Если хост уходит, остальные выбирают нового — room остаётся открытым. Kick и End остаются у избранного хоста."},"help-botdee-smartview-review":{"title":"Проверить и исправить SMARTsummary","body":"Gemini составляет черновик только из публичных полей FLOQR — не при каждом просмотре. Неверный факт: скройте поле или правьте описание. Ваш текст не перезаписывается. Конфликт профиля просит проверку. Сообщите о неверной карточке в оверлее."},"help-botdee-smartview-chrome":{"title":"SMARTview и Site Chrome","body":"People SMARTview берёт Site Chrome FLOQR зрителя (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Второго темы нет. Смена chrome обновляет карточку, черновик чата сохраняется."},"help-botdee-smartview-categories":{"title":"Категории SMARTview","body":"Четыре вкладки: Социальное, Знакомства, Еда, Будущие поездки. Социальное открывается на Музыке, затем Nightlife, Спорт, События. Теги только из того, чем вы поделились — без повторных заголовков и выдуманных поездок или оценок."},"help-botdee-smartview-media":{"title":"Фото и видео SMARTview","body":"Компактная карточка использует то же главное фото, что и публичная страница FLOQR — первый элемент Profile Media (8 фото + 2 видео). Нажмите, чтобы открыть эти публичные фото и видео. Смахните или стрелки, затем X (или Escape) — тот же чат и черновик."},"help-botdee-smartview-privacy":{"title":"Конфиденциальность SMARTview","body":"SMARTview показывает только уже публичные в FLOQR поля. Это не веб-поиск. Знакомства только с явным согласием. Скройте поле в профиле — оно уйдёт. Заблокированные не видят карточку. Сообщите о неверном описании в оверлее."},"help-botdee-smartview-translation":{"title":"Перевод SMARTview","body":"SMARTsummary хранится на языке профиля — это источник, даже если это не английский. После сохранения FLOQR ставит перевод на каждый другой язык, включая английский. Англоязычный зритель видит английский SMARTsummary, когда работа завершена. Пока перевод ждёт или сбой, зрители видят исходный язык с пометкой — не устаревший перевод как актуальный."},"help-botdee-smartview-edit":{"title":"Изменить SMARTsummary","body":"Только вы правите SMARTsummary на языке профиля. Сохранение сразу. Переводы идут в фоне. Gemini не перезаписывает ваш текст. Если публичный профиль изменился, FLOQR просит проверить, а не подменяет."},"help-botdee-privacy-assistant":{"title":"Помощник конфиденциальности BOT DEE","body":"Меняйте видимость в «Моём профиле» — BOT DEE не добавляет второй публичный переключатель. Неверную веб-привязку можно оспорить, не меняя профиль. BOT DEE не обещает удаление на стороннем сайте."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Каждая рекомендация может показать доказательства, дату проверки, персонализацию и спонсорство. Можно попросить BOT DEE не персонализировать этот поиск."},"help-botdee-research-library":{"title":"Библиотека исследований BOT DEE","body":"Сохраняйте места и карточки, о которых вы спрашивали BOT DEE. Place ID Google — не копия фото или отзывов. Можно обновить или удалить. Лицензионные кэши выключены, пока провайдер не одобрен."},"help-botdee-smartview":{"title":"Мой SMARTview","body":"«Мой SMARTview» показывает вашу карточку человека из публичных полей FLOQR, с теми же Profile Media, что и публичная страница, — не макеты клубов или ресторанов. «Изменить мой SMART Summary» меняет текст на языке профиля. Макеты клубов и ресторанов живут в Master Admin → Features → BOT DEE → SMARTviews. Нет живых Places или Yelp."},"help-botdee-memory":{"title":"Сохранённые чаты BOT DEE","body":"Откройте Функции и заказы → Мой BOT DEE, чтобы сохранять чаты после паузы, экспортировать или удалять историю. Пятиминутная пауза завершает живую сессию. При согласии BOT DEE сохраняет чат. Гости не сохраняются. Mingl остаётся в Mingl."},"help-botdee-knows-of-me":{"title":"Что BOT DEE знает обо мне","body":"Факты с вашего согласия — в разделе Функции и заказы → Мой BOT DEE. Список пуст, если память выключена или фактов нет. Экспорт или удаление здесь. BOT DEE не сохраняет IP. Mingl не копируется."},"help-search-settings-appearance":{"title":"Settings на Search","body":"На экране Home Search нажмите Settings, чтобы открыть Profile & Settings на вкладке Appearance — там Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Плитка Settings использует тот же набор chrome-иконок, что и другие метки Search."},"help-club-website-feed":{"title":"Фид для сайта клуба","body":"Показывайте опубликованную страницу клуба FLOQR на своём сайте. Нажмите «Создать ключ и ссылки», затем вставьте код iframe на сайт или передайте веб-администратору ссылку JSON или RSS. Фид показывает ближайшие события, избранных диджеев, избранный персонал, галерею и контакты с учётом настроек публичной страницы. Фото персонала появляются, только если согласие на фото подтверждено. Новый ключ отключает старые ссылки, включая ссылки на расписание персонала."},"help-featured-staff":{"title":"Избранный персонал","body":"Отметьте сотрудников для публичной страницы клуба. Для каждого нажмите на одно из его фото в FLOQR или выберите «Загрузить с компьютера». Роль под именем можно изменить. Нажмите «Save Public Profile», чтобы опубликовать. Перед публикацией фото получите согласие каждого человека и отметьте поле согласия на фото."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox хранит System Messages и внутренние сообщения поддержки. Список загружается первым, чтобы письма появлялись быстро. Нажмите плавающую кнопку New Message, чтобы написать — введите имя или @username, чтобы найти разрешённого получателя (Club Admin, CSR или одобренный персонал). Переписка patron–patron остаётся в Mingl после взаимного Mingl. Открытие приглашения на смену не подтверждает её — просмотрите и нажмите Approve selected в Work Calendar."},"botdee-ask-floqr":{"title":"Спросите FloqR через BOT DEE","body":"Спросите FloqR через BOT DEE — нажмите анимированный знак или дождитесь подсказки, затем опишите, что нужно, простыми словами. Продукты: Mingl, RydR, BartR, ShoutOut, FloqCAST (superstar), клубы. Цели: скажите «я хочу уметь…» (например, стать Club Admin) или «make me a superstar» — получите шаги и ссылки."},"help-vip-book-table":{"title":"Забронировать VIP-стол (VIP reserV)","body":"VIP reserV позволяет изучить план зала и забронировать стол. Откройте VIP reserV из Поиска, выберите Decades или Lima Twist Club и вечер, нажмите зелёный стол, удержите 30 минут, примите условия и оплатите депозит через FloqR Stripe. Бары и DJ не бронируются. Бренд VIP reserV не переводится. В Aurelia откройте Explore 3D walk-through для интерактивного зала (бронирование остаётся на 2D-карте)."},"help-vip-choose-venue":{"title":"Выберите клуб VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. У Decades, Lima Twist Club и Aurelia есть опубликованный 2D-план; у Aurelia также есть Explore 3D walk-through."},"help-become-club-admin":{"title":"Стать Club Admin","body":"Запросите доступ Club Admin, затем получите одобрение площадки."},"help-role-profiles":{"title":"Обзор ролей","body":"Как работают роли Club Admin, DJ, Promoter и hospitality."},"help-staff-scheduling":{"title":"Календарь и планировщик","body":"Календарь Club Admin показывает Draft (фиолетовый), Pending (янтарный), Confirmed (зелёный) и Open/незаполненные карточки — у каждой есть текстовый статус, не только цвет. Scheduler — сетка люди × дни для черновиков и публикации. Website ingest / publicVenueCalendar отдаёт только Confirmed назначения. Зелёная метка Paid this month видна Club Admins, когда staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Подписки клуба на SMS и WhatsApp уведомления","body":"Club Admin → Notifications: Send test alert использует сейчас отмеченные каналы. In-app (и Push) пишет System Message в FloqR Inbox. Email идёт на адреса админов клуба. SMS и WhatsApp требуют оплаченную подписку и телефон оповещения в E.164. Зелёная метка = подписка Firebase 1 (предоплаченный пакет $10); красная = 0. Если Send test alert возвращает Authentication Error - invalid username, секрет Firebase TWILIO_ACCOUNT_SID должен быть Account SID, начинающийся с AC (34 символа) из console.twilio.com — не Auth Token и не API Key (SK)."},"help-club-sms-notification":{"title":"Подписка на SMS уведомления","body":"Метка SMS зелёная, когда Firebase smsSubscribed = 1 (предоплаченный пакет $10, 466 кредитов, не месяц и не год). Красная/мигающая = 0 — откройте ? и нажмите Subscribe $10. Остаток кредитов и дата последней оплаты — в этой справке. Снимите SMS и Save, чтобы приостановить оповещения, не теряя оплаченный пакет."},"help-club-whatsapp-notification":{"title":"Подписка на WhatsApp уведомления","body":"Метка WhatsApp зелёная, когда Firebase whatsappSubscribed = 1 (предоплаченный пакет $10, 233 кредита, не месяц и не год). Красная/мигающая = 0 — откройте ? и нажмите Subscribe $10. Остаток кредитов и дата последней оплаты — в этой справке. Снимите WhatsApp и Save, чтобы приостановить оповещения, не теряя оплаченный пакет."},"help-schedule-message-templates":{"title":"Шаблоны сообщений расписания","body":"Club Admin → Notifications → Message templates. Это System Messages (Inbox / Email / SMS / WhatsApp), не ShoutOuts. Редактируйте заголовок и текст для New shift needs confirmation, Schedule update, Shift confirmed и Shift declined. Плейсхолдеры: {club} {role} {when} {link} {worker}. В inbox работника — Review & confirm shift, никогда не Open Related ShoutOut."},"help-schedule-confirm":{"title":"Подтверждение назначенных смен","body":"Ссылки Inbox / Email / SMS открывают Work Calendar. Просмотрите каждое ожидание, отметьте его (или Select all), затем Approve selected. Открытие ссылки само по себе не подтверждает. Подтвердить может только назначенный service member — Club Admin не может сделать это за него."},"help-template-catalog-report":{"title":"Отчёт каталога шаблонов","body":"Список всех типов шаблонов ShoutOut и поддерживаемых размеров LED (Is96x48, Is64x48, Is64x32). Площадка предлагает шаблон только если хотя бы один флаг = 1 и соответствующий VenueSupports* = 1. Birthday / split-media шаблоны = 1 на 96×48, 64×48 и 64×32. 96×48 — 3 строки рядом; 64×48 и 64×32 чередуют фото и 3-строчный shoutout с карточкой FLOQR + handle."},"help-club-display-screens":{"title":"Экраны FLOQR","body":"В Firebase clubLocations хранятся VenueSupports96x48, VenueSupports64x48 и VenueSupports64x32 как 0 или 1. В templates — Is96x48, Is64x48 и Is64x32 так же. Площадка показывает шаблон, только если хотя бы одна пара = 1. URL Xibo остаются display.html?location=id и display2.html?location=id — размер экрана не в URL. Birthday доступен на всех трёх размерах (3 строки рядом на 96×48; цикл фото/shoutout на 64×48 и 64×32). Primary — display.html. Secondary — display2.html."},"help-staff-week-calendar":{"title":"Планировщик","body":"Планировщик Club Admin — недельная сетка люди × дни. Save shift закрывает редактор с сообщением Schedule card successfully saved. Создавайте черновики, Publish schedule чтобы работники подтвердили pending→confirmed, Select shifts для множественного удаления и Website ingest для публикации смен на сайте клуба. Окно смены по умолчанию = открытие клуба − 2 часа до закрытия + 1 час."},"help-staff-schedule-user-guide":{"title":"Руководство по расписанию персонала","body":"Откройте ? рядом с Scheduler в Club Admin Scheduling. Создайте черновики смен, Publish schedule чтобы работники подтвердили pending→confirmed, затем Select shifts чтобы удалить несколько сразу. Пример: все черновики среды плюс подтверждённый чип четверга."},"help-create-publish-schedule":{"title":"Создать и опубликовать расписание персонала","body":"Добавьте черновики на сетке люди × дни, проверьте чипы, затем Publish schedule. Работники должны подтвердить смену, прежде чем она станет confirmed. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Удалить несколько запланированных или черновых смен","body":"Select shifts, комбинируйте заголовки дней и чипы, затем Delete selected. Пример: все черновики среды плюс одна подтверждённая смена четверга."},"help-staff-worksheet":{"title":"Work Sheet — недельный календарь персонала","body":"Выбранные service members открывают Work Calendar в Settings. Ссылки подтверждения Inbox / Email / SMS ведут сюда. Просмотрите ожидающие назначения, отметьте каждую смену (или Select all), затем Approve selected — открытие сообщения не подтверждает. Недельная сетка показывает опубликованные смены коллег. Черновики остаются в Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Все начинают как patron FLOQR. В My Profile & Settings нажмите Elect to become a service member, выберите роль и клубы, отправьте внизу страницы.\n\nГид по шаблонам профиля — социальные профили patron остаются в Публичных медиа.\n\nУтверждение Club Admin — Club Admin → Employee/Workers → Pending Worker Requests или Проверить и выбрать на этой вкладке."},"help-venue-website-ingest":{"title":"Ингест сайта клуба (API, RSS, iframe)","body":"Club Admin → Scheduling → Website ingest. Сгенерируйте секрет (показывается один раз; хранится только хеш). Тяните опубликованные смены на официальный сайт клуба через JSON (?format=json&dataset=schedule|hours|profile|all), RSS или iframe. Черновики, email и телефон работника никогда не включаются. Смените секрет при утечке."},"help-venue-hours-calendar":{"title":"Часы работы площадки","body":"В Club Public Profile задайте стандартные часы открытия/закрытия на неделю, затем добавьте period overrides для особых недель, не теряя стандарт. Публичная страница клуба показывает сетку вс–сб с диапазоном дат (например Sun 9 – Sat 15, Aug 2026) и календарной раскраской. Ближайшие праздники показывают часы и отмечают отличие от обычного дня недели. Staff Scheduling использует открытие − 2ч до закрытия + 1ч. Guest List может предлагать открытые вечера."},"help-club-admin-affiliation":{"title":"Назначение Club Admin на площадку","body":"Club Admins открывают Venue Command Center только для назначенного клуба. Открытие admin.html без площадки больше не ведёт по умолчанию на Zebbies. Демо-аккаунты temp_clubadmin_N@floqr-demo.com соответствуют temp-democlub-N. Неназначенные админы запрашивают назначение у Master Admin."},"help-venue-command-center":{"title":"Центр управления площадкой","body":"Одобряйте ShoutOuts, смотрите показатели площадки и сверяйте активность аккаунта для этой локации."},"help-club-template-repository":{"title":"Шаблоны вашего клуба","body":"Шаблоны, созданные только для вашего клуба, идут первыми с пометкой «Эксклюзивно в» и названием площадки. Назначенные шаблоны — те, что посетители могут выбрать в вашем клубе; меняйте это кнопками назначения и удаления шаблона. Поиск находит шаблон даже без диакритики или с небольшой опечаткой."},"help-employee-network":{"title":"Сеть сотрудников и персонала","body":"Показаны только люди, связанные с этим клубом: персонал, назначенный или одобренный здесь, администраторы клуба и персонал, привязанный к этому клубу. Чтобы дать человеку роль, введите имя, имя пользователя или email в поле «Назначить посетителя на роль», нажмите «Выбрать» рядом с нужным человеком, выберите роль, затем нажмите «Назначить выбранного посетителя на роль» и подтвердите. Сначала человеку нужен аккаунт посетителя FLOQR. Официантов, официанток и bottle girls из списка можно сделать представителями службы поддержки (CSR)."},"help-template-tags":{"title":"Теги шаблонов","body":"Добавьте слова, которые гости могут ввести при поиске шаблона на вашей площадке, например вечер матча или день рождения. Менеджеры шаблонов могут добавлять теги. Администраторы шаблонов и Club Admin могут также удалять теги. Club Admin назначает эти роли в разделе Role Activity & Permission."},"help-display-idle-default":{"title":"Экран ожидания: Use ShoutOut @ площадка","body":"Когда ShoutOut не показывается, Display 1 показывает «Use ShoutOut @» и название вашей площадки. Каждый одобренный ShoutOut идёт 10 минут, затем экран сам возвращается к этому сообщению. Сброс экрана по умолчанию в Club Admin делает это сразу."},"help-club-messaging-credit":{"title":"Кредит SMS и WhatsApp","body":"Каждый пакет $10 покрывает $7,00 ёмкости Twilio; FloqR оставляет $3,00 платформенной маржи. SMS-пакет → 466 сообщений (≈ $0,015 SMS США). WhatsApp-пакет → 233 сообщения (≈ $0,030 Twilio + Meta marketing). При нуле купите новый пакет перед отправкой. Ops SMS unlock ($10) даёт SMS-пакет. WhatsApp service ($10) даёт WhatsApp-пакет. Расчёт: $10 → 466 SMS или 233 WhatsApp ($7,00 Twilio / $3,00 FloqR)."},"help-club-marketing-campaigns":{"title":"Маркетинговые кампании","body":"Выберите отраслевой шаблон, загрузите фон и доп. изображения, отредактируйте текст, сохраните или отправьте. Отправка списывает кредиты SMS или WhatsApp из раздела кредита сообщений."},"help-club-in-app-marketing":{"title":"In-app маркетинг","body":"Публикуйте флаер или видео до 30 секунд от имени клуба. После оплаты и одобрения FLOQR реклама показывается на экране загрузки поиска, в Mingl, RydR и на других экранах FLOQR. В разделе «Публикаторы рекламы клуба» можно разрешить сотруднику публиковать рекламу (роль Club Ad Poster). SMS-кредиты не нужны."},"help-vip-terms-consent":{"title":"Условия VIP reserV","body":"После удержания стола откройте страницу условий, прочитайте текст и примите один раз (маркетинг отдельно). Согласие сохраняется до FloqR Stripe Checkout — как у платного ShoutOut, затем квитанция и пропуск."},"help-vip-door-pass":{"title":"Пропуск VIP reserV","body":"После подтверждения депозита откройте Мой профиль → Бронирования и нажмите Show pass для одноразового QR. Возьмите ID 21+. Персонал двери использует VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in у двери VIP reserV","body":"VIP Manager открывает VIP reserV Door на сегодня. Сканируйте или вставьте токен, подтвердите ID 21+, затем check-in. No-show только после grace. Ссылка notify не меняет статус."},"help-vip-payment-collector":{"title":"Сборщик оплаты VIP reserV и Club POS","body":"Предпочтительно для живых клубов с Toast/SpotOn: Club POS — FLOQR бронирует/держит/карту; POS владеет депозитом, счётом и тратами. Альтернативы: Club Stripe, FloqMedia Stripe (FloqR) или движок VIP + CSV. Aurelia (Demo Club) по умолчанию FloqMedia Stripe — спросите BOT DEE шаги Master и Club Admin."},"help-vip-table-isbooked":{"title":"Статус isBooked VIP-столов в Firestore","body":"У каждого VIP-клуба есть документ Firestore на номер стола и вечер: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Id = печатный номер (напр. T1, B3). После завершения бронирования: isBooked \"1\", isBookedYes \"yes\". Свободные: \"0\" / \"no\". Hold не меняет isBooked. Отмена → \"0\". getVipAvailability берёт isBooked как статус брони. Отмена всегда → isBooked \"0\"; FloqMedia/Club Stripe может вернуть депозит по политике клуба."},"help-vip-floqr-stripe-aurelia":{"title":"Настроить FloqMedia Stripe для Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) по умолчанию использует FloqMedia Stripe (FloqR Checkout) для VIP-депозита — гости платят на платформенном Stripe FloqR, затем стол считается забронированным.\n\nШаги Master Admin:\n1) Откройте Master Admin → Features Mgmt → VIP reserV Payments.\n2) Убедитесь, что VIP Reservations включён в сети.\n3) Seed / refresh POS-провайдеров только если позже нужен Club POS — для FloqMedia Stripe не требуется.\n4) Оставьте Aurelia на FloqMedia Stripe, если не нужны Club POS или Club Stripe.\n5) После депозитов откройте Network VIP billing.\n\nШаги Club Admin (Aurelia):\n1) Войдите как temp_clubadmin_1@floqr-demo.com (Email OTP на главной) или Club Admin Aurelia.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) В Payment collector выберите FloqMedia Stripe (FloqR).\n4) Оставьте Require deposit before table is marked booked.\n5) Сохраните Save payment collector.\n6) Тест: vip.html?location=temp-democlub-1 → удержать стол → Условия → Оплатить депозит (тест-карта 4242…).\n7) Door / биллинг: Open Door; Refresh billing.\n\nНе выбирайте Club POS для демо Aurelia без sandbox Toast/SpotOn. FloqMedia, Stripe, ShoutOut и VIP reserV — непереводимые бренды."}},"nl":{"help-smartvisuals-notification":{"title":"Mingl Room SMARTnotification","body":"Een compacte Mingl Room-uitnodiging kan op Search verschijnen als jij een schema zet voor een BOT DEE-room, of als een Mingl-vriend je uitnodigde. De host ziet de eigen geplande room op Search zonder de Cancun-demovraag. Uitnodiging bekijken opent Room SMARTview. Join Now gaat naar BOT DEE, niet Mingl-chat. Niet nu verbergt de kaart in dit tabblad; Inbox houdt Review BOT DEE invite. De Cancun-demovraag is alleen Studio. Kunst is illustratie, geen foto. Join Now-rooms zonder plan verschijnen niet op Search."},"help-smartvisuals-room":{"title":"Room SMARTview met SMARTvisuals","body":"Room SMARTview toont de Mingl-uitnodiging: plan, RSVP of live-status, en Join Now. Join Now op Search opent BOT DEE (niet Mingl-chat) met room= en t=. SMARTstencils en SMARTbackgrounds volgen de geautoriseerde roomtitel — Cancun Trip gebruikt reisillustratie, geen echte Cancun-foto. Privé-BOT DEE-chat kiest nooit de kunst. Een gelabelde Ad eronder is een sample van die tags. Leeg bij privéchat of injectie; geen live adverteerder."},"help-scheduling-schedule-for":{"title":"Personeelsplanning","body":"Plan diensten en boekingen en laat iedereen het weten via Inbox, Email, SMS of WhatsApp. Kies onder 'Planning voor' aan welke agenda je werkt: 'Mijn DJ-planning' is je eigen agenda, 'Club' toont de clubs die je beheert en 'Promotiebedrijf' de bedrijven waarvoor je promoot. Elke agenda heeft een eigen abonnement van $ 20 per maand. Diensten die aan jou zijn toegewezen verschijnen onder 'Mijn toewijzingen', waar je ze bevestigt of weigert."},"help-staff-marketing-consent":{"title":"Marketingtoestemming voor personeel","body":"Wanneer je bij het team van een locatie of evenement aansluit, moet je het vakje voor marketingtoestemming aanvinken. Daarmee mogen die locatie of organisator en hun beheerders en managers je FLOQR-naam, je rol en je gepubliceerde foto’s en video’s gebruiken op hun websites, flyers en sociale media (Instagram, Facebook, TikTok, YouTube en vergelijkbare) zonder je voor elk gebruik opnieuw te vragen. Ze mogen je telefoonnummer of e-mailadres niet publiceren. Je kunt op elk moment intrekken in Mijn profiel, tabblad Services en servicemedewerkers. Dat stopt nieuwe marketing; materiaal dat al gedrukt of geplaatst is, hoeft niet te worden teruggehaald. Club Admins zien de toestemmingsstatus van elke medewerker in het Netwerk van medewerkers en personeel en bij Uitgelicht personeel."},"help-botdee-privacy-session":{"title":"BOT DEE privacy en sessie","body":"De pauze van vijf minuten beëindigt de live BOT DEE-sessie. Ze verwijdert deze ingelogde chat, herinneringen of workflows niet. Optionele kopieën in Mijn profiel → Functies en bestellingen → My BOT DEE blijven ook. Gasten blijven tijdelijk. Mingl-chats worden hier nooit gekopieerd. Enter verstuurt; Shift+Enter begint een nieuwe regel. Naam en toon staan in Mijn profiel → My BOT DEE, niet als knop in de chat."},"help-botdee-place-search":{"title":"Vraag BOT DEE naar FLOQR-venues","body":"Vraag in gewone taal — sushi restaurants in Washington DC, clubs in DC of een clubnaam. BOT DEE zoekt alleen onboarded FLOQR-venues, niet Google of Yelp. Treffers openen een compacte Place SMARTview (naam, korte blurb, ratings, publiekspagina) met een SMARTbackground — geen fotobak. Een stad noemen bij VIP reserV (reservations in Miami) koppelt nog steeds Place SMARTview naast de VIP-kaart. Patronfoto’s en ShoutOut-pitches blijven weg tenzij u daarnaar vroeg. Als er nog niets onboarded is, zegt BOT DEE dat."},"help-botdee-page":{"title":"BOT DEE","body":"Chat met BOT DEE op de BOT DEE-pagina in gewone taal: evenementen en clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, je profiel, personeelsroosters of Club Admin-tools. Druk op Enter om te versturen; Shift+Enter start een nieuwe regel. BOT DEE praat als een persoon (probeer How are you?) en zoekt alleen als je vraagt hoe je iets in FLOQR doet. Als je bent ingelogd, bewaart BOT DEE deze chat als je vernieuwt of een andere telefoon opent, en na de pauze verdergaan met de opgeslagen geschiedenis. De pauze verwijdert de chat niet. Antwoorden gebruiken de classificatie van jouw account. Ingelogd ziet BOT DEE dezelfde openbaar gedeelde profieldatapoints als jij (muziek, eten, reizen, hobby’s en de rest van Privacy datapoint sharing) — nooit e-mail, telefoon, kaartgegevens of GPS. Tik op Instellingen onder het chatvak voor opgeslagen chats en herinneringen. Tik in de chat op een foto om die in een apart venster te openen. Sluit met X of Sluiten om de chat weer te zien. De + rechtsboven opent opgeslagen chats en verwijdert ze niet."},"help-botdee-smartview-troubleshoot":{"title":"SMARTview-problemen","body":"Lege kaart: velden verborgen of geblokkeerd. Opslaan mislukt: meld u aan — vertalingen staan op de server. Wachtend of mislukt: brontaal met label. Alleen de eigenaar bewerkt. Master Admin SMARTviews blijft de mock-catalogus; Places en Yelp blijven uit. Thema volgt Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary blijft synchroon","body":"Bewerk uw SMARTsummary in de standaard profieltaal. Opslaan is direct. Open kaarten en SMARTview werken bij vanaf hetzelfde record. Vertalingen lopen op de achtergrond en overschrijven geen nieuwere bewerking. Als u het profiel verbergt, iemand blokkeert of het account verwijdert, verdwijnen die kaarten. Gemini overschrijft uw tekst niet."},"help-botdee-smartcard-search":{"title":"BOT DEE vragen wie iemand is","body":"“Who am I?” opent uw SMARTview. “Who is …”, “What do you know of …” of “What about …” plus voornaam, achternaam, weergavenaam, Mingl- of FloqR-handle, of een social handle (Instagram, TikTok, X). Alleen die identiteitsvelden tellen — geen bio’s, likes, drankjes of genres. Eén match opent een People SMARTview-kaart in de chat — geen markdownlijst of fotogrid. Meer matches tonen compacte SMARTcards. Privé, geblokkeerd of niet-gepubliceerd wordt niet getoond — BOT DEE bevestigt niet of dat account bestaat."},"help-botdee-smartcard":{"title":"Mensen-SMARTcards","body":"Als meer dan één openbaar FLOQR-profiel past, toont BOT DEE compacte mensen-SMARTcards in de chat: eerst een foto over de volle breedte, dan naam en handle, dan een compacte SMARTsummary zonder opgevulde box. Tik om de volledige SMARTview te openen — dezelfde stapeling. Kaarten gebruiken hetzelfde openbare profiel en dezelfde SMARTsummary. Openen roept Gemini niet aan."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Typ Ver, Vers of Version — hoofdletters maken niet uit. BOT DEE toont de versiekaart. Een langere vraag zoals “wat is je versie?” toont ook die kaart."},"help-botdee-version-smartview-status":{"title":"Version SMARTview-status is een live peiling","body":"Servicestatus wordt bij dit Version-verzoek gepeild: Functions en package bereikbaar met Gemini geconfigureerd → Operationeel; Functions en package oké maar Gemini niet geconfigureerd → Verminderd; Functions niet in dit verzoek → Niet beschikbaar. Nooit een statisch Niet gecontroleerd. Het AI-model toont het geconfigureerde Gemini-model-id van deze deployment ook als deze beurt niet genereerde. Frontend- en backendstempels kunnen verschillen; beide zijn gelabeld. Master Admin kan extra diagnostiek zien onder Technische details — patrons niet."},"help-botdee-version-smartview-tabs":{"title":"Version SMARTview-tabbladen","body":"Overzicht beschrijft BOT DEE en opent Technische details zonder de chat te verlaten. Nieuw toont alleen geverifieerde BOT DEE- en Gemini-wijzigingen — geen Master Admin, bèta-testertools of andere FLOQR-productnotities. Help herhaalt het commando Ver / Vers / Version. Tab wisselen of uitklappen bewaart je onverzonden concept en scroll. De kaart gebruikt jouw Site Chrome — er is geen tweede thema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Zeg in de BOT DEE-chat Open Room SMARTview, Start a group chat, of plan een Cancun-reis in gewone woorden. Daarna: Nu deelnemen of Plan instellen. Nu deelnemen opent nu een Mingl-vrienden-sessie en zet geen kaart op Search. Plan instellen is wanneer de BOT DEE-room start — niet Shared Itinerary — en zet Search SMARTnotification aan voor jou en uitgenodigde Mingl-vrienden. Nodig alleen Mingl-vrienden uit — host plus 7 gasten. Gasten kunnen ook uitnodigen. Deelnemen is geen betaling en opent geen gedeelde rekening. BOT DEE neemt nooit kaartnummers. Privé-BOT DEE-berichten blijven privé. Site Chrome volgt Appearance. Een live room blijft open tot End Room, tot ongeveer vier uur na opening, of tot iedereen zo’n 15 minuten weg is. De pauze van privé-BOT DEE-chat is apart."},"help-botdee-room-smartview-invite":{"title":"Mingl-vrienden uitnodigen","body":"Na Confirm (Join Now of Set a schedule) toont Invite alleen je Mingl-vrienden. Tik een vriend of typ Invite lorna — Inbox krijgt Review BOT DEE invite. De chip blijft grijs met Invite sent — opnieuw tikken stuurt geen tweede uitnodiging. Dat is een Room SMARTview-commando, geen VIP reserV en geen People SMARTview Invite. Geen openbare join-link. Cap is host plus 7. Gasten kunnen meer Mingl-vrienden uitnodigen tot de host dat uitzet. Deelnemen is geen betaling. Als een chip jij bent of iemand die al in de sessie zit, staat That’s you of Already in this session en wordt er geen tweede uitnodiging gestuurd."},"help-botdee-room-smartview-join":{"title":"Deelnemen aan een BOT DEE-sessie","body":"Open de Inbox-uitnodiging of Search Join Now terwijl je bent aangemeld als de Mingl-vriend aan wie die is gestuurd. Join Now opent BOT DEE, niet Mingl chat. Jij en uitgenodigde Mingl-vrienden delen de Room SMARTview-groepschat; namen zijn zichtbaar voor leden. Verkeerd account, verlopen of ingetrokken weigert. Deelnemen aan de room is niet deelnemen aan een tab en keurt geen betaling goed. BOT DEE neemt nooit kaartnummers."},"help-botdee-room-smartview-end":{"title":"Room SMARTview beëindigen","body":"Alleen de host kan een room beëindigen. Beëindigen belast niemand en wist geen privéchats van anderen. Een onbetaalde gedeelde rekening moet eerst betaald of geannuleerd. Een live room blijft open tot End Room, tot ongeveer vier uur na opening, of tot iedereen zo’n 15 minuten weg is. De pauze van privé-BOT DEE-chat is geen room-logout. Een gast die weggaat beëindigt de room niet zolang de host er is."},"help-botdee-room-smartview-tab":{"title":"Gedeelde tab Room SMARTview","body":"Eerst opt-in. Voeg dan een regel toe. Sluit als één betaler of splits. Alleen bevestigende uids worden belast via FloqR Stripe. Deelnemen aan de room is niet deelnemen aan een tab. BOT DEE neemt nooit kaartnummers. Club POS komt later."},"help-botdee-room-smartview-who-pays":{"title":"Wie betaalt","body":"Vraag Who’s paying in een Room SMARTview om opt-in te zien. Niemand wordt belast omdat iemand buy zei. De laatste vier van de kaart blijven op het ontvangstbewijs van de betaler."},"help-botdee-room-smartview-kick":{"title":"Iemand uit Room SMARTview verwijderen","body":"Alleen de host kan een gast verwijderen. Een verwijderde vriend leest geen verdere roomberichten. Een modelantwoord kan niemand kicken."},"help-botdee-room-smartview-share":{"title":"Delen in Room SMARTview","body":"Share this conversation kopieert nooit je privé BOT DEE-thread. BOT DEE toont een voorbeeld van geselecteerde deelbare feiten uit dit bericht, gemarkeerd als voorlopig. Je kunt feiten bewerken of weglaten. Profielen en SMARTsummary blijven buiten de room."},"help-botdee-room-smartview-schedule":{"title":"Nu deelnemen of plan instellen","body":"Na Room SMARTview-setup kies je Nu deelnemen of Plan instellen. Nu deelnemen opent de BOT DEE-sessie nu en zet geen kaart op Search. Plan instellen is wanneer de BOT DEE-room start — niet Shared Itinerary. Een toekomstig tijdstip zet Search SMARTnotification alleen aan voor jou en uitgenodigde Mingl-vrienden. Gasten RSVP tot de room live is; daarna opent Join Now BOT DEE (niet Mingl-chat)."},"help-botdee-room-collab":{"title":"Deel een headless boeking in Room SMARTview","body":"In een Room SMARTview zien alle leden de VIP reserV- of ShoutOut-keuzes van de host. Leden stemmen Ja of Nee. Hold it en betalen blijven bij de host — meedoen en stemmen is geen betaling. BOT DEE neemt nooit kaartnummers. Stripe opent in een pop-out."},"help-botdee-room-elect-host":{"title":"Kies een Room SMARTview-host","body":"Iedereen in de sessie kan host zijn. Nomineer jezelf of een ander lid. Een kandidaat wordt host bij 60% van de huidige leden (naar boven afgerond). Als de host vertrekt, kiezen de overgebleven leden een nieuwe — de room blijft open. Kick en End blijven bij de gekozen host."},"help-botdee-smartview-review":{"title":"SMARTsummary controleren en corrigeren","body":"Gemini stelt alleen op uit openbare FLOQR-velden — niet bij elke weergave. Verkeerd feit: veld verbergen of samenvatting zelf bewerken. Uw tekst wordt niet overschreven. Profielconflicten vragen om controle. Meld een foute kaart in de overlay."},"help-botdee-smartview-chrome":{"title":"SMARTview en Site Chrome","body":"People SMARTview gebruikt de FLOQR Site Chrome van de kijker (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Geen tweede thema. Chrome wisselen werkt de kaart bij zonder het chatconcept te verliezen."},"help-botdee-smartview-categories":{"title":"SMARTview-categorieën","body":"Vier tabbladen: Sociaal, Daten, Dineren, Toekomstige reizen. Sociaal opent op Muziek, daarna Nightlife, Sport, Events. Tags zijn alleen wat u deelde — geen dubbele koppen, geen verzonnen reizen of scores. Toekomstige reizen alleen openbaar gemaakte bestemmingen."},"help-botdee-smartview-media":{"title":"SMARTview-foto’s en video’s","body":"De compacte kaart gebruikt dezelfde hero als uw openbare FLOQR-profiel — het eerste Profile Media-item (8 foto’s + 2 video’s). Tik voor Foto’s en Video’s uit die openbare slots. Veeg of pijlen, dan X (of Escape) terug naar dezelfde chatscroll en concept."},"help-botdee-smartview-privacy":{"title":"SMARTview-privacy","body":"SMARTview toont alleen velden die u al openbaar maakte in FLOQR. Geen webzoeken. Daten alleen met opt-in. Verberg een veld in Mijn profiel en het verdwijnt. Geblokkeerden zien de kaart niet. Meld een onjuiste samenvatting in de overlay."},"help-botdee-smartview-translation":{"title":"SMARTview-vertaling","body":"Uw SMARTsummary wordt opgeslagen in de standaard profieltaal — dat is de bron, ook als het geen Engels is. Na opslaan zet FLOQR een vertaling klaar voor elke andere taal, inclusief Engels. Een Engelstalige kijker ziet de Engelse SMARTsummary zodra die job klaar is. Bij wachten of fout ziet de kijker de brontaal met label — nooit een verouderde vertaling als actueel."},"help-botdee-smartview-edit":{"title":"Uw SMARTsummary bewerken","body":"Alleen u bewerkt uw SMARTsummary in de standaard profieltaal. Opslaan is direct. Vertalingen lopen op de achtergrond. Gemini overschrijft uw tekst niet. Als het openbare profiel wijzigt, vraagt FLOQR u te controleren in plaats van te vervangen."},"help-botdee-privacy-assistant":{"title":"BOT DEE Privacy Assistant","body":"Wijzig in Mijn profiel wat andere FLOQR-gebruikers zien — BOT DEE voegt geen tweede openbare schakelaar toe. Verkeerde webkoppeling kunt u betwisten zonder uw profiel te wijzigen. BOT DEE belooft geen verwijdering op sites van derden."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Elke aanbeveling kan bewijs, controledatum, personalisatie en sponsoring tonen. U kunt BOT DEE vragen deze zoekopdracht niet te personaliseren."},"help-botdee-research-library":{"title":"BOT DEE Research Library","body":"Bewaar plaatsen en kaarten die u BOT DEE vroeg. Een Google Place-ID is geen kopie van foto’s of reviews. U kunt vernieuwen of wissen. Gelicentieerde caches blijven uit tot de provider is goedgekeurd."},"help-botdee-smartview":{"title":"Mijn SMARTview bekijken","body":"Mijn SMARTview toont uw Person-kaart uit openbare FLOQR-velden, met dezelfde Profile Media als uw openbare pagina — geen club- of restaurantmocks. Mijn SMART Summary bewerken wijzigt de samenvatting in uw profieltaal. Gelabelde mock-kaarten staan in Master Admin → Features → BOT DEE → SMARTviews. Geen live Places of Yelp."},"help-botdee-memory":{"title":"Opgeslagen BOT DEE-chats","body":"Open Functies & bestellingen → Mijn BOT DEE om chats na de pauze op te slaan, te exporteren of geschiedenis te wissen. De pauze van vijf minuten beëindigt de live sessie. Met opt-in bewaart BOT DEE de chat. Gasten worden niet bewaard. Mingl blijft Mingl."},"help-botdee-knows-of-me":{"title":"Wat BOT DEE van mij weet","body":"Feiten met uw toestemming staan onder Functies & bestellingen → Mijn BOT DEE. De lijst is leeg als geheugen uit staat of er niets is opgeslagen. Exporteer of wis hier. BOT DEE slaat geen IP-adres op. Mingl wordt niet gekopieerd."},"help-search-settings-appearance":{"title":"Settings op Search","body":"Tik op Search op Settings om Profile & Settings te openen op het tabblad Appearance — daar staat Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). De Settings-tegel gebruikt hetzelfde chrome-iconenpakket als de andere Search-merken."},"help-club-website-feed":{"title":"Feed voor de clubwebsite","body":"Toon je gepubliceerde FLOQR-clubpagina op je eigen website. Tik op ‘Sleutel en links aanmaken’ en plak de iframe-code in je website, of geef je webbeheerder de JSON- of RSS-link. De feed toont komende evenementen, uitgelichte dj’s, uitgelicht personeel, de galerij en contactgegevens, volgens je instellingen voor de openbare pagina. Foto’s van personeel verschijnen alleen als de fototoestemming is bevestigd. Een nieuwe sleutel schakelt de oude links uit, ook de links van het personeelsrooster."},"help-featured-staff":{"title":"Uitgelicht servicepersoneel","body":"Vink het personeel aan dat op de openbare clubpagina moet staan. Tik voor elke persoon op een van hun FLOQR-foto’s of kies ‘Uploaden vanaf computer’. Je kunt de rol onder hun naam aanpassen. Tik op ‘Save Public Profile’ om te publiceren. Vraag vóór het publiceren van foto’s ieders toestemming en vink het vakje voor fototoestemming aan."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox bevat System Messages en interne supportberichten. De lijst laadt eerst zodat berichten snel verschijnen. Tik op de zwevende knop New Message om te schrijven — typ een naam of @username om een toegestane ontvanger te vinden (Club Admin, CSR of goedgekeurd personeel). Patron-naar-patron chat blijft in Mingl na wederzijds Mingl. Een shift-uitnodiging openen bevestigt niet — bekijk en tik Approve selected op Work Calendar."},"botdee-ask-floqr":{"title":"Vraag FloqR met BOT DEE","body":"Vraag FloqR met BOT DEE — tik op het bewegende merkteken of wacht op de prompt, en typ in gewone woorden wat je wilt. Producten: Mingl, RydR, BartR, ShoutOut, FloqCAST (superstar), clubs. Doelen: zeg “ik wil kunnen…” (bijv. Club Admin worden) of “make me a superstar” voor stappen en links."},"help-vip-book-table":{"title":"VIP-tafel boeken (VIP reserV)","body":"VIP reserV toont de plattegrond en boekt tafels. Open VIP reserV via Zoeken, kies Decades of Lima Twist Club en een avond, tik een groene tafel, houd 30 minuten, accepteer voorwaarden en betaal de borg met FloqR Stripe. Bars en DJ niet boekbaar. Bij Aurelia gebruikt u Explore 3D walk-through voor de interactieve ruimte (boeken blijft op de 2D-kaart)."},"help-vip-choose-venue":{"title":"Kies een VIP reserV-venue","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club en Aurelia hebben elk een gepubliceerd 2D-plan; Aurelia biedt ook Explore 3D walk-through."},"help-become-club-admin":{"title":"Word Club Admin","body":"Vraag Club Admin-toegang aan en krijg goedkeuring van de venue."},"help-role-profiles":{"title":"Overzicht rolprofielen","body":"Bekijk hoe Club Admin, DJ, Promoter en hospitality-rollen werken."},"help-staff-scheduling":{"title":"Agenda & Planner","body":"Club Admin Calendar toont Draft (paars), Pending (amber), Confirmed (groen) en Open/onbezette kaarten — elk met een tekststatus, niet alleen kleur. Scheduler is het raster mensen × dagen voor concept/publicatie. Website ingest / publicVenueCalendar geeft alleen Confirmed toewijzingen. Een groene Paid this month-pill verschijnt voor Club Admins wanneer staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Club SMS- en WhatsApp-notificatieabonnementen","body":"Club Admin → Notifications: Send test alert gebruikt de momenteel aangevinkte kanalen. In-app (en Push) schrijft een System Message in FloqR Inbox. Email gebruikt clubadmin-adressen. SMS en WhatsApp vereisen een betaald abonnement plus een E.164-alerttelefoon. Groene pill = Firebase-abonnement 1 (vooruitbetaald $10-pakket); rood = 0. Als Send test alert Authentication Error - invalid username teruggeeft, moet Firebase-secret TWILIO_ACCOUNT_SID de Account SID zijn die met AC begint (34 tekens) van console.twilio.com — niet de Auth Token en niet een API Key (SK)."},"help-club-sms-notification":{"title":"SMS-notificatieabonnement","body":"De SMS-pill is groen wanneer Firebase smsSubscribed 1 is (vooruitbetaald $10-pakket, 466 credits, niet maandelijks of jaarlijks). Rood/knipperend betekent 0 — open ? en tik Subscribe $10. Resterende credits en laatste betaaldatum staan in deze hulp. Vink SMS uit en Save om alerts te pauzeren zonder het betaalde pakket te verliezen."},"help-club-whatsapp-notification":{"title":"WhatsApp-notificatieabonnement","body":"De WhatsApp-pill is groen wanneer Firebase whatsappSubscribed 1 is (vooruitbetaald $10-pakket, 233 credits, niet maandelijks of jaarlijks). Rood/knipperend betekent 0 — open ? en tik Subscribe $10. Resterende credits en laatste betaaldatum staan in deze hulp. Vink WhatsApp uit en Save om alerts te pauzeren zonder het betaalde pakket te verliezen."},"help-schedule-message-templates":{"title":"Berichtensjablonen voor roosters","body":"Club Admin → Notifications → Message templates. Dit zijn System Messages (Inbox / Email / SMS / WhatsApp), geen ShoutOuts. Bewerk titel en tekst voor New shift needs confirmation, Schedule update, Shift confirmed en Shift declined. Placeholders: {club} {role} {when} {link} {worker}. Worker-inbox gebruikt Review & confirm shift — nooit Open Related ShoutOut."},"help-schedule-confirm":{"title":"Toegewezen diensten bevestigen","body":"Inbox- / Email- / SMS-links openen Work Calendar. Bekijk elke pending toewijzing, vink aan (of Select all), en dan Approve selected. De link openen bevestigt niet. Alleen het toegewezen service member kan goedkeuren — Club Admin kan dat niet namens hen doen."},"help-template-catalog-report":{"title":"Rapport sjablooncatalogus","body":"Lijst van elk ShoutOut-sjabloontype en welke LED-formaten het ondersteunt (Is96x48, Is64x48, Is64x32). Een venue biedt een sjabloon alleen aan als minstens één van die vlaggen 1 is en de bijpassende VenueSupports*-vlag 1 is. Birthday- / split-media-sjablonen zijn 1 op 96×48, 64×48 en 64×32. 96×48 is 3 regels naast elkaar; 64×48 en 64×32 wisselen foto en 3-regelige shoutout met een FLOQR + handle-kaart."},"help-club-display-screens":{"title":"FLOQR-displayschermen","body":"Firebase clubLocations bewaart VenueSupports96x48, VenueSupports64x48 en VenueSupports64x32 als 0 of 1. templates bewaart Is96x48, Is64x48 en Is64x32 op dezelfde manier. Een venue toont een sjabloon alleen als minstens één paar 1 is. Xibo-URL’s blijven display.html?location=id en display2.html?location=id — schermgrootte zit niet in de URL. Birthday is beschikbaar op alle drie formaten (3 regels naast elkaar op 96×48; foto/shoutout-lus op 64×48 en 64×32). Primary is display.html. Secondary is display2.html."},"help-staff-week-calendar":{"title":"Planner","body":"Club Admin Scheduler is een weekraster mensen × dagen. Save shift sluit de editor met Schedule card successfully saved. Maak concepten, Publish schedule zodat medewerkers pending bevestigen tot confirmed, Select shifts om meerdere te verwijderen, en Website ingest om gepubliceerde diensten op de clubsites te zetten. Standaard dienstvenster = club open − 2 uur tot sluiting + 1 uur."},"help-staff-schedule-user-guide":{"title":"Gebruikersgids personeelsplanning","body":"Open de ? naast Scheduler op Club Admin Scheduling. Maak conceptdiensten, Publish schedule zodat medewerkers pending→confirmed bevestigen, daarna Select shifts om er meerdere tegelijk te verwijderen. Voorbeeld: alle woensdagconcepten plus een donderdag confirmed-chip."},"help-create-publish-schedule":{"title":"Personeelsrooster maken en publiceren","body":"Voeg conceptdiensten toe op het raster mensen × dagen, controleer chips, en Publish schedule. Medewerkers moeten bevestigen voordat een dienst confirmed wordt. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Meerdere geplande of conceptdiensten verwijderen","body":"Select shifts, combineer dagkoppen en chips, daarna Delete selected. Voorbeeld: alle woensdagconcepten plus één donderdag confirmed dienst."},"help-staff-worksheet":{"title":"Work Sheet — wekelijkse personeelskalender","body":"Gekozen service members openen Work Calendar in Settings. Inbox- / Email- / SMS-bevestigingslinks landen hier. Bekijk pending toewijzingen, vink elke dienst aan (of Select all), daarna Approve selected — het bericht openen bevestigt niet. Het weekraster toont gepubliceerde diensten van collega’s. Concepten blijven in Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Iedereen start als FLOQR-patron. Tik Elect to become a service member, kies servicerol en clubs, en dien onderaan in.\n\nProfielsjabloon-gids — patron-sociale profielen blijven onder Openbare media.\n\nClub Admin-goedkeuring — Club Admin → Employee/Workers → Pending Worker Requests, of Beoordelen en kiezen op dit tabblad."},"help-venue-website-ingest":{"title":"Clubwebsite-ingest (API, RSS, iframe)","body":"Club Admin → Scheduling → Website ingest. Genereer een secret (eenmalig zichtbaar; alleen een hash wordt bewaard). Haal gepubliceerde diensten naar de officiële clubsites met JSON (?format=json&dataset=schedule|hours|profile|all), RSS of een iframe-snippet. Concepten, e-mail en telefoon van medewerkers zitten er nooit in. Roteer het secret bij lek."},"help-venue-hours-calendar":{"title":"Openingstijden van de venue","body":"Op Club Public Profile stel je de standaard wekelijkse open/gesloten uren in, en voeg period overrides toe voor speciale weken zonder de standaard te verliezen. De openbare clubpagina toont een zo–za weekraster met datumbereik (bijv. Sun 9 – Sat 15, Aug 2026) en kalenderkleuren. Aankomende feestdagen tonen open/sluituren en markeren afwijkingen van de gebruikelijke weekdag. Staff Scheduling gebruikt open − 2u tot sluit + 1u. Guest List kan open avonden voorstellen."},"help-club-admin-affiliation":{"title":"Club Admin-venue toewijzing","body":"Club Admins openen het Venue Command Center alleen voor een club waaraan ze zijn toegewezen. admin.html zonder venue opent niet langer standaard Zebbies. Demo-accounts temp_clubadmin_N@floqr-demo.com horen bij temp-democlub-N. Niet-toegewezen admins vragen toewijzing aan bij Master Admin."},"help-venue-command-center":{"title":"Venue Command Center","body":"Keur ShoutOuts goed, bekijk venue-prestaties en stem accountactiviteit af voor deze locatie."},"help-club-template-repository":{"title":"Sjablonen van je club","body":"Sjablonen die alleen voor je club zijn, staan bovenaan met ‘Exclusief bij’ en de naam van je locatie. Toegewezen sjablonen kunnen gasten bij je club kiezen; wijzig dat met Sjabloon toewijzen of Sjabloon verwijderen. Zoeken vindt een sjabloon ook zonder accent of met een kleine typfout."},"help-employee-network":{"title":"Netwerk van medewerkers en personeel","body":"Alleen mensen die aan deze club gekoppeld zijn staan in de lijst: personeel dat hier is aangewezen of goedgekeurd, clubbeheerders en personeel dat aan deze club verbonden is. Om iemand een rol te geven, typ je naam, gebruikersnaam of e-mail bij Gast aanwijzen voor een rol, tik je op Selecteren naast de juiste persoon, kies je de rol, tik je op Geselecteerde gast aanwijzen voor rol en bevestig je. De persoon heeft eerst een FLOQR-gastaccount nodig. Obers, serveersters en bottle girls op de lijst kun je klantenservicemedewerker (CSR) maken."},"help-template-tags":{"title":"Sjabloontags","body":"Voeg woorden toe die gasten kunnen typen als ze een sjabloon zoeken bij je locatie, zoals wedstrijdavond of verjaardag. Sjabloonmanagers kunnen tags toevoegen. Sjabloonbeheerders en Club Admins kunnen tags ook verwijderen. Club Admin wijst deze rollen toe onder Role Activity & Permission."},"help-display-idle-default":{"title":"Rustscherm: Use ShoutOut @ locatie","body":"Als er geen ShoutOut speelt, toont Display 1 ‘Use ShoutOut @’ met de naam van je locatie. Elke goedgekeurde ShoutOut speelt 10 minuten; daarna keert het scherm vanzelf terug naar die tekst. Scherm terugzetten naar standaard in Club Admin doet dat meteen."},"help-club-messaging-credit":{"title":"SMS- en WhatsApp-tegoed","body":"Elk pakket van $10 dekt $7,00 Twilio-capaciteit; FloqR houdt $3,00 platformmarge. SMS-pakket → 466 berichten (≈ $0,015 US-SMS). WhatsApp-pakket → 233 berichten (≈ $0,030 Twilio + Meta marketing). Bij saldo 0 eerst een nieuw pakket kopen. Ops SMS-unlock ($10) bevat een SMS-pakket. WhatsApp-service ($10) bevat een WhatsApp-pakket. Rekening: $10 → 466 SMS of 233 WhatsApp ($7,00 Twilio / $3,00 FloqR)."},"help-club-marketing-campaigns":{"title":"Marketingcampagnes","body":"Kies een branchesjabloon, laad achtergrond en extra afbeeldingen, bewerk tekst, sla op of verstuur. Verzenden debiteert SMS- of WhatsApp-tegoed via Messagingtegoed."},"help-club-in-app-marketing":{"title":"In-app marketing","body":"Plaats een flyer of een video van maximaal 30 seconden namens je club. Zodra hij betaald en door FLOQR goedgekeurd is, verschijnt hij op het laadscherm van Zoeken, in Mingl, RydR en op andere FLOQR-schermen. Met Advertentieplaatsers van de club laat je een teamlid advertenties plaatsen (rol Club Ad Poster). Geen sms-tegoed nodig."},"help-vip-terms-consent":{"title":"VIP reserV voorwaarden","body":"Na een tafelhold open je de Voorwaardenpagina, lees de tekst en accepteer één keer (marketing optioneel apart). Toestemming wordt opgeslagen vóór FloqR Stripe Checkout — zoals een betaalde ShoutOut, daarna bon en pass."},"help-vip-door-pass":{"title":"VIP reserV deurpass","body":"Na bevestigde borg: Mijn profiel → Reserveringen → Toon pass voor een eenmalige QR. Neem ID 21+ mee. Deurstaf gebruikt VIP reserV Door."},"help-vip-door-ops":{"title":"VIP reserV deur check-in","body":"VIP Managers openen VIP reserV Door voor vanavond. Scan of plak de token, bevestig ID 21+, check in. No-show alleen na grace. Een notify-link wijzigt de status niet."},"help-vip-payment-collector":{"title":"VIP reserV-betalingscollector & Club POS","body":"Voorkeur voor live clubs met Toast/SpotOn: Club POS — FLOQR boekt/houdt/kaart; POS beheert borg, tab en besteding. Alternatieven: Club Stripe, FloqMedia Stripe (FloqR) of VIP-engine + CSV. Aurelia (Demo Club) standaard FloqMedia Stripe — vraag BOT DEE om Master- en Club Admin-stappen."},"help-vip-table-isbooked":{"title":"VIP-tafel isBooked-status in Firestore","body":"Elke VIP-onboarded club heeft een Firestore-doc per tafelnummer en nacht: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Doc-id = gedrukt nummer (bijv. T1, B3). Na voltooide boeking: isBooked \"1\", isBookedYes \"yes\". Vrij: \"0\" / \"no\". Holds zetten isBooked niet. Annuleren → \"0\". getVipAvailability gebruikt isBooked als boekingsstatus. Annuleren zet isBooked altijd op \"0\"; FloqMedia/Club Stripe kan de storting terugbetalen per clubbeleid."},"help-vip-floqr-stripe-aurelia":{"title":"FloqMedia Stripe instellen voor Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) gebruikt FloqMedia Stripe (FloqR Checkout) als standaard VIP-borgcollector — gasten betalen op FloqR’s platform-Stripe; daarna is de tafel geboekt.\n\nMaster Admin-stappen:\n1) Open Master Admin → Features Mgmt → VIP reserV Payments.\n2) Bevestig dat VIP Reservations netwerkbreed aan staat.\n3) Seed / refresh POS-providers alleen als je later Club POS gebruikt — niet nodig voor FloqMedia Stripe.\n4) Laat Aurelia op FloqMedia Stripe staan tenzij Club POS of Club Stripe nodig is.\n5) Na borgbetalingen: Network VIP billing bekijken.\n\nClub Admin-stappen (Aurelia):\n1) Log in als temp_clubadmin_1@floqr-demo.com (e-mail-OTP op home) of Club Admin van Aurelia.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) Onder Payment collector: FloqMedia Stripe (FloqR).\n4) Houd Require deposit before table is marked booked aan.\n5) Save payment collector.\n6) Test: vip.html?location=temp-democlub-1 → tafel vasthouden → Voorwaarden → Borg betalen (testkaart 4242…).\n7) Door / facturatie: Open Door; Refresh billing.\n\nKies geen Club POS voor Aurelia-demo’s tenzij Toast/SpotOn-sandbox bewust. FloqMedia, Stripe, ShoutOut en VIP reserV blijven merknamen."}},"fr":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Une invitation Mingl Room compacte peut apparaître sur Search quand vous définissez un horaire pour une room BOT DEE, ou qu’un ami Mingl vous y a invité. L’hôte voit sa room planifiée sur Search sans la requête démo Cancun. Voir l’invitation ouvre Room SMARTview. Join Now va vers BOT DEE, pas Mingl chat. Pas maintenant masque la carte dans cet onglet ; Inbox garde Review BOT DEE invite. La requête démo Cancun est réservée au Studio. L’art est une illustration, pas une photo. Les rooms Join Now sans horaire n’apparaissent pas sur Search."},"help-smartvisuals-room":{"title":"Room SMARTview et SMARTvisuals","body":"Room SMARTview montre l’invitation Mingl : horaire, RSVP ou statut en ligne, et Join Now. Join Now sur Search ouvre BOT DEE (pas Mingl chat) avec room= et t=. SMARTstencils et SMARTbackgrounds suivent le titre autorisé — Cancun Trip utilise une illustration voyage, pas une vraie photo de Cancun. Le chat BOT DEE privé ne choisit jamais l’art. Un Ad étiqueté en dessous est un échantillon de ces tags. Vide pour chat privé ou injection ; ce n’est pas un annonceur en direct."},"help-scheduling-schedule-for":{"title":"Planification du personnel","body":"Planifiez des shifts et des bookings, puis prévenez chaque personne par Inbox, Email, SMS ou WhatsApp. Sous « Planning pour », choisissez le calendrier sur lequel vous travaillez : « Mon planning DJ » est votre propre calendrier, « Club » liste les clubs que vous gérez et « Société de promotion » les sociétés pour lesquelles vous faites la promotion. Chaque calendrier a son propre abonnement à 20 $/mois. Les shifts qui vous sont attribués apparaissent sous « Mes affectations », où vous les confirmez ou les refusez."},"help-staff-marketing-consent":{"title":"Consentement marketing du personnel","body":"Lorsque vous rejoignez l’équipe d’un lieu ou d’un événement, vous devez cocher la case de consentement marketing. Elle permet à ce lieu ou à cet organisateur, ainsi qu’à ses administrateurs et responsables, d’utiliser votre nom FLOQR, votre rôle et vos photos et vidéos publiées sur leurs sites web, flyers et réseaux sociaux (Instagram, Facebook, TikTok, YouTube et similaires) sans vous redemander votre accord à chaque utilisation. Ils ne peuvent pas publier votre numéro de téléphone ni votre e-mail. Vous pouvez retirer ce consentement à tout moment dans Mon profil, onglet Services et membres de service. Cela met fin aux nouvelles utilisations ; les supports déjà imprimés ou publiés n’ont pas à être retirés. Les Club Admins voient le statut de consentement de chaque membre du personnel dans Réseau des employés et du personnel et dans Personnel mis en avant."},"help-botdee-privacy-session":{"title":"Confidentialité et session BOT DEE","body":"La pause de cinq minutes termine la session BOT DEE en direct. Elle ne supprime pas ce chat connecté, les souvenirs ni les workflows. Les copies dans Mon profil → Fonctions et commandes → My BOT DEE restent aussi. Les invités restent éphémères. Les discussions Mingl ne sont jamais copiées ici. Entrée envoie ; Maj+Entrée commence une nouvelle ligne. Le nom et le ton se règlent dans Mon profil → My BOT DEE, pas par un bouton dans le chat."},"help-botdee-place-search":{"title":"Demander à BOT DEE des lieux FLOQR","body":"Demandez en mots simples — restaurants de sushi à Washington DC, clubs à DC, ou un club nommé. BOT DEE ne cherche que les venues FLOQR embarquées, pas Google ni Yelp. Les correspondances ouvrent une Place SMARTview compacte (nom, court texte, notes, lien page publique) avec un SMARTbackground — pas un puits photo. Nommer une ville avec VIP reserV (reservations in Miami) attache toujours Place SMARTview à côté de la carte VIP. Photos de patrons et pitches ShoutOut restent hors sujet sauf si vous les avez demandés. S’il n’y a encore rien, BOT DEE le dit."},"help-botdee-page":{"title":"BOT DEE","body":"Discutez avec BOT DEE sur la page BOT DEE en mots simples : événements et clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, votre profil, les plannings du personnel ou les outils Club Admin. Appuyez sur Entrée pour envoyer ; Maj+Entrée commence une nouvelle ligne. BOT DEE discute comme une personne (essayez How are you?) et ne cherche que lorsque vous demandez comment faire quelque chose dans FLOQR. Si vous êtes connecté, BOT DEE conserve cette discussion si vous actualisez ou ouvrez un autre téléphone, et après la pause il peut reprendre l’historique enregistré. La pause ne supprime pas le chat. Les réponses respectent la classification de votre compte. Connecté, BOT DEE voit les mêmes datapoints publics volontaires que vous (musique, nourriture, voyage, hobbies et le reste de Privacy datapoint sharing) — jamais e-mail, téléphone, données de carte ou GPS. Touchez Réglages sous la zone de chat pour les discussions et souvenirs enregistrés. Touchez une photo du chat pour l’ouvrir dans une fenêtre. Fermez avec X ou Fermer pour revoir le chat. Le + en haut à droite ouvre les chats enregistrés sans les supprimer."},"help-botdee-smartview-troubleshoot":{"title":"Dépannage SMARTview","body":"Carte vide : champs masqués ou blocage. Échec d’enregistrement : reconnectez-vous — les traductions sont sur le serveur. Traduction en attente ou en échec : langue source étiquetée. Seul le titulaire édite. SMARTviews Master Admin reste le catalogue mock ; Places et Yelp restent coupés. Le thème suit Site Chrome."},"help-botdee-smartcard-sync":{"title":"Le SMARTsummary reste synchronisé","body":"Modifiez votre SMARTsummary dans la langue par défaut du profil. L’enregistrement est immédiat. Les cartes et SMARTview déjà ouverts se mettent à jour depuis le même enregistrement. Les traductions partent en arrière-plan et n’écrasent pas une édition plus récente. Si vous masquez le profil, bloquez quelqu’un ou supprimez le compte, les cartes disparaissent. Gemini n’écrase pas votre texte."},"help-botdee-smartcard-search":{"title":"Demander à BOT DEE qui est quelqu’un","body":"« Who am I ? » ouvre votre SMARTview. « Who is … », « What do you know of … » ou « What about … » plus prénom, nom, nom d’affichage, identifiant Mingl ou FloqR, ou un identifiant social (Instagram, TikTok, X). La recherche ne porte que sur ces champs d’identité — pas la bio, les likes, les boissons ni les genres. Un résultat ouvre une carte People SMARTview dans le chat — pas une liste markdown ni une grille de photos. Plusieurs résultats montrent des SMARTcards compactes. Les profils privés, bloqués ou non publiés n’apparaissent pas — BOT DEE ne confirme pas l’existence du compte."},"help-botdee-smartcard":{"title":"SMARTcards Personnes","body":"Quand plusieurs profils publics FLOQR correspondent, BOT DEE affiche des SMARTcards compactes dans le chat : photo pleine largeur d’abord, puis nom et identifiant, puis un SMARTsummary compact sans boîte remplie. Touchez une carte pour ouvrir le SMARTview complet — même empilement. Les cartes utilisent le même profil public et le même SMARTsummary que SMARTview. Ouvrir une carte n’appelle pas Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Saisissez Ver, Vers ou Version — les majuscules ne comptent pas. BOT DEE affiche la carte de version. Une question plus longue comme « quelle est votre version ? » affiche aussi cette carte."},"help-botdee-version-smartview-status":{"title":"L’état Version SMARTview est une sonde live","body":"L’état du service est sondé sur cette requête Version : Functions et package joignables avec Gemini configuré → Opérationnel ; Functions et package OK mais Gemini non configuré → Dégradé ; Functions absentes de cette requête → Indisponible. Jamais un libellé statique Non vérifié. Le modèle d’IA affiche l’identifiant Gemini configuré pour ce déploiement même si ce tour n’a pas généré. Les tampons frontend et backend peuvent différer ; les deux sont étiquetés. Master Admin peut voir des diagnostics sous Détails techniques — pas les patrons."},"help-botdee-version-smartview-tabs":{"title":"Onglets Version SMARTview","body":"Aperçu décrit BOT DEE et ouvre les Détails techniques sans quitter le chat. Nouveautés n’affiche que les changements BOT DEE et Gemini vérifiés — pas Master Admin, les outils bêta-testeur, ni les autres notes produit FLOQR. Aide répète la commande Ver / Vers / Version. Changer d’onglet ou déplier garde le brouillon non envoyé et le défilement. La carte utilise votre Site Chrome — pas de second thème."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Dans le chat BOT DEE, dites Open Room SMARTview, Start a group chat, ou planifiez un voyage à Cancun en mots simples. Ensuite : Rejoindre maintenant ou Définir un horaire. Rejoindre maintenant ouvre une session d’amis Mingl tout de suite et ne met pas de carte sur Search. Définir un horaire, c’est le début de la room BOT DEE — pas Shared Itinerary — et active SMARTnotification Search pour vous et les amis Mingl invités. Invitez seulement des amis Mingl — hôte plus 7 invités. Les invités peuvent aussi inviter. Rejoindre n’est pas un paiement et n’ouvre pas d’addition partagée. BOT DEE ne prend jamais de numéros de carte. Les messages BOT DEE privés restent privés. Site Chrome suit Appearance. Une room en ligne reste ouverte jusqu’à End Room, environ quatre heures après l’ouverture, ou si tout le monde est parti depuis environ 15 minutes. La pause du chat BOT DEE privé est séparée."},"help-botdee-room-smartview-invite":{"title":"Inviter des amis Mingl","body":"Après Confirm (Join Now ou Set a schedule), Invite n’affiche que vos amis Mingl. Touchez un ami ou tapez Invite lorna — Inbox reçoit Review BOT DEE invite. La puce reste grisée avec Invite sent — un second tap n’envoie pas une deuxième invitation. C’est une commande Room SMARTview, pas VIP reserV ni People SMARTview Invite. Ce n’est pas un lien public. Capacité : hôte plus 7. Les invités peuvent inviter d’autres amis Mingl sauf si l’hôte désactive cela. Rejoindre n’est pas un paiement. Si une puce est vous ou quelqu’un déjà dans la session, elle reste marquée C’est vous ou Déjà dans cette session et n’envoie pas une deuxième invitation."},"help-botdee-room-smartview-join":{"title":"Rejoindre une session BOT DEE","body":"Ouvrez l’invitation Inbox ou Search Join Now connecté comme l’ami Mingl destinataire. Join Now ouvre BOT DEE, pas Mingl chat. Vous et les amis Mingl invités partagez le chat de groupe Room SMARTview ; les noms s’affichent pour les membres. Mauvais compte, expiration ou révocation refuse. Rejoindre la room n’est pas rejoindre une addition et n’approuve pas un paiement. BOT DEE ne prend jamais de numéros de carte."},"help-botdee-room-smartview-end":{"title":"Terminer Room SMARTview","body":"Seul l’hôte peut terminer une room. Terminer ne facture personne et n’efface pas les chats privés des autres. Une addition partagée impayée doit d’abord être payée ou annulée. Une room en ligne reste ouverte jusqu’à End Room, environ quatre heures après l’ouverture, ou si tout le monde est parti depuis environ 15 minutes. La pause du chat BOT DEE privé n’est pas une déconnexion de room. Un invité qui part ne termine pas la room tant que l’hôte est présent."},"help-botdee-room-smartview-tab":{"title":"Addition partagée Room SMARTview","body":"D’abord l’opt-in. Puis ajoutez une ligne. Fermez en un payeur ou en partage. Seuls les uid qui confirment sont débités via FloqR Stripe. Rejoindre la room n’est pas rejoindre l’addition. BOT DEE ne prend jamais de numéros de carte. Club POS plus tard."},"help-botdee-room-smartview-who-pays":{"title":"Qui paie","body":"Demandez Who’s paying dans Room SMARTview pour voir l’opt-in. Personne n’est débité parce que quelqu’un a dit buy. Les quatre derniers chiffres restent sur le reçu du payeur."},"help-botdee-room-smartview-kick":{"title":"Retirer quelqu’un de Room SMARTview","body":"Seul l’hôte peut retirer un invité. Un ami retiré ne lit plus les messages de la room. Une réponse du modèle ne peut exclure personne."},"help-botdee-room-smartview-share":{"title":"Partager dans Room SMARTview","body":"Share this conversation ne copie jamais votre fil BOT DEE privé. BOT DEE montre un aperçu de faits partageables de ce message, marqués provisoires. Vous pouvez modifier ou retirer des faits. Profils et SMARTsummary restent hors de la room."},"help-botdee-room-smartview-schedule":{"title":"Rejoindre maintenant ou définir un horaire","body":"Après la configuration Room SMARTview, choisissez Rejoindre maintenant ou Définir un horaire. Rejoindre maintenant ouvre la session BOT DEE tout de suite et ne met pas de carte sur Search. Définir un horaire, c’est le début de la room BOT DEE — pas Shared Itinerary. Une heure future active SMARTnotification Search pour vous et les amis Mingl invités seulement. Les invités RSVP jusqu’à ce que la room soit en ligne ; Join Now ouvre alors BOT DEE (pas Mingl chat)."},"help-botdee-room-collab":{"title":"Partager une réservation headless dans Room SMARTview","body":"Dans une Room SMARTview, les choix VIP reserV ou ShoutOut de l’hôte apparaissent pour tout le monde. Les membres votent Oui ou Non. Hold it et le paiement restent à l’hôte — rejoindre et voter n’est pas un paiement. BOT DEE ne prend jamais de numéros de carte. Stripe s’ouvre dans un pop-out."},"help-botdee-room-elect-host":{"title":"Élire un hôte Room SMARTview","body":"N’importe qui dans la session peut être hôte. Proposez-vous ou un autre membre. Un candidat devient hôte à 60 % des membres actuellement présents (arrondi supérieur). Si l’hôte part, les autres élisent un nouvel hôte — la room reste ouverte. Kick et End restent à l’hôte élu."},"help-botdee-smartview-review":{"title":"Relire et corriger un SMARTsummary","body":"Gemini rédige uniquement à partir des champs publics dans FLOQR — jamais à chaque vue. Si un fait est faux, masquez le champ dans la visibilité du profil ou modifiez le résumé. Un texte rédigé par vous n’est pas écrasé. Un conflit de profil demande une relecture. Signalez une carte incorrecte depuis l’overlay."},"help-botdee-smartview-chrome":{"title":"SMARTview et Site Chrome","body":"Le SMARTview personne utilise le Site Chrome FLOQR du visiteur (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Pas de second thème. Changer le chrome met à jour la carte sans perdre le brouillon."},"help-botdee-smartview-categories":{"title":"Catégories SMARTview","body":"Quatre onglets : Social, Rencontre, Cuisine, Voyages à venir. Social s’ouvre sur Musique, puis Nightlife, Sports et Événements. Les tags sont uniquement ce que vous avez partagé — pas de titres en double ni de voyages ou notes inventés. Les voyages à venir n’affichent que les destinations publiques."},"help-botdee-smartview-media":{"title":"Photos et vidéos SMARTview","body":"La carte compacte utilise le même visuel que votre profil public FLOQR — le premier élément Médias du profil (8 photos + 2 vidéos). Appuyez pour Photos et Vidéos depuis ces emplacements publics. Balayez ou flèches, puis X (ou Échap) pour retrouver le chat et le brouillon."},"help-botdee-smartview-privacy":{"title":"Confidentialité SMARTview","body":"SMARTview n’affiche que les champs déjà publics dans FLOQR. Ce n’est pas une recherche web. La rencontre n’apparaît qu’avec opt-in. Masquez un champ dans Mon profil et il quitte SMARTview. Les personnes bloquées ne voient pas la carte. Signalez un résumé incorrect depuis l’overlay."},"help-botdee-smartview-translation":{"title":"Traduction SMARTview","body":"Votre SMARTsummary est enregistré dans la langue par défaut du profil — c’est la source, même si ce n’est pas l’anglais. Après enregistrement, FLOQR met en file une traduction vers chaque autre langue, y compris l’anglais. Un visiteur anglais voit le SMARTsummary en anglais une fois ce travail terminé. En attente ou en échec, les lecteurs voient la langue source clairement indiquée — jamais une traduction périmée comme actuelle."},"help-botdee-smartview-edit":{"title":"Modifier votre SMARTsummary","body":"Vous seul pouvez modifier votre SMARTsummary, dans la langue par défaut du profil. L’enregistrement est immédiat. Les traductions partent en arrière-plan. Gemini n’écrase pas un texte que vous avez modifié. Si le profil public change, FLOQR vous demande de relire le résumé."},"help-botdee-privacy-assistant":{"title":"Assistant confidentialité BOT DEE","body":"Changez ce que les autres utilisateurs FLOQR voient dans la visibilité de Mon profil — BOT DEE n’ajoute pas un second interrupteur public. Si la recherche web a lié la mauvaise personne, vous pouvez contester sans changer votre profil. BOT DEE ne promet pas qu’un site tiers supprimera la page d’origine."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Chaque recommandation peut montrer les preuves, la date de vérification, si la personnalisation était active, et si un emplacement est sponsorisé. Vous pouvez demander à BOT DEE de ne pas personnaliser cette recherche."},"help-botdee-research-library":{"title":"Bibliothèque de recherche BOT DEE","body":"Enregistrez les lieux et cartes demandés à BOT DEE. Un identifiant Google Place n’est pas une copie des photos ou avis Google. Vous pouvez actualiser ou supprimer. Les caches licenciés restent off tant que le fournisseur n’est pas approuvé."},"help-botdee-smartview":{"title":"Voir mon SMARTview","body":"Voir mon SMARTview affiche votre carte Personne depuis les champs publics FLOQR, avec les mêmes Médias du profil que la page publique — pas des maquettes de club ou restaurant. Modifier mon SMART Summary change le résumé dans la langue du profil. Les maquettes club/restaurant sont dans Master Admin → Features → BOT DEE → SMARTviews. Pas de Places ni Yelp en direct."},"help-botdee-memory":{"title":"Chats BOT DEE enregistrés","body":"Ouvrez Fonctionnalités et commandes → Mon BOT DEE pour enregistrer les chats après la pause, exporter ou supprimer l’historique. La pause de cinq minutes termine la session en direct. Si vous acceptez, BOT DEE conserve le chat. Les invités ne sont pas enregistrés. Mingl reste dans Mingl."},"help-botdee-knows-of-me":{"title":"Ce que BOT DEE sait de moi","body":"Les faits enregistrés avec votre accord se trouvent dans Fonctionnalités et commandes → Mon BOT DEE. La liste est vide si la mémoire est désactivée ou vide. Exportez ou supprimez ici. BOT DEE n’enregistre jamais votre adresse IP. Mingl n’est pas copié."},"help-search-settings-appearance":{"title":"Settings sur Search","body":"Sur l’écran Search, touchez Settings pour ouvrir Profile & Settings sur l’onglet Appearance — le Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green) s’y trouve. La tuile Settings utilise le même pack d’icônes chrome que les autres marques Search."},"help-club-website-feed":{"title":"Flux pour le site du club","body":"Affichez votre page de club FLOQR publiée sur votre propre site. Appuyez sur « Générer la clé et les liens », puis collez le code iframe dans votre site ou donnez le lien JSON ou RSS à votre webmaster. Le flux montre les événements à venir, les DJ et le personnel mis en avant, la galerie et les coordonnées, selon vos réglages de page publique. Les photos du personnel n’apparaissent que si le consentement photo est confirmé. Générer une nouvelle clé désactive les anciens liens, y compris ceux du planning du personnel."},"help-featured-staff":{"title":"Personnel mis en avant","body":"Cochez les membres du personnel à afficher sur la page publique du club. Pour chaque personne, touchez une de ses photos FLOQR ou choisissez « Importer depuis l’ordinateur ». Vous pouvez modifier le rôle affiché sous son nom. Appuyez sur « Save Public Profile » pour publier. Avant de publier des photos, obtenez l’accord de chaque personne et cochez la case de consentement photo."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox contient les System Messages et les messages de support internes. La liste se charge d’abord pour afficher vos messages rapidement. Appuyez sur le bouton flottant New Message pour composer — saisissez un nom ou @username pour trouver un destinataire autorisé (Club Admin, CSR ou personnel approuvé). Le chat patron-à-patron reste dans Mingl après un Mingl mutuel. Ouvrir une invitation de shift ne confirme pas — examinez et Approve selected sur Work Calendar."},"botdee-ask-floqr":{"title":"Demandez FloqR avec BOT DEE","body":"Demandez FloqR avec BOT DEE — appuyez sur la marque animée ou attendez l'invite, puis décrivez ce que vous voulez en mots simples. Produits : Mingl, RydR, BartR, ShoutOut, FloqCAST (superstar), clubs. Objectifs : dites « je veux pouvoir… » (par ex. devenir Club Admin) ou « make me a superstar » pour les étapes et les liens."},"help-vip-book-table":{"title":"Réserver une table VIP (VIP reserV)","body":"VIP reserV explore le plan et réserve une table. Ouvrez VIP reserV depuis Recherche, choisissez Decades ou Lima Twist Club et une soirée, touchez une table verte, réservez 30 minutes, acceptez les Conditions et payez l’acompte avec FloqR Stripe. Bars et DJ non réservables. La marque VIP reserV n’est pas traduite. À Aurelia, utilisez Explore 3D walk-through pour la salle interactive (la réservation reste sur le plan 2D)."},"help-vip-choose-venue":{"title":"Choisir un lieu VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club et Aurelia ont chacun un plan 2D publié ; Aurelia propose aussi Explore 3D walk-through."},"help-become-club-admin":{"title":"Devenez un Club Admin","body":"Demandez un accès Club Admin, puis obtenez l'approbation du lieu."},"help-role-profiles":{"title":"Présentation des profils de rôle","body":"Découvrez comment fonctionnent les rôles Club Admin, DJ, Promoter et d'accueil."},"help-staff-scheduling":{"title":"Calendrier et planificateur","body":"Le calendrier Club Admin affiche les cartes Brouillon (violet), En attente (ambre), Confirmé (vert) et Ouvert/non pourvu — chacune avec un statut écrit, pas seulement une couleur. Scheduler est la grille personnes × jours pour brouillon/publication. Website ingest / publicVenueCalendar ne renvoie que les affectations Confirmées. Une pastille verte Paid this month s'affiche pour les Club Admins quand staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Abonnements aux notifications Club SMS et WhatsApp","body":"Club Admin → Notifications : Send test alert utilise les cases actuellement cochées. L'application (et Push) écrit un message système en FloqR Inbox. Le courrier électronique utilise les adresses d'administrateur du club. SMS et WhatsApp ont toujours besoin d'un abonnement payant et d'un téléphone d'alerte E.164. Pilule verte = Firebase abonnement 1 (pack prépayé de 10$) ; rouge = 0. Si Send test alert renvoie Authentication Error - invalid username, Firebase secret TWILIO_ACCOUNT_SID doit être le SID du compte commençant par AC (34 caractères) de console.twilio.com — pas le jeton d'authentification ni une clé API (SK)."},"help-club-sms-notification":{"title":"Abonnement aux notifications SMS","body":"La pastille SMS est verte lorsque Firebase smsSubscribed vaut 1 (pack prépayé 10 $, 466 crédits, ni mensuel ni annuel). Rouge/clignotant signifie 0 — ouvrez ? et appuyez sur Subscribe $10. Les crédits restants et la date du dernier paiement sont dans cette aide. Décochez SMS et Save pour suspendre les alertes sans perdre le pack payé."},"help-club-whatsapp-notification":{"title":"Abonnement aux notifications WhatsApp","body":"La pastille WhatsApp est verte lorsque Firebase whatsappSubscribed vaut 1 (pack prépayé 10 $, 233 crédits, ni mensuel ni annuel). Rouge/clignotant signifie 0 — ouvrez ? et appuyez sur Subscribe $10. Les crédits restants et la date du dernier paiement sont dans cette aide. Décochez WhatsApp et Save pour suspendre les alertes sans perdre le pack payé."},"help-schedule-message-templates":{"title":"Modèles de messages de planning","body":"Club Admin → Notifications → Message templates. Ce sont des System Messages (Inbox / Email / SMS / WhatsApp), pas des ShoutOuts. Modifiez le titre et le texte pour New shift needs confirmation, Schedule update, Shift confirmed et Shift declined. Placeholders : {club} {role} {when} {link} {worker}. La boîte Inbox du travailleur utilise Review & confirm shift — jamais Open Related ShoutOut."},"help-schedule-confirm":{"title":"Confirmer les shifts assignés","body":"Les liens Inbox / Email / SMS ouvrent Work Calendar. Examinez chaque affectation en attente, cochez-la (ou Select all), puis Approve selected. Ouvrir le lien ne confirme pas. Seul le service member assigné peut approuver — un Club Admin ne peut pas confirmer à sa place."},"help-template-catalog-report":{"title":"Rapport de catalogue de modèles","body":"Répertorie chaque ShoutOut type de modèle et les tailles de LED qu'il prend en charge (Is96x48, Is64x48, Is64x32). Un lieu ne propose un modèle que lorsqu'au moins un de ces indicateurs est 1 et que l'indicateur VenueSupports* correspondant est 1. Les modèles d'anniversaire/média partagé sont 1 sur 96×48, 64×48 et 64×32. 96×48 correspond à 3 lignes côte à côte ; 64×48 et 64×32 bouclent la photo puis le cri sur 3 lignes avec une carte FLOQR + poignée."},"help-club-display-screens":{"title":"FLOQR écrans d'affichage","body":"Firebase clubLocations stocke VenueSupports96x48, VenueSupports64x48 et VenueSupports64x32 sous la forme 0 ou 1. Les modèles stockent Is96x48, Is64x48 et Is64x32 de la même manière. Un lieu ne répertorie un modèle que lorsqu'au moins une paire vaut 1. Les URL Xibo restent display.html?location=id et display2.html?location=id — la taille de l'écran n'est pas dans l'URL. Anniversaire est proposé dans les trois tailles (3 lignes côte à côte sur 96×48 ; boucle photo/cri sur 64×48 et 64×32). Le principal est display.html. Le secondaire est display2.html."},"help-staff-week-calendar":{"title":"Planificateur","body":"Club Admin Scheduler est une grille de personnes × jours par semaine. Save shift ferme l'éditeur avec Schedule card successfully saved. Créez des brouillons, Publish schedule pour que les employés confirment en attente jusqu'à confirmation, Select shifts pour effectuer des suppressions multiples et Website ingest pour mettre les équipes publiées sur le site du club. Fenêtre de changement par défaut = club ouvert − 2 heures jusqu'à la fermeture + 1 heure."},"help-staff-schedule-user-guide":{"title":"Guide de l'utilisateur de la planification du personnel","body":"Ouvrez le ? à côté de Planificateur dans Club Admin Planification. Créez des brouillons d'équipes, Publish schedule pour que les travailleurs confirment en attente → confirmé, puis Select shifts pour en supprimer plusieurs à la fois. Exemple : toutes les drafts du mercredi plus un jeton confirmé le jeudi."},"help-create-publish-schedule":{"title":"Créer et publier un planning du personnel","body":"Ajoutez des équipes de brouillon sur la grille personnes × jours, examinez les puces, puis Publish schedule. Les travailleurs doivent confirmer avant qu'un quart de travail soit confirmé. BOT DEE : create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Supprimer plusieurs équipes planifiées ou brouillons","body":"Select shifts, mélangez les têtes de jour et les chips, puis Delete selected. Exemple : toutes les ébauches du mercredi plus une équipe confirmée du jeudi."},"help-staff-worksheet":{"title":"Feuille de travail - Calendrier hebdomadaire du personnel","body":"Les militaires élus ouvrent Work Calendar dans Paramètres. Les liens de confirmation Inbox / Email / SMS atterrissent ici. Vérifiez les missions en attente, cochez chaque équipe (ou Select all), puis Approve selected — l'ouverture du message ne confirme pas. La grille hebdomadaire montre les quarts de travail publiés des collègues. Les brouillons restent en Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Tout le monde commence comme patron FLOQR. Dans My Profile & Settings, appuyez sur Elect to become a service member pour ouvrir cet onglet. Choisissez votre rôle (Waitress, DJ, Promoter, etc.), sélectionnez un ou plusieurs clubs, puis soumettez en bas de page.\n\nGuide des modèles de profil — les profils sociaux patron restent dans Médias publics. Chaque rôle de service a son modèle sur Mon profil (Patron, Promoter, DJ, Waitress, Bus Boys or Security, Venue Manager).\n\nApprobation Club Admin — chaque Club Admin approuve après votre envoi : Club Admin → Employee/Workers → Pending Worker Requests, ou Réviser et élire sur cet onglet."},"help-venue-website-ingest":{"title":"Ingestion du site Web du club (API, RSS, iframe)","body":"Club Admin → Planification → Website ingest. Générez un secret (affiché une fois ; seul un hachage est stocké). Affichez les équipes publiées sur le site Web officiel du club avec JSON (?format=json&dataset=schedule|hours|profile|all), RSS ou un extrait iframe. Les brouillons, les e-mails et les numéros de téléphone des employés ne sont jamais inclus. Faites pivoter le secret s’il fuit."},"help-venue-hours-calendar":{"title":"Horaires d'ouverture du lieu","body":"Sur le profil public du club, définissez les heures d'ouverture/fermeture hebdomadaires par défaut, puis ajoutez des remplacements de période pour les semaines spéciales sans perdre la valeur par défaut. La page du club public affiche une grille hebdomadaire du dimanche au samedi avec la plage de dates (par exemple du dimanche 9 au samedi 15 août 2026) et la coloration du calendrier. Les jours fériés à venir répertorient les heures d'ouverture et de fermeture et avertissent lorsqu'elles diffèrent du jour de semaine habituel. Staff Scheduling utilise l'ouverture − 2h jusqu'à la fermeture + 1h. La liste d'invités peut suggérer des soirées portes ouvertes."},"help-club-admin-affiliation":{"title":"Club Admin affectation du lieu","body":"Les 3 joueurs n'ouvrent le Venue Command Center que pour le club auquel ils sont affectés. L'ouverture de admin.html sans lieu n'est plus par défaut Zebbies. Les comptes de démonstration temp_clubadmin_N@floqr-demo.com correspondent à temp-democlub-N. Les administrateurs non attribués demandent une affectation à Master Admin."},"help-venue-command-center":{"title":"Centre de commande du lieu","body":"Approuvez les ShoutOuts, suivez les performances du lieu et rapprochez l'activité de ce club."},"help-club-template-repository":{"title":"Les modèles de votre club","body":"Les modèles créés uniquement pour votre club apparaissent en premier avec la mention « Exclusif à » suivie du nom du lieu. Les modèles attribués sont ceux que les clients peuvent choisir dans votre club ; modifiez-les avec Attribuer ou Retirer le modèle. La recherche trouve un modèle même sans accent ou avec une petite faute de frappe."},"help-employee-network":{"title":"Réseau des employés et du personnel","body":"Seules les personnes liées à ce club sont listées : personnel désigné ou approuvé ici, admins du club et personnel affilié à ce club. Pour donner un rôle à quelqu’un, saisissez son nom, son nom d’utilisateur ou son e-mail sous Attribuer un rôle à un client, appuyez sur Sélectionner à côté de la bonne personne, choisissez le rôle, puis appuyez sur Attribuer le rôle au client sélectionné et confirmez. La personne doit d’abord avoir un compte client FLOQR. Les serveurs, serveuses et bottle girls de la liste peuvent devenir représentants du service client (CSR)."},"help-template-tags":{"title":"Tags des modèles","body":"Ajoutez des mots que les clients pourraient taper pour trouver un modèle dans votre lieu, comme soirée match ou anniversaire. Les Gestionnaires des modèles peuvent ajouter des tags. Les Administrateurs des modèles et les Club Admins peuvent aussi en retirer. Le Club Admin attribue ces rôles dans Role Activity & Permission."},"help-display-idle-default":{"title":"Écran d’attente : Use ShoutOut @ lieu","body":"Quand aucun ShoutOut n’est diffusé, Display 1 affiche « Use ShoutOut @ » suivi du nom de votre lieu. Chaque ShoutOut approuvé passe 10 minutes, puis l’écran revient seul à ce message. La réinitialisation de l’affichage par défaut dans Club Admin le fait immédiatement."},"help-club-messaging-credit":{"title":"Crédit SMS et WhatsApp","body":"Chaque pack à 10 $ finance 7,00 $ de capacité Twilio ; FloqR conserve 3,00 $ de marge plateforme. Pack SMS → 466 messages (≈ 0,015 $ SMS US tout compris). Pack WhatsApp → 233 messages (≈ 0,030 $ Twilio + Meta marketing). À 0, achetez un nouveau pack avant d’envoyer. Le déblocage SMS ops (10 $) inclut un pack SMS. Le service WhatsApp (10 $) inclut un pack WhatsApp. Calcul : 10 $ → 466 SMS ou 233 WhatsApp (7,00 $ Twilio / 3,00 $ FloqR)."},"help-club-marketing-campaigns":{"title":"Campagnes marketing","body":"Choisissez un modèle sectoriel, ajoutez images de fond et extras, modifiez le texte, puis enregistrez ou envoyez. L’envoi débite les crédits SMS ou WhatsApp depuis Crédit messagerie."},"help-club-in-app-marketing":{"title":"Marketing in-app","body":"Publiez un flyer ou une vidéo de 30 secondes maximum au nom de votre club. Une fois payée et approuvée par FLOQR, elle s'affiche sur l'écran de chargement de la recherche, dans Mingl, RydR et sur d'autres écrans FLOQR. Publicateurs d'annonces du club permet à un membre de l'équipe de publier pour le club (rôle Club Ad Poster). Aucun crédit SMS nécessaire."},"help-vip-terms-consent":{"title":"Conditions VIP reserV","body":"Après avoir retenu une table, ouvrez la page Conditions, lisez le texte, et acceptez une seule fois (marketing optionnel à part). Le consentement est enregistré avant FloqR Stripe Checkout — même schéma qu’un ShoutOut payant, puis reçu et pass."},"help-vip-door-pass":{"title":"Pass porte VIP reserV","body":"Après confirmation de l’acompte, Mon profil → Réservations → Afficher le pass pour un jeton QR unique. Apportez une ID 21+. Le personnel utilise VIP reserV Door."},"help-vip-door-ops":{"title":"Enregistrement porte VIP reserV","body":"Les VIP Managers ouvrent VIP reserV Door pour ce soir. Scannez ou collez le jeton, confirmez ID 21+, enregistrez. No-show seulement après grâce. Un lien notify ne change pas le statut."},"help-vip-payment-collector":{"title":"Collecteur de paiement VIP reserV et Club POS","body":"Préféré pour les clubs live avec Toast/SpotOn : Club POS — FLOQR réserve/maintient/carte ; le POS gère acompte, addition et dépenses. Alternatives : Club Stripe, FloqMedia Stripe (FloqR), ou moteur VIP + CSV. Aurelia (Demo Club) utilise FloqMedia Stripe par défaut — demandez à BOT DEE les étapes Master Admin et Club Admin."},"help-vip-table-isbooked":{"title":"Statut isBooked des tables VIP dans Firestore","body":"Chaque club VIP onboardé a un doc Firestore par numéro de table et par soirée : clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. L’id du doc est le numéro imprimé (ex. T1, B3). Après réservation complète, isBooked = \"1\" et isBookedYes = \"yes\". Tables libres : \"0\" / \"no\". Les holds ne changent pas isBooked. Annulation → \"0\". getVipAvailability utilise isBooked comme statut de réservation. L’annulation remet toujours isBooked à \"0\" ; FloqMedia/Club Stripe peut rembourser le dépôt selon la politique du club."},"help-vip-floqr-stripe-aurelia":{"title":"Configurer FloqMedia Stripe pour Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) utilise FloqMedia Stripe (FloqR Checkout) comme collecteur d’acompte VIP par défaut — les patrons paient sur le Stripe plateforme FloqR, puis la table passe en réservée.\n\nÉtapes Master Admin :\n1) Ouvrir Master Admin → Features Mgmt → VIP reserV Payments.\n2) Vérifier que VIP Reservations est activé pour le réseau (Features & Services / Release Control si besoin).\n3) Seed / refresh des fournisseurs POS seulement si vous activez Club POS plus tard — inutile pour FloqMedia Stripe.\n4) Laisser Aurelia sur FloqMedia Stripe sauf besoin Club POS ou Club Stripe.\n5) Après les acomptes, ouvrir VIP reserV Payments → Network VIP billing pour les règlements / factures FloqR.\n\nÉtapes Club Admin (Aurelia) :\n1) Se connecter en temp_clubadmin_1@floqr-demo.com (OTP e-mail sur l’accueil) ou compte Club Admin Aurelia.\n2) Ouvrir Club Admin → VIP reserV (location=temp-democlub-1).\n3) Sous Payment collector, choisir FloqMedia Stripe (FloqR).\n4) Garder Require deposit before table is marked booked coché pour les démos.\n5) Enregistrer Save payment collector.\n6) Test : vip.html?location=temp-democlub-1 → retenir une table → Conditions → Payer l’acompte (carte test Stripe 4242…).\n7) Door / facturation : Open Door pour le check-in ; Refresh billing pour les relevés.\n\nNe choisissez pas Club POS pour les démos Aurelia sauf connexion sandbox Toast/SpotOn volontaire. FloqMedia, Stripe, ShoutOut et VIP reserV restent des marques non traduites."}},"de":{"help-smartvisuals-notification":{"title":"Mingl Room SMARTnotification","body":"Eine kompakte Mingl-Room-Einladung kann auf Search erscheinen, wenn Sie einen Zeitplan für eine BOT DEE-Room setzen oder ein Mingl-Freund Sie eingeladen hat. Der Host sieht die eigene geplante Room auf Search ohne die Cancun-Demo-Abfrage. Einladung ansehen öffnet Room SMARTview. Join Now geht zu BOT DEE, nicht Mingl-Chat. Nicht jetzt blendet die Karte in diesem Tab aus; Inbox behält Review BOT DEE invite. Die Cancun-Demo-Abfrage ist nur Studio. Kunst ist Illustration, kein Foto. Join-Now-Rooms ohne Zeitplan erscheinen nicht auf Search."},"help-smartvisuals-room":{"title":"Room SMARTview mit SMARTvisuals","body":"Room SMARTview zeigt die Mingl-Einladung: Zeitplan, RSVP oder Live-Status und Join Now. Join Now auf Search öffnet BOT DEE (nicht Mingl-Chat) mit room= und t=. SMARTstencils und SMARTbackgrounds folgen dem autorisierten Room-Titel — Cancun Trip nutzt Reisekunst, kein echtes Cancun-Foto. Privater BOT DEE-Chat wählt nie die Kunst. Ein beschriftetes Ad darunter ist ein Muster aus diesen Tags. Leer bei privatem Chat oder Injektion; kein Live-Werber."},"help-scheduling-schedule-for":{"title":"Mitarbeiterplanung","body":"Plane Schichten und Bookings und benachrichtige jede Person per Inbox, Email, SMS oder WhatsApp. Unter „Planen für“ wählst du, wessen Kalender du bearbeitest: „Mein DJ-Plan“ ist dein eigener Kalender, „Club“ zeigt die Clubs, die du verwaltest, und „Promo-Firma“ die Firmen, für die du promotest. Jeder Kalender hat sein eigenes Abo für 20 $/Monat. Schichten für dich erscheinen unter „Meine Einsätze“, wo du sie bestätigst oder ablehnst."},"help-staff-marketing-consent":{"title":"Marketing-Einwilligung für Personal","body":"Wenn du dem Team einer Location oder eines Events beitrittst, musst du das Feld zur Marketing-Einwilligung anhaken. Damit dürfen diese Location oder dieser Veranstalter sowie deren Admins und Manager deinen FLOQR-Namen, deine Rolle und deine veröffentlichten Fotos und Videos auf ihren Websites, Flyern und in sozialen Medien (Instagram, Facebook, TikTok, YouTube und ähnliche) nutzen, ohne dich für jede Nutzung erneut zu fragen. Deine Telefonnummer und E-Mail dürfen sie nicht veröffentlichen. Du kannst jederzeit in Mein Profil im Tab Services und Service-Mitglieder widerrufen. Das stoppt neues Marketing; bereits gedruckte oder gepostete Materialien müssen nicht zurückgerufen werden. Club Admins sehen den Einwilligungsstatus jeder Person im Mitarbeiter- und Personalnetzwerk und bei Hervorgehobenes Personal."},"help-botdee-privacy-session":{"title":"BOT DEE Datenschutz und Sitzung","body":"Die fünfminütige Pause beendet die Live-Sitzung. Sie löscht nicht diesen angemeldeten Chat, Erinnerungen oder Workflows. Optionale Kopien unter Mein Profil → Funktionen & Bestellungen → My BOT DEE bleiben. Gäste bleiben flüchtig. Mingl-Chats werden hier nie kopiert. Enter sendet; Umschalt+Enter beginnt eine neue Zeile. Name und Ton stellst du unter Mein Profil → My BOT DEE ein, nicht per Schaltfläche im Chat."},"help-botdee-place-search":{"title":"BOT DEE nach FLOQR-Locations fragen","body":"Fragen Sie in einfachen Worten — Sushi-Restaurants in Washington DC, Clubs in DC oder einen Clubnamen. BOT DEE sucht nur onboardete FLOQR-Venues, nicht Google oder Yelp. Treffer öffnen eine kompakte Place SMARTview (Name, Kurztext, Bewertungen, Public-Page-Link) mit SMARTbackground — keinen Fotoschacht. Eine Stadt mit VIP reserV (reservations in Miami) hängt Place SMARTview weiter neben der VIP-Karte an. Patron-Fotos und ShoutOut-Pitches bleiben weg, außer Sie haben danach gefragt. Ist noch nichts onboardet, sagt BOT DEE das."},"help-botdee-page":{"title":"BOT DEE","body":"Chatte mit BOT DEE auf der BOT DEE-Seite in einfachen Worten: Events und Clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, dein Profil, Mitarbeiterpläne oder Club-Admin-Werkzeuge. Enter sendet die Nachricht; Umschalt+Enter beginnt eine neue Zeile. BOT DEE chattet wie ein Mensch (versuch How are you?) und sucht nur, wenn du fragst, wie man etwas in FLOQR macht. Wenn du angemeldet bist, behält BOT DEE diesen Chat beim Aktualisieren oder auf einem zweiten Handy, und nach der Pause den gespeicherten Verlauf fortsetzen. Die Pause löscht den Chat nicht. Antworten nutzen die Klassifizierung deines Kontos. Angemeldet sieht BOT DEE dieselben freiwillig öffentlichen Profildatenpunkte wie du (Musik, Essen, Reisen, Hobbys und der Rest von Privacy datapoint sharing) — niemals E-Mail, Telefon, Kartendaten oder GPS. Tippe unter dem Chatfeld auf Einstellungen für gespeicherte Chats und Erinnerungen. Tippe im Chat auf ein Foto, um es in einem eigenen Fenster zu öffnen. Schließen mit X oder Schließen, um den Chat wieder zu sehen. Das + oben rechts öffnet gespeicherte Chats und löscht sie nicht."},"help-botdee-smartview-troubleshoot":{"title":"SMARTview-Fehlerbehebung","body":"Leere Karte: Felder ausgeblendet oder blockiert. Speichern fehlgeschlagen: anmelden — Übersetzungen laufen auf dem Server. Ausstehend/Fehler: Quellsprache mit Label. Nur der Inhaber bearbeitet. Master-Admin-SMARTviews bleibt Mock; Places/Yelp aus. Theme folgt Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary bleibt synchron","body":"Bearbeiten Sie Ihre SMARTsummary in der Standard-Profilsprache. Speichern ist sofort. Offene Karten und SMARTview aktualisieren sich aus demselben Datensatz. Übersetzungen laufen im Hintergrund und überschreiben keine neuere Bearbeitung. Wenn Sie das Profil verbergen, jemanden blockieren oder das Konto löschen, verschwinden die Karten. Gemini überschreibt Ihren Text nicht."},"help-botdee-smartcard-search":{"title":"BOT DEE fragen, wer jemand ist","body":"„Who am I?“ öffnet Ihre SMARTview. „Who is …“, „What do you know of …“ oder „What about …“ plus Vorname, Nachname, Anzeigename, Mingl- oder FloqR-Handle oder ein Social-Handle (Instagram, TikTok, X). Treffer nur über diese Identitätsfelder — nicht über Bio, Likes, Getränke oder Genres. Ein Treffer öffnet eine People-SMARTview-Karte im Chat — keine Markdown-Liste und kein Fotogitter. Mehrere Treffer zeigen kompakte SMARTcards. Private, blockierte oder unveröffentlichte Profile erscheinen nicht — BOT DEE bestätigt nicht, ob das Konto existiert."},"help-botdee-smartcard":{"title":"Personen-SMARTcards","body":"Wenn mehrere öffentliche FLOQR-Profile passen, zeigt BOT DEE kompakte Personen-SMARTcards im Chat: zuerst das Foto in voller Breite, dann Name und Handle, dann eine kompakte SMARTsummary ohne gepolsterte Box. Tippen öffnet die volle SMARTview — dasselbe Layout. Karten nutzen dasselbe öffentliche Profil und dieselbe SMARTsummary. Öffnen ruft Gemini nicht auf."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Geben Sie Ver, Vers oder Version ein — Groß- und Kleinschreibung spielt keine Rolle. BOT DEE zeigt die Versionskarte. Eine längere Frage wie „Was ist deine Version?“ zeigt ebenfalls diese Karte."},"help-botdee-version-smartview-status":{"title":"Version-SMARTview-Status ist eine Live-Prüfung","body":"Der Dienststatus wird bei dieser Version-Anfrage geprüft: Functions und Package erreichbar und Gemini konfiguriert → Betriebsbereit; Functions und Package da, Gemini nicht konfiguriert → Eingeschränkt; Functions nicht in dieser Anfrage → Nicht verfügbar. Nie ein statisches Nicht geprüft. Das KI-Modell zeigt die konfigurierte Gemini-Modell-ID dieses Deployments, auch wenn dieser Zug nicht generiert. Frontend- und Backend-Stempel können sich unterscheiden; beide sind beschriftet. Master Admin sieht extra Diagnosen unter Technische Details — Gäste nicht."},"help-botdee-version-smartview-tabs":{"title":"Version-SMARTview-Reiter","body":"Übersicht beschreibt BOT DEE und öffnet Technische Details ohne den Chat zu verlassen. Neuigkeiten listet nur geprüfte BOT-DEE- und Gemini-Änderungen — nicht Master Admin, Beta-Tester-Werkzeuge oder andere FLOQR-Produkthinweise. Hilfe wiederholt den Befehl Ver / Vers / Version. Reiterwechsel oder Aufklappen behält den ungesendeten Entwurf und den Scroll. Die Karte nutzt Ihr Site Chrome — kein zweites Thema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Im BOT DEE-Chat sagen Sie Open Room SMARTview, Start a group chat oder planen Sie eine Cancun-Reise in einfachen Worten. Danach: Jetzt beitreten oder Zeitplan festlegen. Jetzt beitreten öffnet eine Mingl-Freunde-Session sofort und legt keine Karte auf Search. Zeitplan festlegen ist der Start der BOT DEE-Room — nicht Shared Itinerary — und schaltet Search SMARTnotification für Sie und eingeladene Mingl-Freunde ein. Nur Mingl-Freunde einladen — Host plus 7 Gäste. Gäste können auch einladen. Beitreten ist keine Zahlung und öffnet keine geteilte Rechnung. BOT DEE nimmt nie Kartennummern. Private BOT DEE-Nachrichten bleiben privat. Site Chrome folgt Appearance. Eine Live-Room bleibt offen, bis der Host End Room tippt, etwa vier Stunden nach dem Öffnen, oder alle etwa 15 Minuten weg sind. Die Pause des privaten BOT DEE-Chats ist getrennt."},"help-botdee-room-smartview-invite":{"title":"Mingl-Freunde einladen","body":"Nach Confirm (Join Now oder Set a schedule) zeigt Invite nur deine Mingl-Freunde. Tippe einen Freund oder schreibe Invite lorna — Inbox erhält Review BOT DEE invite. Der Chip bleibt grau mit Invite sent — ein zweites Tippen sendet keine zweite Einladung. Das ist ein Room SMARTview-Befehl, kein VIP reserV und kein People SMARTview Invite. Kein öffentlicher Join-Link. Maximum Gastgeber plus 7. Gäste können weitere Mingl-Freunde einladen, bis der Gastgeber das abschaltet. Beitreten ist keine Zahlung. Ist ein Chip du selbst oder schon in der Sitzung, bleibt er mit Das sind Sie oder Schon in dieser Sitzung markiert und sendet keine zweite Einladung."},"help-botdee-room-smartview-join":{"title":"Einer BOT DEE-Sitzung beitreten","body":"Öffne die Inbox-Einladung oder Search Join Now, angemeldet als der Mingl-Freund, dem sie gilt. Join Now öffnet BOT DEE, nicht Mingl chat. Du und eingeladene Mingl-Freunde teilt den Room SMARTview-Gruppenchat; Namen sehen Mitglieder. Falsches Konto, Ablauf oder Widerruf lehnt ab. Der Room ist nicht der Tab und genehmigt keine Zahlung. BOT DEE nimmt niemals Kartennummern."},"help-botdee-room-smartview-end":{"title":"Room SMARTview beenden","body":"Nur der Host kann einen Room beenden. Beenden belastet niemanden und löscht keine privaten Chats anderer. Eine unbezahlte geteilte Rechnung muss zuerst bezahlt oder storniert werden. Eine Live-Room bleibt offen bis End Room, etwa vier Stunden nach dem Öffnen, oder bis alle etwa 15 Minuten weg sind. Die Pause des privaten BOT DEE-Chats ist kein Room-Logout. Ein Gast, der geht, beendet die Room nicht, solange der Host da ist."},"help-botdee-room-smartview-tab":{"title":"Gemeinsamer Tab Room SMARTview","body":"Zuerst zustimmen. Dann eine Zeile hinzufügen. Als ein Zahler oder geteilt schließen. Nur bestätigende uids werden über FloqR Stripe belastet. Dem Room beitreten heißt nicht dem Tab beitreten. BOT DEE nimmt niemals Kartennummern. Club POS kommt später."},"help-botdee-room-smartview-who-pays":{"title":"Wer zahlt","body":"Frage Who’s paying in Room SMARTview, um den Opt-in zu sehen. Niemand wird belastet, weil jemand buy gesagt hat. Die letzten vier der Karte bleiben auf dem Beleg des Zahlers."},"help-botdee-room-smartview-kick":{"title":"Jemanden aus Room SMARTview entfernen","body":"Nur der Gastgeber kann einen Gast entfernen. Ein entfernter Freund liest keine weiteren Raumnachrichten. Eine Modellantwort kann niemanden kicken."},"help-botdee-room-smartview-share":{"title":"In Room SMARTview teilen","body":"Share this conversation kopiert niemals deinen privaten BOT DEE-Thread. BOT DEE zeigt eine Vorschau ausgewählter teilbarer Fakten aus dieser Nachricht, als vorläufig markiert. Du kannst Fakten bearbeiten oder streichen. Profile und SMARTsummary bleiben draußen."},"help-botdee-room-smartview-schedule":{"title":"Jetzt beitreten oder Zeitplan festlegen","body":"Nach dem Room-SMARTview-Setup wählen Sie Jetzt beitreten oder Zeitplan festlegen. Jetzt beitreten öffnet die BOT DEE-Session sofort und legt keine Karte auf Search. Zeitplan festlegen ist der Start der BOT DEE-Room — nicht Shared Itinerary. Ein zukünftiger Zeitpunkt schaltet Search SMARTnotification nur für Sie und eingeladene Mingl-Freunde ein. Gäste sagen zu, bis die Room live ist; dann öffnet Join Now BOT DEE (nicht Mingl-Chat)."},"help-botdee-room-collab":{"title":"Headless-Buchung in Room SMARTview teilen","body":"In einer Room SMARTview sehen alle die VIP reserV- oder ShoutOut-Auswahl des Gastgebers. Mitglieder stimmen Ja oder Nein. Hold it und Bezahlen bleiben beim Gastgeber — Beitreten und Abstimmen ist keine Zahlung. BOT DEE nimmt niemals Kartennummern. Stripe öffnet in einem Pop-out."},"help-botdee-room-elect-host":{"title":"Room SMARTview-Gastgeber wählen","body":"Jeder in der Session kann Gastgeber sein. Nominiere dich oder ein anderes Mitglied. Ein Kandidat wird Gastgeber bei 60 % der aktuell beigetretenen Mitglieder (aufgerundet). Wenn der Gastgeber geht, wählen die übrigen einen neuen — der Room bleibt offen. Kick und End bleiben beim gewählten Gastgeber."},"help-botdee-smartview-review":{"title":"SMARTsummary prüfen und korrigieren","body":"Gemini entwirft nur aus öffentlichen FLOQR-Feldern — nie bei jedem Öffnen. Falsche Fakten: Feld in der Profilsichtbarkeit ausblenden oder Summary selbst ändern. Ihr Text wird nicht überschrieben. Profilkonflikte verlangen Prüfung. Falsche Karten im Overlay melden."},"help-botdee-smartview-chrome":{"title":"SMARTview und Site Chrome","body":"People SMARTview nutzt das FLOQR Site Chrome des Betrachters (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Kein zweites Theme. Chrome-Wechsel aktualisiert die Karte, der Chat-Entwurf bleibt."},"help-botdee-smartview-categories":{"title":"SMARTview-Kategorien","body":"Vier Tabs: Social, Dating, Dining, Zukünftige Reisen. Social startet bei Musik, dann Nightlife, Sport, Events. Tags nur Geteiltes — keine doppelten Überschriften, keine erfundenen Reisen oder Bewertungen. Künftige Reisen nur öffentlich markierte Ziele."},"help-botdee-smartview-media":{"title":"SMARTview-Fotos und Videos","body":"Die Karte nutzt dasselbe Hero-Bild wie Ihre öffentliche FLOQR-Seite — das erste Profile-Media-Element (8 Fotos + 2 Videos). Tippen öffnet Fotos und Videos aus diesen öffentlichen Slots. Wischen oder Pfeile, dann X (oder Escape) zurück zum Chat und Entwurf."},"help-botdee-smartview-privacy":{"title":"SMARTview-Datenschutz","body":"SMARTview zeigt nur Felder, die in FLOQR schon öffentlich sind. Keine Websuche. Dating nur mit Opt-in. Blenden Sie ein Feld in Mein Profil aus, verschwindet es. Blockierte Personen sehen die Karte nicht. Falsche Summaries im Overlay melden."},"help-botdee-smartview-translation":{"title":"SMARTview-Übersetzung","body":"Ihre SMARTsummary wird in der Standard-Profilsprache gespeichert — das ist die Quelle, auch wenn es nicht Englisch ist. Nach dem Speichern reiht FLOQR eine Übersetzung für jede andere Sprache ein, einschließlich Englisch. Ein englischsprachiger Betrachter sieht die englische SMARTsummary, sobald der Job fertig ist. Bei ausstehend oder Fehler sehen Betrachter die Quellsprache klar gekennzeichnet — nie eine veraltete Übersetzung als aktuell."},"help-botdee-smartview-edit":{"title":"SMARTsummary bearbeiten","body":"Nur Sie bearbeiten Ihre SMARTsummary in der Standard-Profilsprache. Speichern ist sofort. Übersetzungen laufen im Hintergrund. Gemini überschreibt Ihren Text nicht. Wenn sich das öffentliche Profil ändert, prüft FLOQR mit Ihnen statt zu ersetzen."},"help-botdee-privacy-assistant":{"title":"BOT DEE Privacy Assistant","body":"Ändern Sie in Mein Profil, was andere FLOQR-Nutzer sehen — BOT DEE fügt keinen zweiten Öffentlich-Schalter hinzu. Falsche Web-Zuordnung können Sie widersprechen, ohne das Profil zu ändern. BOT DEE verspricht keine Löschung auf Drittseiten."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Jede Empfehlung kann Belege, Prüfdatum, Personalisierung und Sponsoring zeigen. Sie können BOT DEE bitten, diese Suche nicht zu personalisieren."},"help-botdee-research-library":{"title":"BOT DEE Research Library","body":"Speichern Sie Orte und Karten, die Sie BOT DEE gefragt haben. Eine Google Place-ID ist keine Kopie von Fotos oder Bewertungen. Sie können aktualisieren oder löschen. Lizenzierte Caches bleiben aus, bis der Anbieter genehmigt ist."},"help-botdee-smartview":{"title":"Mein SMARTview anzeigen","body":"Mein SMARTview zeigt Ihre Personenkarte aus öffentlichen FLOQR-Feldern, mit denselben Profile Media wie die öffentliche Seite — keine Club- oder Restaurant-Mocks. Meine SMART Summary bearbeiten ändert den Text in Ihrer Profilsprache. Gekennzeichnete Mock-Karten liegen unter Master Admin → Features → BOT DEE → SMARTviews. Kein Live-Places oder Yelp."},"help-botdee-memory":{"title":"Gespeicherte BOT DEE-Chats","body":"Öffnen Sie Funktionen & Bestellungen → Mein BOT DEE, um Chats nach der Pause zu speichern, zu exportieren oder den Verlauf zu löschen. Die 5-Minuten-Pause beendet die Live-Sitzung. Mit Opt-in behält BOT DEE den Chat. Gäste werden nicht gespeichert. Mingl bleibt Mingl."},"help-botdee-knows-of-me":{"title":"Was BOT DEE von mir weiß","body":"Mit Ihrer Zustimmung gespeicherte Fakten liegen unter Funktionen & Bestellungen → Mein BOT DEE. Die Liste ist leer, wenn die Erinnerung aus ist oder nichts gespeichert ist. Export oder Löschung hier. BOT DEE speichert keine IP-Adresse. Mingl wird nicht kopiert."},"help-search-settings-appearance":{"title":"Settings auf Search","body":"Tippe auf dem Search-Bildschirm auf Settings, um Profile & Settings auf dem Tab Appearance zu öffnen — dort liegt Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Die Settings-Kachel nutzt dasselbe Chrome-Icon-Paket wie die anderen Search-Marken."},"help-club-website-feed":{"title":"Feed für die Club-Website","body":"Zeige deine veröffentlichte FLOQR-Clubseite auf deiner eigenen Website. Tippe auf „Schlüssel und Links erzeugen“ und füge den iframe-Code in deine Website ein oder gib deinem Webadmin den JSON- oder RSS-Link. Der Feed zeigt kommende Events, hervorgehobene DJs und hervorgehobenes Personal, die Galerie und Kontaktdaten gemäß deinen Einstellungen für die öffentliche Seite. Fotos des Personals erscheinen nur, wenn die Foto-Einwilligung bestätigt ist. Ein neuer Schlüssel deaktiviert die alten Links, auch die Links zum Mitarbeiterplan."},"help-featured-staff":{"title":"Hervorgehobenes Servicepersonal","body":"Hake das Personal an, das auf der öffentlichen Clubseite erscheinen soll. Tippe für jede Person auf eines ihrer FLOQR-Fotos oder wähle „Vom Computer hochladen“. Du kannst die Rolle unter dem Namen ändern. Tippe auf „Save Public Profile“, um zu veröffentlichen. Hole vor dem Veröffentlichen von Fotos die Zustimmung jeder Person ein und hake das Feld zur Foto-Einwilligung an."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox enthält System Messages und interne Support-Nachrichten. Die Liste lädt zuerst, damit Nachrichten schnell erscheinen. Tippe auf den schwebenden New Message-Button zum Verfassen — gib einen Namen oder @username ein, um einen erlaubten Empfänger zu finden (Club Admin, CSR oder genehmigtes Personal). Patron-zu-Patron-Chat bleibt in Mingl nach gegenseitigem Mingl. Eine Schicht-Einladung zu öffnen bestätigt nicht — prüfe und tippe Approve selected im Work Calendar."},"botdee-ask-floqr":{"title":"Fragen Sie FloqR mit BOT DEE","body":"Fragen Sie FloqR mit BOT DEE – tippen Sie auf die animierte Markierung oder warten Sie auf die Aufforderung und geben Sie dann in einfachen Worten ein, was Sie möchten. Produkte: Mingl, RydR, BartR, ShoutOut, FloqCAST (Superstar), Keulen. Ziele: Sagen Sie „Ich möchte in der Lage sein…“ (z. B. ein Club Admin werden) oder „make me a superstar“ für Schritte und Links."},"help-vip-book-table":{"title":"VIP-Tisch buchen (VIP reserV)","body":"VIP reserV zeigt den Saalplan und bucht Tische. Öffne VIP reserV aus der Suche, wähle Decades oder Lima Twist Club und einen Abend, tippe einen grünen Tisch, halte 30 Minuten, akzeptiere die AGB und zahle die Anzahlung mit FloqR Stripe. Bars und DJ nie buchbar. Marke VIP reserV wird nicht übersetzt. Bei Aurelia öffnen Sie Explore 3D walk-through für den interaktiven Raum (Buchung bleibt auf dem 2D-Plan)."},"help-vip-choose-venue":{"title":"VIP reserV-Venue wählen","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club und Aurelia haben je einen veröffentlichten 2D-Plan; Aurelia bietet auch Explore 3D walk-through."},"help-become-club-admin":{"title":"Werde ein Club Admin","body":"Fordern Sie Club Admin Zugang an und holen Sie dann die Genehmigung für den Veranstaltungsort ein."},"help-role-profiles":{"title":"Übersicht über Rollenprofile","body":"Sehen Sie, wie die Rollen Club Admin, DJ, Promoter und Gastgewerbe funktionieren."},"help-staff-scheduling":{"title":"Kalender und Terminplaner","body":"Club Admin Der Kalender zeigt Karten „Entwurf“ (lila), „Ausstehend“ (gelb), „Bestätigt“ (grün) und „Offen/unausgefüllt“ an – jeweils mit einem geschriebenen Status, nicht nur mit Farbe. Der Planer ist das Personen × Tage-Entwurfs-/Veröffentlichungsraster. Website ingest / publicVenueCalendar gibt nur bestätigte Aufgaben zurück. Eine grüne „Diesen Monat bezahlt“-Pille wird für Club Admins angezeigt, wenn staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Benachrichtigungsabonnements für Club SMS und WhatsApp","body":"Club Admin → Benachrichtigungen: Send test alert verwendet die aktuell aktivierten Kästchen. In-App (und Push) schreibt eine Systemnachricht in FloqR Inbox. Für E-Mails werden Club-Administratoradressen verwendet. SMS und WhatsApp benötigen weiterhin ein kostenpflichtiges Abonnement sowie ein Alarmierungstelefon für E.164. Grüne Pille = Firebase Abonnement 1 (Prepaid-Paket im Wert von 10 $); rot = 0. Wenn Send test alert Authentication Error - invalid username zurückgibt, muss Firebase Secret TWILIO_ACCOUNT_SID die Konto-SID beginnend mit AC (34 Zeichen) von console.twilio.com sein – nicht das Auth-Token und kein API-Schlüssel (SK)."},"help-club-sms-notification":{"title":"SMS Benachrichtigungsabonnement","body":"Die SMS-Pille ist grün, wenn Firebase smsSubscribed 1 ist (Prepaid-$10-Packung, 466 Credits, nicht monatlich oder jährlich). Rot/Blinken bedeutet 0 – offen? und tippen Sie auf Subscribe $10. Die verbleibenden Credits und das Datum der letzten Zahlung finden Sie in dieser Hilfe. Deaktivieren Sie SMS und „Speichern“, um Benachrichtigungen anzuhalten, ohne das kostenpflichtige Paket zu verlieren."},"help-club-whatsapp-notification":{"title":"WhatsApp Benachrichtigungsabonnement","body":"Die WhatsApp-Pille ist grün, wenn Firebase whatsappSubscribed 1 ist (Prepaid-$10-Packung, 233 Credits, nicht monatlich oder jährlich). Rot/Blinken bedeutet 0 – offen? und tippen Sie auf Subscribe $10. Die verbleibenden Credits und das Datum der letzten Zahlung finden Sie in dieser Hilfe. Deaktivieren Sie WhatsApp und „Speichern“, um Benachrichtigungen anzuhalten, ohne das kostenpflichtige Paket zu verlieren."},"help-schedule-message-templates":{"title":"Planen Sie Nachrichtenvorlagen","body":"Club Admin → Benachrichtigungen → Message templates. Dies sind Systemnachrichten (Inbox / E-Mail / SMS / WhatsApp), nicht ShoutOuts. Titel und Text für New shift needs confirmation bearbeiten, Zeitplan aktualisieren, Schicht bestätigt und Schicht abgelehnt. Platzhalter: {club} {role} {when} {link} {worker}. Der Posteingang des Mitarbeiters verwendet Review & confirm shift – niemals Open Related ShoutOut."},"help-schedule-confirm":{"title":"Bestätigen Sie zugewiesene Schichten","body":"Inbox / E-Mail / SMS Links öffnen Work Calendar. Schauen Sie sich jede ausstehende Aufgabe an, kreuzen Sie sie an (oder Select all) und dann Approve selected. Das Öffnen des Links führt zu keiner Bestätigung. Nur der zugewiesene Servicemitarbeiter kann genehmigen – Club Admin kann nicht in seinem Namen bestätigen."},"help-template-catalog-report":{"title":"Vorlagenkatalogbericht","body":"Listet jeden ShoutOut-Vorlagentyp und die unterstützten LED-Größen auf (Is96x48, Is64x48, Is64x32). Ein Veranstaltungsort bietet nur dann eine Vorlage an, wenn mindestens eines dieser Flags 1 ist und das entsprechende VenueSupports*-Flag 1 ist. Geburtstags-/Split-Media-Vorlagen sind 1 auf 96×48, 64×48 und 64×32. 96×48 ist 3-zeilig nebeneinander; 64×48 und 64×32 Schleife des Fotos, dann der 3-zeilige Shoutout mit einer FLOQR + Handle-Karte."},"help-club-display-screens":{"title":"FLOQR Anzeigebildschirme","body":"Firebase clubLocations speichert VenueSupports96x48, VenueSupports64x48 und VenueSupports64x32 als 0 oder 1. templates speichert Is96x48, Is64x48 und Is64x32 auf die gleiche Weise. Ein Veranstaltungsort listet nur dann eine Vorlage auf, wenn mindestens ein Paar 1 ist. Xibo-URLs bleiben display.html?location=id und display2.html?location=id – die Bildschirmgröße ist nicht in der URL enthalten. „Geburtstag“ wird in allen drei Größen angeboten (dreizeilig nebeneinander auf 96×48; Foto-/Shoutout-Schleife auf 64×48 und 64×32). Primär ist display.html. Sekundär ist display2.html."},"help-staff-week-calendar":{"title":"Planer","body":"Club Admin Scheduler ist ein Personen-×-Tage-Wochen-Raster. Save shift schließt den Editor mit Schedule card successfully saved. Erstellen Sie Entwürfe, Publish schedule, damit die Mitarbeiter die ausstehenden Arbeiten bis zur Bestätigung bestätigen, Select shifts, um sie mehrfach zu löschen, und Website ingest, um veröffentlichte Schichten auf der Club-Website zu veröffentlichen. Standardmäßiges Schichtfenster = geöffneter Club – 2 Stunden bis Schließung + 1 Stunde."},"help-staff-schedule-user-guide":{"title":"Benutzerhandbuch zur Personalplanung","body":"Öffnen Sie das ? neben Scheduler auf Club Admin Scheduling. Erstellen Sie Entwurfsschichten, Publish schedule, damit die Mitarbeiter ausstehend→bestätigt bestätigen, und dann Select shifts, um mehrere auf einmal zu löschen. Beispiel: alle Mittwochs-Drafts plus ein am Donnerstag bestätigter Chip."},"help-create-publish-schedule":{"title":"Erstellen und veröffentlichen Sie einen Personalplan","body":"Fügen Sie Entwurfsschichten im Raster „Personen × Tage“ hinzu, überprüfen Sie die Chips und dann Publish schedule. Arbeiter müssen bestätigen, bevor eine Schicht bestätigt wird. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Löschen Sie mehrere geplante oder Entwurfsschichten","body":"Select shifts, Tagesköpfe und Chips mischen, dann Delete selected. Beispiel: alle Entwürfe am Mittwoch plus eine bestätigte Schicht am Donnerstag."},"help-staff-worksheet":{"title":"Arbeitsblatt – Wöchentlicher Personalkalender","body":"Ausgewählte Servicemitglieder öffnen Work Calendar in den Einstellungen. Inbox / E-Mail / SMS Bestätigungslinks landen hier. Überprüfen Sie ausstehende Aufgaben, kreuzen Sie jede Schicht an (oder Select all) und dann Approve selected – das Öffnen der Nachricht führt nicht zu einer Bestätigung. Das Wochenraster zeigt veröffentlichte Kollegenschichten. Entwürfe bleiben in Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Alle beginnen als FLOQR-Patron. In My Profile & Settings tippen Sie Elect to become a service member. Wählen Sie Ihre Service-Rolle, Clubs, und senden Sie unten auf der Seite.\n\nProfilvorlagen-Leitfaden — Patron-Sozialprofile bleiben unter Öffentliche Medien. Service-Rollen nutzen eigene Vorlagen auf Mein Profil.\n\nClub-Admin-Genehmigung — Club Admin → Employee/Workers → Pending Worker Requests, oder Prüfen und wählen auf diesem Tab."},"help-venue-website-ingest":{"title":"Aufnahme der Club-Website (API, RSS, Iframe)","body":"Club Admin → Terminplanung → Website ingest. Generieren Sie ein Geheimnis (wird einmal angezeigt; es wird nur ein Hash gespeichert). Ziehen Sie veröffentlichte Personalschichten mit JSON (?format=json&dataset=schedule|hours|profile|all), RSS oder einem Iframe-Snippet auf die offizielle Club-Website. Entwürfe, E-Mail-Adressen des Mitarbeiters und Telefonnummern sind niemals enthalten. Drehen Sie das Geheimnis, wenn es ausläuft."},"help-venue-hours-calendar":{"title":"Öffnungszeiten des Veranstaltungsortes","body":"Legen Sie im öffentlichen Profil des Clubs die standardmäßigen wöchentlichen Öffnungs-/Schließzeiten fest und fügen Sie dann Periodenüberschreibungen für besondere Wochen hinzu, ohne die Standardeinstellung zu verlieren. Die öffentliche Clubseite zeigt ein So-Sa-Wochenraster mit dem Datumsbereich (z. B. So, 9. – Sa, 15. August 2026) und Kalenderfarben. Anstehende Feiertage listen die Öffnungs-/Schließzeiten auf und weisen Sie darauf hin, wenn diese vom üblichen Wochentag abweichen. Die Personaleinsatzplanung verwendet Öffnungszeit − 2 Stunden bis Schließungszeit + 1 Stunde. Die Gästeliste kann Ihnen Abende der offenen Tür vorschlagen."},"help-club-admin-affiliation":{"title":"Club Admin Veranstaltungsortzuweisung","body":"Club Admins öffnen das Venue Command Center nur für einen Club, dem sie zugewiesen sind. Beim Öffnen von admin.html ohne Veranstaltungsort wird nicht mehr standardmäßig Zebbies verwendet. Demokonten temp_clubadmin_N@floqr-demo.com sind temp-democlub-N zugeordnet. Nicht zugewiesene Administratoren beantragen eine Zuweisung ab Master Admin."},"help-venue-command-center":{"title":"Venue Command Center","body":"ShoutOuts freigeben, Venue-Leistung prüfen und Kontoaktivität für diesen Standort abstimmen."},"help-club-template-repository":{"title":"Vorlagen deines Clubs","body":"Vorlagen nur für deinen Club stehen ganz oben und sind mit „Exklusiv bei“ und dem Namen deiner Location markiert. Zugewiesene Vorlagen können Gäste in deinem Club wählen; ändere das mit Vorlage zuweisen oder Vorlage entfernen. Die Suche findet eine Vorlage auch ohne Akzent oder mit einem kleinen Tippfehler."},"help-employee-network":{"title":"Mitarbeiter- und Personalnetzwerk","body":"Nur Personen mit Bezug zu diesem Club werden angezeigt: hier ernanntes oder genehmigtes Personal, Club-Admins und mit diesem Club verbundenes Personal. Um jemandem eine Rolle zu geben, gib unter Gast für eine Rolle ernennen Name, Benutzername oder E-Mail ein, tippe neben der richtigen Person auf Auswählen, wähle die Rolle, tippe dann auf Ausgewählten Gast für die Rolle ernennen und bestätige. Die Person braucht zuerst ein FLOQR-Gastkonto. Kellner, Kellnerinnen und Bottle Girls auf der Liste können zu Kundenservice-Vertretern (CSR) gemacht werden."},"help-template-tags":{"title":"Vorlagen-Tags","body":"Füge Wörter hinzu, die Gäste eintippen könnten, wenn sie bei deiner Location eine Vorlage suchen, etwa Spieleabend oder Geburtstag. Vorlagen-Manager können Tags hinzufügen. Vorlagen-Administratoren und Club Admins können Tags auch entfernen. Club Admin vergibt diese Rollen unter Role Activity & Permission."},"help-display-idle-default":{"title":"Ruhebildschirm: Use ShoutOut @ Location","body":"Wenn kein ShoutOut läuft, zeigt Display 1 „Use ShoutOut @“ mit dem Namen deiner Location. Jeder freigegebene ShoutOut läuft 10 Minuten, danach kehrt die Anzeige von selbst zu diesem Text zurück. Anzeige auf Standard zurücksetzen in Club Admin macht das sofort."},"help-club-messaging-credit":{"title":"SMS- & WhatsApp-Guthaben","body":"Jedes 10-$-Paket finanziert 7,00 $ Twilio-Kapazität; FloqR behält 3,00 $ Plattformmarge. SMS-Paket → 466 Nachrichten (≈ 0,015 $ US-SMS). WhatsApp-Paket → 233 Nachrichten (≈ 0,030 $ Twilio + Meta Marketing). Bei 0 Guthaben neues 10-$-Paket kaufen. Ops-SMS-Freischaltung (10 $) inkl. SMS-Paket. WhatsApp-Service (10 $) inkl. WhatsApp-Paket. Rechnung: 10 $ → 466 SMS oder 233 WhatsApp (7,00 $ Twilio / 3,00 $ FloqR)."},"help-club-marketing-campaigns":{"title":"Marketingkampagnen","body":"Branchenvorlage wählen, Hintergrund- und Zusatzbilder laden, Text anpassen, speichern oder senden. Senden belastet SMS- oder WhatsApp-Guthaben unter Messaging-Guthaben."},"help-club-in-app-marketing":{"title":"In-App-Marketing","body":"Veröffentliche einen Flyer oder ein Video bis 30 Sekunden im Namen deines Clubs. Sobald die Anzeige bezahlt und von FLOQR freigegeben ist, erscheint sie auf dem Ladebildschirm der Suche, in Mingl, RydR und auf weiteren FLOQR-Seiten. Unter Anzeigen-Poster des Clubs kannst du einem Teammitglied das Veröffentlichen erlauben (Rolle Club Ad Poster). Keine SMS-Guthaben nötig."},"help-vip-terms-consent":{"title":"VIP reserV AGB","body":"Nach dem Tischhalt öffnen Sie die AGB-Seite, lesen den Text und akzeptieren einmal (Marketing optional). Einwilligung wird vor FloqR Stripe Checkout gespeichert — wie bei einem bezahlten ShoutOut, danach Beleg und Pass."},"help-vip-door-pass":{"title":"VIP reserV Tür-Pass","body":"Nach bestätigter Anzahlung: Mein Profil → Reservierungen → Pass anzeigen für einmaligen QR. Ausweis 21+ mitbringen. Türpersonal nutzt VIP reserV Door."},"help-vip-door-ops":{"title":"VIP reserV Tür-Check-in","body":"VIP Manager öffnen VIP reserV Door für heute. Token scannen/einfügen, ID 21+ prüfen, einchecken. No-Show erst nach Grace. Notify-Links ändern den Status nicht."},"help-vip-payment-collector":{"title":"VIP reserV Zahlungskollektor & Club POS","body":"Bevorzugt für Live-Clubs mit Toast/SpotOn: Club POS — FLOQR bucht/hält/karte; POS übernimmt Anzahlung, Tab und Umsatz. Alternativen: Club Stripe, FloqMedia Stripe (FloqR) oder VIP-Engine + CSV. Aurelia (Demo Club) standardmäßig FloqMedia Stripe — BOT DEE für Master-/Club-Admin-Schritte fragen."},"help-vip-table-isbooked":{"title":"VIP-Tisch isBooked-Status in Firestore","body":"Jeder VIP-onboardete Club hat ein Firestore-Dokument pro Tischnummer und Nacht: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Doc-ID = gedruckte Nummer (z. B. T1, B3). Nach abgeschlossener Buchung: isBooked \"1\", isBookedYes \"yes\". Frei: \"0\" / \"no\". Holds setzen isBooked nicht. Storno → \"0\". getVipAvailability nutzt isBooked als Buchungsstatus. Storno setzt isBooked immer auf \"0\"; FloqMedia/Club Stripe kann die Anzahlung laut Club-Policy erstatten."},"help-vip-floqr-stripe-aurelia":{"title":"FloqMedia Stripe für Aurelia (Demo Club) einrichten","body":"Aurelia (temp-democlub-1) nutzt FloqMedia Stripe (FloqR Checkout) als Standard-VIP-Anzahlung — Gäste zahlen auf FloqRs Plattform-Stripe; danach gilt der Tisch als gebucht.\n\nMaster-Admin-Schritte:\n1) Master Admin → Features Mgmt → VIP reserV Payments öffnen.\n2) VIP Reservations netzwerkweit aktivieren (Features & Services / Release Control bei Bedarf).\n3) POS-Anbieter nur seeden, wenn später Club POS genutzt wird — für FloqMedia Stripe nicht nötig.\n4) Aurelia bei FloqMedia Stripe belassen, außer Club POS oder Club Stripe ist gewünscht.\n5) Nach Anzahlungen VIP reserV Payments → Network VIP billing für FloqR-Abrechnungen prüfen.\n\nClub-Admin-Schritte (Aurelia):\n1) Als temp_clubadmin_1@floqr-demo.com (E-Mail-OTP auf der Startseite) oder zugewiesener Club Admin anmelden.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) Unter Payment collector FloqMedia Stripe (FloqR) wählen.\n4) Require deposit before table is marked booked für Demos aktiviert lassen.\n5) Save payment collector tippen.\n6) Test: vip.html?location=temp-democlub-1 → Tisch halten → AGB → Anzahlung (Stripe-Testkarte 4242…).\n7) Door / Abrechnung: Open Door zum Check-in; Refresh billing für Statements.\n\nFür Aurelia-Demos kein Club POS wählen, außer Toast/SpotOn-Sandbox ist beabsichtigt. FloqMedia, Stripe, ShoutOut und VIP reserV bleiben Markennamen."}},"es":{"help-smartvisuals-notification":{"title":"SMARTnotification de Mingl Room","body":"Una invitación compacta Mingl Room puede aparecer en Search cuando usted fija un horario para una room BOT DEE, o un amigo Mingl lo invitó. El anfitrión ve su room programada en Search sin la consulta demo Cancun. Ver invitación abre Room SMARTview. Join Now va a BOT DEE, no a Mingl chat. Ahora no oculta la tarjeta en esta pestaña; Inbox sigue con Review BOT DEE invite. La consulta demo Cancun es solo Studio. El arte es ilustración, no foto. Las rooms Join Now sin horario no aparecen en Search."},"help-smartvisuals-room":{"title":"Room SMARTview con SMARTvisuals","body":"Room SMARTview muestra la invitación Mingl: horario, RSVP o estado en vivo, y Join Now. Join Now en Search abre BOT DEE (no Mingl chat) con room= y t=. SMARTstencils y SMARTbackgrounds siguen el título autorizado — Cancun Trip usa arte de viaje, no una foto real de Cancun. El chat privado de BOT DEE nunca elige el arte. Un Ad etiquetado debajo es una muestra de esas etiquetas. Vacío para chat privado o inyección; no es un anunciante en vivo."},"help-scheduling-schedule-for":{"title":"Planificación del personal","body":"Planifica turnos y contrataciones y avisa a cada persona por Inbox, Email, SMS o WhatsApp. En «Horario de», elige el calendario con el que trabajas: «Mi horario de DJ» es tu propio calendario, «Club» muestra los clubs que administras y «Empresa de promoción» las empresas para las que promocionas. Cada calendario tiene su propia suscripción de 20 $/mes. Los turnos que te asignan aparecen en «Mis asignaciones», donde los confirmas o rechazas."},"help-staff-marketing-consent":{"title":"Consentimiento de marketing del personal","body":"Cuando te unes al equipo de un local o evento, debes marcar la casilla de consentimiento de marketing. Permite que ese local u organizador, y sus administradores y gerentes, usen tu nombre de FLOQR, tu rol y tus fotos y videos publicados en sus sitios web, flyers y redes sociales (Instagram, Facebook, TikTok, YouTube y similares) sin volver a pedirte permiso para cada uso. No pueden publicar tu teléfono ni tu correo electrónico. Puedes retirarlo en cualquier momento en Mi perfil, pestaña Servicios y miembros de servicio. Esto detiene el nuevo marketing; los materiales ya impresos o publicados no tienen que retirarse. Los Club Admins ven el estado del consentimiento de cada miembro del personal en Red de empleados y personal y en Personal destacado."},"help-botdee-privacy-session":{"title":"Privacidad y sesión de BOT DEE","body":"La pausa de cinco minutos termina la sesión en vivo. No borra este chat con sesión iniciada, los recuerdos ni los flujos. Las copias en Mi perfil → Funciones y pedidos → My BOT DEE también se quedan. Los invitados siguen siendo efímeros. Los chats de Mingl nunca se copian aquí. Intro envía; Mayús+Intro empieza una línea nueva. Nombre y tono se eligen en Mi perfil → My BOT DEE, no con un botón en el chat."},"help-botdee-place-search":{"title":"Preguntar a BOT DEE por locales FLOQR","body":"Pregunte en palabras simples — restaurantes de sushi en Washington DC, clubs en DC o un club concreto. BOT DEE busca solo venues FLOQR dadas de alta, no Google ni Yelp. Las coincidencias abren un Place SMARTview compacto (nombre, texto corto, valoraciones, enlace a la página pública) con un SMARTbackground — no un pozo de foto. Nombrar una ciudad con VIP reserV (reservations in Miami) sigue adjuntando Place SMARTview junto a la tarjeta VIP. Las fotos de patrons y los pitches de ShoutOut no aparecen salvo que los pida. Si aún no hay nada, BOT DEE lo dice."},"help-botdee-page":{"title":"BOT DEE","body":"Chatea con BOT DEE en la página BOT DEE con palabras sencillas: eventos y clubs, ShoutOut, Mingl, RydR, BartR, FloqCAST, tu perfil, horarios del personal o herramientas de Club Admin. Pulsa Intro para enviar; Mayús+Intro empieza una línea nueva. BOT DEE habla como una persona (prueba How are you?) y solo busca cuando preguntas cómo hacer algo en FLOQR. Si has iniciado sesión, BOT DEE guarda este chat si actualizas o abres otro teléfono, y después de la pausa puede continuar el historial guardado. La pausa no borra el chat. Las respuestas usan la clasificación de tu cuenta. Si has iniciado sesión, BOT DEE ve los mismos datapoints públicos voluntarios que tú (música, comida, viajes, hobbies y el resto de Privacy datapoint sharing) — nunca email, teléfono, datos de tarjeta ni GPS. Toca Ajustes bajo el cuadro de chat para chats y recuerdos guardados. Toca una foto del chat para abrirla en una ventana. Cierra con X o Cerrar para volver al chat. El + de arriba a la derecha abre chats guardados y no los borra."},"help-botdee-smartview-troubleshoot":{"title":"Solución de problemas de SMARTview","body":"Tarjeta vacía: campos ocultos o bloqueo. Fallo al guardar: inicie sesión — las traducciones van al servidor. Pendiente o error: idioma de origen etiquetado. Solo el titular edita. SMARTviews de Master Admin sigue siendo el catálogo mock; Places y Yelp apagados. El tema sigue Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary permanece sincronizado","body":"Edite su SMARTsummary en el idioma predeterminado del perfil. El guardado es inmediato. Las tarjetas y SMARTview abiertos se actualizan desde el mismo registro. Las traducciones van en segundo plano y no sobrescriben una edición más nueva. Si oculta el perfil, bloquea a alguien o elimina la cuenta, esas tarjetas desaparecen. Gemini no sobrescribe su texto."},"help-botdee-smartcard-search":{"title":"Preguntar a BOT DEE quién es alguien","body":"«Who am I?» abre su SMARTview. «Who is …», «What do you know of …» o «What about …» más nombre, apellido, nombre para mostrar, identificador Mingl o FloqR, o un identificador social (Instagram, TikTok, X). Solo coinciden esos campos de identidad — no la bio, los likes, las bebidas ni los géneros. Un resultado abre una tarjeta People SMARTview en el chat — no una lista markdown ni una cuadrícula de fotos. Varios muestran SMARTcards compactas. Perfiles privados, bloqueados o no publicados no aparecen — BOT DEE no confirma si esa cuenta existe."},"help-botdee-smartcard":{"title":"SMARTcards de personas","body":"Si coinciden varios perfiles públicos de FLOQR, BOT DEE muestra SMARTcards compactas en el chat: primero la foto a todo el ancho, luego nombre y @identificador, luego un SMARTsummary compacto sin caja rellena. Toque una tarjeta para abrir el SMARTview completo — el mismo apilado. Las tarjetas usan el mismo perfil público y SMARTsummary. Abrir una tarjeta no llama a Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Escriba Ver, Vers o Version — las mayúsculas no importan. BOT DEE muestra la tarjeta de versión. Una pregunta más larga como “¿cuál es tu versión?” también muestra esa tarjeta."},"help-botdee-version-smartview-status":{"title":"El estado de Version SMARTview es una sonda en vivo","body":"El estado del servicio se sondea en esta petición Version: Functions y paquete alcanzables con Gemini configurado → Operativo; Functions y paquete bien pero Gemini no configurado → Degradado; Functions no en esta petición → No disponible. Nunca una etiqueta estática Sin comprobar. El modelo de IA muestra el id de Gemini configurado de este despliegue aunque este turno no genere. Los sellos de frontend y backend pueden diferir; ambos se etiquetan. Master Admin puede ver diagnósticos extra en Detalles técnicos — los patrons no."},"help-botdee-version-smartview-tabs":{"title":"Pestañas de Version SMARTview","body":"Resumen describe BOT DEE y abre Detalles técnicos sin salir del chat. Novedades lista solo cambios verificados de BOT DEE y Gemini — no Master Admin, herramientas de beta testers ni otras notas de producto FLOQR. Ayuda repite el comando Ver / Vers / Version. Cambiar de pestaña o expandir conserva el borrador no enviado y el scroll. La tarjeta usa su Site Chrome — no hay un segundo tema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"En el chat de BOT DEE, diga Open Room SMARTview, Start a group chat, o planee un viaje a Cancun en palabras simples. Luego: Unirse ahora o Fijar un horario. Unirse ahora abre una sesión de amigos Mingl ya y no pone una tarjeta en Search. Fijar un horario es cuando empieza la room BOT DEE — no Shared Itinerary — y activa SMARTnotification de Search para usted y amigos Mingl invitados. Invite solo amigos Mingl — anfitrión más 7 invitados. Los invitados también pueden invitar. Unirse no es un pago y no abre una cuenta compartida. BOT DEE nunca toma números de tarjeta. Los mensajes privados de BOT DEE siguen privados. Site Chrome sigue Appearance. Una room en vivo sigue abierta hasta End Room, unas cuatro horas después de abrir, o si todos se han ido unos 15 minutos. Pausar el chat privado de BOT DEE es aparte."},"help-botdee-room-smartview-invite":{"title":"Invitar amigos Mingl","body":"Tras Confirm (Join Now o Set a schedule), Invite muestra solo tus amigos Mingl. Toque un amigo o escriba Invite lorna — Inbox recibe Review BOT DEE invite. El chip se queda gris con Invite sent — un segundo toque no envía otra invitación. Es un comando de Room SMARTview, no VIP reserV ni People SMARTview Invite. No es un enlace público. Cupo: anfitrión más 7. Los invitados pueden invitar más amigos Mingl salvo que el anfitrión lo desactive. Unirse no es un pago. Si un chip eres tú o alguien ya en la sesión, queda marcado Eres tú o Ya en esta sesión y no envía otra invitación."},"help-botdee-room-smartview-join":{"title":"Unirse a una sesión BOT DEE","body":"Abre la invitación de Inbox o Search Join Now iniciado sesión como el amigo Mingl destinatario. Join Now abre BOT DEE, no Mingl chat. Tú y los amigos Mingl invitados compartís el chat de grupo Room SMARTview; los nombres se ven para miembros. Cuenta incorrecta, caducada o revocada se niega. Unirse a la room no es unirse a una cuenta ni aprobar un pago. BOT DEE nunca toma números de tarjeta."},"help-botdee-room-smartview-end":{"title":"Terminar Room SMARTview","body":"Solo el anfitrión puede terminar una room. Terminar no cobra a nadie ni borra chats privados de otros. Una cuenta compartida impagada debe pagarse o anularse primero. Una room en vivo sigue abierta hasta End Room, unas cuatro horas después de abrir, o si todos se han ido unos 15 minutos. Pausar el chat privado de BOT DEE no es salir de la room. Un invitado que se va no termina la room mientras el anfitrión sigue."},"help-botdee-room-smartview-tab":{"title":"Cuenta compartida Room SMARTview","body":"Primero el opt-in. Luego añade una línea. Cierra con un pagador o dividido. Solo se cobra a los uid que confirman, vía FloqR Stripe. Unirse a la room no es unirse a la cuenta. BOT DEE nunca toma números de tarjeta. Club POS más adelante."},"help-botdee-room-smartview-who-pays":{"title":"Quién paga","body":"Pregunta Who’s paying en Room SMARTview para ver el opt-in. Nadie se cobra porque alguien dijo buy. Los últimos cuatro de la tarjeta quedan en el recibo del pagador."},"help-botdee-room-smartview-kick":{"title":"Quitar a alguien de Room SMARTview","body":"Solo el anfitrión puede quitar a un invitado. Un amigo expulsado no lee más mensajes de la room. Una respuesta del modelo no puede expulsar a nadie."},"help-botdee-room-smartview-share":{"title":"Compartir en Room SMARTview","body":"Share this conversation nunca copia tu hilo privado de BOT DEE. BOT DEE muestra una vista previa de hechos compartibles de este mensaje, marcados como provisionales. Puedes editar o quitar hechos. Perfiles y SMARTsummary quedan fuera de la room."},"help-botdee-room-smartview-schedule":{"title":"Unirse ahora o fijar un horario","body":"Tras configurar Room SMARTview, elija Unirse ahora o Fijar un horario. Unirse ahora abre la sesión BOT DEE ya y no pone una tarjeta en Search. Fijar un horario es cuando empieza la room BOT DEE — no Shared Itinerary. Una hora futura activa SMARTnotification de Search solo para usted y amigos Mingl invitados. Los invitados confirman RSVP hasta que la room esté en vivo; entonces Join Now abre BOT DEE (no Mingl chat)."},"help-botdee-room-collab":{"title":"Compartir una reserva headless en Room SMARTview","body":"En una Room SMARTview, las elecciones VIP reserV o ShoutOut del anfitrión aparecen para todos. Los miembros votan Sí o No. Hold it y el pago quedan con el anfitrión — unirse y votar no es un pago. BOT DEE nunca toma números de tarjeta. Stripe se abre en un pop-out."},"help-botdee-room-elect-host":{"title":"Elegir un anfitrión de Room SMARTview","body":"Cualquiera en la sesión puede ser anfitrión. Nómate a ti o a otro miembro. Un candidato se convierte en anfitrión con el 60 % de los miembros actuales (redondeo hacia arriba). Si el anfitrión se va, el resto elige uno nuevo — la room sigue abierta. Kick y End quedan con el anfitrión elegido."},"help-botdee-smartview-review":{"title":"Revisar y corregir un SMARTsummary","body":"Gemini redacta solo con campos públicos en FLOQR — no en cada vista. Si un dato es falso, oculte el campo o edite el resumen. Su texto no se sobrescribe. Un conflicto de perfil pide revisión. Informe una tarjeta incorrecta desde la superposición."},"help-botdee-smartview-chrome":{"title":"SMARTview y Site Chrome","body":"People SMARTview usa el Site Chrome FLOQR del visitante (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). No hay un segundo tema. Cambiar el chrome actualiza la tarjeta sin perder el borrador."},"help-botdee-smartview-categories":{"title":"Categorías SMARTview","body":"Cuatro pestañas: Social, Citas, Gastronomía y Viajes futuros. Social abre en Música, luego Nightlife, Deportes y Eventos. Las etiquetas son solo lo compartido — sin títulos duplicados ni viajes o notas inventados. Viajes futuros solo destinos públicos."},"help-botdee-smartview-media":{"title":"Fotos y vídeos SMARTview","body":"La tarjeta compacta usa el mismo hero que tu perfil público FLOQR — el primer elemento de Profile Media (8 fotos + 2 vídeos). Toque para Fotos y Vídeos de esos huecos públicos. Deslice o flechas, luego X (o Escape) vuelve al chat y al borrador."},"help-botdee-smartview-privacy":{"title":"Privacidad de SMARTview","body":"SMARTview muestra solo campos ya públicos en FLOQR. No es búsqueda web. Citas solo con opt-in. Oculte un campo en Mi perfil y sale de SMARTview. Quien esté bloqueado no ve la tarjeta. Informe un resumen incorrecto desde la superposición."},"help-botdee-smartview-translation":{"title":"Traducción de SMARTview","body":"Su SMARTsummary se guarda en el idioma predeterminado del perfil — ese es el origen, aunque no sea inglés. Tras guardar, FLOQR encola una traducción a cada otro idioma, incluido el inglés. Un visitante en inglés ve el SMARTsummary en inglés cuando termina ese trabajo. Si está pendiente o falla, se muestra el idioma de origen etiquetado — nunca una traducción antigua como actual."},"help-botdee-smartview-edit":{"title":"Editar su SMARTsummary","body":"Solo usted edita su SMARTsummary en el idioma predeterminado del perfil. El guardado es inmediato. Las traducciones van en segundo plano. Gemini no sobrescribe su texto. Si el perfil público cambia, FLOQR le pide revisar, no reemplazar."},"help-botdee-privacy-assistant":{"title":"Asistente de privacidad BOT DEE","body":"Cambie lo que otros usuarios FLOQR ven en la visibilidad de Mi perfil — BOT DEE no añade un segundo interruptor público. Si la investigación web asoció a la persona equivocada, puede disputarlo sin cambiar su perfil. BOT DEE no promete que un sitio tercero borre la página original."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Cada recomendación puede mostrar evidencias, fecha de comprobación, si hubo personalización y si un espacio es patrocinado. Puede pedir a BOT DEE que no personalice esta búsqueda."},"help-botdee-research-library":{"title":"Biblioteca de investigación BOT DEE","body":"Guarde lugares y tarjetas que pidió a BOT DEE. Un Place ID de Google no copia fotos ni reseñas. Puede actualizar o borrar. Las cachés con licencia siguen apagadas hasta aprobar al proveedor."},"help-botdee-smartview":{"title":"Ver mi SMARTview","body":"Ver mi SMARTview muestra tu tarjeta de persona con campos públicos de FLOQR, con los mismos Profile Media que tu página pública — no maquetas de club o restaurante. Editar mi SMART Summary cambia el resumen en el idioma del perfil. Las maquetas de club/restaurante están en Master Admin → Features → BOT DEE → SMARTviews. No hay Places ni Yelp en vivo."},"help-botdee-memory":{"title":"Chats BOT DEE guardados","body":"Abra Funciones y pedidos → Mi BOT DEE para guardar chats tras la pausa, exportar o borrar historial. La pausa de cinco minutos termina la sesión en vivo. Si acepta, BOT DEE guarda el chat. Los invitados no se guardan. Mingl se queda en Mingl."},"help-botdee-knows-of-me":{"title":"Lo que BOT DEE sabe de mí","body":"Los hechos guardados con su consentimiento están en Funciones y pedidos → Mi BOT DEE. La lista está vacía si la memoria está apagada o no hay datos. Exporte o borre aquí. BOT DEE nunca guarda su dirección IP. Mingl no se copia."},"help-search-settings-appearance":{"title":"Settings en Search","body":"En la pantalla Search, toca Settings para abrir Profile & Settings en la pestaña Appearance — ahí está Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). La ficha Settings usa el mismo pack de iconos chrome que las demás marcas de Search."},"help-club-website-feed":{"title":"Feed para la web del club","body":"Muestra tu página de club de FLOQR publicada en tu propia web. Pulsa «Generar clave y enlaces» y pega el código iframe en tu web, o da el enlace JSON o RSS a tu administrador web. El feed muestra próximos eventos, DJ y personal destacados, la galería y los datos de contacto, según los controles de tu página pública. Las fotos del personal solo aparecen si el consentimiento de fotos está confirmado. Generar una clave nueva desactiva los enlaces anteriores, incluidos los del horario del personal."},"help-featured-staff":{"title":"Personal destacado","body":"Marca el personal que quieres en la página pública del club. Para cada persona, toca una de sus fotos de FLOQR o elige «Subir desde el ordenador». Puedes cambiar el puesto que aparece bajo su nombre. Pulsa «Save Public Profile» para publicar. Antes de publicar fotos, consigue el permiso de cada persona y marca la casilla de consentimiento de fotos."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox guarda System Messages y mensajes internos de soporte. La lista carga primero para que tus mensajes aparezcan rápido. Pulsa el botón flotante New Message para redactar — escribe un nombre o @username para encontrar un destinatario permitido (Club Admin, CSR o personal aprobado). El chat patron-a-patron sigue en Mingl tras Mingl mutuo. Abrir una invitación de turno no confirma — revisa y Approve selected en Work Calendar."},"botdee-ask-floqr":{"title":"Pregunta FloqR con BOT DEE","body":"Pregunta FloqR con BOT DEE: toca la marca animada o espera el mensaje y luego escribe lo que quieras en palabras sencillas. Productos: Mingl, RydR, BartR, ShoutOut, FloqCAST (superestrella), palos. Metas: diga “Quiero poder…” (por ejemplo, convertirme en Club Admin) o “make me a superstar” para conocer los pasos y enlaces."},"help-vip-book-table":{"title":"Reservar mesa VIP (VIP reserV)","body":"VIP reserV muestra el mapa y reserva mesas. Abre VIP reserV desde Buscar, elige Decades o Lima Twist Club y una noche, toca una mesa verde, reserva 30 minutos, acepta Términos y paga el depósito con FloqR Stripe. Barras y DJ no reservables. En Aurelia, use Explore 3D walk-through para la sala interactiva (la reserva sigue en el plano 2D)."},"help-vip-choose-venue":{"title":"Elegir un local VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club y Aurelia tienen cada uno un plano 2D publicado; Aurelia también ofrece Explore 3D walk-through."},"help-become-club-admin":{"title":"Conviértete en un Club Admin","body":"Solicite acceso Club Admin y luego obtenga la aprobación del lugar."},"help-role-profiles":{"title":"Descripción general de los perfiles de roles","body":"Vea cómo funcionan los roles Club Admin, DJ, Promoter y hospitalidad."},"help-staff-scheduling":{"title":"Calendario y programador","body":"Club Admin El calendario muestra tarjetas Borrador (morado), Pendiente (ámbar), Confirmado (verde) y Abierto/sin completar, cada una con un estado escrito, no solo con un color. El programador es la cuadrícula de borrador/publicación de personas × días. Website ingest / publicVenueCalendar devuelve solo asignaciones confirmadas. Se muestra que una pastilla verde Pagada este mes es Club Admins cuando staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Suscripciones de notificación del club SMS y WhatsApp","body":"Club Admin → Notificaciones: Send test alert usa las casillas actualmente marcadas. In-app (y Push) escribe un mensaje del sistema en FloqR Inbox. El correo electrónico utiliza direcciones de administrador del club. SMS y WhatsApp aún necesitan una suscripción paga más un teléfono de alerta E.164. Pastilla verde = Firebase suscripción 1 (paquete prepago de $10); rojo = 0. Si Send test alert devuelve Authentication Error - invalid username, Firebase secreto TWILIO_ACCOUNT_SID debe ser el SID de cuenta que comienza con AC (34 caracteres) de console.twilio.com, no el token de autenticación ni una clave API (SK)."},"help-club-sms-notification":{"title":"SMS suscripción de notificación","body":"La píldora SMS es verde cuando Firebase smsSubscribed es 1 (paquete prepago de $10, 466 créditos, no mensual ni anual). Rojo/intermitente significa 0: ¿abierto? y toque Subscribe $10. Los créditos restantes y la fecha del último pago se encuentran en esta ayuda. Desmarque SMS y Guardar para pausar las alertas sin perder el paquete pago."},"help-club-whatsapp-notification":{"title":"WhatsApp suscripción de notificación","body":"La píldora WhatsApp es verde cuando Firebase whatsappSubscribed es 1 (paquete prepago de $10, 233 créditos, no mensual ni anual). Rojo/intermitente significa 0: ¿abierto? y toque Subscribe $10. Los créditos restantes y la fecha del último pago se encuentran en esta ayuda. Desmarque WhatsApp y Guardar para pausar las alertas sin perder el paquete pago."},"help-schedule-message-templates":{"title":"Programar plantillas de mensajes","body":"Club Admin → Notificaciones → Message templates. Estos son mensajes del sistema (Inbox / correo electrónico / SMS / WhatsApp), no ShoutOut. Edite el título y el cuerpo de New shift needs confirmation, Actualización de programación, Turno confirmado y Turno rechazado. Marcadores de posición: {club} {role} {when} {link} {worker}. La bandeja de entrada del trabajador usa Review & confirm shift, nunca Open Related ShoutOut."},"help-schedule-confirm":{"title":"Confirmar turnos asignados","body":"Inbox / Correo electrónico / SMS enlaces abiertos Work Calendar. Mire cada tarea pendiente, márquela (o Select all), luego Approve selected. Abrir el enlace no confirma. Solo el miembro del servicio asignado puede aprobar; Club Admin no puede confirmar en su nombre."},"help-template-catalog-report":{"title":"Informe de catálogo de plantillas","body":"Enumera cada tipo de plantilla ShoutOut y qué tamaños de LED admite (Is96x48, Is64x48, Is64x32). Un lugar solo ofrece una plantilla cuando al menos una de esas banderas es 1 y la bandera VenueSupports* correspondiente es 1. Las plantillas de cumpleaños/medios divididos son 1 en 96×48, 64×48 y 64×32. 96 × 48 tiene 3 líneas una al lado de la otra; 64×48 y 64×32 repiten la foto y luego el mensaje de 3 líneas con una tarjeta de mango FLOQR +."},"help-club-display-screens":{"title":"FLOQR pantallas de visualización","body":"Firebase clubLocations almacena VenueSupports96x48, VenueSupports64x48 y VenueSupports64x32 como 0 o 1. Las plantillas almacenan Is96x48, Is64x48 y Is64x32 de la misma manera. Un lugar solo enumera una plantilla cuando al menos un par es 1. Las URL de Xibo permanecen display.html?location=id y display2.html?location=id: el tamaño de la pantalla no está en la URL. Cumpleaños se ofrece en los tres tamaños (3 líneas una al lado de la otra en 96×48; bucle de foto/grito en 64×48 y 64×32). El principal es display.html. El secundario es display2.html."},"help-staff-week-calendar":{"title":"Programador","body":"Club Admin El programador es una cuadrícula de personas × días de la semana. Save shift cierra el editor con Schedule card successfully saved. Cree borradores, Publish schedule para que los trabajadores confirmen pendientes hasta que se confirmen, Select shifts para realizar una eliminación múltiple y Website ingest para colocar los turnos publicados en el sitio del club. Ventana de turno predeterminada = club abierto − 2 horas hasta el cierre + 1 hora."},"help-staff-schedule-user-guide":{"title":"Guía del usuario de programación de personal","body":"Abrir el ? al lado de Programador en Club Admin Programación. Cree borradores de turnos, Publish schedule para que los trabajadores confirmen pendientes → confirmados, luego Select shifts para eliminar varios a la vez. Ejemplo: todos los drafts del miércoles más una ficha confirmada el jueves."},"help-create-publish-schedule":{"title":"Crear y publicar un horario de personal","body":"Agregue turnos preliminares en la cuadrícula de personas x días, revise los chips y luego Publish schedule. Los trabajadores deben confirmar antes de que se confirme un turno. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Eliminar múltiples turnos programados o borradores","body":"Select shifts, mezcle las cabezas del día y las patatas fritas, luego Delete selected. Ejemplo: todos los borradores del miércoles más un turno confirmado del jueves."},"help-staff-worksheet":{"title":"Hoja de Trabajo - Calendario Semanal del Personal","body":"Los miembros del servicio electos abren Work Calendar en Configuración. Inbox / Correo electrónico / SMS enlaces de confirmación llegan aquí. Revise las tareas pendientes, marque cada turno (o Select all), luego Approve selected; abrir el mensaje no confirma. La cuadrícula semanal muestra los turnos de colegas publicados. Los borradores se quedan en Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Todos empiezan como patron FLOQR. En My Profile & Settings pulse Elect to become a service member, elija rol, clubs y envíe al final de la página.\n\nGuía de plantillas de perfil — los perfiles sociales patron siguen en Medios públicos. Cada rol de servicio usa su plantilla en Mi perfil.\n\nAprobación Club Admin — Club Admin → Employee/Workers → Pending Worker Requests, o Revisar y elegir en esta pestaña."},"help-venue-website-ingest":{"title":"Ingesta del sitio web del club (API, RSS, iframe)","body":"Club Admin → Programación → Website ingest. Genera un secreto (se muestra una vez; solo se almacena un hash). Introduzca los turnos del personal publicados en el sitio web oficial del club con JSON (?format=json&dataset=schedule|hours|profile|all), RSS o un fragmento de iframe. Los borradores, el correo electrónico de los trabajadores y el teléfono nunca se incluyen. Gire el secreto si gotea."},"help-venue-hours-calendar":{"title":"Horario de apertura del lugar","body":"En el perfil público del club, establezca el horario de apertura/cierre semanal predeterminado y luego agregue anulaciones de períodos para semanas especiales sin perder el horario predeterminado. La página pública del club muestra una cuadrícula de la semana de domingo a sábado con el rango de fechas (por ejemplo, del domingo 9 al sábado 15 de agosto de 2026) y el color del calendario. Los próximos días festivos enumeran los horarios de apertura y cierre y avisan cuando difieren del día habitual de la semana. La programación del personal utiliza abierto − 2 h hasta cierre + 1 h. La lista de invitados puede sugerir noches de puertas abiertas."},"help-club-admin-affiliation":{"title":"Club Admin asignación de lugar","body":"Los 3 solo abren el Centro de comando del lugar para un club al que están asignados. Abrir admin.html sin un lugar ya no es el predeterminado Zebbies. Las cuentas de demostración temp_clubadmin_N@floqr-demo.com se asignan a temp-democlub-N. Los administradores no asignados solicitan la asignación desde Master Admin."},"help-venue-command-center":{"title":"Venue Command Center","body":"Aprueba ShoutOuts, revisa el rendimiento del local y concilia la actividad de la cuenta de esta ubicación."},"help-club-template-repository":{"title":"Plantillas de tu club","body":"Las plantillas creadas solo para tu club aparecen primero, marcadas con «Exclusivo de» y el nombre del local. Las plantillas asignadas son las que los clientes pueden elegir en tu club; cámbialas con Asignar plantilla o Quitar plantilla. La búsqueda encuentra una plantilla aunque falte una tilde o haya una pequeña errata."},"help-employee-network":{"title":"Red de empleados y personal","body":"Solo se muestran personas vinculadas a este club: personal designado o aprobado aquí, administradores del club y personal afiliado a este club. Para dar un rol a alguien, escribe su nombre, usuario o email en Designar cliente para un rol, toca Seleccionar junto a la persona correcta, elige el rol, luego toca Designar rol al cliente seleccionado y confirma. La persona necesita primero una cuenta de cliente FLOQR. Los camareros, camareras y bottle girls de la lista pueden ser representantes de atención al cliente (CSR)."},"help-template-tags":{"title":"Etiquetas de plantillas","body":"Añade palabras que los clientes podrían escribir al buscar una plantilla en tu local, como noche de partido o cumpleaños. Los Gestores de plantillas pueden añadir etiquetas. Los Administradores de plantillas y los Club Admins también pueden quitarlas. El Club Admin asigna estos roles en Role Activity & Permission."},"help-display-idle-default":{"title":"Pantalla en espera: Use ShoutOut @ local","body":"Cuando no se muestra ningún ShoutOut, Display 1 muestra «Use ShoutOut @» con el nombre de tu local. Cada ShoutOut aprobado se muestra 10 minutos y luego la pantalla vuelve sola a ese mensaje. Restablecer la pantalla predeterminada en Club Admin lo hace al instante."},"help-club-messaging-credit":{"title":"Crédito SMS y WhatsApp","body":"Cada paquete de 10 $ financia 7,00 $ de capacidad Twilio; FloqR retiene 3,00 $ de margen. Paquete SMS → 466 mensajes (≈ 0,015 $ SMS US). Paquete WhatsApp → 233 mensajes (≈ 0,030 $ Twilio + Meta marketing). Con saldo 0, compre otro paquete antes de enviar. Desbloqueo SMS ops (10 $) incluye un paquete SMS. Servicio WhatsApp (10 $) incluye un paquete WhatsApp. Cálculo: 10 $ → 466 SMS o 233 WhatsApp (7,00 $ Twilio / 3,00 $ FloqR)."},"help-club-marketing-campaigns":{"title":"Campañas de marketing","body":"Elija plantilla del sector, cargue fondo e imágenes extra, edite textos y guarde o envíe. El envío debita créditos SMS o WhatsApp en Crédito de mensajería."},"help-club-in-app-marketing":{"title":"Marketing in-app","body":"Publica un flyer o un video de hasta 30 segundos en nombre de tu club. Cuando está pagado y aprobado por FLOQR, aparece en la pantalla de carga de la búsqueda, en Mingl, RydR y en otras pantallas de FLOQR. Publicadores de anuncios del club permite que un miembro del equipo publique anuncios para el club (rol Club Ad Poster). No necesitas créditos SMS."},"help-vip-terms-consent":{"title":"Términos VIP reserV","body":"Tras retener una mesa, abre la página de Términos, léelos y acepta una vez (marketing opcional aparte). El consentimiento se guarda antes de FloqR Stripe Checkout — como un ShoutOut de pago, luego recibo y pase."},"help-vip-door-pass":{"title":"Pase de puerta VIP reserV","body":"Tras confirmar el depósito, Mi perfil → Reservas → Mostrar pase para un QR de un solo uso. Trae ID 21+. El personal usa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in en puerta VIP reserV","body":"Los VIP Managers abren VIP reserV Door para esta noche. Escanea o pega el token, confirma ID 21+, check-in. No-show solo tras gracia. Un enlace notify no cambia el estado."},"help-vip-payment-collector":{"title":"Cobrador de pago VIP reserV y Club POS","body":"Preferido para clubs en vivo con Toast/SpotOn: Club POS — FLOQR reserva/retiene/mapa; el POS cobra depósito, cuenta y gasto. Alternativas: Club Stripe, FloqMedia Stripe (FloqR) o motor VIP + CSV. Aurelia (Demo Club) usa FloqMedia Stripe por defecto — pregunte a BOT DEE los pasos Master y Club Admin."},"help-vip-table-isbooked":{"title":"Estado isBooked de mesas VIP en Firestore","body":"Cada club VIP onboarded tiene un doc Firestore por número de mesa y noche: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. El id es el número impreso (p. ej. T1, B3). Tras completar la reserva: isBooked \"1\", isBookedYes \"yes\". Libres: \"0\" / \"no\". Los holds no cambian isBooked. Cancelar → \"0\". getVipAvailability usa isBooked como estado de reserva. Cancelar siempre pone isBooked en \"0\"; FloqMedia/Club Stripe puede reembolsar el depósito según la política del club."},"help-vip-floqr-stripe-aurelia":{"title":"Configurar FloqMedia Stripe para Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) usa FloqMedia Stripe (FloqR Checkout) como cobrador de depósito VIP por defecto — los patronos pagan en el Stripe de plataforma FloqR y luego la mesa queda reservada.\n\nPasos Master Admin:\n1) Abrir Master Admin → Features Mgmt → VIP reserV Payments.\n2) Confirmar que VIP Reservations está habilitado en la red.\n3) Seed / refresh de proveedores POS solo si más adelante usa Club POS — no hace falta para FloqMedia Stripe.\n4) Dejar Aurelia en FloqMedia Stripe salvo Club POS o Club Stripe.\n5) Tras depósitos, revisar Network VIP billing.\n\nPasos Club Admin (Aurelia):\n1) Entrar como temp_clubadmin_1@floqr-demo.com (OTP por email en el inicio) o Club Admin de Aurelia.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) En Payment collector, elegir FloqMedia Stripe (FloqR).\n4) Mantener Require deposit before table is marked booked.\n5) Guardar Save payment collector.\n6) Prueba: vip.html?location=temp-democlub-1 → retener mesa → Términos → Pagar depósito (tarjeta test 4242…).\n7) Door / facturación: Open Door y Refresh billing.\n\nNo elija Club POS en demos Aurelia salvo sandbox Toast/SpotOn. FloqMedia, Stripe, ShoutOut y VIP reserV no se traducen."}},"it":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Un invito compatto Mingl Room può comparire su Search quando imposti un orario per una room BOT DEE, o un amico Mingl ti invita. L’host vede la propria room programmata su Search senza la query demo Cancun. Vedi invito apre Room SMARTview. Join Now va a BOT DEE, non Mingl chat. Non ora nasconde la scheda in questa scheda; Inbox tiene Review BOT DEE invite. La query demo Cancun è solo Studio. L’arte è illustrazione, non foto. Le room Join Now senza orario non appaiono su Search."},"help-smartvisuals-room":{"title":"Room SMARTview con SMARTvisuals","body":"Room SMARTview mostra l’invito Mingl: orario, RSVP o stato live, e Join Now. Join Now su Search apre BOT DEE (non Mingl chat) con room= e t=. SMARTstencils e SMARTbackgrounds seguono il titolo autorizzato — Cancun Trip usa arte di viaggio, non una foto reale di Cancun. La chat BOT DEE privata non sceglie mai l’arte. Un Ad etichettato sotto è un campione da quei tag. Vuoto per chat privata o iniezione; non è un inserzionista live."},"help-scheduling-schedule-for":{"title":"Pianificazione del personale","body":"Pianifica turni e ingaggi, poi avvisa ogni persona tramite Inbox, Email, SMS o WhatsApp. In «Turni per» scegli il calendario su cui lavori: «Il mio calendario DJ» è il tuo calendario, «Club» elenca i club che gestisci e «Società di promozione» le società per cui fai promozione. Ogni calendario ha il proprio abbonamento da 20 $/mese. I turni assegnati a te compaiono in «I miei incarichi», dove li confermi o li rifiuti."},"help-staff-marketing-consent":{"title":"Consenso marketing del personale","body":"Quando entri nel team di un locale o di un evento, devi selezionare la casella del consenso marketing. Consente a quel locale o organizzatore, e ai suoi amministratori e manager, di usare il tuo nome FLOQR, il tuo ruolo e le tue foto e i tuoi video pubblicati su siti web, volantini e social media (Instagram, Facebook, TikTok, YouTube e simili) senza chiederti di nuovo il permesso per ogni utilizzo. Non possono pubblicare il tuo numero di telefono né la tua email. Puoi revocarlo in qualsiasi momento in Il mio profilo, scheda Servizi e membri del servizio. La revoca interrompe il nuovo marketing; i materiali già stampati o pubblicati non devono essere ritirati. I Club Admin vedono lo stato del consenso di ogni membro del personale in Rete di dipendenti e personale e in Personale in evidenza."},"help-botdee-privacy-session":{"title":"Privacy e sessione BOT DEE","body":"La pausa di cinque minuti termina la sessione dal vivo. Non cancella questa chat da connesso, i ricordi o i flussi. Restano anche le copie in Il mio profilo → Funzioni e ordini → My BOT DEE. Gli ospiti restano effimeri. Le chat Mingl non vengono mai copiate qui. Invio invia; Maiusc+Invio inizia una nuova riga. Nome e tono sono in Il mio profilo → My BOT DEE, non un pulsante in chat."},"help-botdee-place-search":{"title":"Chiedere a BOT DEE i locali FLOQR","body":"Chiedi in parole semplici — ristoranti di sushi a Washington DC, club a DC o un club per nome. BOT DEE cerca solo venue FLOQR onboardate, non Google o Yelp. I risultati aprono una Place SMARTview compatta (nome, breve testo, valutazioni, link alla pagina pubblica) con SMARTbackground — non un pozzo foto. Nominare una città con VIP reserV (reservations in Miami) allega ancora Place SMARTview accanto alla card VIP. Foto dei patron e pitch ShoutOut restano fuori se non li hai chiesti. Se non c’è ancora nulla, BOT DEE lo dice."},"help-botdee-page":{"title":"BOT DEE","body":"Chatta con BOT DEE nella pagina BOT DEE con parole semplici: eventi e club, ShoutOut, Mingl, RydR, BartR, FloqCAST, il tuo profilo, gli orari del personale o gli strumenti Club Admin. Premi Invio per inviare; Maiusc+Invio inizia una nuova riga. BOT DEE chiacchiera come una persona (prova How are you?) e cerca solo quando chiedi come fare qualcosa in FLOQR. Se hai effettuato l’accesso, BOT DEE conserva questa chat se aggiorni o apri un altro telefono, e dopo la pausa può riprendere la cronologia salvata. La pausa non cancella la chat. Le risposte usano la classificazione del tuo account. Se hai effettuato l’accesso, BOT DEE vede gli stessi datapoint pubblici volontari che vedi tu (musica, cibo, viaggi, hobby e il resto di Privacy datapoint sharing) — mai email, telefono, dati della carta o GPS. Tocca Impostazioni sotto la casella di chat per chat e memorie salvate. Tocca una foto in chat per aprirla in una finestra. Chiudi con X o Chiudi per tornare alla chat. Il + in alto a destra apre le chat salvate e non le elimina."},"help-botdee-smartview-troubleshoot":{"title":"Risoluzione problemi SMARTview","body":"Scheda vuota: campi nascosti o blocco. Salvataggio fallito: accedi — le traduzioni stanno sul server. In attesa o errore: lingua di origine etichettata. Solo il titolare modifica. SMARTviews Master Admin resta il catalogo mock; Places e Yelp restano off. Il tema segue Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary resta sincronizzato","body":"Modifica lo SMARTsummary nella lingua predefinita del profilo. Il salvataggio è immediato. Schede e SMARTview aperti si aggiornano dallo stesso record. Le traduzioni partono in background e non sovrascrivono una modifica più recente. Se nascondi il profilo, blocchi qualcuno o elimini l’account, le schede scompaiono. Gemini non sovrascrive il tuo testo."},"help-botdee-smartcard-search":{"title":"Chiedere a BOT DEE chi è qualcuno","body":"“Who am I?” apre il tuo SMARTview. “Who is …”, “What do you know of …” o “What about …” più nome, cognome, nome visualizzato, handle Mingl o FloqR, o un handle social (Instagram, TikTok, X). Solo quei campi di identità — non bio, like, drink o generi. Un risultato apre una scheda People SMARTview in chat — non un elenco markdown né una griglia di foto. Più risultati mostrano SMARTcard compatte. Profili privati, bloccati o non pubblicati non compaiono — BOT DEE non conferma se l’account esiste."},"help-botdee-smartcard":{"title":"SMARTcard persone","body":"Se più profili pubblici FLOQR corrispondono, BOT DEE mostra SMARTcard compatte in chat: prima la foto a tutta larghezza, poi nome e handle, poi un SMARTsummary compatto senza riquadro imbottito. Tocca una scheda per aprire lo SMARTview completo — stesso impilamento. Le schede usano lo stesso profilo pubblico e SMARTsummary. Aprire una scheda non chiama Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Digita Ver, Vers o Version — le maiuscole non contano. BOT DEE mostra la scheda della versione. Una domanda più lunga come “qual è la tua versione?” mostra comunque quella scheda."},"help-botdee-version-smartview-status":{"title":"Lo stato Version SMARTview è una sonda live","body":"Lo stato del servizio è sondato su questa richiesta Version: Functions e package raggiungibili con Gemini configurato → Operativo; Functions e package ok ma Gemini non configurato → Degradato; Functions assenti da questa richiesta → Non disponibile. Mai un’etichetta statica Non verificato. Il modello IA mostra l’id Gemini configurato di questo deployment anche se questo turno non ha generato. I timbri frontend e backend possono differire; entrambi sono etichettati. Master Admin può vedere diagnostica extra in Dettagli tecnici — i patron no."},"help-botdee-version-smartview-tabs":{"title":"Schede Version SMARTview","body":"Panoramica descrive BOT DEE e apre Dettagli tecnici senza uscire dalla chat. Novità elenca solo i cambiamenti verificati di BOT DEE e Gemini — non Master Admin, strumenti beta tester o altre note di prodotto FLOQR. Aiuto ripete il comando Ver / Vers / Version. Cambiare scheda o espandere tiene la bozza non inviata e lo scorrimento. La scheda usa il tuo Site Chrome — non c’è un secondo tema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Nella chat BOT DEE di’ Open Room SMARTview, Start a group chat, o pianifica un viaggio a Cancun in parole semplici. Poi: Entra ora o Imposta un orario. Entra ora apre una sessione di amici Mingl subito e non mette una scheda su Search. Imposta un orario è quando inizia la room BOT DEE — non Shared Itinerary — e attiva SMARTnotification di Search per te e gli amici Mingl invitati. Invita solo amici Mingl — host più 7 ospiti. Anche gli ospiti possono invitare. Unirsi non è un pagamento e non apre un conto condiviso. BOT DEE non prende mai numeri di carta. I messaggi BOT DEE privati restano privati. Site Chrome segue Appearance. Una room live resta aperta fino a End Room, circa quattro ore dopo l’apertura, o se tutti sono assenti da circa 15 minuti. La pausa della chat BOT DEE privata è distinta."},"help-botdee-room-smartview-invite":{"title":"Invita amici Mingl","body":"Dopo Confirm (Join Now o Set a schedule), Invite mostra solo i tuoi amici Mingl. Tocca un amico o scrivi Invite lorna — Inbox riceve Review BOT DEE invite. Il chip resta grigio con Invite sent — un secondo tocco non invia un secondo invito. È un comando Room SMARTview, non VIP reserV né People SMARTview Invite. Non è un link pubblico. Capienza: host più 7. Gli ospiti possono invitare altri amici Mingl finché l’host non lo disattiva. Entrare non è un pagamento. Se un chip sei tu o qualcuno già in sessione, resta Sei tu o Già in questa sessione e non invia un secondo invito."},"help-botdee-room-smartview-join":{"title":"Unisciti a una sessione BOT DEE","body":"Apri l’invito Inbox o Search Join Now autenticato come l’amico Mingl destinatario. Join Now apre BOT DEE, non Mingl chat. Tu e gli amici Mingl invitati condividete la chat di gruppo Room SMARTview; i nomi sono visibili ai membri. Account sbagliato, scaduto o revocato rifiuta. Entrare nella room non è entrare in un conto e non approva un pagamento. BOT DEE non prende mai numeri di carta."},"help-botdee-room-smartview-end":{"title":"Termina Room SMARTview","body":"Solo l’host può terminare una room. Terminare non addebita nessuno e non cancella le chat private altrui. Un conto condiviso non pagato va prima pagato o annullato. Una room live resta aperta fino a End Room, circa quattro ore dopo l’apertura, o se tutti sono assenti da circa 15 minuti. La pausa della chat BOT DEE privata non è un logout della room. Un ospite che esce non termina la room se l’host è presente."},"help-botdee-room-smartview-tab":{"title":"Conto condiviso Room SMARTview","body":"Prima l’opt-in. Poi aggiungi una riga. Chiudi con un pagatore o diviso. Solo gli uid che confermano vengono addebitati via FloqR Stripe. Entrare nella room non è entrare nel conto. BOT DEE non prende mai numeri di carta. Club POS più avanti."},"help-botdee-room-smartview-who-pays":{"title":"Chi paga","body":"Chiedi Who’s paying in Room SMARTview per vedere l’opt-in. Nessuno viene addebitato perché qualcuno ha detto buy. Le ultime quattro della carta restano sulla ricevuta del pagatore."},"help-botdee-room-smartview-kick":{"title":"Rimuovi qualcuno da Room SMARTview","body":"Solo l’host può rimuovere un ospite. Un amico rimosso non legge altri messaggi della room. Una risposta del modello non può espellere nessuno."},"help-botdee-room-smartview-share":{"title":"Condividi in Room SMARTview","body":"Share this conversation non copia mai il tuo thread BOT DEE privato. BOT DEE mostra un’anteprima di fatti condivisibili da questo messaggio, contrassegnati come provvisori. Puoi modificare o togliere fatti. Profili e SMARTsummary restano fuori dalla room."},"help-botdee-room-smartview-schedule":{"title":"Entra ora o imposta un orario","body":"Dopo il setup Room SMARTview, scegli Entra ora o Imposta un orario. Entra ora apre la sessione BOT DEE subito e non mette una scheda su Search. Imposta un orario è quando inizia la room BOT DEE — non Shared Itinerary. Un orario futuro attiva SMARTnotification di Search solo per te e gli amici Mingl invitati. Gli ospiti RSVP finché la room è live; poi Join Now apre BOT DEE (non Mingl chat)."},"help-botdee-room-collab":{"title":"Condividere una prenotazione headless in Room SMARTview","body":"In una Room SMARTview le scelte VIP reserV o ShoutOut dell’host appaiono a tutti. I membri votano Sì o No. Hold it e il pagamento restano all’host — unirsi e votare non è un pagamento. BOT DEE non prende mai numeri di carta. Stripe si apre in un pop-out."},"help-botdee-room-elect-host":{"title":"Eleggere un host Room SMARTview","body":"Chiunque nella sessione può essere host. Candidati te stesso o un altro membro. Un candidato diventa host al 60% dei membri attualmente presenti (arrotondato per eccesso). Se l’host esce, gli altri eleggono un nuovo host — la room resta aperta. Kick e End restano all’host eletto."},"help-botdee-smartview-review":{"title":"Rivedi e correggi lo SMARTsummary","body":"Gemini bozza solo dai campi pubblici in FLOQR — non a ogni vista. Se un fatto è sbagliato, nascondi il campo o modifica il riassunto. Il tuo testo non viene sovrascritto. Un conflitto di profilo chiede revisione. Segnala una scheda errata dall’overlay."},"help-botdee-smartview-chrome":{"title":"SMARTview e Site Chrome","body":"People SMARTview usa il Site Chrome FLOQR di chi guarda (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Nessun secondo tema. Cambiare chrome aggiorna la scheda senza perdere la bozza chat."},"help-botdee-smartview-categories":{"title":"Categorie SMARTview","body":"Quattro schede: Social, Dating, Dining, Viaggi futuri. Social si apre su Musica, poi Nightlife, Sport, Eventi. I tag sono solo ciò che hai condiviso — niente titoli duplicati né viaggi o voti inventati. I viaggi futuri mostrano solo destinazioni pubbliche."},"help-botdee-smartview-media":{"title":"Foto e video SMARTview","body":"La scheda compatta usa lo stesso hero della pagina pubblica FLOQR — il primo elemento Profile Media (8 foto + 2 video). Tocca per Foto e Video da quegli slot pubblici. Scorri o frecce, poi X (o Escape) torna allo stesso chat e bozza."},"help-botdee-smartview-privacy":{"title":"Privacy SMARTview","body":"SMARTview mostra solo campi già pubblici in FLOQR. Non è ricerca web. Dating solo con opt-in. Nascondi un campo in Il mio profilo e sparisce. Chi è bloccato non vede la scheda. Segnala un riassunto errato dall’overlay."},"help-botdee-smartview-translation":{"title":"Traduzione SMARTview","body":"Il tuo SMARTsummary è salvato nella lingua predefinita del profilo — quella è la fonte, anche se non è l’inglese. Dopo il salvataggio FLOQR mette in coda una traduzione per ogni altra lingua, incluso l’inglese. Un visitatore inglese vede lo SMARTsummary in inglese a lavoro finito. In attesa o errore i visitatori vedono la lingua di origine etichettata — mai una traduzione vecchia come attuale."},"help-botdee-smartview-edit":{"title":"Modifica lo SMARTsummary","body":"Solo tu modifichi lo SMARTsummary nella lingua predefinita del profilo. Il salvataggio è immediato. Le traduzioni partono in background. Gemini non sovrascrive il tuo testo. Se il profilo pubblico cambia, FLOQR chiede una revisione invece di sostituirlo."},"help-botdee-privacy-assistant":{"title":"Privacy Assistant BOT DEE","body":"Cambia in Il mio profilo cosa vedono gli altri utenti FLOQR — BOT DEE non aggiunge un secondo interruttore pubblico. Se la ricerca web ha collegato la persona sbagliata, puoi contestare senza cambiare il profilo. BOT DEE non promette la cancellazione su siti terzi."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Ogni raccomandazione può mostrare prove, data di verifica, personalizzazione e sponsorship. Puoi chiedere a BOT DEE di non personalizzare questa ricerca."},"help-botdee-research-library":{"title":"Research Library BOT DEE","body":"Salva luoghi e schede chieste a BOT DEE. Un Place ID Google non è una copia di foto o recensioni. Puoi aggiornare o eliminare. Le cache con licenza restano off finché il provider non è approvato."},"help-botdee-smartview":{"title":"Vedi il mio SMARTview","body":"Vedi il mio SMARTview mostra la tua scheda Persona dai campi pubblici FLOQR, con gli stessi Profile Media della pagina pubblica — non mock di club o ristoranti. Modifica il mio SMART Summary cambia il riassunto nella lingua del profilo. I mock club/ristorante stanno in Master Admin → Features → BOT DEE → SMARTviews. Niente Places o Yelp live."},"help-botdee-memory":{"title":"Chat BOT DEE salvate","body":"Apri Funzioni e ordini → Il mio BOT DEE per salvare le chat dopo la pausa, esportare o eliminare la cronologia. La pausa di cinque minuti chiude la sessione dal vivo. Con opt-in BOT DEE tiene la chat. Gli ospiti non vengono salvati. Mingl resta in Mingl."},"help-botdee-knows-of-me":{"title":"Cosa BOT DEE sa di me","body":"I fatti salvati con il tuo consenso sono in Funzioni e ordini → Il mio BOT DEE. L’elenco è vuoto se la memoria è spenta o non c’è nulla. Esporta o elimina qui. BOT DEE non memorizza l’IP. Mingl non viene copiato."},"help-search-settings-appearance":{"title":"Settings su Search","body":"Nella schermata Search tocca Settings per aprire Profile & Settings sulla scheda Appearance — lì c’è Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). La tile Settings usa lo stesso pack di icone chrome degli altri marchi Search."},"help-club-website-feed":{"title":"Feed per il sito del club","body":"Mostra la pagina del club FLOQR pubblicata sul tuo sito. Tocca «Genera chiave e link», poi incolla il codice iframe nel sito o dai il link JSON o RSS al tuo webmaster. Il feed mostra prossimi eventi, DJ e personale in evidenza, galleria e contatti, secondo le impostazioni della pagina pubblica. Le foto del personale compaiono solo se il consenso per le foto è confermato. Generare una nuova chiave disattiva i vecchi link, compresi quelli dell’orario del personale."},"help-featured-staff":{"title":"Personale in evidenza","body":"Seleziona il personale da mostrare nella pagina pubblica del club. Per ogni persona tocca una delle sue foto FLOQR o scegli «Carica dal computer». Puoi cambiare il ruolo mostrato sotto il nome. Tocca «Save Public Profile» per pubblicare. Prima di pubblicare foto, ottieni il consenso di ogni persona e seleziona la casella del consenso per le foto."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox contiene System Messages e messaggi di supporto interni. L’elenco si carica per primo così i messaggi appaiono subito. Tocca il pulsante fluttuante New Message per scrivere — digita un nome o @username per trovare un destinatario consentito (Club Admin, CSR o staff approvato). La chat patron-a-patron resta in Mingl dopo il Mingl reciproco. Aprire un invito di turno non conferma — rivedi e Approve selected su Work Calendar."},"botdee-ask-floqr":{"title":"Chiedi FloqR con BOT DEE","body":"Chiedi FloqR con BOT DEE: tocca il segno animato o attendi il messaggio, quindi digita ciò che desideri in parole semplici. Prodotti: Mingl, RydR, BartR, ShoutOut, FloqCAST (superstar), mazze. Obiettivi: dì \"Voglio poter...\" (ad esempio diventare un Club Admin) o \"make me a superstar\" per passaggi e collegamenti."},"help-vip-book-table":{"title":"Prenota un tavolo VIP (VIP reserV)","body":"VIP reserV mostra la mappa e prenota tavoli. Apri VIP reserV da Cerca, scegli Decades o Lima Twist Club e una serata, tocca un tavolo verde, tieni 30 minuti, accetta i Termini e paga il deposito con FloqR Stripe. Bar e DJ non prenotabili. Ad Aurelia usa Explore 3D walk-through per la sala interattiva (la prenotazione resta sulla mappa 2D)."},"help-vip-choose-venue":{"title":"Scegli un locale VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club e Aurelia hanno ciascuno una pianta 2D pubblicata; Aurelia offre anche Explore 3D walk-through."},"help-become-club-admin":{"title":"Diventa un Club Admin","body":"Richiedi l'accesso Club Admin, quindi ottieni l'approvazione della sede."},"help-role-profiles":{"title":"Panoramica dei profili di ruolo","body":"Scopri come funzionano i ruoli Club Admin, DJ, Promoter e ospitalità."},"help-staff-scheduling":{"title":"Calendario e pianificazione","body":"Club Admin Il calendario mostra le carte Bozza (viola), In sospeso (ambra), Confermata (verde) e Aperte/non compilate, ciascuna con uno stato scritto, non solo il colore. Lo strumento di pianificazione è la griglia di bozze/pubblicazioni persone x giorni. Website ingest / publicVenueCalendar restituisce solo le assegnazioni confermate. Una pillola verde pagata questo mese viene mostrata a Club Admins quando staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Abbonamenti alle notifiche Club SMS e WhatsApp","body":"Club Admin → Notifiche: Send test alert utilizza le caselle attualmente selezionate. In-app (e Push) scrive un messaggio di sistema in FloqR Inbox. L'e-mail utilizza gli indirizzi dell'amministratore del club. SMS e WhatsApp necessitano ancora di un abbonamento a pagamento più un telefono di allarme E.164. Pillola verde = abbonamento da Firebase 1 (pacchetto prepagato da $ 10); rosso = 0. Se Send test alert restituisce Authentication Error - invalid username, Firebase segreto TWILIO_ACCOUNT_SID deve essere il SID dell'account che inizia con AC (34 caratteri) da console.twilio.com — non il token di autenticazione e non una chiave API (SK)."},"help-club-sms-notification":{"title":"SMS abbonamento alle notifiche","body":"La pillola SMS è verde quando Firebase smsSubscribed è 1 (pacchetto prepagato da $ 10, 466 crediti, non mensile o annuale). Rosso/lampeggiante significa 0 — aperto? e tocca Subscribe $10. I crediti rimanenti e la data dell'ultimo pagamento si trovano in questa guida. Deseleziona SMS e Salva per mettere in pausa gli avvisi senza perdere il pacchetto a pagamento."},"help-club-whatsapp-notification":{"title":"WhatsApp abbonamento alle notifiche","body":"La pillola da WhatsApp è verde quando Firebase whatsappSubscribed è 1 (pacchetto prepagato da $ 10, 233 crediti, non mensile o annuale). Rosso/lampeggiante significa 0 — aperto? e tocca Subscribe $10. I crediti rimanenti e la data dell'ultimo pagamento si trovano in questa guida. Deseleziona WhatsApp e Salva per mettere in pausa gli avvisi senza perdere il pacchetto pagato."},"help-schedule-message-templates":{"title":"Pianifica modelli di messaggi","body":"Club Admin → Notifiche → Message templates. Questi sono messaggi di sistema (Inbox / Email / SMS / WhatsApp), non ShoutOut. Modifica titolo e corpo per New shift needs confirmation, Aggiornamento programma, Turno confermato e Turno rifiutato. Segnaposto: {club} {role} {when} {link} {worker}. La posta in arrivo del lavoratore utilizza Review & confirm shift, mai Open Related ShoutOut."},"help-schedule-confirm":{"title":"Conferma i turni assegnati","body":"Inbox / E-mail / SMS i collegamenti si aprono Work Calendar. Guarda ogni compito in sospeso, selezionalo (o Select all), quindi Approve selected. L'apertura del collegamento non conferma. Solo il membro del servizio assegnato può approvare: Club Admin non può confermare per suo conto."},"help-template-catalog-report":{"title":"Rapporto sul catalogo dei modelli","body":"Elenca ogni tipo di modello ShoutOut e le dimensioni dei LED supportati (Is96x48, Is64x48, Is64x32). Una sede offre un modello solo quando almeno uno di questi flag è 1 e il flag VenueSupports* corrispondente è 1. I modelli Compleanno/Split-Media sono 1 su 96×48, 64×48 e 64×32. 96×48 è a 3 righe affiancate; 64×48 e 64×32 mettono in loop la foto, quindi il messaggio di 3 righe con una carta FLOQR + maniglia."},"help-club-display-screens":{"title":"FLOQR schermate di visualizzazione","body":"Firebase clubLocations memorizza VenueSupports96x48, VenueSupports64x48 e VenueSupports64x32 come 0 o 1. I modelli memorizza Is96x48, Is64x48 e Is64x32 allo stesso modo. Una sede elenca un modello solo quando almeno una coppia è 1. Gli URL Xibo rimangono display.html?location=id e display2.html?location=id: la dimensione dello schermo non è nell'URL. Birthday è disponibile in tutti e tre i formati (3 righe affiancate su 96×48; ciclo di foto/scherzi su 64×48 e 64×32). Il principale è display.html. Il secondario è display2.html."},"help-staff-week-calendar":{"title":"Pianificatore","body":"Club Admin Lo Scheduler è una griglia persone x giorni settimana. Save shift chiude l'editor con Schedule card successfully saved. Crea bozze, Publish schedule in modo che i lavoratori confermino in sospeso fino alla conferma, Select shifts per eliminare più volte e Website ingest per inserire i turni pubblicati sul sito del club. Finestra di turno predefinita = club aperto − 2 ore fino alla chiusura + 1 ora."},"help-staff-schedule-user-guide":{"title":"Guida per l'utente alla pianificazione del personale","body":"Apri il ? accanto a Pianificatore in Club Admin Pianificazione. Crea una bozza di turni, Publish schedule in modo che i lavoratori confermino in sospeso→confermato, quindi Select shifts per eliminarne diversi contemporaneamente. Esempio: tutti i draft del mercoledì più una fiche confermata del giovedì."},"help-create-publish-schedule":{"title":"Creare e pubblicare un programma del personale","body":"Aggiungi i turni provvisori sulla griglia persone x giorni, rivedi i chip, quindi Publish schedule. I lavoratori devono confermare prima che un turno venga confermato. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Elimina più turni programmati o bozze","body":"Select shifts, mescola le intestazioni del giorno e le fiches, quindi Delete selected. Esempio: tutte le bozze del mercoledì più un turno confermato del giovedì."},"help-staff-worksheet":{"title":"Foglio di lavoro - Calendario settimanale del personale","body":"I membri del servizio eletti aprono Work Calendar in Impostazioni. I link di conferma Inbox / E-mail / SMS arrivano qui. Rivedi i compiti in sospeso, seleziona ogni turno (o Select all), quindi Approve selected: l'apertura del messaggio non conferma. La griglia settimanale mostra i turni dei colleghi pubblicati. Le bozze restano in Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Tutti iniziano come patron FLOQR. In My Profile & Settings tocca Elect to become a service member, scegli ruolo e club, invia in fondo alla pagina.\n\nGuida modelli profilo — i profili social patron restano in Media pubblici.\n\nApprovazione Club Admin — Club Admin → Employee/Workers → Pending Worker Requests, o Rivedi ed eleggi su questa scheda."},"help-venue-website-ingest":{"title":"Acquisizione del sito web del club (API, RSS, iframe)","body":"Club Admin → Programmazione → Website ingest. Genera un segreto (mostrato una volta; viene memorizzato solo un hash). Inserisci i turni dello staff pubblicati sul sito web ufficiale del club con JSON (?format=json&dataset=schedule|hours|profile|all), RSS o uno snippet iframe. Le bozze, l'e-mail del lavoratore e il telefono non vengono mai inclusi. Ruota il segreto se perde."},"help-venue-hours-calendar":{"title":"Orari di apertura della sede","body":"Nel profilo pubblico del club, imposta gli orari di apertura/chiusura settimanali predefiniti, quindi aggiungi le sostituzioni del periodo per le settimane speciali senza perdere l'impostazione predefinita. La pagina del club pubblico mostra una griglia settimanale da domenica a sabato con l'intervallo di date (ad esempio, domenica 9 - sabato 15, agosto 2026) e la colorazione del calendario. I prossimi giorni festivi elencano gli orari di apertura/chiusura e avvisano quando differiscono dal consueto giorno feriale. La pianificazione del personale utilizza l'apertura da − 2 ore alla chiusura + 1 ora. La Guest List può suggerire serate aperte."},"help-club-admin-affiliation":{"title":"Club Admin assegnazione della sede","body":"I 3 aprono il Venue Command Center solo per il club a cui sono assegnati. L'apertura di admin.html senza una sede non viene più impostata su Zebbies. I conti demo temp_clubadmin_N@floqr-demo.com sono mappati su temp-democlub-N. Gli amministratori non assegnati richiedono l'assegnazione da Master Admin."},"help-venue-command-center":{"title":"Venue Command Center","body":"Approva ShoutOuts, esamina il rendimento della sede e riconcilia l'attività dell'account per questa sede."},"help-club-template-repository":{"title":"I modelli del tuo club","body":"I modelli creati solo per il tuo club compaiono per primi, contrassegnati da «Esclusivo da» e dal nome del locale. I modelli assegnati sono quelli che i clienti possono scegliere nel tuo club; modificali con Assegna modello o Rimuovi modello. La ricerca trova un modello anche senza accento o con un piccolo errore di battitura."},"help-employee-network":{"title":"Rete di dipendenti e personale","body":"Sono elencate solo le persone collegate a questo club: personale nominato o approvato qui, admin del club e personale affiliato a questo club. Per dare un ruolo a qualcuno, scrivi nome, username o email in Nomina un cliente per un ruolo, tocca Seleziona accanto alla persona giusta, scegli il ruolo, poi tocca Nomina il cliente selezionato per il ruolo e conferma. La persona deve prima avere un account cliente FLOQR. Camerieri, cameriere e bottle girl in elenco possono diventare rappresentanti del servizio clienti (CSR)."},"help-template-tags":{"title":"Tag dei modelli","body":"Aggiungi parole che i clienti potrebbero scrivere cercando un modello nel tuo locale, come serata partita o compleanno. I Gestori dei modelli possono aggiungere tag. Gli Amministratori dei modelli e i Club Admin possono anche rimuoverli. Il Club Admin assegna questi ruoli in Role Activity & Permission."},"help-display-idle-default":{"title":"Schermo di attesa: Use ShoutOut @ locale","body":"Quando non c’è nessuno ShoutOut in onda, Display 1 mostra «Use ShoutOut @» con il nome del tuo locale. Ogni ShoutOut approvato resta 10 minuti, poi lo schermo torna da solo a quel messaggio. Il ripristino del display predefinito in Club Admin lo fa subito."},"help-club-messaging-credit":{"title":"Credito SMS e WhatsApp","body":"Ogni pacchetto da $10 finanzia $7,00 di capacità Twilio; FloqR trattiene $3,00 di margine piattaforma. Pacchetto SMS → 466 messaggi (≈ $0,015 SMS US). Pacchetto WhatsApp → 233 messaggi (≈ $0,030 Twilio + Meta marketing). A saldo 0 acquistare un altro pacchetto prima di inviare. Sblocco SMS ops ($10) include un pacchetto SMS. Servizio WhatsApp ($10) include un pacchetto WhatsApp. Calcolo: $10 → 466 SMS o 233 WhatsApp ($7,00 Twilio / $3,00 FloqR)."},"help-club-marketing-campaigns":{"title":"Campagne marketing","body":"Scegli un modello di settore, carica sfondo e immagini extra, modifica i testi, salva o invia. L’invio addebita crediti SMS o WhatsApp da Credito messaggistica."},"help-club-in-app-marketing":{"title":"Marketing in-app","body":"Pubblica un flyer o un video fino a 30 secondi a nome del tuo club. Una volta pagato e approvato da FLOQR, appare nella schermata di caricamento della ricerca, in Mingl, RydR e in altre schermate FLOQR. Pubblicatori di annunci del club consente a un membro del team di pubblicare annunci per il club (ruolo Club Ad Poster). Nessun credito SMS necessario."},"help-vip-terms-consent":{"title":"Termini VIP reserV","body":"Dopo aver bloccato un tavolo, apri la pagina Termini, leggili e accetta una volta (marketing opzionale a parte). Il consenso è salvato prima di FloqR Stripe Checkout — come uno ShoutOut a pagamento, poi ricevuta e pass."},"help-vip-door-pass":{"title":"Pass porta VIP reserV","body":"Dopo la conferma del deposito, Il mio profilo → Prenotazioni → Mostra pass per un QR monouso. Porta ID 21+. Lo staff usa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in porta VIP reserV","body":"I VIP Manager aprono VIP reserV Door per stasera. Scansiona o incolla il token, conferma ID 21+, check-in. No-show solo dopo grace. Un link notify non cambia lo stato."},"help-vip-payment-collector":{"title":"Collettore pagamento VIP reserV e Club POS","body":"Preferito per club live con Toast/SpotOn: Club POS — FLOQR prenota/mantiene/mappa; il POS gestisce deposito, conto e spesa. Alternative: Club Stripe, FloqMedia Stripe (FloqR) o motore VIP + CSV. Aurelia (Demo Club) di default FloqMedia Stripe — chiedi a BOT DEE i passi Master e Club Admin."},"help-vip-table-isbooked":{"title":"Stato isBooked tavoli VIP in Firestore","body":"Ogni club VIP onboarded ha un doc Firestore per numero tavolo e notte: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Id = numero stampato (es. T1, B3). Dopo prenotazione completa: isBooked \"1\", isBookedYes \"yes\". Liberi: \"0\" / \"no\". Gli hold non impostano isBooked. Annulla → \"0\". getVipAvailability usa isBooked come stato prenotazione. Annullare azzera sempre isBooked a \"0\"; FloqMedia/Club Stripe può rimborsare il deposito secondo la policy del club."},"help-vip-floqr-stripe-aurelia":{"title":"Configurare FloqMedia Stripe per Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) usa FloqMedia Stripe (FloqR Checkout) come collettore deposito VIP predefinito — i patron pagano sullo Stripe piattaforma FloqR, poi il tavolo risulta prenotato.\n\nPassi Master Admin:\n1) Aprire Master Admin → Features Mgmt → VIP reserV Payments.\n2) Verificare che VIP Reservations sia abilitato nella rete.\n3) Seed / refresh provider POS solo se userete Club POS — non serve per FloqMedia Stripe.\n4) Lasciare Aurelia su FloqMedia Stripe salvo Club POS o Club Stripe.\n5) Dopo i depositi, aprire Network VIP billing.\n\nPassi Club Admin (Aurelia):\n1) Accedere come temp_clubadmin_1@floqr-demo.com (OTP email sulla home) o Club Admin Aurelia.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) In Payment collector scegliere FloqMedia Stripe (FloqR).\n4) Lasciare attivo Require deposit before table is marked booked.\n5) Salvare Save payment collector.\n6) Test: vip.html?location=temp-democlub-1 → hold tavolo → Termini → Paga deposito (carta test 4242…).\n7) Door / fatturazione: Open Door; Refresh billing.\n\nNon scegliere Club POS per le demo Aurelia salvo sandbox Toast/SpotOn. FloqMedia, Stripe, ShoutOut e VIP reserV restano marchi."}},"pt":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Um convite compacto Mingl Room pode aparecer na Search quando você define um horário para uma room BOT DEE, ou um amigo Mingl o convidou. O anfitrião vê a própria room agendada na Search sem a consulta demo Cancun. Ver convite abre Room SMARTview. Join Now vai para BOT DEE, não Mingl chat. Agora não esconde o cartão neste separador; Inbox mantém Review BOT DEE invite. A consulta demo Cancun é só Studio. A arte é ilustração, não foto. Rooms Join Now sem horário não aparecem na Search."},"help-smartvisuals-room":{"title":"Room SMARTview com SMARTvisuals","body":"Room SMARTview mostra o convite Mingl: horário, RSVP ou estado ao vivo, e Join Now. Join Now na Search abre BOT DEE (não Mingl chat) com room= e t=. SMARTstencils e SMARTbackgrounds seguem o título autorizado — Cancun Trip usa arte de viagem, não uma foto real de Cancun. O chat privado BOT DEE nunca escolhe a arte. Um Ad rotulado abaixo é uma amostra dessas etiquetas. Vazio para chat privado ou injeção; não é um anunciante ao vivo."},"help-scheduling-schedule-for":{"title":"Agendamento de pessoal","body":"Planeje turnos e contratações e avise cada pessoa por Inbox, Email, SMS ou WhatsApp. Em «Escala de», escolha em qual agenda você está trabalhando: «Minha agenda de DJ» é a sua própria agenda, «Clube» lista os clubes que você administra e «Empresa de promoção» as empresas para as quais você promove. Cada agenda tem sua própria assinatura de US$ 20/mês. Os turnos enviados para você aparecem em «Minhas atribuições», onde você os confirma ou recusa."},"help-staff-marketing-consent":{"title":"Consentimento de marketing da equipe","body":"Quando você entra na equipe de uma casa ou evento, precisa marcar a caixa de consentimento de marketing. Ela permite que essa casa ou organizador, e seus administradores e gerentes, usem seu nome no FLOQR, sua função e suas fotos e vídeos publicados em sites, flyers e redes sociais (Instagram, Facebook, TikTok, YouTube e similares) sem pedir sua permissão novamente a cada uso. Eles não podem publicar seu telefone nem seu e-mail. Você pode retirar o consentimento a qualquer momento em Meu perfil, aba Serviços e membros do serviço. Isso interrompe novo marketing; materiais já impressos ou publicados não precisam ser recolhidos. Os Club Admins veem o status de consentimento de cada pessoa da equipe em Rede de funcionários e equipe e em Equipe em destaque."},"help-botdee-privacy-session":{"title":"Privacidade e sessão BOT DEE","body":"A pausa de cinco minutos termina a sessão ao vivo. Não apaga este chat com sessão iniciada, memórias ou fluxos. As cópias em O meu perfil → Funções e encomendas → My BOT DEE também ficam. Os convidados continuam efémeros. Os chats Mingl nunca são copiados para aqui. Enter envia; Shift+Enter começa uma nova linha. Nome e tom estão em O meu perfil → My BOT DEE, não num botão no chat."},"help-botdee-place-search":{"title":"Perguntar ao BOT DEE por locais FLOQR","body":"Pergunte em palavras simples — restaurantes de sushi em Washington DC, clubs em DC ou um clube pelo nome. O BOT DEE pesquisa só venues FLOQR onboardadas, não Google nem Yelp. As correspondências abrem um Place SMARTview compacto (nome, texto curto, classificações, ligação à página pública) com SMARTbackground — não um poço de foto. Nomear uma cidade com VIP reserV (reservations in Miami) continua a anexar Place SMARTview ao lado do cartão VIP. Fotos de patrons e pitches de ShoutOut ficam de fora salvo se pedir. Se ainda não houver listing, o BOT DEE diz."},"help-botdee-page":{"title":"BOT DEE","body":"Converse com o BOT DEE na página BOT DEE em palavras simples: eventos e clubes, ShoutOut, Mingl, RydR, BartR, FloqCAST, seu perfil, escalas da equipe ou ferramentas de Club Admin. Pressione Enter para enviar; Shift+Enter começa uma nova linha. O BOT DEE conversa como uma pessoa (experimente How are you?) e só pesquisa quando você pergunta como fazer algo no FLOQR. Se você estiver conectado, o BOT DEE guarda este chat se você atualizar ou abrir outro telefone, e depois da pausa pode continuar o histórico guardado. A pausa não apaga o chat. As respostas usam a classificação da sua conta. Se estiver conectado, o BOT DEE vê os mesmos datapoints públicos voluntários que você (música, comida, viagem, hobbies e o restante de Privacy datapoint sharing) — nunca e-mail, telefone, dados de cartão ou GPS. Toque em Definições abaixo da caixa de chat para chats e memórias guardados. Toque numa foto do chat para abri-la numa janela. Feche com X ou Fechar para voltar ao chat. O + no canto superior direito abre chats guardados e não os apaga."},"help-botdee-smartview-troubleshoot":{"title":"Resolução de problemas SMARTview","body":"Cartão vazio: campos ocultos ou bloqueio. Falha ao guardar: inicie sessão — as traduções ficam no servidor. Pendente ou falha: idioma de origem com etiqueta. Só o dono edita. SMARTviews Master Admin continua o catálogo mock; Places e Yelp desligados. O tema segue o Site Chrome."},"help-botdee-smartcard-sync":{"title":"O SMARTsummary fica sincronizado","body":"Edite o SMARTsummary no idioma predefinido do perfil. A gravação é imediata. Cards e SMARTview abertos atualizam a partir do mesmo registo. As traduções correm em segundo plano e não substituem uma edição mais nova. Se ocultar o perfil, bloquear alguém ou apagar a conta, essas cards desaparecem. O Gemini não substitui o seu texto."},"help-botdee-smartcard-search":{"title":"Perguntar ao BOT DEE quem é alguém","body":"“Who am I?” abre o seu SMARTview. “Who is …”, “What do you know of …” ou “What about …” mais nome, apelido, nome de exibição, handle Mingl ou FloqR, ou um handle social (Instagram, TikTok, X). Só esses campos de identidade — não bios, likes, bebidas ou géneros. Um resultado abre um cartão People SMARTview no chat — não uma lista markdown nem uma grelha de fotos. Vários mostram SMARTcards compactos. Perfis privados, bloqueados ou não publicados não aparecem — o BOT DEE não confirma se essa conta existe."},"help-botdee-smartcard":{"title":"SMARTcards de pessoas","body":"Quando mais de um perfil público FLOQR corresponde, o BOT DEE mostra SMARTcards compactas no chat: foto em largura total primeiro, depois nome e handle, depois um SMARTsummary compacto sem caixa preenchida. Toque para abrir o SMARTview completo — o mesmo empilhamento. As cards usam o mesmo perfil público e SMARTsummary. Abrir não chama o Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Digite Ver, Vers ou Version — maiúsculas não importam. BOT DEE mostra o cartão de versão. Uma pergunta mais longa como “qual é a sua versão?” também mostra esse cartão."},"help-botdee-version-smartview-status":{"title":"O estado do Version SMARTview é uma sonda ao vivo","body":"O estado do serviço é sondado neste pedido Version: Functions e pacote alcançáveis com Gemini configurado → Operacional; Functions e pacote ok mas Gemini não configurado → Degradado; Functions fora deste pedido → Indisponível. Nunca um rótulo estático Não verificado. O modelo de IA mostra o id Gemini configurado deste deployment mesmo quando esta vez não gerou. Os carimbos de frontend e backend podem diferir; ambos são rotulados. Master Admin pode ver diagnósticos extra em Detalhes técnicos — patrons não."},"help-botdee-version-smartview-tabs":{"title":"Abas do Version SMARTview","body":"Visão geral descreve o BOT DEE e abre Detalhes técnicos sem sair do chat. Novidades lista só mudanças verificadas de BOT DEE e Gemini — não Master Admin, ferramentas de beta tester nem outras notas de produto FLOQR. Ajuda repete o comando Ver / Vers / Version. Trocar de aba ou expandir mantém o rascunho não enviado e a rolagem. O cartão usa o seu Site Chrome — não há um segundo tema."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"No chat BOT DEE, diga Open Room SMARTview, Start a group chat, ou planeie uma viagem a Cancun em palavras simples. Depois: Entrar agora ou Definir um horário. Entrar agora abre uma sessão de amigos Mingl já e não põe um cartão na Search. Definir um horário é quando a room BOT DEE começa — não Shared Itinerary — e liga SMARTnotification da Search para si e amigos Mingl convidados. Convide só amigos Mingl — anfitrião mais 7 convidados. Convidados também podem convidar. Entrar não é um pagamento e não abre uma conta partilhada. O BOT DEE nunca pede números de cartão. As mensagens privadas do BOT DEE ficam privadas. Site Chrome segue Appearance. Uma room ao vivo fica aberta até End Room, cerca de quatro horas depois de abrir, ou se todos saíram há cerca de 15 minutos. Pausar o chat privado BOT DEE é separado."},"help-botdee-room-smartview-invite":{"title":"Convidar amigos Mingl","body":"Depois de Confirm (Join Now ou Set a schedule), Invite mostra só os seus amigos Mingl. Toque um amigo ou escreva Invite lorna — Inbox recebe Review BOT DEE invite. O chip fica cinzento com Invite sent — um segundo toque não envia outro convite. É um comando Room SMARTview, não VIP reserV nem People SMARTview Invite. Não é um link público. Limite: anfitrião mais 7. Convidados podem convidar mais amigos Mingl até o anfitrião desligar isso. Entrar não é pagamento. Se um chip é você ou alguém já na sessão, fica É você ou Já nesta sessão e não envia outro convite."},"help-botdee-room-smartview-join":{"title":"Entrar numa sessão BOT DEE","body":"Abra o convite do Inbox ou Search Join Now autenticado como o amigo Mingl destinatário. Join Now abre BOT DEE, não Mingl chat. Tu e os amigos Mingl convidados partilham o chat de grupo Room SMARTview; os nomes aparecem para membros. Conta errada, expirado ou revogado recusa. Entrar na room não é entrar numa conta nem aprovar um pagamento. BOT DEE nunca pega números de cartão."},"help-botdee-room-smartview-end":{"title":"Terminar Room SMARTview","body":"Só o anfitrião pode terminar uma room. Terminar não cobra ninguém nem apaga chats privados de outros. Uma conta partilhada por pagar deve ser paga ou anulada primeiro. Uma room ao vivo fica aberta até End Room, cerca de quatro horas depois de abrir, ou se todos saíram há cerca de 15 minutos. Pausar o chat privado BOT DEE não é logout da room. Um convidado que sai não termina a room enquanto o anfitrião está presente."},"help-botdee-room-smartview-tab":{"title":"Conta partilhada Room SMARTview","body":"Primeiro o opt-in. Depois adicione uma linha. Feche com um pagador ou dividido. Só uid que confirmam são cobrados via FloqR Stripe. Entrar na room não é entrar na conta. BOT DEE nunca pega números de cartão. Club POS mais tarde."},"help-botdee-room-smartview-who-pays":{"title":"Quem paga","body":"Pergunte Who’s paying em Room SMARTview para ver o opt-in. Ninguém é cobrado porque alguém disse buy. Os últimos quatro do cartão ficam no recibo do pagador."},"help-botdee-room-smartview-kick":{"title":"Remover alguém de Room SMARTview","body":"Só o anfitrião pode remover um convidado. Um amigo removido não lê mais mensagens da room. Uma resposta do modelo não pode expulsar ninguém."},"help-botdee-room-smartview-share":{"title":"Partilhar em Room SMARTview","body":"Share this conversation nunca copia o seu tópico privado BOT DEE. BOT DEE mostra uma pré-visualização de factos partilháveis desta mensagem, marcados como provisórios. Pode editar ou retirar factos. Perfis e SMARTsummary ficam fora da room."},"help-botdee-room-smartview-schedule":{"title":"Entrar agora ou definir um horário","body":"Depois da configuração Room SMARTview, escolha Entrar agora ou Definir um horário. Entrar agora abre a sessão BOT DEE já e não põe um cartão na Search. Definir um horário é quando a room BOT DEE começa — não Shared Itinerary. Uma hora futura liga SMARTnotification da Search só para si e amigos Mingl convidados. Convidados RSVP até a room estar ao vivo; depois Join Now abre BOT DEE (não Mingl chat)."},"help-botdee-room-collab":{"title":"Partilhar uma reserva headless no Room SMARTview","body":"Num Room SMARTview, as escolhas VIP reserV ou ShoutOut do anfitrião aparecem para todos. Os membros votam Sim ou Não. Hold it e o pagamento ficam com o anfitrião — juntar-se e votar não é um pagamento. BOT DEE nunca pede números de cartão. O Stripe abre num pop-out."},"help-botdee-room-elect-host":{"title":"Eleger um anfitrião do Room SMARTview","body":"Qualquer pessoa na sessão pode ser anfitrião. Nomeie-se a si ou a outro membro. Um candidato torna-se anfitrião com 60% dos membros atuais (arredondado para cima). Se o anfitrião sair, os restantes elegem um novo — a room fica aberta. Kick e End ficam com o anfitrião eleito."},"help-botdee-smartview-review":{"title":"Rever e corrigir o SMARTsummary","body":"O Gemini redige só a partir de campos públicos no FLOQR — não em cada vista. Se um facto estiver errado, oculte o campo ou edite o resumo. O seu texto não é substituído. Um conflito de perfil pede revisão. Reporte um cartão errado na sobreposição."},"help-botdee-smartview-chrome":{"title":"SMARTview e Site Chrome","body":"O People SMARTview usa o Site Chrome FLOQR de quem vê (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Não há segundo tema. Mudar o chrome atualiza o cartão sem perder o rascunho."},"help-botdee-smartview-categories":{"title":"Categorias SMARTview","body":"Quatro separadores: Social, Dating, Dining e Viagens futuras. Social abre em Música, depois Nightlife, Desporto e Eventos. As etiquetas são só o que partilhou — sem títulos duplicados nem viagens ou notas inventadas. Viagens futuras só destinos públicos."},"help-botdee-smartview-media":{"title":"Fotos e vídeos SMARTview","body":"O cartão compacto usa o mesmo hero da página pública FLOQR — o primeiro item de Profile Media (8 fotos + 2 vídeos). Toque para Fotos e Vídeos desses espaços públicos. Deslize ou setas, depois X (ou Escape) regressa ao mesmo chat e rascunho."},"help-botdee-smartview-privacy":{"title":"Privacidade SMARTview","body":"O SMARTview mostra só campos já públicos no FLOQR. Não é pesquisa web. Dating só com opt-in. Oculte um campo no perfil e sai do SMARTview. Bloqueados não veem o cartão. Reporte um resumo errado na sobreposição."},"help-botdee-smartview-translation":{"title":"Tradução SMARTview","body":"O seu SMARTsummary fica no idioma predefinido do perfil — essa é a origem, mesmo que não seja inglês. Depois de guardar, o FLOQR mete na fila uma tradução para cada outro idioma, incluindo inglês. Um visitante em inglês vê o SMARTsummary em inglês quando o trabalho termina. Pendente ou falhado, vê-se o idioma de origem com etiqueta — nunca uma tradução antiga como atual."},"help-botdee-smartview-edit":{"title":"Editar o SMARTsummary","body":"Só você edita o SMARTsummary no idioma predefinido do perfil. A gravação é imediata. As traduções correm em segundo plano. O Gemini não substitui o seu texto. Se o perfil público mudar, o FLOQR pede revisão em vez de substituir."},"help-botdee-privacy-assistant":{"title":"Assistente de privacidade BOT DEE","body":"Altere em O meu perfil o que outros utilizadores FLOQR veem — o BOT DEE não adiciona um segundo interruptor público. Se a pesquisa web associou a pessoa errada, pode contestar sem alterar o perfil. O BOT DEE não promete que um site terceiro apague a página original."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Cada recomendação pode mostrar evidências, data da verificação, personalização e patrocínio. Pode pedir ao BOT DEE para não personalizar esta pesquisa."},"help-botdee-research-library":{"title":"Biblioteca de pesquisa BOT DEE","body":"Guarde lugares e cartões que pediu ao BOT DEE. Um Place ID do Google não copia fotos ou avaliações. Pode atualizar ou apagar. Caches licenciados ficam desligados até o fornecedor ser aprovado."},"help-botdee-smartview":{"title":"Ver o meu SMARTview","body":"Ver o meu SMARTview mostra o seu cartão de Pessoa a partir dos campos públicos FLOQR, com os mesmos Profile Media da página pública — não mocks de clube ou restaurante. Editar o meu SMART Summary altera o resumo no idioma do perfil. Os mocks de clube/restaurante ficam em Master Admin → Features → BOT DEE → SMARTviews. Sem Places ou Yelp em direto."},"help-botdee-memory":{"title":"Chats BOT DEE guardados","body":"Abra Funcionalidades e encomendas → O meu BOT DEE para guardar chats após a pausa, exportar ou apagar histórico. A pausa de cinco minutos termina a sessão ao vivo. Se aderir, o BOT DEE guarda o chat. Convidados não são guardados. Mingl fica no Mingl."},"help-botdee-knows-of-me":{"title":"O que o BOT DEE sabe de mim","body":"Factos guardados com a sua aprovação estão em Funcionalidades e encomendas → O meu BOT DEE. A lista fica vazia se a memória estiver desligada ou não houver dados. Exporte ou apague aqui. O BOT DEE não guarda IP. Mingl não é copiado."},"help-search-settings-appearance":{"title":"Settings na Search","body":"No ecrã Search, toque em Settings para abrir Profile & Settings no separador Appearance — o Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green) fica aí. O mosaico Settings usa o mesmo pack de ícones chrome das outras marcas Search."},"help-club-website-feed":{"title":"Feed para o site do clube","body":"Mostre a página do clube publicada no FLOQR no seu próprio site. Toque em “Gerar chave e links” e cole o código iframe no site, ou passe o link JSON ou RSS para o administrador do site. O feed mostra próximos eventos, DJs e equipe em destaque, galeria e contatos, conforme os controles da página pública. As fotos da equipe só aparecem quando o consentimento de fotos está confirmado. Gerar uma nova chave desativa os links antigos, inclusive os da escala da equipe."},"help-featured-staff":{"title":"Equipe em destaque","body":"Marque a equipe que deve aparecer na página pública do clube. Para cada pessoa, toque em uma das fotos dela no FLOQR ou escolha “Enviar do computador”. Você pode mudar a função exibida abaixo do nome. Toque em “Save Public Profile” para publicar. Antes de publicar fotos, obtenha a concordância de cada pessoa e marque a caixa de consentimento de fotos."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"O FloqR Inbox guarda System Messages e mensagens internas de suporte. A lista carrega primeiro para as mensagens aparecerem depressa. Toque no botão flutuante New Message para escrever — digite um nome ou @username para encontrar um destinatário permitido (Club Admin, CSR ou staff aprovado). O chat patron-a-patron fica no Mingl após Mingl mútuo. Abrir um convite de turno não confirma — reveja e Approve selected no Work Calendar."},"botdee-ask-floqr":{"title":"Pergunte FloqR com BOT DEE","body":"Pergunte FloqR com BOT DEE — toque na marca animada ou aguarde o prompt e digite o que deseja em palavras simples. Produtos: Mingl, RydR, BartR, ShoutOut, FloqCAST (superstar), clubes. Metas: diga “Eu quero poder…” (por exemplo, tornar-se um Club Admin) ou “make me a superstar” para etapas e links."},"help-vip-book-table":{"title":"Reservar mesa VIP (VIP reserV)","body":"VIP reserV mostra o mapa e reserva mesas. Abra VIP reserV na Busca, escolha Decades ou Lima Twist Club e uma noite, toque numa mesa verde, segure 30 minutos, aceite os Termos e pague o depósito com FloqR Stripe. Barras e DJ não reserváveis. Em Aurelia, use Explore 3D walk-through para a sala interativa (a reserva continua no mapa 2D)."},"help-vip-choose-venue":{"title":"Escolher um local VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club e Aurelia têm cada um um mapa 2D publicado; Aurelia também oferece Explore 3D walk-through."},"help-become-club-admin":{"title":"Torne-se um Club Admin","body":"Solicite acesso Club Admin e obtenha a aprovação do local."},"help-role-profiles":{"title":"Visão geral dos perfis de função","body":"Veja como funcionam as funções Club Admin, DJ, Promoter e hospitalidade."},"help-staff-scheduling":{"title":"Calendário e agendador","body":"Club Admin O calendário mostra os cartões Rascunho (roxo), Pendente (âmbar), Confirmado (verde) e Aberto/não preenchido — cada um com um status escrito, e não apenas uma cor. O Agendador é a grade de rascunho/publicação de pessoas × dias. Website ingest / publicVenueCalendar retorna apenas atribuições confirmadas. Uma pílula verde paga este mês é mostrada como Club Admins quando staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Assinaturas de notificação do Club SMS e WhatsApp","body":"Club Admin → Notificações: Send test alert usa as caixas atualmente marcadas. No aplicativo (e Push) escreve uma mensagem do sistema em FloqR Inbox. O e-mail usa endereços de administrador do clube. SMS e WhatsApp ainda precisam de uma assinatura paga, além de um telefone de alerta E.164. Pílula verde = Firebase assinatura 1 (pacote pré-pago de US$ 10); vermelho = 0. Se Send test alert retornar Authentication Error - invalid username, Firebase segredo TWILIO_ACCOUNT_SID deve ser o SID da conta começando com AC (34 caracteres) de console.twilio.com — não o token de autenticação e não uma chave de API (SK)."},"help-club-sms-notification":{"title":"SMS assinatura de notificação","body":"A pílula SMS é verde quando Firebase smsSubscribed é 1 (pacote pré-pago de US$ 10, 466 créditos, não mensal ou anual). Vermelho/piscando significa 0 — aberto? e toque em Subscribe $10. Os créditos restantes e a data do último pagamento estão nesta ajuda. Desmarque SMS e Salvar para pausar alertas sem perder o pacote pago."},"help-club-whatsapp-notification":{"title":"WhatsApp assinatura de notificação","body":"A pílula WhatsApp é verde quando Firebase whatsappSubscribed é 1 (pacote pré-pago de US$ 10, 233 créditos, não mensal ou anual). Vermelho/piscando significa 0 — aberto? e toque em Subscribe $10. Os créditos restantes e a data do último pagamento estão nesta ajuda. Desmarque WhatsApp e Salvar para pausar alertas sem perder o pacote pago."},"help-schedule-message-templates":{"title":"Agendar modelos de mensagens","body":"Club Admin → Notificações → Message templates. Estas são mensagens do sistema (Inbox / Email / SMS / WhatsApp), não ShoutOuts. Edite o título e o corpo de New shift needs confirmation, Atualização programada, Turno confirmado e Turno recusado. Espaços reservados: {club} {role} {when} {link} {worker}. A caixa de entrada do trabalhador usa Review & confirm shift — nunca Open Related ShoutOut."},"help-schedule-confirm":{"title":"Confirmar turnos atribuídos","body":"Inbox / Email / SMS links abrem Work Calendar. Veja cada tarefa pendente, marque-a (ou Select all) e depois Approve selected. Abrir o link não confirma. Somente o membro do serviço designado pode aprovar — Club Admin não pode confirmar em seu nome."},"help-template-catalog-report":{"title":"Relatório de catálogo de modelos","body":"Lista cada tipo de modelo ShoutOut e quais tamanhos de LED ele suporta (Is96x48, Is64x48, Is64x32). Um local só oferece um modelo quando pelo menos um desses sinalizadores é 1 e o sinalizador VenueSupports* correspondente é 1. Os modelos de aniversário/mídia dividida são 1 em 96×48, 64×48 e 64×32. 96×48 são 3 linhas lado a lado; 64×48 e 64×32 fazem um loop na foto e depois na mensagem de 3 linhas com um cartão FLOQR + alça."},"help-club-display-screens":{"title":"FLOQR telas de exibição","body":"Firebase clubLocations armazena VenueSupports96x48, VenueSupports64x48 e VenueSupports64x32 como 0 ou 1. templates armazena Is96x48, Is64x48 e Is64x32 da mesma maneira. Um local só lista um modelo quando pelo menos um par é 1. As URLs do Xibo permanecem display.html?location=id e display2.html?location=id — o tamanho da tela não está na URL. O aniversário é oferecido em todos os três tamanhos (3 linhas lado a lado em 96×48; loop de foto/mensagem em 64×48 e 64×32). O principal é display.html. O secundário é display2.html."},"help-staff-week-calendar":{"title":"Agendador","body":"Club Admin O Agendador é uma grade de pessoas × dias por semana. Save shift fecha o editor com Schedule card successfully saved. Crie rascunhos, Publish schedule para que os trabalhadores confirmem pendências até serem confirmados, Select shifts para exclusão múltipla e Website ingest para colocar turnos publicados no site do clube. Janela de turno padrão = clube aberto − 2 horas até o fechamento + 1 hora."},"help-staff-schedule-user-guide":{"title":"Guia do usuário de agendamento de equipe","body":"Abra o? ao lado de Agendador em Club Admin Agendamento. Crie turnos de rascunho, Publish schedule para que os trabalhadores confirmem pendentes→confirmados, depois Select shifts para excluir vários de uma vez. Exemplo: todos os drafts de quarta-feira mais uma ficha confirmada de quinta-feira."},"help-create-publish-schedule":{"title":"Crie e publique uma agenda de equipe","body":"Adicione turnos de rascunho na grade pessoas × dias, revise fichas e depois Publish schedule. Os trabalhadores devem confirmar antes que um turno seja confirmado. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Excluir vários turnos agendados ou rascunhos","body":"Select shifts, misture cabeçalhos e fichas do dia e depois Delete selected. Exemplo: todos os rascunhos de quarta-feira mais um turno confirmado de quinta-feira."},"help-staff-worksheet":{"title":"Planilha de Trabalho - Calendário Semanal da Equipe","body":"Os militares eleitos abrem Work Calendar em Configurações. Inbox / Email / SMS links de confirmação chegam aqui. Revise as tarefas pendentes, marque cada turno (ou Select all) e depois Approve selected — abrir a mensagem não confirma. A grade semanal mostra os turnos publicados dos colegas. Os rascunhos ficam em Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Todos começam como patron FLOQR. Em My Profile & Settings toque Elect to become a service member, escolha papel e clubes, envie no final da página.\n\nGuia de modelos de perfil — perfis sociais patron ficam em Mídia pública.\n\nAprovação Club Admin — Club Admin → Employee/Workers → Pending Worker Requests, ou Revisar e eleger neste separador."},"help-venue-website-ingest":{"title":"Ingestão do site do clube (API, RSS, iframe)","body":"Club Admin → Agendamento → Website ingest. Gere um segredo (mostrado uma vez; apenas um hash é armazenado). Extraia os turnos de funcionários publicados no site oficial do clube com JSON (?format=json&dataset=schedule|hours|profile|all), RSS ou um snippet de iframe. Rascunhos, e-mail do funcionário e telefone nunca são incluídos. Gire o segredo se ele vazar."},"help-venue-hours-calendar":{"title":"Horário de funcionamento do local","body":"No Perfil Público do Clube, defina o horário de abertura/fechamento semanal padrão e, em seguida, adicione substituições de período para semanas especiais sem perder o padrão. A página pública do clube mostra uma grade semanal de domingo a sábado com o intervalo de datas (por exemplo, domingo, 9 a sábado, 15 de agosto de 2026) e cores do calendário. Os próximos feriados listam os horários de abertura/fechamento e avisam quando forem diferentes do dia normal da semana. O agendamento da equipe utiliza aberto − 2h até fechamento + 1h. A Guest List pode sugerir noites abertas."},"help-club-admin-affiliation":{"title":"Club Admin atribuição de local","body":"Club Adminsó abrem o Venue Command Center para um clube ao qual estão atribuídos. Abrir admin.html sem um local não é mais o padrão Zebbies. As contas de demonstração temp_clubadmin_N@floqr-demo.com são mapeadas para temp-democlub-N. Administradores não atribuídos solicitam atribuição de Master Admin."},"help-venue-command-center":{"title":"Centro de Comando do Local","body":"Aprovar ShoutOuts, avaliar o desempenho do local e reconciliar a atividade da conta para este local."},"help-club-template-repository":{"title":"Modelos do seu clube","body":"Os modelos feitos só para o seu clube aparecem primeiro, marcados com «Exclusivo em» e o nome do local. Os modelos atribuídos são os que os clientes podem escolher no seu clube; altere isso com Atribuir modelo ou Remover modelo. A busca encontra um modelo mesmo sem acento ou com um pequeno erro de digitação."},"help-employee-network":{"title":"Rede de funcionários e equipe","body":"Só aparecem pessoas vinculadas a este clube: equipe designada ou aprovada aqui, admins do clube e equipe afiliada a este clube. Para dar uma função a alguém, digite o nome, usuário ou e-mail em Designar cliente para uma função, toque em Selecionar ao lado da pessoa certa, escolha a função, depois toque em Designar função ao cliente selecionado e confirme. A pessoa precisa primeiro de uma conta de cliente FLOQR. Garçons, garçonetes e bottle girls da lista podem ser representantes de atendimento ao cliente (CSR)."},"help-template-tags":{"title":"Tags de modelos","body":"Adicione palavras que os clientes possam digitar ao procurar um modelo no seu local, como noite de jogo ou aniversário. Gestores de modelos podem adicionar tags. Administradores de modelos e Club Admins também podem removê-las. O Club Admin atribui esses papéis em Role Activity & Permission."},"help-display-idle-default":{"title":"Tela de espera: Use ShoutOut @ local","body":"Quando nenhum ShoutOut está no ar, o Display 1 mostra «Use ShoutOut @» com o nome do seu local. Cada ShoutOut aprovado fica 10 minutos e depois a tela volta sozinha para essa mensagem. Redefinir a tela padrão no Club Admin faz isso na hora."},"help-club-messaging-credit":{"title":"Crédito SMS e WhatsApp","body":"Cada pacote de $10 financia $7,00 de capacidade Twilio; a FloqR retém $3,00 de margem. Pacote SMS → 466 mensagens (≈ $0,015 SMS EUA). Pacote WhatsApp → 233 mensagens (≈ $0,030 Twilio + Meta marketing). Com saldo 0, compre outro pacote antes de enviar. Desbloqueio SMS ops ($10) inclui um pacote SMS. Serviço WhatsApp ($10) inclui um pacote WhatsApp. Conta: $10 → 466 SMS ou 233 WhatsApp ($7,00 Twilio / $3,00 FloqR)."},"help-club-marketing-campaigns":{"title":"Campanhas de marketing","body":"Escolha um modelo do setor, carregue fundo e imagens extra, edite textos, guarde ou envie. O envio debita créditos SMS ou WhatsApp em Crédito de mensagens."},"help-club-in-app-marketing":{"title":"Marketing in-app","body":"Publique um flyer ou um vídeo até 30 segundos em nome do seu clube. Depois de pago e aprovado pela FLOQR, aparece no ecrã de carregamento da pesquisa, no Mingl, no RydR e noutros ecrãs FLOQR. Publicadores de anúncios do clube permite que um membro da equipa publique anúncios para o clube (função Club Ad Poster). Não são necessários créditos SMS."},"help-vip-terms-consent":{"title":"Termos VIP reserV","body":"Depois de reter uma mesa, abra a página de Termos, leia e aceite uma vez (marketing opcional à parte). O consentimento é guardado antes do FloqR Stripe Checkout — como um ShoutOut pago, depois recibo e passe."},"help-vip-door-pass":{"title":"Passe de porta VIP reserV","body":"Após confirmar o depósito, Meu perfil → Reservas → Mostrar passe para um QR de uso único. Traga ID 21+. A equipa usa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in na porta VIP reserV","body":"VIP Managers abrem VIP reserV Door para esta noite. Digitalize ou cole o token, confirme ID 21+, faça check-in. No-show só após grace. Um link notify não altera o estado."},"help-vip-payment-collector":{"title":"Cobrador de pagamento VIP reserV e Club POS","body":"Preferido para clubs ao vivo com Toast/SpotOn: Club POS — FLOQR reserva/segura/mapa; o POS trata depósito, conta e gasto. Alternativas: Club Stripe, FloqMedia Stripe (FloqR) ou motor VIP + CSV. Aurelia (Demo Club) usa FloqMedia Stripe por omissão — pergunte ao BOT DEE os passos Master e Club Admin."},"help-vip-table-isbooked":{"title":"Estado isBooked das mesas VIP no Firestore","body":"Cada clube VIP onboarded tem um doc Firestore por número de mesa e noite: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Id = número impresso (ex. T1, B3). Após reserva completa: isBooked \"1\", isBookedYes \"yes\". Livres: \"0\" / \"no\". Holds não alteram isBooked. Cancelar → \"0\". getVipAvailability usa isBooked como estado da reserva. Cancelar sempre define isBooked como \"0\"; FloqMedia/Club Stripe pode reembolsar o depósito conforme a política do clube."},"help-vip-floqr-stripe-aurelia":{"title":"Configurar FloqMedia Stripe para Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) usa FloqMedia Stripe (FloqR Checkout) como cobrador padrão de depósito VIP — os patronos pagam no Stripe da plataforma FloqR e a mesa fica reservada.\n\nPassos Master Admin:\n1) Abrir Master Admin → Features Mgmt → VIP reserV Payments.\n2) Confirmar VIP Reservations ativo na rede.\n3) Seed / refresh de POS só se for usar Club POS depois — não é preciso para FloqMedia Stripe.\n4) Manter Aurelia em FloqMedia Stripe salvo Club POS ou Club Stripe.\n5) Após depósitos, ver Network VIP billing.\n\nPassos Club Admin (Aurelia):\n1) Entrar como temp_clubadmin_1@floqr-demo.com (OTP de e-mail na home) ou Club Admin da Aurelia.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) Em Payment collector, escolher FloqMedia Stripe (FloqR).\n4) Manter Require deposit before table is marked booked.\n5) Guardar Save payment collector.\n6) Teste: vip.html?location=temp-democlub-1 → reter mesa → Termos → Pagar depósito (cartão teste 4242…).\n7) Door / faturação: Open Door; Refresh billing.\n\nNão escolha Club POS nas demos Aurelia salvo sandbox Toast/SpotOn. FloqMedia, Stripe, ShoutOut e VIP reserV não se traduzem."}},"el":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Μια συμπαγής πρόσκληση Mingl Room μπορεί να εμφανιστεί στο Search όταν ορίζετε πρόγραμμα για BOT DEE room, ή σας προσκάλεσε φίλος Mingl. Ο οικοδεσπότης βλέπει τη δική του προγραμματισμένη room στο Search χωρίς το demo Cancun. Προβολή πρόσκλησης ανοίγει Room SMARTview. Το Join Now πηγαίνει στο BOT DEE, όχι Mingl chat. Όχι τώρα κρύβει την κάρτα σε αυτή την καρτέλα· το Inbox κρατά Review BOT DEE invite. Το demo Cancun είναι μόνο Studio. Η τέχνη είναι εικονογράφηση, όχι φωτογραφία. Rooms Join Now χωρίς πρόγραμμα δεν εμφανίζονται στο Search."},"help-smartvisuals-room":{"title":"Room SMARTview με SMARTvisuals","body":"Το Room SMARTview δείχνει την πρόσκληση Mingl: πρόγραμμα, RSVP ή live κατάσταση, και Join Now. Το Join Now στο Search ανοίγει BOT DEE (όχι Mingl chat) με room= και t=. SMARTstencils και SMARTbackgrounds ακολουθούν τον εγκεκριμένο τίτλο — Cancun Trip χρησιμοποιεί ταξιδιωτική εικονογράφηση, όχι πραγματική φωτογραφία Cancun. Η ιδιωτική συνομιλία BOT DEE δεν επιλέγει ποτέ την τέχνη. Ένα επισημασμένο Ad από κάτω είναι δείγμα από αυτές τις ετικέτες. Κενό για ιδιωτική συνομιλία ή έγχυση· δεν είναι ζωντανός διαφημιστής."},"help-scheduling-schedule-for":{"title":"Προγραμματισμός προσωπικού","body":"Σχεδιάστε βάρδιες και κρατήσεις και ειδοποιήστε κάθε άτομο μέσω Inbox, Email, SMS ή WhatsApp. Στο «Πρόγραμμα για» επιλέξτε σε ποιο ημερολόγιο δουλεύετε: «Το πρόγραμμά μου ως DJ» είναι το δικό σας ημερολόγιο, το «Club» δείχνει τα clubs που διαχειρίζεστε και η «Εταιρεία προώθησης» τις εταιρείες για τις οποίες κάνετε προώθηση. Κάθε ημερολόγιο έχει τη δική του συνδρομή 20 $/μήνα. Οι βάρδιες που σας ανατίθενται εμφανίζονται στις «Οι αναθέσεις μου», όπου τις επιβεβαιώνετε ή τις απορρίπτετε."},"help-staff-marketing-consent":{"title":"Συγκατάθεση μάρκετινγκ προσωπικού","body":"Όταν εντάσσεστε στην ομάδα ενός χώρου ή μιας εκδήλωσης, πρέπει να επιλέξετε το πλαίσιο συγκατάθεσης μάρκετινγκ. Επιτρέπει σε αυτόν τον χώρο ή διοργανωτή, και στους διαχειριστές και υπευθύνους του, να χρησιμοποιούν το όνομά σας στο FLOQR, τον ρόλο σας και τις δημοσιευμένες φωτογραφίες και βίντεό σας σε ιστότοπους, φυλλάδια και μέσα κοινωνικής δικτύωσης (Instagram, Facebook, TikTok, YouTube και παρόμοια) χωρίς να σας ρωτούν ξανά για κάθε χρήση. Δεν επιτρέπεται να δημοσιεύουν το τηλέφωνο ή το email σας. Μπορείτε να την ανακαλέσετε ανά πάσα στιγμή στο «Το προφίλ μου», καρτέλα «Μέλη Υπηρεσιών & Υπηρεσιών». Η ανάκληση σταματά το νέο μάρκετινγκ· υλικό που έχει ήδη τυπωθεί ή δημοσιευτεί δεν χρειάζεται να αποσυρθεί. Οι Club Admins βλέπουν την κατάσταση συγκατάθεσης κάθε μέλους του προσωπικού στο Δίκτυο υπαλλήλων και προσωπικού και στο Προβεβλημένο προσωπικό."},"help-botdee-privacy-session":{"title":"Απόρρητο και συνεδρία BOT DEE","body":"Η παύση των πέντε λεπτών τελειώνει τη ζωντανή συνεδρία. Δεν διαγράφει αυτή τη συνομιλία για συνδεδεμένους, τις μνήμες ή τις ροές. Οι προαιρετικές αντιγραφές στο Προφίλ μου → Λειτουργίες και παραγγελίες → My BOT DEE μένουν κι αυτές. Οι επισκέπτες μένουν προσωρινοί. Οι συνομιλίες Mingl δεν αντιγράφονται εδώ. Enter στέλνει· Shift+Enter ξεκινά νέα γραμμή. Όνομα και ύφος είναι στο Προφίλ μου → My BOT DEE, όχι κουμπί στη συνομιλία."},"help-botdee-place-search":{"title":"Ρωτήστε τον BOT DEE για χώρους FLOQR","body":"Ρωτήστε απλά — εστιατόρια σούσι στην Washington DC, clubs στην DC ή ένα club με όνομα. Ο BOT DEE ψάχνει μόνο onboarded χώρους FLOQR, όχι Google ή Yelp. Τα αποτελέσματα ανοίγουν μια συμπαγή Place SMARTview (όνομα, σύντομο κείμενο, βαθμολογίες, σύνδεσμος δημόσιας σελίδας) με SMARTbackground — όχι πηγάδι φωτογραφίας. Αν ονομάσετε μια πόλη με VIP reserV (reservations in Miami), το Place SMARTview επισυνάπτεται ακόμα δίπλα στην κάρτα VIP. Φωτογραφίες patrons και pitches ShoutOut μένουν εκτός εκτός αν τα ζητήσατε. Αν δεν υπάρχει ακόμα, ο BOT DEE το λέει."},"help-botdee-page":{"title":"BOT DEE","body":"Συνομιλήστε με τον BOT DEE στη σελίδα BOT DEE με απλά λόγια: εκδηλώσεις και κλαμπ, ShoutOut, Mingl, RydR, BartR, FloqCAST, το προφίλ σας, προγράμματα προσωπικού ή εργαλεία Club Admin. Πατήστε Enter για αποστολή· Shift+Enter ξεκινά νέα γραμμή. Ο BOT DEE συνομιλεί σαν άνθρωπος (δοκιμάστε How are you?) και αναζητά μόνο όταν ρωτάτε πώς να κάνετε κάτι στο FLOQR. Αν έχετε συνδεθεί, ο BOT DEE κρατά αυτή τη συνομιλία αν ανανεώσετε ή ανοίξετε άλλο τηλέφωνο, και μετά την παύση μπορεί να συνεχίσει το αποθηκευμένο ιστορικό. Η παύση δεν διαγράφει τη συνομιλία. Οι απαντήσεις χρησιμοποιούν την ταξινόμηση του λογαριασμού σας. Αν έχετε συνδεθεί, ο BOT DEE βλέπει τα ίδια δημόσια εθελοντικά datapoints προφίλ με εσάς (μουσική, φαγητό, ταξίδια, χόμπι και τα υπόλοιπα του Privacy datapoint sharing) — ποτέ email, τηλέφωνο, στοιχεία κάρτας ή GPS. Πατήστε Ρυθμίσεις κάτω από το πλαίσιο συνομιλίας για αποθηκευμένες συνομιλίες και μνήμες. Πατήστε μια φωτογραφία στη συνομιλία για να ανοίξει σε παράθυρο. Κλείστε με X ή Κλείσιμο για να δείτε πάλι τη συνομιλία. Το + πάνω δεξιά ανοίγει αποθηκευμένες συνομιλίες και δεν τις διαγράφει."},"help-botdee-smartview-troubleshoot":{"title":"Αντιμετώπιση SMARTview","body":"Κενή κάρτα: κρυμμένα πεδία ή αποκλεισμός. Αποτυχία αποθήκευσης: συνδεθείτε — οι μεταφράσεις είναι στον διακομιστή. Εκκρεμές/αποτυχία: γλώσσα πηγής με σήμανση. Μόνο ο κάτοχος επεξεργάζεται. Το SMARTviews Master Admin μένει mock. Places/Yelp κλειστά. Το θέμα ακολουθεί το Site Chrome."},"help-botdee-smartcard-sync":{"title":"Το SMARTsummary μένει συγχρονισμένο","body":"Επεξεργαστείτε το SMARTsummary στην προεπιλεγμένη γλώσσα προφίλ. Η αποθήκευση είναι άμεση. Ανοιχτές κάρτες και SMARTview ενημερώνονται από την ίδια εγγραφή. Οι μεταφράσεις τρέχουν στο παρασκήνιο και δεν αντικαθιστούν νεότερη επεξεργασία. Αν κρύψετε το προφίλ, αποκλείσετε κάποιον ή διαγράψετε τον λογαριασμό, οι κάρτες εξαφανίζονται. Το Gemini δεν αντικαθιστά το κείμενό σας."},"help-botdee-smartcard-search":{"title":"Ρωτήστε τον BOT DEE ποιος είναι κάποιος","body":"Το «Who am I?» ανοίγει το SMARTview σας. Το «Who is …», «What do you know of …» ή «What about …» με όνομα, επώνυμο, εμφανιζόμενο όνομα, handle Mingl ή FloqR, ή social handle (Instagram, TikTok, X). Μόνο αυτά τα πεδία ταυτότητας — όχι βιογραφικά, likes, ποτά ή είδη. Ένα αποτέλεσμα ανοίγει κάρτα People SMARTview στη συνομιλία — όχι λίστα markdown ούτε πλέγμα φωτογραφιών. Πολλά δείχνουν συμπαγείς SMARTcard. Ιδιωτικά, αποκλεισμένα ή μη δημοσιευμένα δεν εμφανίζονται — ο BOT DEE δεν επιβεβαιώνει αν υπάρχει λογαριασμός."},"help-botdee-smartcard":{"title":"SMARTcard ατόμων","body":"Όταν ταιριάζουν περισσότερα δημόσια προφίλ FLOQR, ο BOT DEE δείχνει συμπαγείς SMARTcard στη συνομιλία: πρώτα φωτογραφία σε πλήρες πλάτος, μετά όνομα και handle, μετά συμπαγές SMARTsummary χωρίς γεμάτο πλαίσιο. Πατήστε για πλήρες SMARTview — ίδια στοίβαξη. Οι κάρτες χρησιμοποιούν το ίδιο δημόσιο προφίλ και SMARTsummary. Το άνοιγμα δεν καλεί Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Πληκτρολογήστε Ver, Vers ή Version — τα κεφαλαία δεν μετράνε. Η BOT DEE δείχνει την κάρτα έκδοσης. Μια μεγαλύτερη ερώτηση όπως «ποια είναι η έκδοσή σου;» δείχνει επίσης αυτή την κάρτα."},"help-botdee-version-smartview-status":{"title":"Η κατάσταση Version SMARTview είναι ζωντανός έλεγχος","body":"Η κατάσταση υπηρεσίας ελέγχεται σε αυτό το αίτημα Version: Functions και πακέτο προσβάσιμα με ρυθμισμένο Gemini → Λειτουργικό; Functions και πακέτο εντάξει αλλά Gemini μη ρυθμισμένο → Υποβαθμισμένο; Functions εκτός αυτού του αιτήματος → Μη διαθέσιμο. Ποτέ στατική ετικέτα Δεν ελέγχθηκε. Το μοντέλο ΤΝ δείχνει το ρυθμισμένο id Gemini αυτού του deployment ακόμα κι αν αυτός ο γύρος δεν παρήγαγε. Τα σφραγίσματα frontend και backend μπορεί να διαφέρουν· και τα δύο έχουν ετικέτα. Ο Master Admin μπορεί να δει επιπλέον διάγνωση στις Τεχνικές λεπτομέρειες — οι patrons όχι."},"help-botdee-version-smartview-tabs":{"title":"Καρτέλες Version SMARTview","body":"Η Επισκόπηση περιγράφει το BOT DEE και ανοίγει Τεχνικές λεπτομέρειες χωρίς να φύγετε από τη συνομιλία. Νέα δείχνει μόνο επαληθευμένες αλλαγές BOT DEE και Gemini — όχι Master Admin, εργαλεία beta tester ή άλλες σημειώσεις προϊόντος FLOQR. Βοήθεια επαναλαμβάνει την εντολή Ver / Vers / Version. Αλλαγή καρτέλας ή ανάπτυξη κρατά το μη σταλμένο πρόχειρο και την κύλιση. Η κάρτα χρησιμοποιεί το Site Chrome σας — δεν υπάρχει δεύτερο θέμα."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"Στη συνομιλία BOT DEE πείτε Open Room SMARTview, Start a group chat ή σχεδιάστε ταξίδι Cancun με απλά λόγια. Έπειτα: Συμμετοχή τώρα ή Ορισμός προγράμματος. Η συμμετοχή τώρα ανοίγει συνεδρία φίλων Mingl τώρα και δεν βάζει κάρτα στο Search. Ορισμός προγράμματος είναι η έναρξη του BOT DEE room — όχι Shared Itinerary — και ενεργοποιεί Search SMARTnotification για εσάς και προσκεκλημένους φίλους Mingl. Προσκαλέστε μόνο φίλους Mingl — host συν 7 επισκέπτες. Οι επισκέπτες μπορούν επίσης να προσκαλούν. Η είσοδος δεν είναι πληρωμή και δεν ανοίγει κοινό λογαριασμό. Το BOT DEE δεν παίρνει ποτέ αριθμούς κάρτας. Τα ιδιωτικά μηνύματα BOT DEE μένουν ιδιωτικά. Το Site Chrome ακολουθεί Appearance. Ένα live room μένει ανοιχτό μέχρι End Room, περίπου τέσσερις ώρες μετά το άνοιγμα, ή αν όλοι έχουν φύγει περίπου 15 λεπτά. Η παύση ιδιωτικής συνομιλίας BOT DEE είναι ξεχωριστή."},"help-botdee-room-smartview-invite":{"title":"Πρόσκληση φίλων Mingl","body":"Μετά το Confirm (Join Now ή Set a schedule), το Invite δείχνει μόνο τους φίλους Mingl. Πατήστε έναν φίλο ή γράψτε Invite lorna — το Inbox λαμβάνει Review BOT DEE invite. Το chip μένει γκρι με Invite sent — δεύτερο πάτημα δεν στέλνει δεύτερη πρόσκληση. Είναι εντολή Room SMARTview, όχι VIP reserV ούτε People SMARTview Invite. Όχι δημόσιος σύνδεσμος. Όριο: οικοδεσπότης συν 7. Οι επισκέπτες μπορούν να προσκαλούν περισσότερους φίλους Mingl μέχρι ο οικοδεσπότης να το κλείσει. Η συμμετοχή δεν είναι πληρωμή. Αν ένα chip είστε εσείς ή κάποιος ήδη στη συνεδρία, μένει Είστε εσείς ή Ήδη στη συνεδρία και δεν στέλνει δεύτερη πρόσκληση."},"help-botdee-room-smartview-join":{"title":"Συμμετοχή σε συνεδρία BOT DEE","body":"Ανοίξτε την πρόσκληση Inbox ή Search Join Now συνδεδεμένοι ως ο φίλος Mingl στον οποίο στάλθηκε. Το Join Now ανοίγει BOT DEE, όχι Mingl chat. Εσείς και οι προσκεκλημένοι φίλοι Mingl μοιράζεστε το group chat Room SMARTview· τα ονόματα φαίνονται στα μέλη. Λάθος λογαριασμός, λήξη ή ανάκληση αρνείται. Η είσοδος στη room δεν είναι είσοδος σε λογαριασμό ούτε έγκριση πληρωμής. Το BOT DEE δεν παίρνει ποτέ αριθμούς καρτών."},"help-botdee-room-smartview-end":{"title":"Τέλος Room SMARTview","body":"Μόνο ο host μπορεί να τελειώσει μια room. Το τέλος δεν χρεώνει κανέναν και δεν σβήνει ιδιωτικές συνομιλίες άλλων. Ένας απλήρωτος κοινός λογαριασμός πρέπει πρώτα να πληρωθεί ή να ακυρωθεί. Ένα live room μένει ανοιχτό μέχρι End Room, περίπου τέσσερις ώρες μετά το άνοιγμα, ή αν όλοι έχουν φύγει περίπου 15 λεπτά. Η παύση ιδιωτικής συνομιλίας BOT DEE δεν είναι αποσύνδεση room. Ένας επισκέπτης που φεύγει δεν τελειώνει τη room όσο ο host είναι εκεί."},"help-botdee-room-smartview-tab":{"title":"Κοινός λογαριασμός Room SMARTview","body":"Πρώτα opt-in. Μετά προσθέστε γραμμή. Κλείστε με έναν πληρωτή ή μοιρασμένα. Χρεώνονται μόνο uid που επιβεβαιώνουν, μέσω FloqR Stripe. Η είσοδος στη room δεν είναι είσοδος στον λογαριασμό. Το BOT DEE δεν παίρνει ποτέ αριθμούς καρτών. Club POS αργότερα."},"help-botdee-room-smartview-who-pays":{"title":"Ποιος πληρώνει","body":"Ρωτήστε Who’s paying σε Room SMARTview για να δείτε το opt-in. Κανείς δεν χρεώνεται επειδή κάποιος είπε buy. Τα τελευταία τέσσερα της κάρτας μένουν στην απόδειξη του πληρωτή."},"help-botdee-room-smartview-kick":{"title":"Αφαίρεση από Room SMARTview","body":"Μόνο ο οικοδεσπότης αφαιρεί επισκέπτη. Ένας απομακρυσμένος φίλος δεν διαβάζει άλλα μηνύματα room. Απάντηση μοντέλου δεν αποκλείει κανέναν."},"help-botdee-room-smartview-share":{"title":"Κοινοποίηση σε Room SMARTview","body":"Το Share this conversation δεν αντιγράφει ποτέ το ιδιωτικό νήμα BOT DEE. Το BOT DEE δείχνει προεπισκόπηση επιλεγμένων κοινοποιήσιμων στοιχείων από αυτό το μήνυμα, ως προσωρινά. Μπορείτε να επεξεργαστείτε ή να αφαιρέσετε στοιχεία. Προφίλ και SMARTsummary μένουν έξω από τη room."},"help-botdee-room-smartview-schedule":{"title":"Συμμετοχή τώρα ή ορισμός προγράμματος","body":"Μετά το setup Room SMARTview επιλέξτε Συμμετοχή τώρα ή Ορισμός προγράμματος. Η συμμετοχή τώρα ανοίγει τη συνεδρία BOT DEE τώρα και δεν βάζει κάρτα στο Search. Ορισμός προγράμματος είναι η έναρξη του BOT DEE room — όχι Shared Itinerary. Μελλοντική ώρα ενεργοποιεί Search SMARTnotification μόνο για εσάς και προσκεκλημένους φίλους Mingl. Οι επισκέπτες RSVP μέχρι το room να είναι live· μετά το Join Now ανοίγει BOT DEE (όχι Mingl chat)."},"help-botdee-room-collab":{"title":"Κοινή headless κράτηση στο Room SMARTview","body":"Σε ένα Room SMARTview οι επιλογές VIP reserV ή ShoutOut του οικοδεσπότη φαίνονται σε όλους. Τα μέλη ψηφίζουν Ναι ή Όχι. Το Hold it και η πληρωμή μένουν στον οικοδεσπότη — η συμμετοχή και η ψήφος δεν είναι πληρωμή. Το BOT DEE δεν παίρνει ποτέ αριθμούς κάρτας. Το Stripe ανοίγει σε pop-out."},"help-botdee-room-elect-host":{"title":"Εκλογή οικοδεσπότη Room SMARTview","body":"Οποιοσδήποτε στη συνεδρία μπορεί να είναι οικοδεσπότης. Προτείνετε τον εαυτό σας ή άλλο μέλος. Ένας υποψήφιος γίνεται οικοδεσπότης στο 60% των τρεχόντων μελών (στρογγυλοποίηση προς τα πάνω). Αν φύγει ο οικοδεσπότης, οι υπόλοιποι εκλέγουν νέο — το room μένει ανοιχτό. Kick και End μένουν στον εκλεγμένο οικοδεσπότη."},"help-botdee-smartview-review":{"title":"Έλεγχος και διόρθωση SMARTsummary","body":"Το Gemini συντάσσει μόνο από δημόσια πεδία FLOQR — όχι σε κάθε προβολή. Λάθος γεγονός: αποκρύψτε το πεδίο ή επεξεργαστείτε την περίληψη. Το κείμενό σας δεν αντικαθίσταται. Σύγκρουση προφίλ ζητά έλεγχο. Αναφέρετε λάθος κάρτα από την επικάλυψη."},"help-botdee-smartview-chrome":{"title":"SMARTview και Site Chrome","body":"Το People SMARTview χρησιμοποιεί το FLOQR Site Chrome του θεατή (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Δεν υπάρχει δεύτερο θέμα. Η αλλαγή chrome ενημερώνει την κάρτα χωρίς απώλεια προσχεδίου."},"help-botdee-smartview-categories":{"title":"Κατηγορίες SMARTview","body":"Τέσσερις καρτέλες: Κοινωνικά, Γνωριμίες, Εστίαση, Μελλοντικά ταξίδια. Τα Κοινωνικά ανοίγουν στη Μουσική, μετά Nightlife, Αθλητισμός, Εκδηλώσεις. Οι ετικέτες είναι μόνο όσα μοιραστήκατε — χωρίς διπλούς τίτλους ή επινοημένα ταξίδια."},"help-botdee-smartview-media":{"title":"Φωτογραφίες και βίντεο SMARTview","body":"Η συμπαγής κάρτα χρησιμοποιεί το ίδιο κύριο μέσο με τη δημόσια σελίδα FLOQR — το πρώτο στοιχείο Profile Media (8 φωτογραφίες + 2 βίντεο). Πατήστε για Φωτογραφίες και Βίντεο από αυτές τις δημόσιες θέσεις. Σύρετε ή βέλη, μετά X (ή Escape) επιστρέφετε στην ίδια συνομιλία και προσχέδιο."},"help-botdee-smartview-privacy":{"title":"Απόρρητο SMARTview","body":"Το SMARTview δείχνει μόνο πεδία ήδη δημόσια στο FLOQR. Δεν είναι αναζήτηση ιστού. Γνωριμίες μόνο με opt-in. Απόκρυψη πεδίου στο προφίλ το αφαιρεί. Οι αποκλεισμένοι δεν βλέπουν την κάρτα. Αναφέρετε λάθος περίληψη από την επικάλυψη."},"help-botdee-smartview-translation":{"title":"Μετάφραση SMARTview","body":"Το SMARTsummary αποθηκεύεται στην προεπιλεγμένη γλώσσα προφίλ — αυτή είναι η πηγή, ακόμη κι αν δεν είναι αγγλικά. Μετά την αποθήκευση το FLOQR βάζει σε ουρά μετάφραση για κάθε άλλη γλώσσα, συμπεριλαμβανομένων των Αγγλικών. Ένας αγγλόφωνος βλέπει το αγγλικό SMARTsummary όταν τελειώσει η εργασία. Σε εκκρεμότητα ή αποτυχία φαίνεται η γλώσσα πηγής με σήμανση — ποτέ παλιά μετάφραση ως τρέχουσα."},"help-botdee-smartview-edit":{"title":"Επεξεργασία SMARTsummary","body":"Μόνο εσείς επεξεργάζεστε το SMARTsummary στην προεπιλεγμένη γλώσσα προφίλ. Η αποθήκευση είναι άμεση. Οι μεταφράσεις τρέχουν στο παρασκήνιο. Το Gemini δεν αντικαθιστά το κείμενό σας. Αν αλλάξει το δημόσιο προφίλ, το FLOQR ζητά έλεγχο αντί αντικατάστασης."},"help-botdee-privacy-assistant":{"title":"Βοηθός απορρήτου BOT DEE","body":"Αλλάξτε στο Προφίλ μου τι βλέπουν άλλοι χρήστες FLOQR — το BOT DEE δεν προσθέτει δεύτερο δημόσιο διακόπτη. Λάθος διαδικτυακή αντιστοίχιση μπορείτε να αμφισβητήσετε χωρίς αλλαγή προφίλ. Το BOT DEE δεν υπόσχεται διαγραφή σε ιστότοπο τρίτου."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Κάθε σύσταση μπορεί να δείξει στοιχεία, ημερομηνία ελέγχου, εξατομίκευση και χορηγία. Μπορείτε να ζητήσετε από το BOT DEE να μην εξατομικεύσει αυτή την αναζήτηση."},"help-botdee-research-library":{"title":"Βιβλιοθήκη έρευνας BOT DEE","body":"Αποθηκεύστε μέρη και κάρτες που ρωτήσατε το BOT DEE. Ένα Google Place ID δεν αντιγράφει φωτογραφίες ή κριτικές. Μπορείτε να ανανεώσετε ή να διαγράψετε. Οι αδειοδοτημένες μνήμες μένουν κλειστές μέχρι έγκριση παρόχου."},"help-botdee-smartview":{"title":"Το SMARTview μου","body":"Το SMARTview μου δείχνει την κάρτα Προσώπου από δημόσια πεδία FLOQR, με τα ίδια Profile Media της δημόσιας σελίδας — όχι mock χώρων ή εστιατορίων. Η επεξεργασία SMART Summary αλλάζει την περίληψη στη γλώσσα προφίλ. Τα mock χώρων/εστιατορίων είναι στο Master Admin → Features → BOT DEE → SMARTviews. Χωρίς ζωντανά Places ή Yelp."},"help-botdee-memory":{"title":"Αποθηκευμένες συνομιλίες BOT DEE","body":"Ανοίξτε Λειτουργίες & παραγγελίες → Το BOT DEE μου για αποθήκευση μετά την παύση, εξαγωγή ή διαγραφή ιστορικού. Η παύση πέντε λεπτών κλείνει τη ζωντανή συνεδρία. Με opt-in το BOT DEE κρατά τη συνομιλία. Οι επισκέπτες δεν αποθηκεύονται. Το Mingl μένει στο Mingl."},"help-botdee-knows-of-me":{"title":"Τι γνωρίζει το BOT DEE για μένα","body":"Τα γεγονότα με την έγκρισή σας βρίσκονται σε Λειτουργίες & παραγγελίες → Το BOT DEE μου. Η λίστα είναι κενή αν η μνήμη είναι off ή δεν υπάρχουν δεδομένα. Εξαγωγή ή διαγραφή εδώ. Το BOT DEE δεν αποθηκεύει IP. Το Mingl δεν αντιγράφεται."},"help-search-settings-appearance":{"title":"Settings στην Search","body":"Στην οθόνη Search πατήστε Settings για να ανοίξετε Profile & Settings στην καρτέλα Appearance — εκεί είναι το Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Το πλακίδιο Settings χρησιμοποιεί το ίδιο πακέτο εικονιδίων chrome με τα άλλα σήματα Search."},"help-club-website-feed":{"title":"Ροή για τον ιστότοπο του κλαμπ","body":"Δείξτε τη δημοσιευμένη σελίδα του κλαμπ στο FLOQR στον δικό σας ιστότοπο. Πατήστε «Δημιουργία κλειδιού και συνδέσμων» και επικολλήστε τον κώδικα iframe στον ιστότοπο ή δώστε τον σύνδεσμο JSON ή RSS στον διαχειριστή του. Η ροή δείχνει επερχόμενες εκδηλώσεις, προβεβλημένους DJ και προσωπικό, τη συλλογή και τα στοιχεία επικοινωνίας, σύμφωνα με τις ρυθμίσεις της δημόσιας σελίδας. Οι φωτογραφίες του προσωπικού εμφανίζονται μόνο όταν η συγκατάθεση έχει επιβεβαιωθεί. Ένα νέο κλειδί απενεργοποιεί τους παλιούς συνδέσμους, και αυτούς του προγράμματος προσωπικού."},"help-featured-staff":{"title":"Προβεβλημένο προσωπικό","body":"Επιλέξτε το προσωπικό για τη δημόσια σελίδα του κλαμπ. Για κάθε άτομο, πατήστε μία από τις φωτογραφίες του στο FLOQR ή επιλέξτε «Μεταφόρτωση από υπολογιστή». Μπορείτε να αλλάξετε τον ρόλο κάτω από το όνομα. Πατήστε «Save Public Profile» για δημοσίευση. Πριν δημοσιεύσετε φωτογραφίες, πάρτε τη συμφωνία κάθε ατόμου και επιλέξτε το πλαίσιο συγκατάθεσης."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"Το FloqR Inbox κρατά System Messages και εσωτερικά μηνύματα υποστήριξης. Η λίστα φορτώνει πρώτη ώστε τα μηνύματα να εμφανίζονται γρήγορα. Πατήστε το αιωρούμενο κουμπί New Message για σύνταξη — πληκτρολογήστε όνομα ή @username για επιτρεπόμενο παραλήπτη (Club Admin, CSR ή εγκεκριμένο προσωπικό). Η συνομιλία patron-προς-patron μένει στο Mingl μετά από αμοιβαίο Mingl. Το άνοιγμα πρόσκλησης βάρδιας δεν επιβεβαιώνει — ελέγξτε και Approve selected στο Work Calendar."},"botdee-ask-floqr":{"title":"Ρωτήστε το FloqR με το BOT DEE","body":"Ρωτήστε το FloqR με το BOT DEE — πατήστε την κινούμενη ένδειξη ή περιμένετε να σας ζητηθεί και μετά πληκτρολογήστε αυτό που θέλετε με απλά λόγια. Προϊόντα: Mingl, RydR, BartR, ShoutOut, FloqCAST (σούπερ σταρ), κλαμπ. Στόχοι: πείτε «Θέλω να μπορώ να…» (π.χ. να γίνω Club Admin) ή «make me a superstar» για βήματα και συνδέσμους."},"help-vip-book-table":{"title":"Κράτηση VIP τραπεζιού (VIP reserV)","body":"Το VIP reserV δείχνει τον χάρτη και κλείνει τραπέζια. Ανοίξτε VIP reserV από Αναζήτηση, επιλέξτε Decades ή Lima Twist Club και βράδυ, πατήστε πράσινο τραπέζι, κρατήστε 30 λεπτά, αποδεχτείτε Όρους και πληρώστε με FloqR Stripe. Μπαρ και DJ μη κρατήσιμα. Στην Aurelia χρησιμοποιήστε Explore 3D walk-through για την διαδραστική αίθουσα (η κράτηση μένει στο 2D)."},"help-vip-choose-venue":{"title":"Επιλέξτε χώρο VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Τα Decades, Lima Twist Club και Aurelia έχουν δημοσιευμένο 2D σχέδιο· η Aurelia προσφέρει και Explore 3D walk-through."},"help-become-club-admin":{"title":"Γίνε Club Admin","body":"Ζητήστε πρόσβαση Club Admin και, στη συνέχεια, λάβετε έγκριση του χώρου."},"help-role-profiles":{"title":"Επισκόπηση προφίλ ρόλων","body":"Δείτε πώς λειτουργούν οι ρόλοι Club Admin, DJ, Promoter και φιλοξενίας."},"help-staff-scheduling":{"title":"Ημερολόγιο & Χρονοδιάγραμμα","body":"Club Admin Το Ημερολόγιο εμφανίζει πρόχειρες (μωβ), Εκκρεμείς (πορτοκαλί), Επιβεβαιωμένες (πράσινες) και Ανοιχτές/μη συμπληρωμένες κάρτες — καθεμία με γραπτή κατάσταση, όχι μόνο χρώμα. Ο χρονοπρογραμματιστής είναι το πλέγμα προσχέδιο/δημοσίευσης ατόμων × ημερών. Το Website ingest / publicVenueCalendar επιστρέφει Μόνο επιβεβαιωμένες εργασίες. Ένα πράσινο χάπι Payid this month εμφανίζεται σε Club Admins όταν staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Συνδρομές ειδοποιήσεων Club SMS και WhatsApp","body":"Club Admin → Ειδοποιήσεις: Send test alert χρησιμοποιεί τα πλαίσια που είναι επιλεγμένα αυτήν τη στιγμή. Εντός εφαρμογής (και Push) γράφει ένα μήνυμα συστήματος στο FloqR Inbox. Το email χρησιμοποιεί διευθύνσεις διαχειριστή συλλόγου. Τα SMS και WhatsApp εξακολουθούν να χρειάζονται συνδρομή επί πληρωμή συν ένα τηλέφωνο ειδοποίησης E.164. Πράσινο χάπι = Firebase συνδρομή 1 (προπληρωμένο πακέτο 10 $). κόκκινο = 0. Εάν το Send test alert επιστρέψει Authentication Error - invalid username, το Firebase μυστικό TWILIO_ACCOUNT_SID πρέπει να είναι το SID του λογαριασμού που ξεκινά με AC (34 χαρακτήρες) από το console.twilio.com — όχι το Auth Token και όχι ένα κλειδί API (SK)."},"help-club-sms-notification":{"title":"SMS συνδρομή ειδοποιήσεων","body":"Το χάπι SMS είναι πράσινο όταν το Firebase smsSubscribed είναι 1 (προπληρωμένο πακέτο $10, 466 μονάδες, όχι μηνιαία ή ετήσια). Κόκκινο/αναβοσβήνει σημαίνει 0 — ανοιχτό ? και πατήστε Subscribe $10. Οι πιστώσεις που απομένουν και η ημερομηνία τελευταίας πληρωμής είναι σε αυτήν τη βοήθεια. Καταργήστε την επιλογή SMS και Αποθήκευση για παύση των ειδοποιήσεων χωρίς να χάσετε το πακέτο επί πληρωμή."},"help-club-whatsapp-notification":{"title":"WhatsApp συνδρομή ειδοποιήσεων","body":"Το χάπι WhatsApp είναι πράσινο όταν το Firebase whatsappSubscribed είναι 1 (προπληρωμένο πακέτο $10, 233 μονάδες, όχι μηνιαία ή ετήσια). Κόκκινο/αναβοσβήνει σημαίνει 0 — ανοιχτό ? και πατήστε Subscribe $10. Οι πιστώσεις που απομένουν και η ημερομηνία τελευταίας πληρωμής είναι σε αυτήν τη βοήθεια. Καταργήστε την επιλογή WhatsApp και Αποθήκευση για παύση των ειδοποιήσεων χωρίς να χάσετε το πακέτο επί πληρωμή."},"help-schedule-message-templates":{"title":"Προγραμματίστε πρότυπα μηνυμάτων","body":"Club Admin → Ειδοποιήσεις → Message templates. Αυτά είναι μηνύματα συστήματος (Inbox / Email / SMS / WhatsApp), όχι ShoutOut. Επεξεργαστείτε τον τίτλο και το σώμα για το New shift needs confirmation, το πρόγραμμα ενημέρωσης, το Shift επιβεβαιώθηκε και το Shift απορρίφθηκε. Placeholders: {club} {role} {when} {link} {worker}. Τα εισερχόμενα εργαζομένων χρησιμοποιούν Review & confirm shift — ποτέ Open Related ShoutOut."},"help-schedule-confirm":{"title":"Επιβεβαιώστε τις ανατεθειμένες βάρδιες","body":"Οι σύνδεσμοι Inbox / Email / SMS ανοίγουν Work Calendar. Κοιτάξτε κάθε εκκρεμή εργασία, σημειώστε την (ή Select all) και μετά Approve selected. Το άνοιγμα του συνδέσμου δεν επιβεβαιώνεται. Μόνο το εξουσιοδοτημένο μέλος σέρβις μπορεί να εγκρίνει — Club Admin δεν μπορεί να επιβεβαιώσει εκ μέρους του."},"help-template-catalog-report":{"title":"Πρότυπο αναφοράς καταλόγου","body":"Εμφανίζει κάθε τύπο προτύπου ShoutOut και ποια μεγέθη LED υποστηρίζει (Is96x48, Is64x48, Is64x32). Ένας χώρος προσφέρει ένα πρότυπο μόνο όταν τουλάχιστον μία από αυτές τις σημαίες είναι 1 και η αντίστοιχη σημαία VenueSupports* είναι 1. Τα πρότυπα γενεθλίων / διαχωρισμένων μέσων είναι 1 σε 96×48, 64×48 και 64×32. Το 96×48 είναι 3 γραμμών δίπλα-δίπλα. 64×48 και 64×32 επαναφέρετε τη φωτογραφία και στη συνέχεια το φωνητικό 3 γραμμών με μια κάρτα λαβής FLOQR +."},"help-club-display-screens":{"title":"FLOQR οθόνες εμφάνισης","body":"Το Firebase clubLocations αποθηκεύει τα VenueSupports96x48, VenueSupports64x48 και VenueSupports64x32 ως 0 ή 1. Τα πρότυπα αποθηκεύουν τα Is96x48, Is64x48 και Is64x32 με τον ίδιο τρόπο. Ένας χώρος εμφανίζει ένα πρότυπο μόνο όταν τουλάχιστον ένα ζεύγος είναι 1. Οι διευθύνσεις URL Xibo παραμένουν display.html?location=id και display2.html?location=id — το μέγεθος οθόνης δεν περιλαμβάνεται στη διεύθυνση URL. Το Birthday προσφέρεται και στα τρία μεγέθη (3-γραμμές δίπλα-δίπλα σε 96×48· βρόχος φωτογραφίας/αναφώνησης σε 64×48 και 64×32). Το κύριο είναι το display.html. Δευτερεύον είναι το display2.html."},"help-staff-week-calendar":{"title":"Προγραμματιστής","body":"Club Admin Προγραμματιστής είναι ένα πλέγμα ατόμων × ημερών της εβδομάδας. Το Save shift κλείνει το πρόγραμμα επεξεργασίας με Schedule card successfully saved. Δημιουργήστε πρόχειρα, Publish schedule έτσι ώστε οι εργαζόμενοι να επιβεβαιώνουν ότι εκκρεμούν μέχρι να επιβεβαιωθούν, Select shifts για πολλαπλή διαγραφή και Website ingest για να τοποθετήσετε δημοσιευμένες βάρδιες στον ιστότοπο του κλαμπ. Προεπιλεγμένο παράθυρο βάρδιας = κλαμπ ανοιχτό − 2 ώρες έως κλείσιμο + 1 ώρα."},"help-staff-schedule-user-guide":{"title":"Οδηγός Χρήστη Προγραμματισμός Προσωπικού","body":"Ανοίξτε το ? δίπλα στο Χρονοδιάγραμμα στο Club Admin Προγραμματισμός. Δημιουργήστε πρόχειρες βάρδιες, Publish schedule ώστε οι εργαζόμενοι να επιβεβαιώσουν ότι βρίσκονται σε εκκρεμότητα→ επιβεβαιωθεί, και μετά Select shifts για να διαγράψετε πολλές ταυτόχρονα. Παράδειγμα: όλα τα ντραφτ της Τετάρτης συν ένα τσιπ επιβεβαιωμένο την Πέμπτη."},"help-create-publish-schedule":{"title":"Δημιουργήστε και δημοσιεύστε ένα πρόγραμμα προσωπικού","body":"Προσθέστε αλλαγές πρόχειρων στο πλέγμα ατόμων × ημερών, ελέγξτε τις μάρκες και μετά Publish schedule. Οι εργαζόμενοι πρέπει να επιβεβαιώσουν πριν επιβεβαιωθεί μια βάρδια. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Διαγράψτε πολλές προγραμματισμένες ή πρόχειρες βάρδιες","body":"Select shifts, ανακατέψτε κεφαλίδες ημέρας και μάρκες και μετά Delete selected. Παράδειγμα: όλα τα ντραφτ της Τετάρτης συν μία Πέμπτη επιβεβαιωμένη βάρδια."},"help-staff-worksheet":{"title":"Φύλλο Εργασίας - Εβδομαδιαίο Ημερολόγιο Προσωπικού","body":"Τα εκλεγμένα μέλη υπηρεσίας ανοίγουν το Work Calendar στις Ρυθμίσεις. Οι σύνδεσμοι Inbox / Email / SMS επιβεβαιώνουν εδώ. Ελέγξτε τις εκκρεμείς εργασίες, επιλέξτε κάθε βάρδια (ή Select all) και μετά Approve selected — το άνοιγμα του μηνύματος δεν επιβεβαιώνεται. Το πλέγμα εβδομάδας δείχνει δημοσιευμένες βάρδιες συναδέλφων. Τα πρόχειρα παραμένουν στο Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Όλοι ξεκινούν ως patron FLOQR. Στο My Profile & Settings πατήστε Elect to become a service member, επιλέξτε ρόλο και clubs, υποβάλετε στο κάτω μέρος.\n\nΟδηγός προτύπων προφίλ — τα κοινωνικά προφίλ patron παραμένουν στα Δημόσια μέσα.\n\nΈγκριση Club Admin — Club Admin → Employee/Workers → Pending Worker Requests, ή Αναθεώρηση και επιλογή σε αυτή την καρτέλα."},"help-venue-website-ingest":{"title":"Απορρόφηση ιστότοπου συλλόγου (API, RSS, iframe)","body":"Club Admin → Προγραμματισμός → Website ingest. Δημιουργήστε ένα μυστικό (εμφανίζεται μία φορά, αποθηκεύεται μόνο ένας κατακερματισμός). Τραβήξτε τις δημοσιευμένες μετακινήσεις προσωπικού στον επίσημο ιστότοπο του συλλόγου με JSON (?format=json&dataset=schedule|hours|profile|all), RSS ή ένα απόσπασμα iframe. Πρόχειρα, email εργαζομένου και τηλέφωνο δεν περιλαμβάνονται ποτέ. Περιστρέψτε το μυστικό εάν διαρρεύσει."},"help-venue-hours-calendar":{"title":"Ώρες λειτουργίας του χώρου","body":"Στο Δημόσιο Προφίλ Club, ορίστε τις προεπιλεγμένες εβδομαδιαίες ανοιχτές/κλειστές ώρες και, στη συνέχεια, προσθέστε παρακάμψεις περιόδου για ειδικές εβδομάδες χωρίς να χάσετε την προεπιλογή. Η δημόσια σελίδα του κλαμπ εμφανίζει ένα πλέγμα εβδομάδας Κυριακής-Σαββάτου με το εύρος ημερομηνιών (π.χ. Κυρ 9 – Σαβ 15, Αυγ 2026) και χρωματισμό ημερολογίου. Οι επερχόμενες επίσημες αργίες αναφέρουν τις ώρες λειτουργίας/κλεισίματος και καλέστε όταν διαφέρουν από τις συνηθισμένες καθημερινές. Ο Προγραμματισμός Προσωπικού χρησιμοποιεί ανοιχτό − 2h έως κλείσιμο + 1h. Η λίστα επισκεπτών μπορεί να προτείνει ανοιχτές βραδιές."},"help-club-admin-affiliation":{"title":"Club Admin ανάθεση χώρου","body":"Club Admin ανοίγει μόνο το Κέντρο Διοίκησης του Χώρου για μια λέσχη στην οποία έχουν ανατεθεί. Το άνοιγμα του admin.html χωρίς χώρο δεν είναι πλέον ως προεπιλογή Zebbies. Οι δοκιμαστικοί λογαριασμοί temp_clubadmin_N@floqr-demo.com αντιστοιχίζονται στο temp-democlub-N. Οι μη εκχωρημένοι διαχειριστές ζητούν εκχώρηση από το Master Admin."},"help-venue-command-center":{"title":"Κέντρο εντολών του χώρου διεξαγωγής","body":"Έγκριση ShoutOuts, έλεγχος απόδοσης χώρου και αντιστοίχιση δραστηριότητας λογαριασμού για αυτήν την τοποθεσία."},"help-club-template-repository":{"title":"Τα πρότυπα του club σας","body":"Τα πρότυπα που έγιναν μόνο για το club σας εμφανίζονται πρώτα, με την ένδειξη «Αποκλειστικά στο» και το όνομα του χώρου. Τα ανατεθειμένα πρότυπα είναι αυτά που μπορούν να επιλέξουν οι πελάτες στο club σας· αλλάξτε τα με Ανάθεση ή Αφαίρεση προτύπου. Η αναζήτηση βρίσκει ένα πρότυπο ακόμη και χωρίς τόνο ή με μικρό ορθογραφικό λάθος."},"help-employee-network":{"title":"Δίκτυο υπαλλήλων και προσωπικού","body":"Εμφανίζονται μόνο άτομα συνδεδεμένα με αυτό το club: προσωπικό που ορίστηκε ή εγκρίθηκε εδώ, διαχειριστές του club και προσωπικό συνδεδεμένο με αυτό το club. Για να δώσετε ρόλο σε κάποιον, πληκτρολογήστε όνομα, όνομα χρήστη ή email στο Ορισμός πελάτη σε ρόλο, πατήστε Επιλογή δίπλα στο σωστό άτομο, διαλέξτε τον ρόλο, μετά πατήστε Ορισμός ρόλου στον επιλεγμένο πελάτη και επιβεβαιώστε. Το άτομο χρειάζεται πρώτα λογαριασμό πελάτη FLOQR. Σερβιτόροι, σερβιτόρες και bottle girls της λίστας μπορούν να γίνουν εκπρόσωποι εξυπηρέτησης πελατών (CSR)."},"help-template-tags":{"title":"Ετικέτες προτύπων","body":"Προσθέστε λέξεις που μπορεί να πληκτρολογήσουν οι πελάτες όταν ψάχνουν πρότυπο στον χώρο σας, όπως βραδιά αγώνα ή γενέθλια. Οι Υπεύθυνοι προτύπων μπορούν να προσθέτουν ετικέτες. Οι Διαχειριστές προτύπων και οι Club Admin μπορούν επίσης να τις αφαιρούν. Ο Club Admin αναθέτει αυτούς τους ρόλους στο Role Activity & Permission."},"help-display-idle-default":{"title":"Οθόνη αναμονής: Use ShoutOut @ χώρος","body":"Όταν δεν παίζει κανένα ShoutOut, το Display 1 δείχνει «Use ShoutOut @» με το όνομα του χώρου σας. Κάθε εγκεκριμένο ShoutOut παίζει 10 λεπτά και μετά η οθόνη επιστρέφει μόνη της σε αυτό το μήνυμα. Η επαναφορά της προεπιλεγμένης οθόνης στο Club Admin το κάνει αμέσως."},"help-club-messaging-credit":{"title":"Πίστωση SMS & WhatsApp","body":"Κάθε πακέτο $10 χρηματοδοτεί $7,00 χωρητικότητας Twilio· η FloqR κρατά $3,00 πλατφόρμας. Πακέτο SMS → 466 μηνύματα (≈ $0,015 SMS ΗΠΑ). Πακέτο WhatsApp → 233 μηνύματα (≈ $0,030 Twilio + Meta marketing). Σε μηδενικό υπόλοιπο αγοράστε νέο πακέτο πριν την αποστολή. Ops SMS unlock ($10) περιλαμβάνει πακέτο SMS. Υπηρεσία WhatsApp ($10) περιλαμβάνει πακέτο WhatsApp. Υπολογισμός: $10 → 466 SMS ή 233 WhatsApp ($7,00 Twilio / $3,00 FloqR)."},"help-club-marketing-campaigns":{"title":"Καμπάνιες marketing","body":"Επιλέξτε πρότυπο κλάδου, φορτώστε φόντο και επιπλέον εικόνες, επεξεργαστείτε κείμενο, αποθηκεύστε ή στείλτε. Η αποστολή χρεώνει πίστωση SMS ή WhatsApp από Πίστωση μηνυμάτων."},"help-club-in-app-marketing":{"title":"Marketing in-app","body":"Δημοσιεύστε ένα flyer ή ένα βίντεο έως 30 δευτερόλεπτα εκ μέρους του club σας. Μόλις πληρωθεί και εγκριθεί από το FLOQR, εμφανίζεται στην οθόνη φόρτωσης της αναζήτησης, στο Mingl, στο RydR και σε άλλες οθόνες του FLOQR. Με τους Δημοσιευτές διαφημίσεων του club επιτρέπετε σε μέλος της ομάδας να δημοσιεύει για το club (ρόλος Club Ad Poster). Δεν χρειάζονται μονάδες SMS."},"help-vip-terms-consent":{"title":"Όροι VIP reserV","body":"Μετά την κράτηση τραπεζιού, ανοίξτε τη σελίδα Όρων, διαβάστε και αποδεχτείτε μία φορά (προαιρετικό marketing χωριστά). Η συναίνεση αποθηκεύεται πριν το FloqR Stripe Checkout — όπως πληρωμένο ShoutOut, μετά απόδειξη και πάσο."},"help-vip-door-pass":{"title":"Πάσο πόρτας VIP reserV","body":"Μετά την επιβεβαίωση προκαταβολής, Το προφίλ μου → Κρατήσεις → Εμφάνιση πάσου για QR μίας χρήσης. Φέρτε ID 21+. Το προσωπικό χρησιμοποιεί VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in πόρτας VIP reserV","body":"Οι VIP Managers ανοίγουν VIP reserV Door για απόψε. Σαρώστε ή επικολλήστε token, επιβεβαιώστε ID 21+, check-in. No-show μόνο μετά από grace. Σύνδεσμος notify δεν αλλάζει κατάσταση."},"help-vip-payment-collector":{"title":"Συλλέκτης πληρωμής VIP reserV και Club POS","body":"Προτιμώμενο για ζωντανά clubs με Toast/SpotOn: Club POS — το FLOQR κρατάει/χαρτογραφεί· το POS διαχειρίζεται προκαταβολή, λογαριασμό και δαπάνη. Εναλλακτικές: Club Stripe, FloqMedia Stripe (FloqR) ή VIP engine + CSV. Η Aurelia (Demo Club) προεπιλέγει FloqMedia Stripe — ρωτήστε το BOT DEE τα βήματα Master και Club Admin."},"help-vip-table-isbooked":{"title":"Κατάσταση isBooked τραπεζιών VIP στο Firestore","body":"Κάθε VIP club έχει ένα doc Firestore ανά αριθμό τραπεζιού και βραδιά: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Id = εκτυπωμένος αριθμός (π.χ. T1, B3). Μετά την ολοκλήρωση κράτησης: isBooked \"1\", isBookedYes \"yes\". Ελεύθερα: \"0\" / \"no\". Τα holds δεν αλλάζουν isBooked. Ακύρωση → \"0\". Το getVipAvailability χρησιμοποιεί το isBooked ως κατάσταση κράτησης. Η ακύρωση μηδενίζει πάντα το isBooked σε \"0\"· FloqMedia/Club Stripe μπορεί να επιστρέψει την προκαταβολή ανά πολιτική του club."},"help-vip-floqr-stripe-aurelia":{"title":"Ρύθμιση FloqMedia Stripe για Aurelia (Demo Club)","body":"Η Aurelia (temp-democlub-1) χρησιμοποιεί FloqMedia Stripe (FloqR Checkout) ως προεπιλεγμένο συλλέκτη προκαταβολής VIP — οι πελάτες πληρώνουν στο platform Stripe του FloqR και μετά το τραπέζι σημειώνεται ως booked.\n\nΒήματα Master Admin:\n1) Ανοίξτε Master Admin → Features Mgmt → VIP reserV Payments.\n2) Επιβεβαιώστε ότι το VIP Reservations είναι ενεργό στο δίκτυο.\n3) Seed / refresh παρόχων POS μόνο αν θα χρησιμοποιήσετε Club POS — δεν χρειάζεται για FloqMedia Stripe.\n4) Αφήστε την Aurelia σε FloqMedia Stripe εκτός αν χρειάζεται Club POS ή Club Stripe.\n5) Μετά τις προκαταβολές, ανοίξτε Network VIP billing.\n\nΒήματα Club Admin (Aurelia):\n1) Σύνδεση ως temp_clubadmin_1@floqr-demo.com (Email OTP στην αρχική) ή Club Admin Aurelia.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) Στο Payment collector επιλέξτε FloqMedia Stripe (FloqR).\n4) Κρατήστε Require deposit before table is marked booked.\n5) Save payment collector.\n6) Δοκιμή: vip.html?location=temp-democlub-1 → κράτηση τραπεζιού → Όροι → Πληρωμή (δοκιμαστική κάρτα 4242…).\n7) Door / τιμολόγηση: Open Door· Refresh billing.\n\nΜην επιλέξετε Club POS για demos Aurelia χωρίς sandbox Toast/SpotOn. Τα FloqMedia, Stripe, ShoutOut και VIP reserV δεν μεταφράζονται."}},"pl":{"help-smartvisuals-notification":{"title":"SMARTnotification Mingl Room","body":"Kompaktowe zaproszenie Mingl Room może pojawić się na Search, gdy ustawisz harmonogram room BOT DEE albo znajomy Mingl Cię zaprosi. Gospodarz widzi własną zaplanowaną room na Search bez zapytania demo Cancun. Zobacz zaproszenie otwiera Room SMARTview. Join Now idzie do BOT DEE, nie Mingl chat. Nie teraz chowa kartę w tej karcie; Inbox zostawia Review BOT DEE invite. Demo Cancun jest tylko Studio. Grafika to ilustracja, nie zdjęcie. Roomy Join Now bez harmonogramu nie pojawiają się na Search."},"help-smartvisuals-room":{"title":"Room SMARTview ze SMARTvisuals","body":"Room SMARTview pokazuje zaproszenie Mingl: harmonogram, RSVP lub status na żywo oraz Join Now. Join Now na Search otwiera BOT DEE (nie Mingl chat) z room= i t=. SMARTstencils i SMARTbackgrounds idą za autoryzowanym tytułem — Cancun Trip używa grafiki podróży, nie prawdziwego zdjęcia Cancun. Prywatny czat BOT DEE nigdy nie wybiera grafiki. Oznakowane Ad poniżej to próbka z tych tagów. Puste przy czacie prywatnym lub iniekcji; to nie żywy reklamodawca."},"help-scheduling-schedule-for":{"title":"Planowanie personelu","body":"Planuj zmiany i bookingi, a potem powiadamiaj każdą osobę przez Inbox, Email, SMS lub WhatsApp. W sekcji „Grafik dla” wybierz, czyim kalendarzem się zajmujesz: „Mój grafik DJ” to twój własny kalendarz, „Klub” pokazuje kluby, którymi zarządzasz, a „Firma promocyjna” firmy, dla których promujesz. Każdy kalendarz ma własną subskrypcję za 20 $/miesiąc. Zmiany przypisane tobie pojawiają się w „Moje przydziały”, gdzie je potwierdzasz lub odrzucasz."},"help-staff-marketing-consent":{"title":"Zgoda marketingowa personelu","body":"Dołączając do zespołu lokalu lub wydarzenia, musisz zaznaczyć pole zgody marketingowej. Pozwala ona temu lokalowi lub organizatorowi oraz jego administratorom i menedżerom używać Twojej nazwy FLOQR, roli oraz opublikowanych zdjęć i filmów na swoich stronach, ulotkach i w mediach społecznościowych (Instagram, Facebook, TikTok, YouTube i podobne) bez ponownego pytania o każde użycie. Nie mogą publikować Twojego numeru telefonu ani adresu e-mail. Zgodę możesz wycofać w każdej chwili w sekcji Mój profil, karta Usługi i członkowie serwisu. Wycofanie zatrzymuje nowy marketing; materiałów już wydrukowanych lub opublikowanych nie trzeba wycofywać. Club Admini widzą status zgody każdej osoby w Sieci pracowników i personelu oraz w Wyróżnionym personelu."},"help-botdee-privacy-session":{"title":"Prywatność i sesja BOT DEE","body":"Pięciominutowa pauza kończy sesję na żywo. Nie usuwa tego czatu dla zalogowanych, wspomnień ani przepływów. Zostają też kopie w Mój profil → Funkcje i zamówienia → My BOT DEE. Goście pozostają tymczasowi. Czaty Mingl nigdy nie są tu kopiowane. Enter wysyła; Shift+Enter zaczyna nową linię. Imię i ton ustawisz w Mój profil → My BOT DEE, nie przyciskiem na czacie."},"help-botdee-place-search":{"title":"Zapytaj BOT DEE o lokale FLOQR","body":"Pytaj zwykłym językiem — restauracje sushi w Washington DC, kluby w DC albo konkretny klub. BOT DEE szuka tylko onboardowanych venue FLOQR, nie Google ani Yelp. Trafienia otwierają zwartą kartę Place SMARTview (nazwa, krótki opis, oceny, link do strony publicznej) ze SMARTbackground — nie studnią zdjęcia. Podanie miasta z VIP reserV (reservations in Miami) nadal dołącza Place SMARTview obok karty VIP. Zdjęcia patronów i pitch ShoutOut zostają pominięte, chyba że o nie poprosisz. Jeśli nic jeszcze nie jest onboardowane, BOT DEE to powie."},"help-botdee-page":{"title":"BOT DEE","body":"Czatuj z BOT DEE na stronie BOT DEE prostymi słowami: wydarzenia i kluby, ShoutOut, Mingl, RydR, BartR, FloqCAST, Twój profil, grafiki personelu lub narzędzia Club Admin. Naciśnij Enter, aby wysłać; Shift+Enter zaczyna nową linię. BOT DEE rozmawia jak człowiek (spróbuj How are you?) i szuka tylko gdy pytasz, jak coś zrobić w FLOQR. Po zalogowaniu BOT DEE zachowuje ten czat przy odświeżeniu lub na drugim telefonie, a po pauzie może wrócić do zapisanej historii. Pauza nie usuwa czatu. Odpowiedzi używają klasyfikacji Twojego konta. Po zalogowaniu BOT DEE widzi te same dobrowolnie publiczne datapointy profilu co Ty (muzyka, jedzenie, podróże, hobby i reszta Privacy datapoint sharing) — nigdy e-mail, telefon, dane karty ani GPS. Dotknij Ustawienia pod polem czatu, aby otworzyć zapisane czaty i wspomnienia. Dotknij zdjęcia na czacie, aby otworzyć je w osobnym oknie. Zamknij X lub Zamknij, aby wrócić do czatu. Znak + w prawym górnym rogu otwiera zapisane czaty i ich nie usuwa."},"help-botdee-smartview-troubleshoot":{"title":"Rozwiązywanie problemów SMARTview","body":"Pusta karta: ukryte pola lub blokada. Zapis nieudany: zaloguj się — tłumaczenia są na serwerze. Oczekujące/błąd: język źródłowy z etykietą. Edytuje tylko właściciel. SMARTviews Master Admin to nadal mock; Places i Yelp wyłączone. Motyw idzie za Site Chrome."},"help-botdee-smartcard-sync":{"title":"SMARTsummary zostaje zsynchronizowane","body":"Edytuj SMARTsummary w domyślnym języku profilu. Zapis jest natychmiastowy. Otwarte karty i SMARTview aktualizują się z tego samego rekordu. Tłumaczenia idą w tle i nie nadpisują nowszej edycji. Ukrycie profilu, blokada lub usunięcie konta chowa te karty. Gemini nie nadpisuje Twojego tekstu."},"help-botdee-smartcard-search":{"title":"Zapytaj BOT DEE, kim ktoś jest","body":"„Who am I?” otwiera Twoje SMARTview. „Who is …”, „What do you know of …” lub „What about …” plus imię, nazwisko, nazwa wyświetlana, handle Mingl lub FloqR albo handle społecznościowy (Instagram, TikTok, X). Trafienia tylko po tych polach tożsamości — nie bio, polubienia, napoje ani gatunki. Jeden wynik otwiera kartę People SMARTview w czacie — nie listę markdown ani siatkę zdjęć. Więcej wyników to zwarte SMARTcard. Prywatne, zablokowane lub nieopublikowane nie są listowane — BOT DEE nie potwierdza, czy konto istnieje."},"help-botdee-smartcard":{"title":"SMARTcard osób","body":"Gdy pasuje więcej niż jeden publiczny profil FLOQR, BOT DEE pokazuje zwarte karty w czacie: najpierw zdjęcie na pełną szerokość, potem imię i handle, potem zwarty SMARTsummary bez wypełnionego pola. Dotknij, aby otworzyć pełny SMARTview — ten sam układ. Karty używają tego samego profilu i SMARTsummary. Otwarcie nie wywołuje Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"Wpisz Ver, Vers lub Version — wielkość liter nie ma znaczenia. BOT DEE pokazuje kartę wersji. Dłuższe pytanie, na przykład „jaka jest twoja wersja?”, też pokazuje tę kartę."},"help-botdee-version-smartview-status":{"title":"Status Version SMARTview to żywa sonda","body":"Status usługi jest sondowany przy tym żądaniu Version: Functions i pakiet osiągalne z skonfigurowanym Gemini → Działa; Functions i pakiet ok, ale Gemini nieskonfigurowane → Ograniczone; Functions poza tym żądaniem → Niedostępne. Nigdy statyczna etykieta Nie sprawdzono. Model AI pokazuje skonfigurowane id Gemini tego wdrożenia nawet gdy ta tura nie generowała. Stemple frontendu i backendu mogą się różnić; oba są opisane. Master Admin może zobaczyć dodatkową diagnostykę w Szczegółach technicznych — patroni nie."},"help-botdee-version-smartview-tabs":{"title":"Karty Version SMARTview","body":"Przegląd opisuje BOT DEE i otwiera Szczegóły techniczne bez opuszczania czatu. Nowości wypisuje tylko zweryfikowane zmiany BOT DEE i Gemini — nie Master Admin, narzędzia beta testerów ani inne notatki produktów FLOQR. Pomoc powtarza polecenie Ver / Vers / Version. Zmiana karty lub rozwinięcie zostawia niewysłany szkic i przewijanie. Karta używa Twojego Site Chrome — nie ma drugiego motywu."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"W czacie BOT DEE powiedz Open Room SMARTview, Start a group chat albo zaplanuj wyjazd do Cancun zwykłymi słowami. Potem: Dołącz teraz lub Ustaw harmonogram. Dołącz teraz otwiera sesję znajomych Mingl od razu i nie kładzie karty na Search. Ustaw harmonogram to start room BOT DEE — nie Shared Itinerary — i włącza Search SMARTnotification dla Ciebie i zaproszonych znajomych Mingl. Zaproś tylko znajomych Mingl — host plus 7 gości. Goście też mogą zapraszać. Dołączenie to nie płatność i nie otwiera wspólnego rachunku. BOT DEE nigdy nie bierze numerów kart. Prywatne wiadomości BOT DEE zostają prywatne. Site Chrome idzie za Appearance. Live room zostaje otwarty do End Room, około czterech godzin po otwarciu, albo gdy wszyscy nieobecni są około 15 minut. Pauza prywatnego czatu BOT DEE jest osobna."},"help-botdee-room-smartview-invite":{"title":"Zaproś znajomych Mingl","body":"Po Confirm (Join Now lub Set a schedule) Invite pokazuje tylko Twoich znajomych Mingl. Dotknij znajomego albo wpisz Invite lorna — Inbox dostaje Review BOT DEE invite. Chip zostaje szary z Invite sent — drugie stuknięcie nie wysyła drugiego zaproszenia. To polecenie Room SMARTview, nie VIP reserV i nie People SMARTview Invite. To nie jest publiczny link. Limit: gospodarz plus 7. Goście mogą zapraszać więcej znajomych Mingl, dopóki gospodarz tego nie wyłączy. Dołączenie nie jest płatnością. Jeśli chip to ty albo ktoś już w sesji, zostaje To ty albo Już w tej sesji i nie wysyła drugiego zaproszenia."},"help-botdee-room-smartview-join":{"title":"Dołącz do sesji BOT DEE","body":"Otwórz zaproszenie Inbox lub Search Join Now zalogowany jako znajomy Mingl, do którego je wysłano. Join Now otwiera BOT DEE, nie Mingl chat. Ty i zaproszeni znajomi Mingl dzielicie czat grupowy Room SMARTview; imiona widzą członkowie. Złe konto, wygaśnięcie lub odwołanie odmawia. Dołączenie do room to nie dołączenie do rachunku ani zgoda na płatność. BOT DEE nigdy nie bierze numerów kart."},"help-botdee-room-smartview-end":{"title":"Zakończ Room SMARTview","body":"Tylko host może zakończyć room. Zakończenie nikogo nie obciąża i nie kasuje prywatnych czatów innych. Nieopłacony wspólny rachunek trzeba najpierw zapłacić lub unieważnić. Live room zostaje otwarty do End Room, około czterech godzin po otwarciu, albo gdy wszyscy nieobecni są około 15 minut. Pauza prywatnego czatu BOT DEE to nie wylogowanie z room. Gość, który wychodzi, nie zamyka room, gdy host jest obecny."},"help-botdee-room-smartview-tab":{"title":"Wspólny rachunek Room SMARTview","body":"Najpierw opt-in. Potem dodaj pozycję. Zamknij jednym płatnikiem lub podziel. Obciążani są tylko potwierdzający uid przez FloqR Stripe. Dołączenie do room to nie dołączenie do rachunku. BOT DEE nigdy nie bierze numerów kart. Club POS później."},"help-botdee-room-smartview-who-pays":{"title":"Kto płaci","body":"Zapytaj Who’s paying w Room SMARTview, by zobaczyć opt-in. Nikt nie jest obciążany, bo ktoś powiedział buy. Ostatnie cztery karty zostają na paragonie płatnika."},"help-botdee-room-smartview-kick":{"title":"Usuń kogoś z Room SMARTview","body":"Tylko gospodarz może usunąć gościa. Usunięty znajomy nie czyta dalszych wiadomości room. Odpowiedź modelu nikogo nie wyrzuca."},"help-botdee-room-smartview-share":{"title":"Udostępnij w Room SMARTview","body":"Share this conversation nigdy nie kopiuje Twojego prywatnego wątku BOT DEE. BOT DEE pokazuje podgląd wybranych faktów z tej wiadomości, oznaczonych jako wstępne. Możesz edytować lub odrzucić fakty. Profile i SMARTsummary zostają poza room."},"help-botdee-room-smartview-schedule":{"title":"Dołącz teraz lub ustaw harmonogram","body":"Po konfiguracji Room SMARTview wybierz Dołącz teraz lub Ustaw harmonogram. Dołącz teraz otwiera sesję BOT DEE od razu i nie kładzie karty na Search. Ustaw harmonogram to start room BOT DEE — nie Shared Itinerary. Przyszła godzina włącza Search SMARTnotification tylko dla Ciebie i zaproszonych znajomych Mingl. Goście RSVP, aż room będzie na żywo; potem Join Now otwiera BOT DEE (nie Mingl chat)."},"help-botdee-room-collab":{"title":"Udostępnij rezerwację headless w Room SMARTview","body":"W Room SMARTview wybory VIP reserV lub ShoutOut gospodarza widzą wszyscy. Członkowie głosują Tak lub Nie. Hold it i płatność zostają u gospodarza — dołączenie i głos to nie płatność. BOT DEE nigdy nie bierze numerów kart. Stripe otwiera się w pop-out."},"help-botdee-room-elect-host":{"title":"Wybierz gospodarza Room SMARTview","body":"Każdy w sesji może być gospodarzem. Nominuj siebie lub innego członka. Kandydat zostaje gospodarzem przy 60% aktualnych członków (zaokrąglenie w górę). Jeśli gospodarz wyjdzie, pozostali wybierają nowego — room zostaje otwarty. Kick i End zostają u wybranego gospodarza."},"help-botdee-smartview-review":{"title":"Przejrzyj i popraw SMARTsummary","body":"Gemini szkicuje tylko z publicznych pól FLOQR — nie przy każdym otwarciu. Błędny fakt: ukryj pole lub edytuj podsumowanie. Twój tekst nie jest nadpisywany. Konflikt profilu prosi o przegląd. Zgłoś błędną kartę z nakładki."},"help-botdee-smartview-chrome":{"title":"SMARTview i Site Chrome","body":"People SMARTview używa Site Chrome FLOQR oglądającego (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Nie ma drugiego motywu. Zmiana chrome odświeża kartę bez utraty szkicu czatu."},"help-botdee-smartview-categories":{"title":"Kategorie SMARTview","body":"Cztery karty: Społeczność, Randki, Jedzenie, Przyszłe podróże. Społeczność otwiera się na Muzyce, potem Nightlife, Sport, Wydarzenia. Tagi to tylko to, co udostępniłeś — bez podwójnych nagłówków i wymyślonych podróży."},"help-botdee-smartview-media":{"title":"Zdjęcia i filmy SMARTview","body":"Zwarta karta używa tego samego zdjęcia głównego co publiczna strona FLOQR — pierwszy element Profile Media (8 zdjęć + 2 filmy). Dotknij Zdjęcia i Filmy z tych publicznych slotów. Przesuń lub strzałki, potem X (lub Escape) wraca do tego samego czatu i szkicu."},"help-botdee-smartview-privacy":{"title":"Prywatność SMARTview","body":"SMARTview pokazuje tylko pola już publiczne w FLOQR. To nie wyszukiwarka sieci. Randki tylko po opt-in. Ukryj pole w profilu — zniknie. Zablokowani nie widzą karty. Zgłoś błędne podsumowanie z nakładki."},"help-botdee-smartview-translation":{"title":"Tłumaczenie SMARTview","body":"Twój SMARTsummary jest zapisany w domyślnym języku profilu — to źródło, nawet gdy to nie angielski. Po zapisie FLOQR kolejuje tłumaczenie na każdy inny język, w tym angielski. Angielski widz widzi angielski SMARTsummary po zakończeniu zadania. Gdy trwa lub zawiedzie, widać język źródłowy z etykietą — nigdy stare tłumaczenie jako aktualne."},"help-botdee-smartview-edit":{"title":"Edytuj SMARTsummary","body":"Tylko Ty edytujesz SMARTsummary w domyślnym języku profilu. Zapis jest natychmiastowy. Tłumaczenia idą w tle. Gemini nie nadpisuje Twojego tekstu. Gdy profil publiczny się zmieni, FLOQR prosi o przegląd zamiast zastępować."},"help-botdee-privacy-assistant":{"title":"Asystent prywatności BOT DEE","body":"W Mój profil zmień, co widzą inni użytkownicy FLOQR — BOT DEE nie dodaje drugiego przełącznika publicznego. Błędne powiązanie z sieci możesz zgłosić bez zmiany profilu. BOT DEE nie obiecuje usunięcia na stronie trzeciej."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"Każda rekomendacja może pokazać dowody, datę sprawdzenia, personalizację i sponsoring. Możesz poprosić BOT DEE, aby nie personalizował tego wyszukiwania."},"help-botdee-research-library":{"title":"Biblioteka badań BOT DEE","body":"Zapisuj miejsca i karty, o które pytałeś BOT DEE. Google Place ID to nie kopia zdjęć ani recenzji. Możesz odświeżyć lub usunąć. Licencjonowane cache zostaje wyłączone, dopóki dostawca nie zostanie zatwierdzony."},"help-botdee-smartview":{"title":"Zobacz mój SMARTview","body":"Zobacz mój SMARTview pokazuje Twoją kartę osoby z publicznych pól FLOQR, z tymi samymi Profile Media co strona publiczna — nie mocki klubów ani restauracji. Edytuj mój SMART Summary zmienia streszczenie w języku profilu. Mocki klubów/restauracji są w Master Admin → Features → BOT DEE → SMARTviews. Brak żywego Places ani Yelp."},"help-botdee-memory":{"title":"Zapisane czaty BOT DEE","body":"Otwórz Funkcje i zamówienia → Mój BOT DEE, aby zapisywać czaty po pauzie, eksportować lub usuwać historię. Pięciominutowa pauza kończy sesję na żywo. Po zgodzie BOT DEE zachowuje czat. Goście nie są zapisywani. Mingl zostaje w Mingl."},"help-botdee-knows-of-me":{"title":"Co BOT DEE wie o mnie","body":"Fakty zapisane za zgodą są w Funkcje i zamówienia → Mój BOT DEE. Lista jest pusta, gdy pamięć jest wyłączona lub brak danych. Eksport lub usuń tutaj. BOT DEE nie zapisuje IP. Mingl nie jest kopiowany."},"help-search-settings-appearance":{"title":"Settings na Search","body":"Na ekranie Search stuknij Settings, aby otworzyć Profile & Settings na karcie Appearance — tam jest Site chrome (Nightlife, Traditional, Black Tiffany, White/Black, Purple & White, Black & Dark Green). Kafelek Settings używa tego samego pakietu ikon chrome co inne znaki Search."},"help-club-website-feed":{"title":"Kanał dla strony klubu","body":"Pokaż opublikowaną stronę klubu FLOQR na własnej stronie. Naciśnij „Utwórz klucz i linki”, a potem wklej kod iframe na stronę albo przekaż webmasterowi link JSON lub RSS. Kanał pokazuje nadchodzące wydarzenia, wyróżnionych DJ-ów i personel, galerię oraz dane kontaktowe zgodnie z ustawieniami strony publicznej. Zdjęcia personelu pojawiają się tylko po potwierdzeniu zgody na zdjęcia. Nowy klucz wyłącza stare linki, także linki do grafiku personelu."},"help-featured-staff":{"title":"Wyróżniony personel","body":"Zaznacz pracowników, którzy mają być na publicznej stronie klubu. Dla każdej osoby dotknij jednego z jej zdjęć w FLOQR lub wybierz „Prześlij z komputera”. Możesz zmienić rolę pod imieniem. Naciśnij „Save Public Profile”, aby opublikować. Przed opublikowaniem zdjęć uzyskaj zgodę każdej osoby i zaznacz pole zgody na zdjęcia."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"FloqR Inbox przechowuje System Messages i wewnętrzne wiadomości wsparcia. Lista ładuje się najpierw, aby wiadomości pojawiały się szybko. Dotknij pływającego przycisku New Message, aby napisać — wpisz imię lub @username, by znaleźć dozwolonego odbiorcę (Club Admin, CSR lub zatwierdzony personel). Czat patron-do-patron zostaje w Mingl po wzajemnym Mingl. Otwarcie zaproszenia na zmianę nie potwierdza — przejrzyj i Approve selected w Work Calendar."},"botdee-ask-floqr":{"title":"Zapytaj FloqR z BOT DEE","body":"Zapytaj FloqR z BOT DEE — stuknij animowaną ikonę lub poczekaj na komunikat, a następnie wpisz, czego chcesz w zwykłych słowach. Produkty: Mingl, RydR, BartR, ShoutOut, FloqCAST (supergwiazda), kluby. Cele: powiedz „Chcę być w stanie…” (np. zostać Club Admin) lub „make me a superstar” po kroki i linki."},"help-vip-book-table":{"title":"Zarezerwuj stolik VIP (VIP reserV)","body":"VIP reserV pokazuje mapę i rezerwuje stoliki. Otwórz VIP reserV z Wyszukiwania, wybierz Decades lub Lima Twist Club i wieczór, stuknij zielony stolik, blokuj 30 min, zaakceptuj warunki i zapłać depozyt FloqR Stripe. Bary i DJ nie do rezerwacji. W Aurelii użyj Explore 3D walk-through dla interaktywnej sali (rezerwacja zostaje na mapie 2D)."},"help-vip-choose-venue":{"title":"Wybierz lokal VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. Decades, Lima Twist Club i Aurelia mają opublikowany plan 2D; Aurelia oferuje też Explore 3D walk-through."},"help-become-club-admin":{"title":"Zostań Club Admin","body":"Poproś o dostęp do Club Admin, a następnie uzyskaj zatwierdzenie miejsca."},"help-role-profiles":{"title":"Przegląd profili ról","body":"Zobacz, jak działają role Club Admin, DJ, Promoter i gościnne."},"help-staff-scheduling":{"title":"Kalendarz i Harmonogram","body":"Kalendarz Club Admin pokazuje Wersje robocze (fioletowe), Oczekujące (bursztynowe), Potwierdzone (zielone) i Otwarte/niewypełnione karty — każda z pisanym statusie, nie tylko kolorem. Harmonogram to siatka osób × dni dla wersji roboczej/publikacji. Website ingest / publicVenueCalendar pokazuje tylko potwierdzone zadania. Zielona etykieta Opłacone w tym miesiącu jest wyświetlana dla Club Admin, gdy staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"Subskrypcje powiadomień Klubowe dla SMS i WhatsApp","body":"Club Admin → Powiadomienia: Send test alert używa obecnie zaznaczonych pól. W aplikacji (i Push) zapisuje wiadomość systemową w FloqR Inbox. E-mail używa adresów administratora klubu. SMS i WhatsApp nadal wymagają płatnej subskrypcji oraz telefonu ostrzegawczego E.164. Zielona tabletka = Firebase subskrypcja 1 (przedpłacony pakiet $10); czerwona = 0. Jeśli Send test alert zwraca Authentication Error - invalid username, sekret Firebase TWILIO_ACCOUNT_SID musi być SID konta zaczynającym się od AC (34 znaki) z console.twilio.com — nie Token uwierzytelniający i nie Klucz API (SK)."},"help-club-sms-notification":{"title":"SMS subskrypcja powiadomień","body":"Tabletka SMS jest zielona, gdy Firebase smsSubscribed wynosi 1 (przedpłacony pakiet $10, 466 kredytów, nie miesięczny ani roczny). Czerwona/migająca oznacza 0 — otwórz ? i stuknij Subscribe $10. Pozostałe kredyty i data ostatniej płatności są w tej pomocy. Odznacz SMS i Zapisz, aby wstrzymać alerty bez utraty opłaconego pakietu."},"help-club-whatsapp-notification":{"title":"WhatsApp subskrypcja powiadomień","body":"Pigułka WhatsApp jest zielona, gdy Firebase whatsappSubscribed wynosi 1 (przedpłacony pakiet $10, 233 kredyty, nie miesięczny ani roczny). Czerwona/migająca oznacza 0 — otwórz ? i stuknij Subscribe $10. Pozostałe kredyty i ostatnia data płatności znajdują się w tej pomocy. Odznacz WhatsApp i Zapisz, aby wstrzymać alerty bez utraty opłaconego pakietu."},"help-schedule-message-templates":{"title":"Szablony wiadomości w harmonogramie","body":"Club Admin → Powiadomienia → Message templates. Są to Wiadomości systemowe (Inbox / Email / SMS / WhatsApp), nie ShoutOut. Edytuj tytuł i treść dla New shift needs confirmation, Aktualizacja harmonogramu, Potwierdzono zmianę i Odrzucono zmianę. Pola zastępcze: {club} {role} {when} {link} {worker}. Skrzynka odbiorcza pracownika używa Review & confirm shift — nigdy Open Related ShoutOut."},"help-schedule-confirm":{"title":"Potwierdź przypisane zmiany","body":"Inbox / Email / linki SMS otwierają Work Calendar. Sprawdź każde oczekujące przypisanie, zaznacz je (lub Select all), a następnie Approve selected. Otwarcie linku nie oznacza potwierdzenia. Tylko przypisany członek służby może zatwierdzić — Club Admin nie może potwierdzić w jego imieniu."},"help-template-catalog-report":{"title":"Raport katalogu szablonów","body":"Wymienia każdy typ szablonu ShoutOut i jakie rozmiary LED obsługuje (Is96x48, Is64x48, Is64x32). Miejsce oferuje szablon tylko wtedy, gdy przynajmniej jeden z tych wskaźników wynosi 1, a odpowiadający mu wskaźnik VenueSupports* jest również równy 1. Szablony urodzinowe / z podziałem mediów są 1 na 96×48, 64×48 i 64×32. 96×48 to 3-liniowy obok siebie; 64×48 i 64×32 pokazują w pętli zdjęcie, a następnie 3-liniowy shoutout z kartą FLOQR + handle."},"help-club-display-screens":{"title":"FLOQR ekrany wyświetlaczy","body":"Firebase clubLocations przechowuje VenueSupports96x48, VenueSupports64x48 i VenueSupports64x32 jako 0 lub 1. Szablony przechowują Is96x48, Is64x48 i Is64x32 w ten sam sposób. Miejsce wyświetla szablon tylko wtedy, gdy przynajmniej jedna para wynosi 1. Adresy URL Xibo pozostają display.html?location=id i display2.html?location=id — rozmiar ekranu nie jest w URL. Urodziny są oferowane we wszystkich trzech rozmiarach (3-liniowy obok siebie na 96×48; pętla zdjęcie/shoutout na 64×48 i 64×32). Główny to display.html. Drugorzędny to display2.html."},"help-staff-week-calendar":{"title":"Harmonogram","body":"Club Admin Harmonogram to siatka osób × dni tygodnia. Save shift zamyka edytor z Schedule card successfully saved. Twórz szkice, Publish schedule aby pracownicy potwierdzili oczekujące na potwierdzenie, Select shifts do wielokrotnego usuwania oraz Website ingest do publikowania harmonogramu zmian na stronie klubu. Domyślne okno zmian = otwarcie klubu − 2 godziny do zamknięcia + 1 godzina."},"help-staff-schedule-user-guide":{"title":"Przewodnik użytkownika do harmonogramu personelu","body":"Otwórz ? obok Harmonogramu na Club Admin Harmonogramowanie. Twórz szkice zmian, Publish schedule aby pracownicy potwierdzili oczekujące→potwierdzone, następnie Select shifts aby usunąć kilka naraz. Przykład: wszystkie środowe szkice oraz potwierdzona zmianę z czwartku."},"help-create-publish-schedule":{"title":"Tworzenie i publikowanie harmonogramu pracy personelu","body":"Dodaj robocze zmiany na siatce osoby × dni, przejrzyj chipy, potem Publish schedule. Pracownicy muszą potwierdzić, zanim zmiana zostanie potwierdzona. BOT DEE: create a schedule, publish schedule, how to schedule staff."},"help-multi-delete-shifts":{"title":"Usuń wiele zaplanowanych lub roboczych zmian","body":"Select shifts, połącz nagłówki dni i chipy, potem Delete selected. Przykład: wszystkie robocze zmiany w środę plus jedna potwierdzona zmiana w czwartek."},"help-staff-worksheet":{"title":"Arkusz pracy - Tygodniowy kalendarz personelu","body":"Wybrani członkowie służby otwierają Work Calendar w Ustawieniach. Inbox / Email / SMS linki potwierdzające trafiają tutaj. Przejrzyj oczekujące zadania, zaznacz każdą zmianę (lub Select all), potem Approve selected — otwarcie wiadomości nie oznacza potwierdzenia. Siatka tygodnia pokazuje opublikowane zmiany współpracowników. Robocze pozostają w Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"Wszyscy zaczynają jako patron FLOQR. W My Profile & Settings naciśnij Elect to become a service member, wybierz rolę i kluby, wyślij na dole strony.\n\nPrzewodnik po szablonach profilu — profile społeczne patron pozostają w Mediach publicznych.\n\nZatwierdzenie Club Admin — Club Admin → Employee/Workers → Pending Worker Requests lub Przegląd i wybór na tej karcie."},"help-venue-website-ingest":{"title":"Import strony klubu (API, RSS, iframe)","body":"Club Admin → Harmonogram → Website ingest. Wygeneruj sekret (pokazany raz; przechowywany jest tylko hash). Pobierz opublikowane zmiany pracowników na oficjalną stronę klubu za pomocą JSON (?format=json&dataset=schedule|hours|profile|all), RSS lub fragmentu iframe. Szkice, e-mail pracownika i telefon nigdy nie są uwzględniane. Zmień sekret, jeśli wycieknie."},"help-venue-hours-calendar":{"title":"Godziny otwarcia lokalu","body":"Na profilu publicznym klubu ustaw domyślne godziny otwarcia/zamknięcia w tygodniu, a następnie dodaj nadpisania okresowe dla specjalnych tygodni, nie tracąc wartości domyślnych. Publiczna strona klubu pokazuje siatkę tygodnia od niedzieli do soboty z zakresem dat (np. Nied 9 – Sob 15, sierpnia 2026) i kolorowanie kalendarza. Nadchodzące święta publiczne uwzględniają godziny otwarcia/zamknięcia i wskazują, kiedy różnią się od zwykłego dnia roboczego. Harmonogram pracowników korzysta z czasu otwarcia − 2h do zamknięcia + 1h. Lista gości może sugerować nocne otwarcia."},"help-club-admin-affiliation":{"title":"Club Admin przypisanie lokalu","body":"Club Adminotwierza tylko Centrum Dowodzenia Miejsca dla klubu, do którego są przypisani. Otwarcie admin.html bez miejsca nie domyślnie ustawia już Zebbies. Konta demonstracyjne temp_clubadmin_N@floqr-demo.com mapują na temp-democlub-N. Nieprzypisani administratorzy proszą o przypisanie od Master Admin."},"help-venue-command-center":{"title":"Centrum dowodzenia obiektem","body":"Zatwierdź ShoutOuts, sprawdź wydajność atrakcji i uzgodnij aktywność na koncie dla tej lokalizacji."},"help-club-template-repository":{"title":"Szablony Twojego klubu","body":"Szablony stworzone tylko dla Twojego klubu są na początku listy, oznaczone „Na wyłączność w” z nazwą lokalu. Przypisane szablony to te, które goście mogą wybrać w Twoim klubie; zmienisz to przyciskami Przypisz szablon lub Usuń szablon. Wyszukiwarka znajdzie szablon nawet bez polskich znaków lub z drobną literówką."},"help-employee-network":{"title":"Sieć pracowników i personelu","body":"Widoczne są tylko osoby powiązane z tym klubem: personel wyznaczony lub zatwierdzony tutaj, administratorzy klubu i personel powiązany z tym klubem. Aby nadać komuś rolę, wpisz imię, nazwę użytkownika lub e-mail w polu Wyznacz gościa do roli, stuknij Wybierz obok właściwej osoby, wybierz rolę, potem stuknij Wyznacz wybranego gościa do roli i potwierdź. Ta osoba potrzebuje najpierw konta gościa FLOQR. Kelnerzy, kelnerki i bottle girls z listy mogą zostać przedstawicielami obsługi klienta (CSR)."},"help-template-tags":{"title":"Tagi szablonów","body":"Dodaj słowa, które goście mogą wpisać, szukając szablonu w Twoim lokalu, np. wieczór meczowy albo urodziny. Menedżerowie szablonów mogą dodawać tagi. Administratorzy szablonów i Club Admin mogą je też usuwać. Club Admin przydziela te role w sekcji Role Activity & Permission."},"help-display-idle-default":{"title":"Ekran oczekiwania: Use ShoutOut @ lokal","body":"Gdy nie leci żaden ShoutOut, Display 1 pokazuje „Use ShoutOut @” z nazwą Twojego lokalu. Każdy zatwierdzony ShoutOut trwa 10 minut, potem ekran sam wraca do tego komunikatu. Przywrócenie domyślnego ekranu w Club Admin robi to od razu."},"help-club-messaging-credit":{"title":"Kredyt SMS i WhatsApp","body":"Każdy pakiet $10 finansuje $7,00 pojemności Twilio; FloqR zatrzymuje $3,00 marży platformy. Pakiet SMS → 466 wiadomości (≈ $0,015 SMS US). Pakiet WhatsApp → 233 wiadomości (≈ $0,030 Twilio + Meta marketing). Przy saldzie 0 kup kolejny pakiet przed wysyłką. Ops SMS unlock ($10) obejmuje pakiet SMS. Usługa WhatsApp ($10) obejmuje pakiet WhatsApp. Rachunek: $10 → 466 SMS lub 233 WhatsApp ($7,00 Twilio / $3,00 FloqR)."},"help-club-marketing-campaigns":{"title":"Kampanie marketingowe","body":"Wybierz szablon branżowy, dodaj tło i dodatkowe obrazy, edytuj treść, zapisz lub wyślij. Wysyłka obciąża kredyt SMS lub WhatsApp w Kredyt wiadomości."},"help-club-in-app-marketing":{"title":"Marketing in-app","body":"Opublikuj ulotkę lub wideo do 30 sekund w imieniu klubu. Po opłaceniu i zatwierdzeniu przez FLOQR reklama pojawia się na ekranie ładowania wyszukiwania, w Mingl, RydR i na innych ekranach FLOQR. Publikujący reklamy klubu pozwala członkowi zespołu publikować reklamy dla klubu (rola Club Ad Poster). Kredyty SMS nie są potrzebne."},"help-vip-terms-consent":{"title":"Warunki VIP reserV","body":"Po zablokowaniu stolika otwórz stronę Warunków, przeczytaj i zaakceptuj raz (marketing opcjonalnie osobno). Zgoda jest zapisywana przed FloqR Stripe Checkout — jak płatny ShoutOut, potem paragon i pass."},"help-vip-door-pass":{"title":"Pass drzwi VIP reserV","body":"Po potwierdzeniu depozytu: Mój profil → Rezerwacje → Pokaż pass dla jednorazowego QR. Weź ID 21+. Personel używa VIP reserV Door."},"help-vip-door-ops":{"title":"Check-in drzwi VIP reserV","body":"VIP Managerowie otwierają VIP reserV Door na dziś. Zeskanuj lub wklej token, potwierdź ID 21+, check-in. No-show dopiero po grace. Link notify nie zmienia statusu."},"help-vip-payment-collector":{"title":"Kolektor płatności VIP reserV i Club POS","body":"Preferowane dla klubów live z Toast/SpotOn: Club POS — FLOQR rezerwuje/trzyma/mapę; POS obsługuje depozyt, rachunek i wydatki. Alternatywy: Club Stripe, FloqMedia Stripe (FloqR) lub silnik VIP + CSV. Aurelia (Demo Club) domyślnie FloqMedia Stripe — zapytaj BOT DEE o kroki Master i Club Admin."},"help-vip-table-isbooked":{"title":"Status isBooked stolików VIP w Firestore","body":"Każdy klub VIP ma dokument Firestore na numer stolika i noc: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. Id = drukowany numer (np. T1, B3). Po zakończeniu rezerwacji: isBooked \"1\", isBookedYes \"yes\". Wolne: \"0\" / \"no\". Hold nie ustawia isBooked. Anulowanie → \"0\". getVipAvailability używa isBooked jako statusu rezerwacji. Anulowanie zawsze ustawia isBooked na \"0\"; FloqMedia/Club Stripe może zwrócić depozyt wg polityki klubu."},"help-vip-floqr-stripe-aurelia":{"title":"Skonfiguruj FloqMedia Stripe dla Aurelia (Demo Club)","body":"Aurelia (temp-democlub-1) domyślnie używa FloqMedia Stripe (FloqR Checkout) jako kolektora depozytu VIP — patroni płacą na platformowym Stripe FloqR, potem stolik jest zarezerwowany.\n\nKroki Master Admin:\n1) Otwórz Master Admin → Features Mgmt → VIP reserV Payments.\n2) Potwierdź, że VIP Reservations jest włączone w sieci.\n3) Seed / refresh dostawców POS tylko gdy później użyjesz Club POS — niepotrzebne dla FloqMedia Stripe.\n4) Zostaw Aurelię na FloqMedia Stripe, chyba że Club POS lub Club Stripe.\n5) Po depozytach otwórz Network VIP billing.\n\nKroki Club Admin (Aurelia):\n1) Zaloguj się jako temp_clubadmin_1@floqr-demo.com (OTP e-mail na stronie głównej) lub Club Admin Aurelii.\n2) Club Admin → VIP reserV (location=temp-democlub-1).\n3) W Payment collector wybierz FloqMedia Stripe (FloqR).\n4) Zostaw Require deposit before table is marked booked.\n5) Zapisz Save payment collector.\n6) Test: vip.html?location=temp-democlub-1 → hold stolika → Warunki → Zapłać depozyt (karta testowa 4242…).\n7) Door / rozliczenia: Open Door; Refresh billing.\n\nNie wybieraj Club POS w demo Aurelii bez sandbox Toast/SpotOn. FloqMedia, Stripe, ShoutOut i VIP reserV pozostają markami."}},"ar":{"help-smartvisuals-notification":{"title":"SMARTnotification لـ Mingl Room","body":"يمكن أن تظهر دعوة Mingl Room مختصرة على Search عندما تضبط جدولاً لـ room BOT DEE أو يدعوك صديق Mingl. يرى المضيف room المجدولة على Search دون استعلام Cancun التجريبي. عرض الدعوة يفتح Room SMARTview. Join Now يذهب إلى BOT DEE وليس Mingl chat. ليس الآن يخفي البطاقة في هذا التبويب؛ يبقى Inbox فيه Review BOT DEE invite. استعلام Cancun التجريبي لـ Studio فقط. الرسم توضيح وليس صورة. غرف Join Now بلا جدول لا تظهر على Search."},"help-smartvisuals-room":{"title":"Room SMARTview مع SMARTvisuals","body":"يعرض Room SMARTview دعوة Mingl: الجدول وRSVP أو الحالة المباشرة وJoin Now. Join Now على Search يفتح BOT DEE (وليس Mingl chat) مع room= وt=. تتبع SMARTstencils وSMARTbackgrounds العنوان المصرّح — Cancun Trip فن سفر وليس صورة Cancun حقيقية. دردشة BOT DEE الخاصة لا تختار الرسم أبداً. إعلان موسوم أسفلها عيّنة من تلك الوسوم. يبقى فارغاً للدردشة الخاصة أو الحقن وليس معلناً مباشراً."},"help-scheduling-schedule-for":{"title":"جداول الموظفين","body":"خطّط المناوبات والحجوزات ثم أبلغ كل شخص عبر Inbox أو Email أو SMS أو WhatsApp. من «الجدول لـ» اختر التقويم الذي تعمل عليه: «جدولي كـ DJ» هو تقويمك الخاص، و«نادٍ» يعرض النوادي التي تديرها، و«شركة ترويج» يعرض الشركات التي تروّج لها. لكل تقويم اشتراكه الخاص بـ 20 دولارًا شهريًا. تظهر المناوبات المسندة إليك في «مهامي» حيث تؤكدها أو ترفضها."},"help-staff-marketing-consent":{"title":"موافقة الطاقم على التسويق","body":"عند انضمامك إلى فريق مكان أو فعالية، يجب أن تحدد مربع الموافقة على التسويق. تسمح هذه الموافقة لذلك المكان أو المنظّم ومسؤوليه ومديريه باستخدام اسمك على FLOQR ودورك وصورك ومقاطع الفيديو المنشورة على مواقعهم الإلكترونية ومنشوراتهم ووسائل التواصل الاجتماعي (Instagram وFacebook وTikTok وYouTube وما شابهها) دون أن يطلبوا إذنك مجددًا لكل استخدام. لا يجوز لهم نشر رقم هاتفك أو بريدك الإلكتروني. يمكنك سحب الموافقة في أي وقت من ملفي، علامة تبويب أعضاء الخدمات والخدمة. يوقف السحب التسويق الجديد، ولا يلزم استرجاع المواد المطبوعة أو المنشورة بالفعل. يرى Club Admins حالة موافقة كل فرد من الطاقم في شبكة الموظفين والعاملين وفي الطاقم المميز."},"help-botdee-privacy-session":{"title":"خصوصية وجلسة BOT DEE","body":"توقف الخمس دقائق ينهي جلسة BOT DEE المباشرة. لا يحذف هذه المحادثة للمستخدم المسجّل أو الذكريات أو مسارات العمل. تبقى النسخ الاختيارية في ملفي → الميزات والطلبات → My BOT DEE أيضًا. يبقى الضيوف مؤقتين. لا تُنسخ محادثات Mingl إلى هنا. Enter يرسل؛ Shift+Enter يبدأ سطرًا جديدًا. الاسم والأسلوب من ملفي → My BOT DEE، وليس زرًا في المحادثة."},"help-botdee-place-search":{"title":"اسأل BOT DEE عن أماكن FLOQR","body":"اسأل بكلمات بسيطة — مطاعم السوشي في Washington DC أو النوادي في DC أو نادٍ باسمه. يبحث BOT DEE فقط في أماكن FLOQR المسجّلة، وليس Google أو Yelp. النتائج تفتح Place SMARTview مضغوطًا (الاسم، نبذة قصيرة، التقييمات، رابط الصفحة العامة) مع SMARTbackground — وليس بئر صورة. ذكر مدينة مع VIP reserV (reservations in Miami) ما زال يُرفق Place SMARTview بجانب بطاقة VIP. صور الرواد وعروض ShoutOut لا تظهر إلا إذا طلبتها. إذا لم يُدرج المكان بعد، يقول BOT DEE ذلك."},"help-botdee-page":{"title":"BOT DEE","body":"تحدث مع BOT DEE في صفحة BOT DEE بكلمات بسيطة: الفعاليات والنوادي وShoutOut وMingl وRydR وBartR وFloqCAST وملفك الشخصي وجداول الطاقم وأدوات Club Admin. اضغط Enter للإرسال؛ Shift+Enter يبدأ سطرًا جديدًا. يتحدث BOT DEE كشخص (جرّب How are you?) ويبحث فقط عندما تسأل كيف تفعل شيئًا في FLOQR. إذا سجّلت الدخول، يحتفظ BOT DEE بهذه المحادثة عند التحديث أو على هاتف آخر وبعد التوقف يمكنه متابعة السجل المحفوظ. التوقف لا يحذف المحادثة. تستخدم الإجابات تصنيف حسابك. بعد تسجيل الدخول يرى BOT DEE نفس نقاط البيانات العامة المتطوع بها التي تراها (الموسيقى والطعام والسفر والهوايات وبقية Privacy datapoint sharing) — لا بريد إلكتروني ولا هاتف ولا بيانات بطاقة ولا GPS. اضغط الإعدادات تحت صندوق الدردشة للمحادثات والذكريات المحفوظة. اضغط على صورة في المحادثة لفتحها في نافذة. أغلق بـ X أو إغلاق للعودة إلى المحادثة. علامة + أعلى اليمين تفتح المحادثات المحفوظة ولا تحذفها."},"help-botdee-smartview-troubleshoot":{"title":"استكشاف أخطاء SMARTview","body":"بطاقة فارغة: الحقول مخفية أو أنت محظور. فشل الحفظ: سجّل الدخول — الترجمات على الخادم. انتظار أو فشل: لغة المصدر بوسم. التعديل للمالك فقط. SMARTviews في Master Admin ما زال كتالوج المحاكاة؛ Places وYelp متوقفان. السمة تتبع Site Chrome."},"help-botdee-smartcard-sync":{"title":"يبقى SMARTsummary متزامنًا","body":"عدّل SMARTsummary بلغة الملف الافتراضية. الحفظ فوري. البطاقات وSMARTview المفتوحة تتحدّث من نفس السجل. تُترجم اللغات الأخرى في الخلفية ولا تستبدل تعديلاً أحدث. إذا أخفيت الملف أو حظرت شخصًا أو حذفت الحساب تختفي البطاقات. لا يستبدل Gemini نصك."},"help-botdee-smartcard-search":{"title":"اسأل BOT DEE من هذا الشخص","body":"«Who am I?» يفتح SMARTview الخاص بك. «Who is …» أو «What do you know of …» أو «What about …» مع الاسم الأول أو الأخير أو الاسم المعروض أو معرّف Mingl أو FloqR أو معرّف اجتماعي (Instagram أو TikTok أو X). المطابقة على حقول الهوية فقط — وليس السيرة أو الإعجابات أو المشروبات أو الأنواع. نتيجة واحدة تفتح بطاقة People SMARTview في الدردشة — وليس قائمة markdown أو شبكة صور. عدة نتائج تعرض SMARTcard مدمجة. الملفات الخاصة أو المحظورة أو غير المنشورة لا تُعرض — BOT DEE لا يؤكد وجود الحساب."},"help-botdee-smartcard":{"title":"SMARTcard الأشخاص","body":"عندما يطابق أكثر من ملف FLOQR عام، يعرض BOT DEE بطاقات مضغوطة في الدردشة: الصورة بعرض كامل أولاً، ثم الاسم والمعرّف، ثم SMARTsummary مضغوط بلا صندوق مبطّن. اضغط لفتح SMARTview الكامل — نفس الترتيب. البطاقات تستخدم نفس الملف العام وSMARTsummary. الفتح لا يستدعي Gemini."},"help-botdee-version-smartview":{"title":"Version SMARTview","body":"اكتب Ver أو Vers أو Version — لا يهم حجم الأحرف. تعرض BOT DEE بطاقة الإصدار. سؤال أطول مثل «ما إصدارك؟» يعرض هذه البطاقة أيضًا."},"help-botdee-version-smartview-status":{"title":"حالة Version SMARTview فحص حي","body":"تُفحص حالة الخدمة في طلب Version هذا: Functions والحزمة قابلان للوصول وGemini مضبوط → تشغيلي؛ Functions والحزمة جاهزان لكن Gemini غير مضبوط → متدهور؛ Functions ليست في هذا الطلب → غير متاح. ليست أبداً تسمية ثابتة «لم يُتحقق». يعرض نموذج الذكاء الاصطناعي معرّف Gemini المضبوط لهذا النشر حتى إن لم يولّد هذا الدور. يمكن أن يختلف ختم الواجهة عن الخلفية؛ كلاهما مُسمّى. قد يرى Master Admin تشخيصاً إضافياً تحت التفاصيل التقنية — الضيوف لا."},"help-botdee-version-smartview-tabs":{"title":"علامات Version SMARTview","body":"نظرة عامة تصف BOT DEE وتفتح التفاصيل التقنية دون مغادرة الدردشة. ما الجديد يعرض تغييرات BOT DEE وGemini الموثّقة فقط — وليس Master Admin أو أدوات مختبري بيتا أو ملاحظات منتجات FLOQR الأخرى. المساعدة تكرر أمر Ver / Vers / Version. تبديل العلامات أو توسيع التفاصيل يبقي المسودة غير المُرسلة والتمرير. البطاقة تستخدم Site Chrome لديك — لا يوجد مظهر ثانٍ."},"help-botdee-room-smartview":{"title":"Room SMARTview","body":"في دردشة BOT DEE قل Open Room SMARTview أو Start a group chat أو خطط لرحلة Cancun بكلام بسيط. بعد ذلك: انضم الآن أو تعيين جدول. انضم الآن يفتح جلسة أصدقاء Mingl فوراً ولا يضع بطاقة على Search. تعيين جدول هو وقت بدء room BOT DEE — وليس Shared Itinerary — ويفعّل SMARTnotification في Search لك ولأصدقاء Mingl المدعوين. ادعُ أصدقاء Mingl فقط — مضيف زائد 7 ضيوف. يمكن للضيوف الدعوة أيضاً. الانضمام ليس دفعاً ولا يفتح فاتورة مشتركة. BOT DEE لا يأخذ أرقام بطاقات أبداً. رسائل BOT DEE الخاصة تبقى خاصة. يتبع Site Chrome مظهر Appearance. تبقى الـ room المباشرة مفتوحة حتى End Room، أو نحو أربع ساعات بعد فتحها، أو إذا غاب الجميع نحو 15 دقيقة. إيقاف دردشة BOT DEE الخاصة أمر منفصل."},"help-botdee-room-smartview-invite":{"title":"دعوة أصدقاء Mingl","body":"بعد Confirm (Join Now أو Set a schedule) يعرض Invite أصدقاء Mingl فقط. اضغط صديقاً أو اكتب Invite lorna — يصل Inbox كـ Review BOT DEE invite. تبقى الشريحة رمادية مع Invite sent — الضغط مرة أخرى لا يرسل دعوة ثانية. هذا أمر Room SMARTview وليس VIP reserV ولا People SMARTview Invite. ليست رابط انضمام عاماً. الحد المضيف مع 7. يمكن للضيوف دعوة مزيد من أصدقاء Mingl ما لم يوقف المضيف ذلك. الانضمام ليس دفعاً. إذا كانت الشريحة أنت أو شخصاً موجوداً في الجلسة تُعلَّم هذا أنت أو موجود في هذه الجلسة ولا تُرسل دعوة ثانية."},"help-botdee-room-smartview-join":{"title":"الانضمام إلى جلسة BOT DEE","body":"افتح دعوة Inbox أو Search Join Now وأنت مسجّل كصديق Mingl المُرسَل إليه. Join Now يفتح BOT DEE وليس Mingl chat. أنت وأصدقاء Mingl المدعوون تتشاركون دردشة مجموعة Room SMARTview؛ تظهر الأسماء للأعضاء. الحساب الخطأ أو المنتهية أو الملغاة تُرفض. الانضمام إلى room ليس انضماماً إلى حساب مشترك ولا موافقة على دفع. BOT DEE لا يأخذ أرقام البطاقات أبداً."},"help-botdee-room-smartview-end":{"title":"إنهاء Room SMARTview","body":"المضيف وحده يمكنه إنهاء room. الإنهاء لا يحصّل أحداً ولا يمسح دردشات الآخرين الخاصة. يجب دفع الفاتورة المشتركة غير المدفوعة أو إلغاؤها أولاً. تبقى الـ room المباشرة مفتوحة حتى End Room، أو نحو أربع ساعات بعد فتحها، أو إذا غاب الجميع نحو 15 دقيقة. إيقاف دردشة BOT DEE الخاصة ليس خروجاً من الـ room. مغادرة ضيف لا تنهي الـ room ما دام المضيف موجوداً."},"help-botdee-room-smartview-tab":{"title":"الحساب المشترك Room SMARTview","body":"أولاً الموافقة. ثم أضف بنداً. أغلق بدافع واحد أو مقسّم. يُخصم فقط من الحسابات المؤكِّدة عبر FloqR Stripe. الانضمام إلى room ليس انضماماً إلى الحساب. BOT DEE لا يأخذ أرقام البطاقات أبداً. Club POS لاحقاً."},"help-botdee-room-smartview-who-pays":{"title":"من يدفع","body":"اسأل Who’s paying في Room SMARTview لرؤية حالة الموافقة. لا يُخصم أحد لأن شخصاً قال buy. آخر أربعة أرقام تبقى على إيصال الدافع."},"help-botdee-room-smartview-kick":{"title":"إزالة شخص من Room SMARTview","body":"المضيف فقط يخرج ضيفاً. الصديق المُزال لا يقرأ رسائل الـ room بعدها. رد النموذج لا يطرد أحداً."},"help-botdee-room-smartview-share":{"title":"المشاركة في Room SMARTview","body":"Share this conversation لا ينسخ محادثتك الخاصة في BOT DEE أبداً. يعرض BOT DEE معاينة حقائق قابلة للمشاركة من هذه الرسالة، معلَّمة مؤقتة. يمكنك تعديل الحقائق أو حذفها. الملفات الشخصية وSMARTsummary تبقى خارج الـ room."},"help-botdee-room-smartview-schedule":{"title":"انضم الآن أو عيّن جدولاً","body":"بعد إعداد Room SMARTview اختر انضم الآن أو تعيين جدول. انضم الآن يفتح جلسة BOT DEE فوراً ولا يضع بطاقة على Search. تعيين جدول هو وقت بدء room BOT DEE — وليس Shared Itinerary. وقت مستقبلي يفعّل SMARTnotification في Search لك ولأصدقاء Mingl المدعوين فقط. الضيوف يؤكدون RSVP حتى تصبح الـ room مباشرة؛ ثم Join Now يفتح BOT DEE (وليس Mingl chat)."},"help-botdee-room-collab":{"title":"مشاركة حجز headless في Room SMARTview","body":"في Room SMARTview تظهر اختيارات المضيف لـ VIP reserV أو ShoutOut للجميع. يصوّت الأعضاء بنعم أو لا. يبقى Hold it والدفع لدى المضيف — الانضمام والتصويت ليسا دفعًا. BOT DEE لا يأخذ أرقام بطاقات أبدًا. يفتح Stripe في نافذة منبثقة."},"help-botdee-room-elect-host":{"title":"انتخاب مضيف Room SMARTview","body":"أي شخص في الجلسة يمكن أن يكون مضيفًا. رشّح نفسك أو عضوًا آخر. يصبح المرشح مضيفًا عند 60٪ من الأعضاء الحاليين (تقريب لأعلى). إذا غادر المضيف، ينتخب الباقون مضيفًا جديدًا — تبقى الغرفة مفتوحة. يبقى Kick و End لدى المضيف المنتخب."},"help-botdee-smartview-review":{"title":"مراجعة وتصحيح SMARTsummary","body":"يصوغ Gemini من حقول FLOQR العامة فقط — ليس عند كل عرض. إن كان واقعًا خاطئًا أخفِ الحقل أو عدّل الملخص. لا يُستبدل نصك. تعارض الملف يطلب مراجعة. بلّغ عن بطاقة خاطئة من الطبقة."},"help-botdee-smartview-chrome":{"title":"SMARTview وSite Chrome","body":"يستخدم People SMARTview Site Chrome الحالي للمشاهد (Nightlife وTraditional وBlack Tiffany وWhite/Black وPurple & White وBlack & Dark Green). لا إعداد سمة ثانٍ. تغيير الكروم يحدّث البطاقة دون فقدان مسودة الدردشة."},"help-botdee-smartview-categories":{"title":"فئات SMARTview","body":"أربع علامات: اجتماعي، مواعدة، طعام، رحلات قادمة. الاجتماعي يفتح على الموسيقى ثم Nightlife والرياضة والفعاليات. الوسوم فقط ما شاركته — بلا عناوين مكررة أو رحلات أو تقييمات مخترعة. الرحلات القادمة للوجهات العامة فقط."},"help-botdee-smartview-media":{"title":"صور وفيديو SMARTview","body":"تستخدم البطاقة نفس الصورة الرئيسية لصفحة FLOQR العامة — أول عنصر في وسائط الملف (8 صور + فيديوهان). اضغط للصور والفيديو من تلك الخانات العامة. اسحب أو الأسهم، ثم X (أو Escape) للعودة لنفس الدردشة والمسودة."},"help-botdee-smartview-privacy":{"title":"خصوصية SMARTview","body":"يعرض SMARTview فقط الحقول التي جعلتها عامة داخل FLOQR. ليس بحثًا على الويب. المواعدة تظهر بموافقة صريحة فقط. إخفاء حقل في ملفي يزيله. المحظورون لا يرون البطاقة. بلّغ عن ملخص خاطئ من الطبقة."},"help-botdee-smartview-translation":{"title":"ترجمة SMARTview","body":"يُحفظ SMARTsummary بلغة الملف الافتراضية — تلك هي المصدر حتى إن لم تكن الإنجليزية. بعد الحفظ يضع FLOQR ترجمة لكل لغة أخرى في الانتظار، بما فيها الإنجليزية. يرى المشاهد الإنجليزي SMARTsummary بالإنجليزية عند اكتمال المهمة. أثناء الانتظار أو الفشل تُعرض لغة المصدر بوسم واضح — لا ترجمة قديمة كأنها الحالية."},"help-botdee-smartview-edit":{"title":"تعديل SMARTsummary","body":"أنت وحدك تعدّل SMARTsummary بلغة الملف الافتراضية. الحفظ فوري. تُترجم اللغات الأخرى في الخلفية. لا يستبدل Gemini نصك. إذا تغيّر الملف العام، يطلب FLOQR المراجعة بدل الاستبدال."},"help-botdee-privacy-assistant":{"title":"مساعد خصوصية BOT DEE","body":"غيّر في ملفي ما يراه مستخدمو FLOQR الآخرون — لا يضيف BOT DEE مفتاحًا عامًا ثانيًا. إذا ربط البحث شخصًا خطأ، يمكنك الاعتراض دون تغيير ملفك. لا يعد BOT DEE بحذف الصفحة الأصلية لدى طرف ثالث."},"help-botdee-explain":{"title":"Explain My Recommendation","body":"يمكن لكل توصية إظهار الأدلة وتاريخ الفحص وما إذا كان التخصيص قيد التشغيل وما إذا كان الموضع مدعومًا. يمكنك أن تطلب من BOT DEE عدم تخصيص هذا البحث."},"help-botdee-research-library":{"title":"مكتبة بحث BOT DEE","body":"احفظ الأماكن والبطاقات التي سألت BOT DEE عنها. معرّف Google Place ليس نسخة من صور أو مراجعات Google. يمكنك التحديث أو الحذف. تبقى ذاكرة التخزين المرخّصة متوقفة حتى اعتماد المزود."},"help-botdee-smartview":{"title":"عرض SMARTview الخاص بي","body":"عرض SMARTview يظهر بطاقة الشخص من الحقول العامة في FLOQR، مع نفس وسائط الملف العام — وليست نماذج نوادٍ أو مطاعم. تعديل SMART Summary يغيّر الملخص بلغة الملف. نماذج النوادي/المطاعم في Master Admin → Features → BOT DEE → SMARTviews. لا Places أو Yelp مباشر."},"help-botdee-memory":{"title":"محادثات BOT DEE المحفوظة","body":"افتح الميزات والطلبات → BOT DEE الخاص بي لحفظ المحادثات بعد التوقف أو التصدير أو الحذف. توقف الخمس دقائق ينهي الجلسة المباشرة. إذا وافقت، يحتفظ BOT DEE بالمحادثة. لا يُحفظ الضيوف. يبقى Mingl في Mingl."},"help-botdee-knows-of-me":{"title":"ما يعرفه BOT DEE عني","body":"الحقائق المحفوظة بموافقتك في الميزات والطلبات → BOT DEE الخاص بي. القائمة فارغة إذا كانت الذاكرة مغلقة أو لا توجد بيانات. صدّر أو احذف هنا. لا يخزّن BOT DEE عنوان IP. لا يُنسخ Mingl."},"help-search-settings-appearance":{"title":"Settings في Search","body":"في شاشة Search، اضغط Settings لفتح Profile & Settings على تبويب Appearance — حيث يوجد Site chrome (Nightlife وTraditional وBlack Tiffany وWhite/Black وPurple & White وBlack & Dark Green). تستخدم بلاطة Settings نفس حزمة أيقونات الكروم لعلامات Search الأخرى."},"help-club-website-feed":{"title":"موجز موقع النادي","body":"اعرض صفحة ناديك المنشورة على FLOQR في موقعك الخاص. اضغط «إنشاء المفتاح والروابط»، ثم الصق رمز iframe في موقعك أو أعطِ مسؤول الموقع رابط JSON أو RSS. يعرض الموجز الفعاليات القادمة ومنسقي الموسيقى والطاقم المميزين ومعرض الصور وبيانات التواصل وفق إعدادات صفحتك العامة. لا تظهر صور الطاقم إلا بعد تأكيد الموافقة على الصور. إنشاء مفتاح جديد يعطّل الروابط القديمة، بما فيها روابط جدول الطاقم."},"help-featured-staff":{"title":"طاقم الخدمة المميز","body":"حدّد أفراد الطاقم الذين تريدهم في صفحة النادي العامة. لكل شخص، اضغط على إحدى صوره في FLOQR أو اختر «رفع من الكمبيوتر». يمكنك تغيير الدور الظاهر تحت اسمه. اضغط «Save Public Profile» للنشر. قبل نشر الصور، احصل على موافقة كل شخص وحدّد مربع الموافقة على الصور."},"help-floqr-inbox-rules":{"title":"FloqR Inbox","body":"يحفظ FloqR Inbox رسائل System Messages ورسائل الدعم الداخلية. تُحمَّل القائمة أولاً لتظهر رسائلك بسرعة. اضغط زر New Message العائم للكتابة — اكتب اسمًا أو @username للعثور على مستلم مسموح (Club Admin أو CSR أو طاقم معتمد). محادثة patron-إلى-patron تبقى في Mingl بعد Mingl متبادل. فتح دعوة وردية لا يؤكدها — راجع ثم Approve selected في Work Calendar."},"botdee-ask-floqr":{"title":"اسأل FloqR مع BOT DEE","body":"اسأل FloqR مع BOT DEE — اضغط على العلامة المتحركة أو انتظر المطالبة، ثم اكتب ما تريد بكلمات عادية. المنتجات: Mingl، RydR، BartR، ShoutOut، FloqCAST (نجمة مشهورة)، الأندية. الأهداف: قُل “أريد أن أتمكن من…” (مثلاً أن أصبح Club Admin) أو “make me a superstar” للخطوات والروابط."},"help-vip-book-table":{"title":"حجز طاولة VIP (VIP reserV)","body":"VIP reserV يعرض خريطة القاعة ويحجز الطاولات. افتح VIP reserV من البحث، اختر Decades أو Lima Twist Club وليلة، اضغط طاولة خضراء، احجز 30 دقيقة، اقبل الشروط وادفع العربون عبر FloqR Stripe. البارات وDJ غير قابلة للحجز. في Aurelia استخدم Explore 3D walk-through للقاعة التفاعلية (الحجز يبقى على خريطة 2D)."},"help-vip-choose-venue":{"title":"اختر مكان VIP reserV","body":"Only clubs subscribed to VIP reserV appear here. The first four are nearest (GPS). Cards show open days, minimum deposit, dress code, and age. Search by name, city, or genre, then Select venue to open that club’s floor map and night picker."},"help-vip-floor-map":{"title":"VIP reserV floor map","body":"Green = available, amber = held, red = booked, grey = not bookable, blue = DJ booth. On phones the map opens on one area with chips to jump; pinch and pan; targets are at least 44px. Area names are club-editable; printed table labels stay as drawn. لدى Decades وLima Twist Club وAurelia خطة 2D منشورة؛ Aurelia توفر أيضاً Explore 3D walk-through."},"help-become-club-admin":{"title":"كن Club Admin","body":"اطلب الوصول إلى Club Admin، ثم الحصول على موافقة المكان."},"help-role-profiles":{"title":"نظرة عامة على ملفات الأدوار","body":"شاهد كيف تعمل أدوار Club Admin وDJ وPromoter ودوام الضيافة."},"help-staff-scheduling":{"title":"التقويم والجدولة","body":"يعرض تقويم Club Admin الحالات المسودة (بنفسجي)، المعلقة (كهرماني)، المؤكدة (أخضر)، والبطاقات المفتوحة / غير المملوءة — كل منها مع حالة مكتوبة، وليس اللون فقط. الجدول هو شبكة الأشخاص × الأيام للمسودات / النشر. تعود Website ingest / publicVenueCalendar بالمهام المؤكدة فقط. يتم عرض علامة مدفوع هذا الشهر باللون الأخضر لـ Club Admins عندما تكون staffSchedulingPaid=1."},"help-club-notification-subscriptions":{"title":"اشتراكات الإشعارات لنادي SMS وWhatsApp","body":"Club Admin → الإشعارات: Send test alert يستخدم المربعات المؤشرة حاليًا. داخل التطبيق (والإشعارات الفورية) يكتب رسالة نظام في FloqR Inbox. البريد الإلكتروني يستخدم عناوين مديري النادي. SMS و WhatsApp لا تزال بحاجة إلى اشتراك مدفوع بالإضافة إلى هاتف تنبيه E.164. الحبة الخضراء = اشتراك Firebase 1 (حزمة مسبقة الدفع بقيمة 10 دولارات)؛ الأحمر = 0. إذا أعاد Send test alert Authentication Error - invalid username، يجب أن يكون سر Firebase TWILIO_ACCOUNT_SID هو SID الحساب الذي يبدأ بـ AC (34 حرفًا) من console.twilio.com — وليس رمز المصادقة ولا مفتاح API (SK)."},"help-club-sms-notification":{"title":"اشتراك إشعارات SMS","body":"الحبة SMS خضراء عندما يكون Firebase smsSubscribed 1 (حزمة مسبقة الدفع بقيمة 10 دولارات، 466 رصيدًا، ليست شهرية أو سنوية). الأحمر/يومض يعني 0 — افتح ؟ واضغط على Subscribe $10. الأرصدة المتبقية وآخر تاريخ دفع موجودان في هذه المساعدة. قم بإلغاء تحديد SMS وحفظ للإيقاف المؤقت للتنبيهات دون فقدان الحزمة المدفوعة."},"help-club-whatsapp-notification":{"title":"اشتراك إشعارات WhatsApp","body":"حبّة WhatsApp تكون خضراء عندما يكون Firebase whatsappSubscribed 1 (حزمة مدفوعة مسبقًا $10، 233 رصيد، ليست شهرية أو سنوية). الأحمر / الوميض يعني 0 — افتح ? واضغط Subscribe $10. الأرصدة المتبقية وتاريخ الدفع الأخير موجودان في هذه المساعدة. قم بإلغاء تحديد WhatsApp وحفظ لإيقاف التنبيهات دون فقدان الحزمة المدفوعة."},"help-schedule-message-templates":{"title":"جدول نماذج الرسائل","body":"Club Admin → الإشعارات → Message templates. هذه رسائل النظام (Inbox / البريد الإلكتروني / SMS / WhatsApp)، ليست ShoutOut. حرر العنوان والنص لـ New shift needs confirmation، تحديث الجدول، تأكيد الوردية، ورفض الوردية. العناصر النائبة: {club} {role} {when} {link} {worker}. صندوق وارد العامل يستخدم Review & confirm shift — أبدًا Open Related ShoutOut."},"help-schedule-confirm":{"title":"تأكيد الورديات المخصصة","body":"Inbox / البريد الإلكتروني / روابط SMS تفتح Work Calendar. انظر لكل مهمة معلقة، ضع علامة عليها (أو Select all)، ثم Approve selected. فتح الرابط لا يؤكد. فقط عضو الخدمة المخصص يمكنه الموافقة — Club Admin لا يمكنه التأكيد نيابة عنه."},"help-template-catalog-report":{"title":"تقرير كتالوج النماذج","body":"يسرد كل نوع قالب ShoutOut وأي أحجام LED يدعمه (Is96x48، Is64x48، Is64x32). يقدم المكان قالبًا فقط عندما يكون واحد على الأقل من هذه العلامات 1 وعلامة VenueSupports* المطابقة 1. قوالب عيد الميلاد / الوسائط المقسمة هي 1 على 96×48 و64×48 و64×32. 96×48 عبارة عن 3 أسطر جنبًا إلى جنب؛ 64×48 و64×32 يقومان بتكرار الصورة ثم التحية المكونة من 3 أسطر مع بطاقة FLOQR + معرف."},"help-club-display-screens":{"title":"شاشات العرض FLOQR","body":"مخازن clubLocations Firebase تحفظ VenueSupports96x48 وVenueSupports64x48 وVenueSupports64x32 كـ 0 أو 1. القوالب تحفظ Is96x48 وIs64x48 و8 بنفس الطريقة. يسرد المكان قالبًا فقط عندما تكون إحدى الأزواج 1 على الأقل. تظل عناوين Xibo URL على display.html?location=id وdisplay2.html?location=id — حجم الشاشة غير موجود في URL. يتم تقديم عيد الميلاد بجميع الأحجام الثلاثة (3 أسطر جنبًا إلى جنب على 96×48؛ تكرار الصورة/التحية على 64×48 و64×32). القالب الأساسي هو display.html. القالب الثانوي هو display2.html."},"help-staff-week-calendar":{"title":"الجدول الزمني","body":"الجدول الزمني 5 هو شبكة أشخاص × أيام الأسبوع. 4 يغلق المحرر باستخدام 0. إنشاء مسودات، 1 حتى يؤكد العمال ما هو معلق حتى يُؤكد، 3 للحذف الجماعي، و2 لوضع الورديات المنشورة على موقع النادي. نافذة الورديات الافتراضية = وقت فتح النادي − ساعتان مروراً بالإغلاق + ساعة واحدة."},"help-staff-schedule-user-guide":{"title":"دليل مستخدم جدولة الموظفين","body":"افتح ؟ بجانب الجدول الزمني على 2 الجدولة. أنشئ مسودات الورديات، 0 حتى يؤكد العمال ما هو معلق→مؤكد، ثم 1 لحذف عدة ورديات مرة واحدة. مثال: جميع مسودات يوم الأربعاء بالإضافة إلى شريحة يوم الخميس المؤكدة."},"help-create-publish-schedule":{"title":"إنشاء ونشر جدول الموظفين","body":"أضف نوبات مسودة على شبكة الأشخاص × الأيام، راجع البطاقات، ثم Publish schedule. يجب على العمال التأكيد قبل أن تصبح النوبة مؤكدة. BOT DEE: create a schedule، publish schedule، how to schedule staff."},"help-multi-delete-shifts":{"title":"حذف عدة نوبات مجدولة أو مسودة","body":"Select shifts، اخلط رؤوس الأيام والبطاقات، ثم Delete selected. مثال: جميع مسودات يوم الأربعاء بالإضافة إلى نوبة مؤكدة واحدة يوم الخميس."},"help-staff-worksheet":{"title":"ورقة العمل - تقويم الموظفين الأسبوعي","body":"الأعضاء المنتخبون يفتحون Work Calendar في الإعدادات. روابط التأكيد Inbox / البريد الإلكتروني / SMS تصل هنا. راجع المهام المعلقة، ضع علامة على كل نوبة (أو Select all)، ثم Approve selected — فتح الرسالة لا يؤكد. تظهر شبكة الأسبوع نوبات الزملاء المنشورة. تبقى المسودات في Club Admin."},"help-service-members":{"title":"Services & Service Members","body":"يبدأ الجميع كـ patron FLOQR. في My Profile & Settings اضغط Elect to become a service member واختر الدور والأندية وأرسل في أسفل الصفحة.\n\nدليل قوالب الملف — تبقى الملفات الاجتماعية للـ patron في الوسائط العامة.\n\nموافقة Club Admin — Club Admin → Employee/Workers → Pending Worker Requests، أو مراجعة واختيار على هذا التبويب."},"help-venue-website-ingest":{"title":"استيراد موقع النادي (API، RSS، iframe)","body":"Club Admin → الجدولة → Website ingest. إنشاء سرّي (يُعرض مرة واحدة فقط؛ يُخزن مجرد هاش). استدعاء الورديات المنشورة للموظفين على الموقع الرسمي للنادي باستخدام JSON (?format=json&dataset=schedule|hours|profile|all)، أو RSS، أو كود iframe. المسودات، البريد الإلكتروني للموظفين، والهاتف لا تُدرج أبداً. قم بتدوير السر إذا تسرب."},"help-venue-hours-calendar":{"title":"ساعات فتح المكان","body":"في الملف العام للنادي، اضبط ساعات الفتح/الإغلاق الأسبوعية الافتراضية، ثم أضف تجاوزات للفترات الخاصة دون فقدان الافتراضي. تُظهر صفحة النادي العامة شبكة أسبوعية من الأحد إلى السبت مع نطاق التواريخ (مثلاً الأحد 9 – السبت 15، أغسطس 2026) وتلوين التقويم. تُدرج قائمة العطلات الرسمية القادمة ساعات الفتح والإغلاق وتوضح متى تختلف عن أيام الأسبوع المعتادة. يستخدم جدول الموظفين ساعات من الفتح − ساعتين إلى الإغلاق + ساعة. يمكن لقائمة الضيوف اقتراح الليالي المفتوحة."},"help-club-admin-affiliation":{"title":"Club Admin تعيين المكان","body":"Club Admin يفتح فقط مركز قيادة المكان للنادي الذي يتم تعيينه له. فتح admin.html بدون مكان لم يعد يحدد Zebbies افتراضياً. حسابات العرض temp_clubadmin_N@floqr-demo.com تتطابق مع temp-democlub-N. المطالبين الذين لم يتم تعيينهم يطلبون التعيين من Master Admin."},"help-venue-command-center":{"title":"مركز قيادة المنشأة","body":"الموافقة على ShoutOuts، ومراجعة أداء المكان، وتسوية نشاط الحساب لهذا الموقع."},"help-club-template-repository":{"title":"قوالب ناديك","body":"تظهر القوالب المصممة لناديك فقط في المقدمة مع عبارة «حصريًا في» واسم المكان. القوالب المعيّنة هي التي يمكن للزبائن اختيارها في ناديك؛ غيّر ذلك عبر تعيين القالب أو إزالة القالب. يعثر البحث على القالب حتى بدون علامات التشكيل أو مع خطأ إملائي بسيط."},"help-employee-network":{"title":"شبكة الموظفين والعاملين","body":"تظهر هنا فقط الأشخاص المرتبطون بهذا النادي: العاملون المعيّنون أو الموافق عليهم هنا، ومسؤولو النادي، والعاملون المنتسبون إلى هذا النادي. لمنح شخص دورًا، اكتب اسمه أو اسم المستخدم أو بريده الإلكتروني في تعيين زبون لدور، ثم اضغط اختيار بجانب الشخص الصحيح، واختر الدور، ثم اضغط تعيين الزبون المحدد للدور وأكّد. يحتاج الشخص أولًا إلى حساب زبون في FLOQR. يمكن جعل النُدُل والنادلات والـ bottle girls في القائمة ممثلين لخدمة العملاء (CSR)."},"help-template-tags":{"title":"وسوم القوالب","body":"أضف كلمات قد يكتبها الزبائن عند البحث عن قالب في مكانك، مثل ليلة المباراة أو عيد الميلاد. يمكن لمديري القوالب إضافة الوسوم. ويمكن لمسؤولي القوالب وClub Admin إزالتها أيضًا. يعيّن Club Admin هذه الأدوار من قسم Role Activity & Permission."},"help-display-idle-default":{"title":"شاشة الانتظار: Use ShoutOut @ المكان","body":"عندما لا يُعرض أي ShoutOut، يعرض Display 1 عبارة «Use ShoutOut @» مع اسم مكانك. يُعرض كل ShoutOut معتمد لمدة 10 دقائق ثم تعود الشاشة تلقائيًا إلى هذه الرسالة. إعادة ضبط الشاشة إلى الوضع الافتراضي في Club Admin تفعل ذلك فورًا."},"help-club-messaging-credit":{"title":"رصيد SMS وWhatsApp","body":"كل حزمة بـ 10$ تموّل 7.00$ من سعة Twilio؛ تحتفظ FloqR بـ 3.00$ هامش المنصة. حزمة SMS → 466 رسالة (≈ 0.015$ SMS أمريكي). حزمة WhatsApp → 233 رسالة (≈ 0.030$ Twilio + Meta marketing). عند الرصيد 0 اشترِ حزمة أخرى قبل الإرسال. فتح SMS ops (10$) يمنح حزمة SMS. خدمة WhatsApp (10$) تمنح حزمة WhatsApp. الحساب: 10$ → 466 SMS أو 233 WhatsApp (7.00$ Twilio / 3.00$ FloqR)."},"help-club-marketing-campaigns":{"title":"حملات التسويق","body":"اختر قالبًا للقطاع، حمّل الخلفية والصور الإضافية، عدّل النص، ثم احفظ أو أرسل. الإرسال يخصم رصيد SMS أو WhatsApp من رصيد المراسلة."},"help-club-in-app-marketing":{"title":"التسويق داخل التطبيق","body":"انشر منشورًا دعائيًا أو فيديو حتى 30 ثانية باسم ناديك. بعد الدفع وموافقة FLOQR يظهر على شاشة تحميل البحث وفي Mingl وRydR وشاشات FLOQR الأخرى. يتيح ناشرو إعلانات النادي لأحد أعضاء الفريق نشر إعلانات للنادي (دور Club Ad Poster). لا حاجة إلى رصيد SMS."},"help-vip-terms-consent":{"title":"شروط VIP reserV","body":"بعد حجز الطاولة افتح صفحة الشروط واقرأها واقبل مرة واحدة (التسويق اختياري ومنفصل). تُحفظ الموافقة قبل FloqR Stripe Checkout — مثل ShoutOut المدفوع ثم الإيصال وتصريح الباب."},"help-vip-door-pass":{"title":"تصريح باب VIP reserV","body":"بعد تأكيد العربون، ملفي → الحجوزات → عرض التصريح لرمز QR لمرة واحدة. أحضر هوية 21+. يستخدم طاقم الباب VIP reserV Door."},"help-vip-door-ops":{"title":"تسجيل الدخول عند الباب VIP reserV","body":"يفتح VIP Managers صفحة VIP reserV Door لهذه الليلة. امسح أو الصق الرمز، أكّد هوية 21+، ثم check-in. No-show فقط بعد المهلة. رابط notify لا يغيّر الحالة."},"help-vip-payment-collector":{"title":"جامع دفع VIP reserV وClub POS","body":"المفضّل للأندية الحية مع Toast/SpotOn: Club POS — FLOQR يحجز/يمسك/خريطة؛ الـ POS يملك العربون والحساب والإنفاق. بدائل: Club Stripe أو FloqMedia Stripe (FloqR) أو محرك VIP + CSV. Aurelia (Demo Club) افتراضياً FloqMedia Stripe — اسأل BOT DEE عن خطوات Master وClub Admin."},"help-vip-table-isbooked":{"title":"حالة isBooked لطاولات VIP في Firestore","body":"لكل نادٍ VIP مستند Firestore لكل رقم طاولة وليلة: clubLocations/{locationId}/vipNights/{YYYY-MM-DD}/tables/{tableNumber}. المعرّف = الرقم المطبوع (مثل T1، B3). بعد اكتمال الحجز: isBooked \"1\" وisBookedYes \"yes\". الفارغة: \"0\" / \"no\". الـhold لا يغيّر isBooked. الإلغاء → \"0\". getVipAvailability يعتمد isBooked لحالة الحجز. الإلغاء يصفّر isBooked دائماً إلى \"0\"؛ ويمكن لـ FloqMedia/Club Stripe استرداد العربون وفق سياسة النادي."},"help-vip-floqr-stripe-aurelia":{"title":"إعداد FloqMedia Stripe لنادي Aurelia (Demo Club)","body":"يستخدم Aurelia (temp-democlub-1) FloqMedia Stripe (FloqR Checkout) كجامع عربون VIP الافتراضي — يدفع الرواد على Stripe منصة FloqR ثم تُعلَّم الطاولة محجوزة.\n\nخطوات Master Admin:\n1) افتح Master Admin ← Features Mgmt ← VIP reserV Payments.\n2) تأكد من تفعيل VIP Reservations على الشبكة.\n3) Seed / refresh لمزوّدي POS فقط إذا ستستخدم Club POS لاحقاً — غير مطلوب لـ FloqMedia Stripe.\n4) أبقِ Aurelia على FloqMedia Stripe ما لم تحتاج Club POS أو Club Stripe.\n5) بعد العربون افتح Network VIP billing.\n\nخطوات Club Admin (Aurelia):\n1) سجّل الدخول كـ temp_clubadmin_1@floqr-demo.com (OTP عبر البريد من الصفحة الرئيسية) أو حساب Club Admin لأوريليا.\n2) Club Admin ← VIP reserV (location=temp-democlub-1).\n3) تحت Payment collector اختر FloqMedia Stripe (FloqR).\n4) أبقِ Require deposit before table is marked booked مفعّلاً للعروض.\n5) احفظ Save payment collector.\n6) اختبار: vip.html?location=temp-democlub-1 ← احجز طاولة ← الشروط ← ادفع العربون (بطاقة اختبار 4242…).\n7) الباب / الفوترة: Open Door؛ Refresh billing.\n\nلا تختر Club POS لعروض Aurelia إلا مع sandbox Toast/SpotOn عمداً. FloqMedia وStripe وShoutOut وVIP reserV علامات تجارية لا تُترجم."}}};
  if (global.FLOQRHelpRepository && global.FLOQRHelpRepository.registerMany) {
    global.FLOQRHelpRepository.registerMany(entries);
  }
  if (global.FLOQRI18nHelp && global.FLOQRI18nHelp.mergePacks) {
    global.FLOQRI18nHelp.mergePacks(packs);
  }
  try { global.FLOQRI18nHelp && global.FLOQRI18nHelp.applyHelpDom && global.FLOQRI18nHelp.applyHelpDom(global.document); } catch (error) {}
})(typeof window !== "undefined" ? window : globalThis);
